window.CHAKRA_DATA = {"ystr": {"1": ["белсенділік, сенімділік, батылдық, оптимизм, шешімділік, қауіпсіздік сезімі, жақсы иммунитет, энергиялылық, эмоциялық орнықтылық, төзімділік.", "мазасыздық, қорқыныш, алаңдаушылық, сенімсіздік, агрессия, дау, жалқаулық, енжарлық, бос жүрушілік.", "сүйек жүйесі, омыртқа, қан, аяқ, бұлшықеттер, тіс, шаш, иммунитет, ішек, салмақтың қосылуы немесе азаюы, жарақаттар, жаңа өскіндер.", ["Батылдық пен шешімділік танытыңыз.", "Бастаманы өз қолыңызға алыңыз.", "Өзгерістен қорықпаңыз — оларды өзіңіз бастаңыз.", "Денеге көңіл бөліңіз: тексеруден өтіңіз, массажға барыңыз, нығайтатын және қалпына келтіретін процедуралар курсынан өтіңіз.", "Тоқырау сезінетін салаларда көптен бері өзгерткіңіз келген нәрсені өзгертіңіз.", "Кез келген дене белсенділігіне уақыт табыңыз. Өміріңізде спорт болмаса, бірден кросс жүгіріп немесе 50 рет жерден көтерілудің қажеті жоқ — 10–15 минут жеңіл жаттығу немесе таңғы жаттығу жеткілікті.", "Ашуланшақтық пен агрессиядан аулақ болып, ішкі тыныштыққа ұмтылыңыз.", "Сізді қолдамаса және идеяларыңызды қабылдамаса да, айналадағыларға төзімді болыңыз — өзгенің пікірін абыроймен қабылдаңыз.", "Ішкі қысылуды жоя отырып, ашуды жұмсақ шығаруды үйреніңіз.", "Сапарға шығып, жаңа әсер жинаңыз.", "Жалғыз немесе отбасыңызбен серуендеңіз — бұл аулада серуендеу немесе ауа райына қарай орманда, велосипедпен, шаңғымен немесе конькимен серуен болуы мүмкін.", "Өміріңізге жерге байлану (заземление) практикасын енгізіңіз: табиғатта жиі болыңыз, жалаңаяқ жүріңіз, моншаға барыңыз."], "спорт және созылу жаттығулары, дене практикалары мен массаж, денеге қамқорлық, өзіне сенімділікті дамыту, саяхат пен сапарлар, қорқыныш пен мазасыздықпен жұмыс, арт-терапия және нейрографика, көшбасшылық қасиеттерді дамыту, жарыстар, табиғатпен және стихиялармен араласу, шыдамдылық, төзім, ұқыптылық, тәртіп пен режим маңызды мұқият бір сарынды жұмыс, құрылыс, бағбандық және фермерлік."], "2": ["сүйкімділік, тартымдылық, сезімталдық, еркіндік, шығармашылық, денелік, оптимизм, қабылдағыштық, үйлесімді қарым-қатынас, ашықтық, жомарттық, өзіне-өзі жеткіліктілік.", "жалқаулық, жауапсыздық, ұшқалақтық, сенімсіздік, қызғаныш, тәуелділіктер, бірге тәуелділік, отбасындағы және серіктеспен дау, ауыр ажырасулар, кешендер, ұят сезімі, кінә сезімі, сезімді көрсетуге тыйым.", "лимфа, несеп-жыныс, ұрпақ өрбіту және бөліп шығару жүйелері.", ["Отбасы мен серіктеске көңіл бөліңіз.", "Достарыңызбен уақыт өткізіп, өзіңізге демалуға рұқсат беріңіз.", "Жалғыз болсаңыз — айналаға қарайтын нақ уақыт.", "Әбігер мен асығыстықтан аулақ болып, айналадағы әлеммен тепе-теңдікті сақтаңыз.", "Ынтымақтастықтан бас тартпаңыз — келісіп, байланыс құрыңыз.", "Қазір екпін мен күштен гөрі сезімталдық пен әдептілік жақсы жұмыс істейді.", "Шығармашылықпен, сізді шабыттандыратын нәрсемен айналысыңыз.", "Махаббат пен қолдауды таңдай отырып, отбасылық өкпемен жұмыс істеңіз.", "Анаңызбен қарым-қатынаспен жұмыс істеп, одан ішкі бөлінуді аяқтаңыз.", "Шынайы тілектеріңізді анықтап, оларды кішкентайдан бастап орындаңыз (мысалы, шопинг немесе спа).", "Сумен байланыста болыңыз: моншаға барыңыз, ваннаға түсіңіз, бассейнде жүзіңіз, контраст душ қабылдаңыз.", "Сезімталдығыңызды ашыңыз — тәжірибе жасап, өзіңізді танитын нақ уақыт.", "Жалқаулық пен тәуелділікке кетпей, денеге жеңіл жүктеме беріңіз: йога, пилатес, созылу, ер адамдарға — жекпе-жек."], "балалармен араласу, әйелдермен араласу, дене практикалары, спа және массаж, ойын-сауық және әртістік керек нәрсенің бәрі, шығармашылық, сексология мен психологияны оқу, икемділік керек спорт — гимнастика, мәнерлеп сырғанау, балет, йога, кез келген би, үйде және жұмыс орнында жайлылық жасау, суда белсенділік — жүзу, сёрфинг және т.б., стилистпен жұмыс және өз стилін жаңарту."], "3": ["көшбасшылық, өршілдік, табандылық, ерік күші, харизма, өзін бақылау, сенімділік, нәтижеге бағытталу, табыстылық, ықпалдылық.", "қызғаныш, ашу, басқаларға қысым жасау, алаңдаушылық, шыдамсыздық, ашуланшақтық, мақтаншақтық, ысырапшылдық, сараңдық, дауға бейімділік, апатия, жалқаулық, енжарлық, шешімсіздік, ұят.", "ас қорыту жүйесі, асқазан-ішек жолы, зат алмасу, тамақтану тәртібі мен сипатының бұзылуы, терінің күйі.", ["Қаржылық және мансаптық мүмкіндіктерді пайдаланыңыз.", "Әлеуметтік белсенділік танытыңыз.", "Басқару және басшылық дағдыларын қолданыңыз.", "Қаржылық сауаттылықты арттырып, бюджетті бөліңіз.", "Қаржылық «қор жинағын» (подушка безопасности) жасай бастаңыз: ақшаның бір бөлігін (әдетте айлық таза табыстың 5–10 %) қорапқа салыңыз немесе жалақы картасынан кез келген соманы жинақ шотына аударыңыз.", "Тұрақты дене белсенділігін енгізіп, жүктемені біртіндеп арттырыңыз.", "Жұмыс пен демалыстың тепе-теңдігін реттеңіз.", "Ұзақ мерзімді мақсаттар қойып, оларға апаратын қадамдарды жазыңыз.", "Күн сайын қалаған нәрсеге ең болмаса 15 минут бөліңіз.", "Шоттарды ретке келтіріп, барлық қарызды төлеңіз.", "Сараңдықтан, материалдыққа берілуден және ысырапшылдықтан аулақ болып, ақша энергиясының заңдарын есте сақтаңыз.", "Күн тәртібін реттеп, ұйқыңызды қандырыңыз.", "Рационға көңіл бөліңіз: өнім таңдауын, порция көлемін және тамақтану жиілігін ойластырыңыз.", "Аскеза мен шектеулер енгізіңіз.", "Ашуды шығарудың жұмсақ тәсілдерін табыңыз — тыныс алу практикалары, спорт."], "қоғамдағы табыс пен мансаптық жетістіктерге байланысты нәрсенің бәрі, қаржылық стратегиялар мен жобалар, мақсат қою және жоспарлау дағдыларын дамыту, спорт және жаттықтырушылық, саясат, сатылым және жылжыту, коучинг, нутрициология, тамақ әзірлеу және тамақтану саласы — мысалы, аспаздық немесе мейрамхана бизнесі, салауатты өмір салты, аскеза және саналы тұтыну."], "4": ["альтруизм, жанашырлық, өзіне және әлемге деген махаббат, өзін және әлемді қабылдау, алғыс, шығармашылық, шынайылық, адалдық, сезімталдық, эмпатия, ашықтық.", "өшпенділік, ашу, кінә, салқындық, құрбандыққа бейімділік, алаңдаушылық, менмендік, тәкаппарлық, ашуланшақтық, талапшылдық, фанатизм, сенімсіздік, немқұрайдылық, бақылау, мазасыздық, көңілсіздік, қанағаттанбау.", "жүрек-қантамыр жүйесі, жүрек, үрей ұстамалары (панические атаки), өкпе, бронхтар, қан айналымы, омыртқаның кеуде бөлігі, кеуде қуысы, сүт бездері және қолтықасты аймағы, айырша без (тимус).", ["Үйлесімді қарым-қатынасқа көңіл бөліңіз — мүмкін, отбасы психологының көмегімен.", "Жұп немесе отбасын құру туралы ойланыңыз: таныстық сайтына тіркеліңіз, әлеуметтік желі жүргізіңіз.", "Эмоциялық тепе-теңдікке ұмтылыңыз: өкпе мен жағымсыз эмоциялармен жұмыс істеу тәсілдерін (арт-терапия, нейрографика және т.б.) жаттықтырыңыз, жазыңыз, эмоция күнделігін жүргізіңіз.", "Алғысты дамытыңыз: алғыс күнделігін жүргізіп, алғыс хаттарын жазыңыз — ата-анадан бастап.", "Достармен кездесіп, жанашырлық танытыңыз, өзгенің шекарасын құрметтеп, өзіңіздікін құрыңыз, артық тұтасып кетпеңіз.", "Басқаларға көмектесіп, қолдаңыз, мысалы, қайырымдылық пен волонтёрлық арқылы. Жақындарға жақсылықты таңбай, сұраған кезде көмектесіңіз.", "Хендмейдте немесе аспаздықта өзіңізді байқап көріңіз.", "Медитация мен дене практикалары арқылы махаббат энергиясына толыңыз, өзіңізге қуаныш жасаңыз — мысалы, сізге ресурс беретін жағдайлар мен істердің тізімін жасап, керек кезде соған жүгініңіз.", "Үй жануарын алғыңыз келсе — қазір нақ уақыт. Оны баспанадан немесе көшеден алсаңыз, тамаша."], "психология мен коучингті оқу, эзотериканы оқу, эмоциялық интеллектті дамыту, нумерология, таро, руналар, қол шеберлігі мен хендмейд, емшілік, қолөнер, шығармашылық, оқыту және тәрбиелеу, аспаздық, косметология, қайырымдылық және волонтёрлық."], "5": ["өзін білдіру, ашықтық, дипломатия, өзін түсіну, адалдық, шынайылық, шығармашылық, дауыс күші, шешендік қабілет, сенімділік, әдептілік.", "эмоция мен ойды білдіре алмау, сезімді көрсетуге тыйым, эмоцияны ұстай алмау, тілі келмеу, сөзуарлық, тұйықтық пен ұялшақтық, көпшілік алдында сөйлеуден қорқу, өзін көрсетуден және шындықтан қорқу, дауға бейімділік, өз пікірін қорғап айқайлағысы келу, келісімге барғысы келмеу, шығармашылық дамудың болмауы.", "тамақ, көмей, мұрын-жұтқыншақ, қалқанша және қалқанша маңы бездері, дауыс байламдары, өкпенің жоғарғы бөлігі, тіс, жақ, тіл, сөйлеу.", ["Таланттар мен қабілеттерді ашатын уақыт.", "Араласу дағдыларын дамытыңыз.", "Дауыс пен сөйлеумен жұмыс істеңіз.", "Шығармашылықпен айналысыңыз.", "Әлеуметтік белсенділік танытыңыз.", "Дау мен жанжалды жұмсақ шешуді және келісуді үйреніңіз.", "Ымыраға барыңыз.", "Вокалмен айналысып, караокеге барған пайдалы.", "Жазыңыз — оның ішінде өлең.", "Шығармашылық шеберлік сабағына барыңыз.", "Эмоцияны білдіру үшін күнделік жүргізе бастаңыз.", "Көпшілік алдында сөйлеу жемісті болады.", "Адамдарға дауысыңызбен әсер етіңіз.", "Идеялар мен жобаларды жүзеге асырыңыз.", "Тіл үйренуге тамаша уақыт.", "Дауысты жаттықтырыңыз: жаңылтпаштар, дауыстап оқу.", "Кітап оқыңыз.", "Бала кезде жақсы көрген және шабыттандыратын нәрсемен айналысыңыз."], "шығармашылық әуестіктер, дауыспен жұмыс, музыкалық және актёрлық қызмет, оқыту және тәлімгерлік, жазушылық, көркем қызмет, блогинг және көпшілік алдында болу, психология және коучинг, сатылым, медиация (даулардағы делдалдық)."], "6": ["түйсікке сену, жақсы есте сақтау, ақыл күші, стратегиялық ақыл, ойдың жүзеге асуы, ойлау икемділігі, идеяға бай болу, білімдарлық, тапқырлық.", "ұйқысыздық, оқудағы қиындықтар, қорқыныш пен фобиялар, көңілсіздік, елестер, қалыпқа салынғандық, пессимизм, алаңдаушылық, менмендік.", "ми, көз, құлақ, мұрын, бет нерві, бет, бас сүйек, тіс, жақ, есте сақтау, психосоматика.", ["Интеллектуалдық жағынан жүзеге асыңыз.", "Оқуға тамаша уақыт.", "Басқаларға ой мен шешімді түсінуге көмектесіңіз.", "Тәлімгерлік пен оқытуда өзіңізді көрсетіңіз.", "Жазушылық қабілет пен креативтілікті дамытыңыз.", "Түйсікті және ішкі дауыс пен тағдыр белгілеріне сенуді дамытыңыз.", "Ой-өріс пен ойлауды кеңейтіңіз.", "Әлем заңдарын зерттеп, тиісті әдебиетті оқыңыз.", "Қорқыныш пен ұстанымдармен жұмыс істеңіз: олардың қайдан шыққанын және олардан қалай арылуға болатынын анықтаңыз.", "Жаңа білім алып, ми шабуылына қатысыңыз.", "Басқатырғыш, сөзжұмбақ, жұмбақ шешіп, квесттерден өтіңіз.", "Идеяларды ұзақ жәшікке салмаңыз — оларды жүзеге асыру стратегиясын ойластырыңыз.", "Мақсат қойып, оларды шағын мақсаттарға бөліңіз."], "оқыту және тәлімгерлік, өнертапқыштық және зерттеулер, жазушылық және сценарийлер, бағдарламалау және IT, креативті идеялар мен шешімдер табу керек нәрсенің бәрі, интеллектуалдық және ғылыми қызмет, ми шабуылы мен интеллектуалдық жарыстар, стратегия және жоспарлау, медитация және ақылды тыныштандыру тәсілдері, басқаларға өмірлік міндеттерді шешуге және шешім іздеуге көмектесу."], "7": ["шабыт, сенім, Ғаламмен байланыс, жоғары күштермен байланыс, ішкі тыныштық, жан тыныштығы, өзін және әлемді тану, экстрасенсорлық қабілеттер, түйсік күші, көкірек көзінің ашылуы, ішкі тірек.", "апатия, көңілсіздік, үрей ұстамалары, өзін түсінудегі қиындықтар, өмір мәнін жоғалту, мұң, психикалық тұрақсыздық, әрекетсіздік пен жалқаулық, оңашалану, түйсікке сенбеу, материалдыққа берілу, шындықтан алшақтау.", "орталық жүйке жүйесі, психика, шаш, психосоматика.", ["Энергия беретін өз Күш көзіңізді табыңыз: сенім, шығармашылық, әлем туралы дәстүрлі емес білім мен ғылымдар (психология, философия, нумерология және т.б.).", "Медитация, табиғат стихиялары және оңашалық арқылы ішкі диалогты тоқтатуды үйреніңіз. Психологпен жұмыс істеп, психологиялық құралдар мен тәсілдерді пайдаланыңыз.", "Зерттеу және таным жұмысы пайдалы.", "Жемісті оқып, қосымша білім алуға болады.", "Эзотерика мен экстрасенсорика арқылы өзіңізді тану уақыты.", "Түйсікті дамытыңыз: өзіңізге құлақ асып, белгілерді байқап, түсті жорыңыз.", "Кез келген энергетикалық практика және санасыздықпен жұмыс пайдалы.", "Кітап оқуға, музыка мен медитацияға уақыт бөліңіз.", "Өз кеңістігіңізді жасап, өзіңізбен оңаша болуға үнемі уақыт табыңыз.", "Күн тәртібін реттеп, ерте тұруды жаттықтырыңыз.", "Жеңіл дене жүктемесін, созылуды және таза ауада серуенді қосыңыз.", "Ниетті орындау үшін кез келген аскеза пайдалы: үнсіздік, байланып қалған зиянды өнімнен бас тарту (мысалы, кофе немесе шоколад), сүйіспеншілікпен тамақ әзірлеу, көмек сұрай білу, басқаларға көмектесу, «қонақтарға» — құстарға, мысықтарға, иттерге, баспанасыздар мен мұқтаждарға қамқорлық."], "шығармашылық жұмыс немесе хобби, өнермен байланыс, белгісіз және жасырын нәрсеге қызығушылық, ғылыми қызмет пен зерттеулер, философия және дін, психология және адам санасы мен әлем құрылысының заңдары туралы әртүрлі ілімдер, эзотерика және энергетикалық практикалар, тәлімгерлік және білім беру."], "8": ["құндылықтарды қайта бағалау, көшбасшылық, басқару, әлемге әсер ету, ішкі еркіндік, харизма, батылдық, мақсаттылық, тәуелділіктен шығу, рух күші, руханилық, табандылық.", "өзгерістен және әрекеттен қорқу, өзін-өзі бағалаудың төмендеуі, мазасыздық, өзіне сенімсіздік, өзін құрту, тәуелділіктер, өзіне зиян келтіру, ақталмаған тәуекел, мақсаттан бас тарту, апатия және құрбан позициясы, көңілсіздік, материалдыққа берілу.", "психика, жарақаттар, жаңа өскіндер, өзіне зиян келтіретін мінез-құлық.", ["Көшбасшылық пен басқару дағдыларын пайдаланыңыз.", "Өмірдің рухани негізін танумен айналысыңыз.", "Өзгерістерді позитивті қабылдаңыз.", "Ескімен қоштасып, жаңаға орын босатыңыз — үйді жинаудан, телефон мен контактілерді тазалаудан және ескі шектейтін ұстанымдармен жұмыстан бастаңыз.", "Шешімде батылдық танытыңыз.", "Өз ісіңізді, жобаңызды немесе бағытыңызды дамыта бастаңыз.", "Құрбан позициясымен жұмыс істеңіз.", "Әрі қарай өсу мен табыс үшін іс саласын түбегейлі өзгерткен пайдалы.", "Жағымсыз ойлар мен өзін құрту сәттерін байқап, олармен — өзіңіз немесе психологпен — жұмыс істеңіз. Психология, эзотерика, философия және әлем заңдарын (бумеранг заңы, «ұқсас ұқсасты тартады», энергия тепе-теңдігі заңы және т.б.) зерттеу көмектеседі.", "Қуаныш пен шабыт әкелетін істерді, орындарды немесе жағдайларды тауып, оларға үнемі жүгініңіз.", "Ауыр ойлар азырақ, сындарлы шешімдер мен әрекеттер көбірек болсын.", "Мансаптық өсу мен жетістіктерге ұмтылыңыз.", "Рухани мен ақшаның тепе-теңдігін сақтап, шектен тыс материалдыққа берілуден аулақ болыңыз.", "Өсу дағдарыс арқылы келетінін есте сақтап, табанды еңбек ете беріңіз."], "психология мен философияны оқу, көшбасшыларға арналған коучинг пен тренингтер, басқару және басшылық дағдыларын дамыту, өз бизнесін құру, эзотерика мен өзін-өзі танудың әртүрлі жүйелерін оқу, экстрасенсорика мен регрессологияны оқу, дінді тану және рухани қызмет, терең ұстанымдарды анықтау және жан жараларымен жұмыс істеу үшін психологпен жұмыс, спорт, оның ішінде экстремалды — парашют, тау шаңғысы және т.б., тамақ пен ішімдікті саналы шектеу."], "9": ["әлеуметтік белсенділік пен маңыздылық, танымалдық пен атақ, құндылықтарды қайта бағалау, сәттілік пен жолдың болуы, ішкі күш, руханилық, жанашырлық, мейірімділік, ізгілік, адамгершілік.", "дау, агрессия, кедергілер мен сәтсіздіктер, көңіл қалу, қорқыныш пен мазасыздық, құрбан рөлі, өкпе мен кекшілдік, оңашалану, тұйықтық, өзін жүзеге асыра алмау.", "диагноз қоюдағы қиындықтар, бала көтеру мен оны сақтаудағы қиындықтар, жарақаттар, күтпеген сырқаттар, психологиялық қиындықтар.", ["Әлеуметтік белсенділік танытыңыз.", "Шығармашылыққа көңіл бөліңіз.", "Басқаларға жобаларды жүзеге асыруға көмектесіңіз.", "Волонтёрлық пен қайырымдылықпен айналысыңыз.", "Өмірдің рухани жағын таныңыз.", "Ашу мен агрессияны жеңіп, олардан жұмсақ арылуды үйреніңіз.", "Кестеңізге спорт пен тұрақты дене белсенділігін қосыңыз.", "Ішкі тепе-теңдікті қадағалаңыз.", "Ортаны мұқият таңдаңыз.", "Дене практикаларын байқап көріңіз.", "Психологпен сөйлесіңіз.", "Өз кеңістігіңізді жасап, өзіңізбен оңаша болуға уақыт табыңыз.", "Алғыс айтуды үйреніңіз — бұл жағымсыз эмоциялар мен өкпеден аулақ болуға көмектеседі.", "Өз әрекетіңіз үшін жауапкершілікті дамытыңыз — бұл саналы өмір сүріп, жақсара түсуге мүмкіндік береді.", "Моральдық және этикалық нормаларды басшылыққа алып, шекарадан аспай, жақсылықтан әрекет етіңіз."], "өнер және шығармашылық, актёрлық қызмет, саяхат, тәлімгерлік, спорт, психологияны оқу, қайырымдылық, волонтёрлық."]}, "mon_tr": {"0": "Нөл айын болжау қиын, ол «таза парақ» сияқты жұмыс істейді: өз шындығын жинаған тәжірибесіне, таланттары мен мүмкіндіктеріне сүйене отырып, тек адамның өзі қалыптастырады.\nБұл ай керемет сәттілік және судан құрғақ шыға білуді әкелуі мүмкін, ал бетбұрыс оқиғалары мен дағдарыстар уақыты да болуы мүмкін.\nОны жақсы жағынан өмір сүру үшін адамның санасында адамгершілік және рухани негіз қалыптасып, өмірлік міндеттер мен бағдарлар анықталып, мақсаттар қойылған болуы керек.\nСонда ай сәттілікке толып, мақсаттар айқын пішінге ие болады, қалаған нәрсе тез келеді. Керек уақытта керек адамдар пайда болып, керек таныстықтар орнап, ресурстар табылып, әртүрлі салаларда жаңа деңгейге шығаратын оқиғалар болады.", "1": "Бұл ай — ішкі мазасыздыққа және қорқынышқа қарамастан, батыл идеялар мен тағдырлы шешімдерге жақсы уақыт.\nАртқа қарамай, шешімді әрекет етіп, жаңа мүмкіндіктерді пайдалану маңызды.\nКүн тәртібі мен өзін-өзі тәртіпке салуды реттеп, әрі қарайғы әрекеттердің стратегиясын жасайтын нақ уақыт.\nСпорт пен дене белсенділігін кейінге қалдырып жүрсеңіз, бастап, тұрақты айналысатын уақыт келді.\nАй болашаққа берік негіз қалауға көмектеседі. Дәл қазір қалыптар мен консерватизмнен бас тартып, белсенді түрде алға қадам басуға болады.\nҚанағат бермейтін немесе әлдеқашан өзін сарқып болған салаларда керекті өзгерістерді бастауға күшіңіз жетеді.\nКөшбасшылық қасиеттерді көрсетіп, көптен армандаған нәрсені істеп, бұрын батылыңыз бармаған жерде өзіңізді сынап көріңіз.\nСапар мен саяхат, жарыстар және әлеуметтік белсенділік тамаша келеді.\nМүмкін, көшу немесе жұмыс ауыстыру туралы ойлар немесе мүмкіндіктер пайда болады — сеніңіз, бұл өзгерістер жақсылыққа.\nДенсаулыққа қамқорлық жасап, иммунитетті нығайтыңыз, дене сигналдарына мұқият әрі ұқыпты қараңыз.", "2": "Бұл айда алдыңғы орынға қарым-қатынас және адамдармен араласу шығады. Бұл — қарым-қатынас құруға, серіктеспен кездесуге және жеке өмірді реттеуге қолайлы уақыт. Тағдырлы кездесу де, тұрақты серіктеспен неке де болуы мүмкін.\nҚарым-қатынаста үйлесім жоқ болса және ол өзін сарқып болса, жаңа мүмкіндіктер үшін ажырасатын нақ уақыт.\nСезімталдық күшейіп, дене ләззаты мен өмір қуанышына деген ниет пайда болады.\nБұл — баланы жоспарлауға, бала көтеруге немесе босануға тамаша уақыт.\nҚарым-қатынасты реттеу үшін дипломатия мен әдептілік керек. Достармен кездесу, кештер, мерекелер мен той-томалақ болуы мүмкін.\nСіз тым қабылдағыш болуыңыз мүмкін, сондықтан улы адамдарды және сізді өз мүддесіне пайдаланатындарды іріктеп, ортаны мұқият таңдау маңызды.\nҚажеттіліктерді елемей, өзіңізге және өз тілектеріңізге көңіл бөліңіз. Өзіңізді, денеңізді және өзіңіздің «ішкі балаңызды» ар-ұят азабынсыз еркелетіңіз.\nБұл айда баяулап, асықпай, ішкі әлемге көбірек еніп, өзіңізге құлақ асқан дұрыс.\nАнаңызбен қарым-қатынасты реттеп, онымен байланыс тапқыңыз келуі мүмкін — немесе керісінше, қарым-қатынас шегіне дейін шиеленісіп, ескі өкпелер шығуы мүмкін.\nОған тәуелділікті сезінсеңіз және ішкі бөлінуді аяқтамасаңыз, мұнымен айналысатын нақ уақыт.", "3": "Бұл ай қоғамдағы орын мен қаржылық әл-ауқатты нығайту үшін даму мен белсенділікті талап етеді.\nӨзіңізді және мақсаттылығыңызды көрсетіп, ойлағанды жүзеге асыратын нақ уақыт.\nТабандылық пен төзім жемісті жұмыс істеуге көмектеседі. Көп мүмкіндік пен идея пайда болып, жаңа жобаларға күш сезінуіңіз мүмкін.\nАй жаңа мәртебеге және табыстың өсуіне серпін береді.\nСонымен бірге елеулі шешімдер мен ерік күшін талап ететін жағдайлар болуы мүмкін — жолдан таймай, табандылық таныту маңызды.\nМақсат қойып, оған қарай жүргенде адамдарға төзімдірек болыңыз, дау мен айтысқа араласпай, басқаларға қысым жасауға тырыспаңыз.\nКәсіби ұсыныстар немесе іс ауыстыру мүмкіндігі пайда болса, қазір оларды пайдалануға тамаша уақыт.\nАй тамақтануды қайта қарап, тамақ ішуге ақылмен қарауға және тәртіпті реттеуге көмектеседі.\nБелгілі бір ережелер, аскеза мен шектеулер енгізетін нақ уақыт — мысалы, тәттісіз күндер, күніне екі рет тамақтану, аралықпен ашығу және т.б. Бұл денсаулыққа да, ерік күшін жаттықтыруға да пайдалы.", "4": "Бұл ай адамдармен эмоциялық байланысқа, сіздің ішкі жайлылығыңызға және қолдап, көмектесе отырып сезімімен бөлісу ниетіне назар аударады.\nІшкі тірегіңізді, өзіңізге деген махаббатты және өзіңізді қабылдауды тексеретін сияқты жағдайлар туындауы мүмкін.\nСізге эмоциялық та, денелік те жақсы болатын адамдармен араласып, улы адамдарды, «энергетикалық вампирлерді» және тұтынушыларды алып тастау маңызды.\nСізді бағаламайтын немесе пайдаланатындармен ажырасу болуы мүмкін. Бірақ ай өзіңізді жақсы көруге және жүрегіңізді оятатын серіктесті кездестіруге де мүмкіндік береді.\nАй романтикаға, араласуға, кездесулерге және махаббат туралы айтуға қолайлы, қарым-қатынас жаңа деңгейге шығуы мүмкін.\nАлдыңғы орынға ата-анамен қарым-қатынас та шығуы мүмкін — толық қабылдау немесе керісінше, жағымсыз эмоциялар мен өкпе.\nСондықтан «ішкі баламен» жұмыс істеу практикалары және туғаннан бар өз құндылығыңды сезіну өте пайдалы.\nБұл уақытта жүрегіңіз бен мейіріміңіздің көлемі ұлғайған сияқты, сондықтан көмектесуге, қолдауға және қамқорлық жасауға ниет пайда болуы мүмкін. Өзіңізге бұдан бас тартпаңыз — айдың басты міндеттерінің бірі дәл көмек. Іште бос сияқты көрінсе де, жанашырлықтан жасалған қарапайым істер сізді энергияға толтырады.\nОрманды жай жинаудан бастап қайырымдылық пен волонтёрлыққа қатысуға дейін бәрі пайдалы.\nЕкпін мен шығармашылық энергияны сезсеңіз, оларды өз қолыңызбен бірдеңе жасап, іс жүзінде қолданған тамаша.", "5": "Бұл ай араласуды дамытуға мүмкіндік ашып, өзін білдіруді және өзгеріске деген ниетті күшейтеді.\nБұл — дипломатияны дамытуға және шешендік пен тәлімгерлікте өзін жүзеге асыруға тамаша уақыт. Шығармашылықпен, келісімдермен және ой мен идеяны білдірумен байланысты кез келген қызмет жемісті болады.\nӘртүрлі салада өзгерістер, жаңа таныстықтар мен пайдалы байланыстар, өзін білдіру керек болады — ай бұған ықпал етеді.\nМүмкін, өз көзқарасыңыз бен мақсатыңызды қорғауға тура келеді — мұны шекарадан аспай, адамгершілік қағидаларды сақтап, әдепті түрде істеу маңызды.\nШығармашылық қабілеттеріңіз жол тауып, жұмысыңызды орындаудың тың тәсілдерін іздей бастауыңыздың ықтималдығы жоғары.\nТаңдау жағдайлары болуы мүмкін — ар-ожданмен істеу ме, әлде айла жасау ма, — көп нәрсе осы таңдауға байланысты болуы мүмкін.\nБұл уақыт сізді жиналғанды — өкпені, наразылықты, ащы сезімді шығаруға итермелейді. Мұны жұмсақ істеңіз, бірақ іште сақтамаңыз: босап, толық дауыспен естілетін уақыт келді.\nКөпшілік алдындағы қызмет, блогинг және жазушылық тамаша келеді — қорқынышты жеңіп, таланттарыңызды көрсете аласыз.\nАй емтиханға, сөз сөйлеуге және әлеуметтік белсенділікке қолайлы. Бастысы — өтірік пен өсекке бармай, адал әрекет етіп, әділ болып, өз әрекетіңіз үшін жауап беру.", "6": "Ай интеллектуалдық қабілеттерді көрсетуге көмектеседі, оқуға және білім алуға қолайлы.\nСіз жұмыста да, үйде де кеңесші, делдал немесе тәлімгер бола аласыз.\nӘрекет стратегиясын жасап, талдап, қорытынды жасау керек жағдайлар болуы мүмкін.\nТалдау мен логика өте пайдалы, бірақ түйсікті де ұмытпаңыз — өзіңізді тыңдап, ішкі сезіміңізге сеніңіз.\nАй жаңа дүниетанымға және өмір бағытын өзгертуге жол ашады.\nОл үшін қоғам немесе жақындар таңған қалыптар мен ұстанымдардан шығу керек.\nӘлем заңдары мен адамзаттың рухани негізін зерттеу өзекті. Бұл білім ойдың жүзеге асу күшін түсінуге және бәрі жай ғана емес, салдары бар екенін ұғынуға көмектеседі — бұл құндылықтарды қайта бағалауға және саналы мінез-құлыққа серпін береді.\nАй өзекті мақсаттарды жоспарлап, қойып, қадам-қадамдық жоспарды талдап, әрекет етуді бастауға мүмкіндік береді.", "7": "Бұл ай — өзіне үңілу, өзін және әлемді тану уақыты. Алдыңғы орынға Сенімге жету, өз мақсат-мұратын және өмірдегі орнын түсіну мәселелері шығады.\nСірә, оңашалық пен істерден алыстау керек болады. Өзіңізге және түйсігіңізге құлақ асыңыз: ойлана отырып, ой мен сезімді ретке келтіріп, керекті мәселені түсінесіз.\nӨзін-өзі дамыту мен біліммен айналысқан пайдалы — толық бақыт үшін жетпей тұрған нәрсені табуыңыз әбден мүмкін. Бұл оқуға жақсы уақыт, әсіресе қосымша білім мүмкіндіктеріңізді толық ашуға керек дағдыларды берсе. Зейін қоюды, зерттеу қабілетін және жағдайдың нәзік тұстарына үңіле білуді талап ететін кез келген қызмет тамаша келеді.\nАлдыңғы орынға адамдармен қарым-қатынас емес, өзіңізбен үйлесім шығады. Еркіндік, тәуелсіздік және өзіне-өзі жеткіліктілік керек болады. Сын мен айыптаудан аулақ болып, өзіңіздегі тәкаппарлық пен мақтаншақтықты байқап, тоқтатқан жөн.\nМатериалдық тілектерді шетке ысырып, рухани және ой мақсаттары алға шығады.\nАй шығармашылық ойлау мен креативті ұсынуға ықпал етеді, бірақ ойлағанды жүзеге асыруды ұмытпаңыз.", "8": "Бұл ай белсенді әрекет пен шешімділікті талап етуі мүмкін. Әрекет етіп, өз дегеніңізге жететін, өз ісіңіз бен кәсіби өсуді дамытатын немесе мақсатқа апаратын жолды мұқият ойластыратын нақ уақыт.\nӨзіңізге сенімділік танытып, мүмкіндіктеріңізді байыппен бағаласаңыз, мәртебеңіз бен материалдық деңгейіңізді көтере аласыз. Ақылмен әрі практикалық әрекет ету маңызды.\nАй бұрынғы әрекеттеріңіздің салдарын көрсетіп, болашақтың негізін қалайды, сондықтан өз ойыңыз бен әрекетіңіз үшін жауапкершілікті алу маңызды. Бірдеңе ұнамаса — өз өміріңіздің жасаушысы бола отырып, өзгертіңіз!\nДәм әдеттерін өзгертіп, сау денеге алғашқы қадам жасайтын нақ уақыт.\nСпорт, дене және күш жүктемелері, күнделікті күш салу бекер кетпейді: олар өзін жеңу және күш салу арқылы әрекет ету әдетін қалыптастырады, бұл айда ол өте пайдалы.\nҚазір еңбекқорлық пен табандылық нәтиже береді, ал жалқаулық пен бос жүрушілік сәтсіздік пен дағдарысқа әкеледі. Көшбасшылық қасиеттер, адамдарды соңынан ерте білу, команданы басқару және басқару қабілеті керек болуы мүмкін. Шеберлік, бедел және ішкі күш таныта отырып, бастағанды соңына дейін жеткізу маңызды.\nБәрін өз қолыңызға алып, әлем мен адамдар сізге бірдеңе қарыз деп күтпеңіз — бұл көңіл қалу мен өкпеден аулақ болуға көмектеседі.\nЖоғары мақсаттар мен мақсат-мұратқа еру шектен тыс материалдыққа берілуден және тұрмыстық ұсақтықтан алыстап, өмір сүру мәнін түсініп, өз құнын сезінуге көмектеседі.", "9": "Бұл айда қанағат бермейтін ескі байланыстар мен көзқарастардан бас тарту керек болуы мүмкін.\nМүмкін, жаңа жоспарларға жол ашу үшін өз мақсаттарыңыз бен тілектеріңізді түсінуге тура келеді.\nШыдамдылық пен жанашырлықты талап ететін жағдайлар туындауы мүмкін. Сіз ең жақсы қасиеттеріңізді, оның ішінде мейірім мен даналықты көрсете аласыз. Пайдакүнемсіз істер мен басқаларға көмек сізге де, айдың жалпы энергиясына да өте жақсы әсер етеді.\nАй жағымсыз эмоциялардан, жұмыс істемейтін идеялардан және жайсыз ортадан арылу уақыты болуы мүмкін. Басыңызда да, үйде де тәртіп орнатуға сәтті уақыт.\nШығармашылық белсенділік, қоғамда өзін көрсету ниеті мен шабыт күшеюі мүмкін — бұл мүмкіндіктерді міндетті түрде пайдаланыңыз.\nЭмоцияны басқаруды және ішкі тепе-теңдікті сақтауды үйрену маңызды.\nӘртүрлі салада жетіліп, танып, оқып, жалпы сауаттылықты арттыратын нақ уақыт.\nБұл айда бумеранг заңы өте тез іске қосылады, сондықтан өз әрекеттеріңіз үшін ерекше жауапкершілік керек.\nБұл кезеңді жақсы жағынан өмір сүруге өзін-өзі талдау, әлем құрылысының заңдарын тану және ішкі рухани негіз жасау көмектеседі. Оның үш тірегі — алғыс, махаббат және жеке жауапкершілік.\nӨз әрекетіңіз үшін жауапкершілікті дамытыңыз — бұл саналы өмір сүріп, жақсара түсуге мүмкіндік береді.\nМоральдық және этикалық нормаларды басшылыққа алып, шекарадан аспай, жақсылықтан әрекет етіңіз."}, "mon_warn": {"0": ["Бұл айдағы ескертулер мен денсаулыққа қатысты тәуекелдерді ай кодының екінші саны бойынша қараңыз.", ""], "1": ["Өзіңізді және шешімділігіңізді көрсеткенде, айналадағыларды құрметтеуді және жұмсақ араласу тәсілдерін ұмытпаңыз: бұл уақытта дау, айтыс және шекараны қорғау қажеттілігінің ықтималдығы жоғары.\nСенімсіздік немесе ішкі тіректі жоғалту ықтималдығы артып, қорқыныш пен мазасыздық басуы мүмкін.\nЖалқаулық пен апатия сізді тоқтатып, басым түсуі мүмкін, сондықтан тек тұрақты белсенділік пен жеке ынта сізді сілкіп, энергияны дұрыс арнаға бағыттайды.\nСонымен бірге жұмысқа шектен тыс берілу (трудоголизм) де жақсы рөл атқармайды — демалуды және күш жинауды ұмытпаңыз.", "Бұл айдағы әлсіз тұстар — сүйек, бұлшықет, тіс, аяқ, омыртқа, ішек. Үйде де, көшеде де абай болыңыз: жарақат пен жол оқиғасы тәуекелі бар."], "2": ["Серіктеске, ортаға немесе жағдайға тәуелділікті сезінуіңіз мүмкін, бұл сізді құрбан рөліне итермелейді. Өз әрекетіңізге, идеяларыңыз бен жобаларыңызға сенімсіздіктен ішкі теңгерімсіздік пен мазасыздық, эмоциялар мен сыртқы оқиғалардың біраз тежелуі болуы мүмкін.\nӘлсіз жағында ай қарым-қатынастың немесе жұмыс келісімдерінің үзілуіне әкелуі мүмкін.\nӘбігер, асығыстық пен шыдамсыздық қатты кедергі келтіреді: оқиғаны асықтырсаңыз, істе одан да үлкен кешігу немесе үзіліс аласыз.\nШектен тыс эмоционалдылық, тіке сөйлеу мен өткірлік тек жағдайды нашарлатып, дау тудырады.\nАй араласуда шиеленісті болуы мүмкін, әсіресе өкпе мен айтылмаған нәрсе қалса.", "Несеп-жыныс және ұрпақ өрбіту жүйелеріне көңіл бөлу керек. Жақын өмірде сақтық шараларын сақтап, суықтап қалмаңыз. Ісінуден аулақ болып, лимфа жүйесіне көңіл бөліңіз. Гинекологиялық және урологиялық мәселелер өршуі мүмкін — алдын алуға қамқорлық жасаңыз."], "3": ["Ақша шығыны мен күштің құлдырауын болдырмау үшін зейінді жоғалтпай, шамаңызды біліп, ұстамды болыңыз.\nОйланбай әрекет ету тәуекелі бар, сондықтан шешімге салмақпен қарап, бәрін ойластырыңыз.\nОйланбаған салымнан, несие мен қарыздан аулақ болыңыз — бұл уақытта қарыз міндеттемелерінің тәуекелі артады.\nБюджетті қадағалап, ақшаны сауатты бөліңіз.\nҚорқыныш пен шешімсіздік шешім қабылдауға кедергі келтіріп, қаржылық және мансаптық мүмкіндіктерді жабуы мүмкін.\nЖауапкершілік алудан қорқып, мүмкіндікті — мысалы, жаңа лауазымды — жіберіп алу тәуекелі бар.\nӨзін-өзі бағалаудың төмендігінен және қоғамда жүзеге асқысы келмегендіктен «өзін лайықсыз сезіну синдромы» мен өмірді «кейінге» қалдыру әдеті өршуі мүмкін.\nӘртүрлі тәуелділіктер, оның ішінде тамаққа тәуелділік өзекті болуы мүмкін — өзін бақылау керек.\nКүн тәртібінің бұзылуы және жұмысқа шектен тыс берілу ресурстарды сарқып, асқазан-ішек жолының бұзылуына әкелуі мүмкін.", "Ас қорыту жүйесіне көңіл бөлу керек: тамақты қорыту және сіңірумен байланысты сырқаттар болуы мүмкін. Асқазан-ішек жолына қатысты бәрінің алдын алуға уақыт бөлген маңызды. Зат алмасу мен тамақтану әдеттерінің бұзылу тәуекелі бар. Тері мәселелері мен аллергиялық реакциялар өршуі мүмкін."], "4": ["Мұң мен эмоциялық тұрақсыздыққа тексерулер болуы мүмкін, сондықтан алғыс айту дағдысын шыңдап, бұл айда және өмірде жақсыға сүйенген маңызды.\nЖақындармен дау мен түсінісу болуы мүмкін — қарым-қатынас беріктікке тексеріледі.\nЖүректегіні айту жиі қиын болады, өкпе басады, айналадағылар салқындық пен немқұрайдылықты меңзейді. Жүректі ең алдымен өзіңізге ашуды үйрену маңызды — алдымен сезімді, мысалы, қағазға шығарып, содан кейін жұмсақ сөйлесу.\nІштей бостық, «жүректегі тесік», жалғыздық, махаббат пен қолдаудың жетіспеуі сезімі пайда болуы мүмкін. Мұның бәрі өзін-өзі бағалаудың төмендігімен, «ішкі баланың» қиындықтарымен және құрбан рөлінде қалып қоюмен байланысты.\nКөңіл қалу, ауыр ажырасу және жүрек ауыртатын жағдайлар болуы мүмкін. Серіктеске, оның сезімі мен эмоциясына тәуелділік сезілуі мүмкін.", "Жүрек-қантамыр жүйесіне көңіл бөлу керек: қан қысымының ауытқуы, үрей ұстамалары, ырғақтың бұзылуы болуы мүмкін. Стресс пен толқудан аулақ болыңыз. Бронх-өкпе жүйесінің алдын алу маңызды. Қол мен кеуде қуысын сақтаңыз — жарақат немесе қабыну тәуекелі бар."], "5": ["Шектен тыс нәрсеге — тамаққа, ішімдікке, темекіге құмарлық пайда болуы мүмкін, сондықтан абай болыңыз.\nАйналадағылармен қарым-қатынас қызуы мүмкін, қатты дауласып, дұрыстығын айқаймен дәлелдеуге бейімділік пайда болады — сіз тараптан да, сізге қатысты да. Ұрыс жоқ жерден шығуы мүмкін, ұстамды болып, ымыра табу оңай болмайды. Бірақ айқайдан, жанжалдан және балағаттан аулақ болыңыз — олар тек жағдайды нашарлатады. Ал айтылмаған өкпе байқаусыз денеде қысылу мен психосоматика болып көрінеді.\nАй сіздің адамгершілік және этикалық ұстанымдарыңызды тексеруі мүмкін, сондықтан заңмен, қоғамдық нормалармен және ережелермен қиындықтар болуы мүмкін.\nКөпшілік алдында сөйлеуден қорқу және «өзін лайықсыз сезіну синдромы» пайда болуы мүмкін, сондықтан өзін білдіру және қоғамда белсенді болу қиын болады.", "Тамаққа, мұрын-жұтқыншаққа және жоғарғы тыныс жолдарына көңіл бөліңіз — бұл аймақтарда созылмалы мәселелер болса, алдын алуға қамқорлық жасаңыз. Тіс пен қалқанша безді қадағалаңыз. Дауыс байламдарын сақтаңыз — олар әлсіреуі мүмкін."], "6": ["Сіз бастағы шектейтін сенімдер мен ұстанымдарға тап болуыңыз мүмкін. Олар сізді тоқтатып, маңызды шешім қабылдауға мүмкіндік бермей, қатты кедергі келтіруі мүмкін. Көзқарастың қатып қалуы мен шектен тыс сенімділік алға жібермеуі мүмкін.\nСіз қорқыныш пен мазасыздықты шындыққа жатпайтын көлемге дейін үрлеп, өзіңізді шексіз қайрай беруіңіз мүмкін.\nҚиындықтар елес туғызуы мүмкін — «қызғылт көзілдірікті» шешу өте қиын болады.\nИдеялар өлі жүк болып жатуы мүмкін: шешімділік пен стратегия жетпегендіктен ақылды қолдану қиын.\nБасқалар үшін тым көп істеуге, олар үшін жауапкершілік алуға және ақыл үйретуге бейімділік пайда болуы мүмкін. Сіз мұны әдейі істемесеңіз де, сізді жабысқақ және өзгенің ісіне араласатын адам деп санауы мүмкін.", "Бас аймағына көңіл бөліңіз. Көзді қадағалап, көруді шамадан тыс жүктемеңіз. Мигрень мен бас айналу тәуекелі жоғары — жүйке жүйесі мен мидың күйін қадағалаңыз. Мұрын, құлақ және тіс үшін алдын алу керек болуы мүмкін."], "7": ["Көбіне өзінің ерекшелігі, айналадағылардан артықшылығы сезімі, тәкаппарлық пайда болады — бірақ сонымен бірге іште өзін-өзі сынау мен өзіне көңілі толмау күшті.\nЖағымсыз ойға және көңілсіз күйге түсіп кетпеу маңызды: өзіңізбен ортақ тіл табу қиын болып, айналадағылар сізді түсінбейтін сияқты көрінеді.\nТұйықтық пен өзіне үңілу ұзаққа созылған жалғыздыққа және өзін «ақ қарға» сезінуге әкелуі мүмкін.\nӨзіне және жоғары күштерге сенімді жоғалтудан апатия мен өмір мәнін жоғалту басуы мүмкін, бірақ дәл осы өз шынайы ұмтылыстарын тануға серпін болады.\nҰйқысыздық, психологиялық қиындықтар, кешендер мен мазасыздықтың өршуі болуы мүмкін.", "Ұйқысыздық, психологиялық қиындықтар, қорқыныш пен мазасыздықтың өршуі болуы мүмкін. Көңілсіздік пен үрей ұстамаларының тәуекелі бар, сондықтан жаман көңіл-күй мен апатиялы ойларды елемеңіз — психологиялық тәсілдерді пайдаланып, психологқа жүгініңіз. Психика мен жүйке жүйесінің күйі ерекше назарды қажет етуі мүмкін."], "8": ["Көңілсіз және апатиялы көңіл-күй, өмір сүрудің мәнсіздігі мен бекерлігі сезімі келуі мүмкін. Адам бұл күйзелістерді өзі бірнеше есе күшейтіп, үрлейтінін түсіну маңызды.\nАй әртүрлі жоғалтулар — адамдарды да, ақшаны да — байланыстардың үзілуін және кейде өте ауыр, күрт өзгерістерді әкелуі мүмкін. Адам құрбан рөліне кетуі немесе қатал цинигтің бетпердесін киюі мүмкін.\nМазасыздық пен әрекет етуден қорқу, өзіне сенімсіздік пен өзін-өзі бағалаудың төмендеуі күшеюі мүмкін. Шеткі жағдайларда өмірдің мәнсіздігі туралы ойлар және өзін құртатын мінез-құлық — тәуелділіктен бастап өте ауыр көңіл-күйге дейін болуы мүмкін.\nБұл айға ақталмаған тәуекел және өз қауіпсіздігіне немқұрайды қарау тән.", "Психологиялық күй ерекше назарды қажет етуі мүмкін — эмоциялық сарқылу мен шаршап-шалдығу (выгорание) тәуекелі бар. Қауіпсіздік шараларын сақтап, өзіңізді аялаңыз: жол оқиғасы мен жарақат, сырттан қысым мен агрессия болуы мүмкін. Шамадан тыс жүктемеден аулақ болып, демалыс пен босаңсуға көңіл бөліңіз."], "9": ["Өзіңізден көңіл қалып, бұрынғы барлық байланыстар мен істерге қызығушылық жоғалуы мүмкін.\nСізге өзгерістер мен болашақтан қорқу әсер етіп, мазасыздықты күшейтуі мүмкін.\nАй агрессия мен күш қолдануға, оның ішінде өзіне қатысты да итермелеуі мүмкін. Сондықтан энергияны дұрыс басқарып, оны жасампаз арнаға бағыттауды үйрену маңызды.\nДүниетаным мен басымдықтарды өзгертетін дағдарыс жағдайлары болуы мүмкін.\nСондықтан өзімен үнемі және жан-жақты жұмыс, әртүрлі салада — дене, интеллект, шығармашылық және эмоция салаларында ең жақсы қасиеттерді дамыту керек.\nАй ерекше назарды талап етеді: тоғыздық өз күшімен адамның өз әрекеттері қайда бағытталғанына қарай теріс жаққа да, ай кодының екінші санының ең жақсы қасиеттерін дамытуға да жұмыс істеуі мүмкін.", "Жарақат пен жол оқиғасының ықтималдығы артады — қауіпсіздік техникасын сақтап, жолда мұқият болыңыз. Күтпеген сырқат пен стресс болуы мүмкін, созылмалы аурулар алдын алуды талап етеді. Диагноз қоюдағы қиындық немесе қате диагноз тәуекелі бар."]}, "day_up": {"0": ["сәттілік, мүмкіндіктер, мәселені тез шешу, таңдау еркіндігі.", "жалығу, апатия, энергияның жетіспеуі, енжарлық, күтпеген жағымсыз жағдайлар, ішкі бостық, белгісіздік.", "өмірге саналы қарау, назарды ең асыл армандарды орындауға бағыттау, не істеу керектігін анық түсіну, қалаған бағытта жаңа дағдыларды меңгеру."], "1": ["спорт, денеге назар, белсенділік, дене күші, төзімділік, жұмыс немесе тұрғылықты жерді ауыстыру, дербестік, өз өмірі үшін жауапкершілік, әлемге сену, ұқыптылық, кедергілерді жеңу, саяхат пен сапарлар, жеңістер.", "менмендік, ойланбай жасалған әрекеттер, төбелес, агрессия, ашу, соғылу, жол оқиғалары, өз денесін қабылдамау, тірек-қимыл жүйесінің мәселелері, фобиялар, қорқыныш, әлсіреген иммунитет, енжарлық, жалқаулық, сылбырлық, жарақаттар.", "агрессия мен төзбеушілікпен жұмыс істеу, үлкендерді және өз руын құрметтеу, ру практикаларын орындау, спортпен айналысу, жерде жалаңаяқ жүру, жалқауланбау, көбірек әрекет ету, өзіне сенімділікпен, қорқыныш пен фобиялармен жұмыс істеу, шешімді әрекет ету."], "2": ["берік қарым-қатынас, сезімталдықтың ашылуы, босаңсу, энергиялылық, өзара әрекет, серіктестік, тартымдылық, өмірден ләззат алу.", "әйелдік сырқаттар (әйелдерде), қарым-қатынаста, балалармен, отбасында және серіктестермен қиындықтар, энергияның жетіспеуі, шиеленіс, қысылу, кінә сезімі, ұят, қызғаныш, салқындық немесе бетімен кету.", "отбасымен араласу, демалып, босаңсу, балалармен, оның ішінде өз балаларыңызбен (болса) уақыт өткізу, кінә сезімімен жұмыс істеу, хош иіс терапиясын, шам, массажды пайдалану."], "3": ["тұлғалық және қаржылық өсу, шешімділік, энергиялылық, мықты ерік күші, көшбасшылық қасиеттер, бизнес, іскерлік кездесулер.", "ақшаның жетіспеуі, айла-шарғы (манипуляция), күшті өзімшілдік, тәуелділіктер, энергияның құлдырауы, жалқаулық, мінезсіздік, асқазан-ішек жолының мәселелері.", "тамақтануды қадағалау, аскезаны сақтау, қаржылық сауаттылықты меңгеру, ерте тұру, көшбасшылық қасиеттер мен жауапкершілікті дамыту."], "4": ["үйлесім, махаббат, қуаныш, ашықтық, мейірім, емшілік қабілеттер, айналадағылармен жақсы қарым-қатынас, сенім, эмпатия.", "жабық жүрек, тұйықтық, көңіл қалу, өкпешілдік, эмоциялық құбылмалылық, сенімсіздік, кеуде қуысы мүшелерінің мәселелері.", "сеніммен жұмыс істеу, жүректі ашу практикаларын орындау, қайырымдылықпен айналысу, алғыс айтуды жаттықтыру."], "5": ["қоғамда жүзеге асу, араласу, өзін білдіру, шешендік өнер, көпшілік алдында сөйлеу, шетел тілдерін үйрену, мәселені сөйлесу арқылы шешу.", "заңға қатысты қиындықтар, өзін көрсеткісі келмеу, жанжал, дауға бейімділік, сын, өсек, тамақ мәселелері, өтірік.", "өсек айтпау, ән айту, қоғамда өзін көрсету, көпшілік алдында сөйлеу, араласу, өзін білдіру."], "6": ["бай қиял, идеялар, түйсік, даналық, ақыл әлеуетінің ашылуы, өзін және айналадағыларды анық түсіну.", "жағымсыз ойлардың көптігі, нашар есте сақтау, бас ауруы, ұйқысыздық, тәкаппарлық, өз қиялыңнан жайсыздық.", "түйсік пен позитивті ойлауды дамыту, ой-өрісті кеңейту, кітап оқу, өлең жаттап, есте сақтауды жаттықтыру, интеллектуалдық ойындар ойнау."], "7": ["руханилық, жоғары күштермен байланыс, дамыған түйсік, мықты психика.", "жүйкенің тозуы мен көңілсіздік, шындықтан қашу, оның ішінде ішімдік пен басқа тәуелділіктер арқылы, күмәнді топтар мен секталар, жүйке жүйесінің әлсіреуі, Құдайға сенбеу.", "рухани даму, йога, медитация және дұға жаттықтыру, дінді зерттеу, ішімдік пен адамгершілікке жат өмір салтын алып тастау, күш орындарына бару."], "8": ["өзін-өзі дамыту, өмір мәнін іздеу, өмір салты мен құндылықтарды қайта ой елегінен өткізу.", "өзін құрту, әдеттегі көзқарастардың құлауы, өмірдің мәнсіздігі сезімі, жағымсыз оқиғалар, кері кету.", "қайырымдылықпен айналысу, психологияны зерттеу, өмір мәнін жоғалтқандарға көмектесу, өзіңізде жауапкершілікті тәрбиелеп, алдаудан аулақ болу."], "9": ["энергия мен ресурстың көптігі, әлеуеттің ашылуы, мақсат-мұратқа еру, таланттарды көрсету.", "кедергілер, тағдырлы кармалық оқиғалар, күтпеген өзгерістер.", "махаббат пен қызмет көрсету, таланттарды ашу, ойластырылған шешім қабылдау, саналылықты дамыту."]}, "year_res": {"0": "нөлдену, түбегейлі өзгерістер, сәттілік пен жолдың болуы.", "1": "тұрақтылық пен сенімділікке жету, әрі қарайғы даму үшін берік негіз, даудан сәтті шығу, саяхат пен сапарлар, жақсы өмір үшін көшу, ру байланыстарын нығайту, жаңа идеяларды жүзеге асыру, шешімділік пен батылдық, қорқыныш пен шектейтін ұстанымдарды жеңу мүмкіндігі, жақсы денсаулық және мықты иммунитет, дене белсенділігі мен энергиялылық, тәуелсіздік және даралықты көрсету.", "2": "қарым-қатынасты үйлестіру, серіктеспен кездесу, некеге тұру, бала көтеру және бала туу, сезімталдықтың ашылуы, отбасындағы қолдау мен қамқорлық, өзін және өз денесін қабылдау, қоғамда көріну, балаларды үйлесімді тәрбиелеу, жарқын жақын өмір және сезімталдықтың өсуі, сау өзін-өзі бағалау, өкпемен жұмыс, шығармашылық қабілеттерді дамыту, өзін білдіруге деген ниеттің өсуі, жемісті араласу, шығармашылық идеяларды жүзеге асыру, әлеуметтік жобаларды жүзеге асыру.", "3": "мансаптық өсу, пайда үшін іс ауыстыру, өршілдікті жүзеге асыру, қаржылық табыс, ақшаны көбейту, мақсаттарға жету, салауатты өмір салты, ой және қаржы тәуелсіздігі, харизма мен көшбасшылық қасиеттерді дамыту, әлеуметтік белсенділік, басқару дағдыларын дамыту, өз ісін немесе бизнесін дамыту, саналы тамақтануды таңдау.", "4": "үйлесімді қарым-қатынас, ғашықтық пен махаббат, жұп пен отбасын құру, эмоциялық тепе-теңдік, алғыс айта білу, айналадағылардың адалдығы мен әділдігі, өзін жақсы көруді дамыту, жаңа достар, шығармашылық идеяларды жүзеге асыру, көмектесетін мамандықта жүзеге асу, ресурстың молдығы мен жанашырлықтан көмектесуге деген ниет, жүректің ашылуы және эмпатияның дамуы, хендмейд пен қол жұмысындағы табыс, бақыт сезімі, өзін және әлемді қабылдау, қайырымдылық.", "5": "таланттар мен қабілеттерді көрсету және жүзеге асыру, жемісті араласу, дипломатияны дамыту, дауыспен адамдарға әсер ету, шығармашылық даму, жазушылық, музыкалық және вокалдық қабілеттерді дамыту, әлеуметтік белсенділік пен жемісті өзара әрекет, өмірге құштарлық пен ашықтық, сөзді бақылау, ішкі еркіндік пен сенімділік, дау мен жанжалды шешу, түсінбеушілікті бейбіт реттеу, танымалдық.", "6": "интеллектуалдық жүзеге асу, жемісті оқу, тәлімгерлік пен оқытуда өзін көрсету мүмкіндігі, жазушылық қабілет пен креативтіліктің өсуі, түйсікті дамыту және ішкі дауыс пен тағдыр белгілеріне сену, жағдайды талдап, қорытынды жасай білу, ой-өріс пен ойлаудың кеңеюі, саналы өмір мен рухани дамудың маңызын түсіну, әлем заңдарын зерттеу және өмір мәнін табу, қорқынышпен жұмыс және сенімділікке жету, ақыл, талдау және себеп пен салдарды түсіну арқылы бірдеңе жасай білу.", "7": "өмір мәнін табу, өз мақсат-мұратын анық көру, зерттеу және таным жұмысы, экстрасенсорлық және эзотерикалық қабілеттердің ашылуы, жан тыныштығы мен эмоциялық тепе-теңдік, күшті түйсік, орнықты психика, психологиялық қиындықтарды шешу, жан жараларымен жұмыс, жаңалықтар мен көкірек көзінің ашылуы, сенімге жету және әлем заңдарын түсіну, ішкі өзек пен тірек қалыптастыру.", "8": "құндылықтарды қайта бағалау, көшбасшылық пен басқару дағдылары, рухани негіз қалыптастыру, өз өміріне және ортаға әсер ету, оң өзгерістер, ішкі еркіндік пен күшке жету, шешімдегі батылдық, қаржылық табыс, мақсаттарға жету және тілектердің орындалуы, өз бизнесін дамыту, тәуелділіктен немесе тәуелді жағдайдан шығу, әрі қарай өсу мен табыс үшін істі түбегейлі ауыстыру, жеңістер мен жетістіктер, қоғамда жүзеге асу.", "9": "әлеуметтік белсенділік пен маңыздылық, танымалдық пен атақ, құндылықтарды қайта бағалау, жақсыға қарай тағдырлы өзгерістер, сәттілік пен жолдың болуы, керекті кездесулер мен жағдайлар, мақсаттарға жету және тілектердің орындалуы."}, "year_risk": {"0": ["Жылдың мәселелері мен тәуекелдерін жыл кодының екінші саны бойынша қараңыз.", ""], "1": ["тұрақтылықтың, қауіпсіздік пен тіректің жетіспеуі, дербес болмау және шешімсіздік, өмір үшін қорқыныш және жақындарды жоғалтудан қорқу, өзгерістер мен батыл қадамдардан қорқу, аман қалуға шоғырлану, ертеңгі күн туралы мазасыздық пен алаңдаушылық, енжарлық, құрбан рөлі, өзгергісі және ескіні босатқысы келмеу, өзіне сенбеу, өмірге сенбеу және одан көңіл қалу, денеге немқұрайды қарау және соның салдарынан жарақаттар мен әлсіреген иммунитет, дауға бейімділік, жалқаулық және істі кейінге қалдыру.", "сүйек жүйесі, оның ішінде омыртқа, бұлшықеттер, тіс (қабыну және тістің түсуі), шаш (түсуі және құрылымының нашарлауы), қан, иммунитет, ішек, жарақаттар мен жол оқиғалары, аяқ, салмақтың қосылуы немесе азаюы, жаңа өскіндер."], "2": ["серіктеспен дау мен ұрыс, отбасындағы түсінбеушілік, өзін-өзі бағалаудың төмендеуі және өзін-өзі сынау, анаға өкпе және оған тәуелділік, бірге тәуелді қарым-қатынас, кінә сезімі, басылған эмоциялар, басылған сезімталдық пен қысылу, жалғыздық және жеке өмірдің болмауы, өмірді ысырап ету және тәуелділіктер, сараңдық және үнемі үнемдеу, өзіне жұмсағысы және өзін қуантқысы келмеу, бала көтеру, оны сақтау және босанудағы қиындықтар, жалқаулық және энергияның құлдырауы.", "лимфа жүйесі, несеп-жыныс жүйесі, бүйрек, урологиялық және гинекологиялық мәселелер, ұрпақ өрбіту жүйесі."], "3": ["мансаптағы кедергілер, жұмыстан айырылу, ақша шығыны, несие мен қарыздар, әртүрлі тәуелділіктер, өзіне сенімсіздік, өзін толыққанды емес сезіну, қоғамда жүзеге асудағы қиындықтар, басқаның жетегінде жүру және құрбандыққа бейімділік, тамақтану әдеттерінің бұзылуы, толықтық немесе арықтық, өмірді «кейінге» қалдыру әдеті, жаңа тәжірибе мен жаңа міндеттерден қорқу, істі кейінге қалдыру, дау мен қысым, ақшамен қоштасқысы келмеу және шектен тыс үнемдеу, ақшаны қалай табуға болатынын түсінбеу.", "ас қорыту жүйесі, асқазан-ішек жолы, зат алмасу, қант деңгейінің жоғарылауы (диабет), тамақтану тәртібі мен сипатының бұзылуы, дәрумендердің жетіспеуі, тері мәселелері."], "4": ["жақындармен дау, серіктестерге тәуелділік, қарым-қатынаста құрбандыққа бейімділік, эмоционалдылық пен жылауықтық, долылық пен эмоциялық тұрақсыздық, ажырасу мен опасыздық, айтылмаған өкпенің жүгі, кінәлау мен айыптау, эмоциялық салқындық — сіздің немесе серіктестің, жүрек күйзелістері мен кешендер, жауапсыз махаббат, махаббат үшбұрыштары, қысым мен кемсіту бар қарым-қатынас, жақындардың алғыссыздығы, екіжүзділік пен шындықтың жоқтығы — сіздің немесе жақындардың, жалғыздық, махаббатқа лайық емеспін деген сезім, жабысқақтық, тұйықтық пен салқындық.", "жүрек-қантамыр жүйесі, жүрек, өкпе, бронхтар, қан айналымы, үрей ұстамалары (панические атаки), омыртқаның кеуде бөлігі, кеуде қуысы, сүт бездері және қолтықасты аймағы, айырша без (тимус)."], "5": ["айналадағылармен дау, айтыс пен түсінісу, өкпені іште сақтау және айтылмай қалғандар, қоғамдағы қиындықтар мен тұйықтық, сөйлеу мәселелері, көпшілік алдында сөйлеуден қорқу, заңға қатысты қиындықтар, мансаптық өсуден қорқу, «өзін лайықсыз сезіну синдромы», шығармашылықта өзін көрсете алмау, ұнамайтын жұмыс, темекі және басқа тәуелділіктер, өзін көрсетуден және шындықтан қорқу, келісімге барғысы келмеу, өсек пен қудалау.", "тамақ, көмей, мұрын-жұтқыншақ, қалқанша және қалқанша маңы бездері, дауыс байламдары, өкпенің жоғарғы бөлігі, тіс, жақ, тіл, сөйлеу."], "6": ["тәкаппарлық пен менмендік, материалдыққа шектен тыс берілу, түйсікке сенбеу, руханилықты жоққа шығару, білімін қолдана алмау және интеллектуалдық жүзеге аса алмау, шектейтін ұстанымдар, жүзеге аспайтын армандар мен елестер, оқудағы қиындықтар және оқығысы келмеу, жаңа ақпаратты қабылдамау, есте сақтау мәселелері, әлемді тек логика арқылы қабылдау, қорқынышты үрлеп-ұлғайту, өткенде қалып қою, ақылдың шамадан тыс жүктелуі, бастағы ауыр сценарийлер.", "ми, көз, құлақ, мұрын, бет нерві, бет, бас сүйек, тіс, жақ, есте сақтау, психосоматика."], "7": ["әртүрлі салалардағы өмірлік дағдарыс, өзін түсінудегі қиындықтар, өмір мәнін жоғалту, мұң мен көңілсіздік, психикалық тұрақсыздық, әрекетсіздік пен жалқаулық, өзімен және айналадағылармен алауыздық, оңашалану, сенімсіздік — өзіне де, жоғары күштерге де, екіжүзділік пен алдау, түйсікке сенбеу, материалдыққа берілу, шындықтан алшақтау.", "көңілсіздік, үрей ұстамалары, орталық жүйке жүйесі, психика, психосоматика, шаш."], "8": ["жақындармен ажырасу, жұмыстан айырылу, өзгерістен және әрекеттен қорқу, өзін-өзі бағалаудың төмендеуі, мазасыздық, өзіне сенімсіздік, өмірдің мәнсіздігі туралы ауыр ойлар, ақша шығыны, өзін құрту, тәуелділіктер, өзіне зиян келтіру, ақталмаған тәуекел, мақсаттан бас тарту, апатия және құрбан позициясы, қатаңдық пен цинизм.", "психика, жарақаттар, жаңа өскіндер."], "9": ["дау-жанжалды жағдайлар, агрессия және күш қолдану, күтпеген кедергілер мен сәтсіздіктер, адамдардан көңіл қалу және сатқындық, өмір мәнін жоғалту, қорқыныш пен мазасыздық, күшпен қысым жасау, құрбан рөлі немесе озбырлық, ауыр өкпе мен кекшілдік, адамгершілік заңдарын сақтамау, шынайы мақсаттарды түсінбеу, оңашалану және тұйықтық, денсаулыққа кенеттен соққы, өзін жүзеге асыра алмау.", "жарақаттар, шок күйлері, күтпеген сырқаттар, психологиялық қиындықтар, диагноз қоюдағы қиындықтар."]}, "year_task": {"0": ["«Таза парақ» жылы", [["", "Нөл басқаратын жылды болжау қиын, ол «таза парақ» сияқты жұмыс істейді: өз шындығын жинаған тәжірибесіне, таланттары мен қабілеттеріне сүйене отырып, тек адамның өзі қалыптастырады. Бұл жыл керемет сәттілік және судан құрғақ шыға білуді әкелуі мүмкін, ал бетбұрыс оқиғалары мен дағдарыстар уақыты да болуы мүмкін. Нөл жылын жақсы жағынан өмір сүру үшін адамның санасында адамгершілік және рухани негіз қалыптасып, өмірлік міндеттер мен бағдарлар анықталған болуы керек. Сонда жыл сәттілікке толып, мақсаттар айқын пішінге ие болады, қалаған нәрсе тез келеді. Керек уақытта керек адамдар пайда болып, керек таныстықтар орнап, ресурстар табылып, әртүрлі салаларда жаңа деңгейге шығаратын оқиғалар болады."]], []], "1": ["", [["Шыдамдылық пен төзімділікті дамыту", "Жыл бойы тұрақты дене белсенділігі мен өзін-өзі тәртіпке салу керек. Спорт, күнделікті серуен, созылу және икемділікке арналған жаттығулар өте пайдалы. Жағымсыз эмоция болғанда ашу мен агрессияны жұмсақ өткеру үшін тыныштандыру және эмоцияны шығарудың психологиялық тәсілдерін қолдануға болады. Қатты ашуланған сәтте грушаны ұрып, жастыққа айқайлап, аяқты тарсылдатып немесе секіріп — яғни эмоция кептеліп қалмауы үшін денені қосқан жақсы. Нейрографика мен арт-терапия тамаша көмектеседі."], ["Асықпай, әбігерден аулақ болып, жерге байлану", "Бұл жылы өзгерістер кезінде тұрақтылықты сақтау үшін бар күшті салу маңызды. Тыныштандыру мен үйлестірудің психологиялық тәсілдері, тыныс алу практикалары, саналы ойлау мен ақыл икемділігін дамыту көмектеседі. Баяулауға табиғат пен медитация көмектеседі. Табиғат стихияларымен байланыс, бағбандық, жерде және жермен жұмыс, дене практикалары мен массаж өте пайдалы."], ["Өзіне және оқиғалардың жақсы аяқталатынына сенімді болу", "Шешім қабылдай білу және мақсатқа барар жолдағы батылдық көмектеседі. Көшбасшылық, бастама және идеялар әрі қарай даму үшін базалық қажеттіліктерді қамтамасыз етуге, өзін жүзеге асыруға ықпал етеді. Себеп пен салдарды түсіну, өмірге құштарлық пен оптимизм өмір ағысына сенуге көмектеседі."], ["Денеден белсенді және энергияға толы болу", "Дене белсенділігі, саяхат пен сапарлар көмектеседі. Жаңа әсерге ұмтылу, басқа мәдениеттер мен өмір салтымен танысу араласудағы икемділік пен жеңіл қозғалуды дамытады. Өзіңізге жаңа мақсаттар қойып, белсенді өмірге ынта тауып, бір орында тұрып қалмау және жалқаулықта қалып қоймау маңызды."], ["Өз руын құрметтеу және өзін ру жүйесінің бөлігі ретінде сезіну", "Бұл жылы туыстарды біріктіріп, ру байланыстарын нығайту және өз тамырын түсіну маңызды. Ру кітабы мен шежіре ағашы, туыстармен араласу, ата-баба мекені мен бала кезгі жерлерге барып кездесу, туыстарға көмектесу көмектеседі."]], ["Мен өзімді қауіпсіз сезінемін бе?", "Мені қандай қорқыныштар мазалайды?", "Мен шын мәнінде не қалаймын?", "Мен берік қаржылық тіректі сезінемін бе?", "Мен өмірімді қалай өткізгім келеді?", "Мен неге жеткім келеді?", "Мен үшін шын мәнінде не маңызды?", "Бұл жылы өмірімде неге көбірек орын бергім келеді?", "Бұл жылға менің өзгеріс жоспарым қандай?"]], "2": ["", [["Серіктеспен және жақындармен қарым-қатынасты үйлестіру", "Ең алдымен өзімен жұмыс істеп, сұрақ қою: мен қарым-қатынастан не қалаймын, бұл серіктес маған не үшін керек, бұл қарым-қатынас маған нені үйретеді. Өкпемен жұмыс істеп, өз шекарасын құрып, өзгенікін құрметтеу. Өзіне-өзі жеткілікті және тәуелсіз болуды дамыту, бірақ сонымен бірге жақындарға көмектесіп, оларға қамқорлық жасау. Серіктес әзірге болмаса — қарым-қатынасты бастауға да, отбасын құруға да нақ уақыт. Бастысы — отбасылық құндылықтар мен жұптағы қажеттіліктерді анықтау."], ["Балалармен және анамен қарым-қатынасты реттеу", "Балалар болса, бұл жыл ортақ қызығушылықтар мен бірге өткізетін уақыт іздеуге жақсы, үйлесімді араласу құру үшін психологқа жүгінуге болады. Балалар болмаса, жыл жүктілікті жоспарлауға да, сәтті бала көтеру мен босануға да қолайлы — алдын ала міндетті түрде мұқият тексеруден өтіп, талдау тапсырып, дәрумен ішіңіз. Бұл жылы анамен қарым-қатынас шиеленісуі мүмкін, сондықтан мүмкіндігінше онымен араласуды реттеп, жақсартып, ішкі бөлінуді аяқтап, өкпемен жұмыс істеу маңызды."], ["Өзін және денесін еркелету", "Тәуелділікке — қоздырғыштарға да, адамдарға да — түспей, ләззат алу және босаңсу білу көмектеседі. Бұл жылы дене сигналдары мен өз тілектеріңізге құлақ асқан өте пайдалы. Дене практикалары, массаж, сумен байланыс, жүзу, монша, спа-процедуралар көмектеседі."], ["Жақын өмірді реттеу", "Өзін-өзі бағалаумен жұмыс, өзіне және өз денесіне деген махаббатты дамыту, өзіне қамқорлық, жақындықты өз күйінде қабылдау, ұят сезімімен және интимдік салаға қатысты ата-ана ұстанымдарымен жұмыс көмектеседі. Өз сезімталдығын зерттеу, би, дене белсенділігі, пластика және созылу өзекті."], ["Өзін шығармашылықпен білдіріп, қоғамда көріну", "Шығармашылық дағдыларды дамытатын істер және өзін білдіру еркіндігі көмектеседі. Шабыттандыратын жобаларға айналатын ішкі серпінді сезіну маңызды. Бұл жыл әлемнің шығармашылық сұлулығына жанасу процесінің өзінен қуаныш сезінуге тамаша келеді."]], ["Мен өз тартымдылығымды сезінемін бе?", "Адамдармен сау әрі жылы қарым-қатынас құру үшін не істеймін?", "Айналысатын ісімнен ләззат аламын ба?", "Мен өз сезімталдығымды қабылдаймын ба?", "Менде не қызғаныш немесе күншілдік тудырады?", "Серіктеспен үйлесімді қарым-қатынас құруға қандай өкпе кедергі келтіреді?"]], "3": ["", [["Жауапкершілікті дамыту", "Мақсат қою және жоспарлау практикалары көмектеседі: жылға, айға және т.б. мақсаттарды жазып, соларды ұстану. Бұл жылы ішкі кемелдікті дамыту өзекті — қолға үйреткендері үшін жауап беру, уәдені орындап, сөзде тұру."], ["Өршілдік пен әлеуметтік белсенділік таныту", "Бұл жылы алдыңғы орынға жоспарлау мен мансаптық өсу шығады, бастама керек болады. Басшылық пен басқару дағдыларын меңгеріп, коучинг пен шешендік өнерден білім алған пайдалы. Мансаптық өсуге қоғамдағы жетістіктер, көшбасшылық қасиеттер, пікір мен мінез-құлықтың тәуелсіздігі көмектеседі."], ["Қаржыны сауатты басқару", "Ақша табу және көбейту қажеттілігі пайда болады, жыл бұған ықпал етіп, өсуге мүмкіндік береді. Сондықтан қаржылық сауаттылықты дамытып, ақша ағындарымен дұрыс жұмыс істеп, қаражатты сауатты жоспарлап, бөле отырып, қарыз бен несиесіз жинауды және көбейтуді үйрену маңызды."], ["Саналы тұтынуды жаттықтыру", "Бұл жылы тәуелділікке, бақылаусыз тамақтануға және тамақтану әдеттерінің бұзылуына итермелейтін жағдайлар, асқазан-ішек жолы жұмысында ақаулар болуы мүмкін, сондықтан тамақтануға көңіл бөлген жөн. Саналы тұтыну — бұл тек дұрыс тамақ, күн тәртібі және «тамақ қоқысынан» бас тарту ғана емес, саналы шығын да: шкафты киім мен косметикаға толтырмау, не және не үшін сатып алатыныңызды түсіну, табиғатқа ұқыпты қарау — су мен жарықты үнемдеу, қоқысты сұрыптау. Бұған сөздің саналылығы да жатады: не және не үшін айтатынымыз, сөздің тазалығы мен әдептілік. Ашу мен ызаны өзіне және адамдарға бағыттамай, оны жеңе білу өте пайдалы."], ["Төзімділік пен ерік күшін дамыту", "Әртүрлі аскеза мен шектеулер, тоқырауы мен әдеттік қозғалыссыз дене және ой белсенділігі, күту режимінен шығу көмектеседі. Спорт, ынталандыратын жаттығулар мен жарыстар сенімділік пен табандылыққа жетуге көмектеседі."]], ["Ақша мен материалдық ресурстарды қаншалықты ақылмен және дұрыс бөлемін?", "Мен ақшамен жұмыс істей аламын ба?", "Мен «алу — беру» тепе-теңдігін сақтаймын ба?", "Мен өз жұмысым мен қызметімнің нақты бағасын айта аламын ба?", "Табысым мені қанағаттандыра ма?", "Менде байлық пен табысқа тыйым салатын ұстанымдар бар ма?", "Барлық қажетті шығынды өтеп, болашаққа жинау үшін маған (отбасыма) айына немесе жылына қанша сома керек?"]], "4": ["", [["Өзін жақсы көруді және қабылдауды үйрену", "Бұл жылы өзін және айналадағыларды жақсы көруді және қабылдауды үйрену мүмкіндігі пайда болып, бұл тақырып басты болады. «Ішкі баламен» жұмыс істеу практикалары және туғаннан бар өз құндылығыңды сезіну өте пайдалы, ата-анамен қарым-қатынаспен жұмыс маңызды. Сізді қолдайтын, шабыттандыратын және позитивті ойлайтын жайлы араласу ортасын қалыптастырыңыз. Сізді сынауға, жетістігіңізді кемсітуге жол беретін және пікіріңізді бағаламайтындармен қоштасатын нақ уақыт. Улы адамдардан аулақ болып, қысым мен кемсітуге жол бермеңіз."], ["Эмоциялық тепе-теңдік табу", "Қуаныш әкелетін нәрсеге шоғырланып, айналадағы жақсыны байқаңыз — бұл жылы эмоциялық қолдауға, жан қанағаты мен бақытқа деген ниет ерекше күшті. Алғыс айтуды жаттықтырып, оны әдетке айналдырыңыз (алғыс күнделігі, алғыс хаттары). Өкпе мен жағымсыз эмоциялармен жұмыс істеу тәсілдерін (арт-терапия, нейрографика және т.б.) жаттықтырыңыз, жазыңыз, эмоция күнделігін жүргізіңіз. Эмоциялық интеллектті және өзімен, адамдармен қарым-қатынастың психологиялық негіздерін зерттеңіз. Өкпе — сіздің таңдауыңыз және жауапкершілігіңіз екенін қабылдап, өкініп, кешірім сұрап, өзіңіз де өкпе сақтамау маңызды."], ["Басқаларға көмектесу және қамқорлық жасау", "Бұл жылы көмектесетін мамандықты меңгергіңіз, хендмейдпен айналысқыңыз, басқаларға көмектесіп, қолдағыңыз келуі мүмкін. Қайырымдылық пен волонтёрлық көмектеседі, үй жануарын асырап, оған қамқорлық жасаған пайдалы. Тамаша идея — аспаздық курсынан өтіп, өзіңізге және жақындарға сүйіспеншілікпен тамақ әзірлеу әдетін қалыптастыру, мысалы, демалыста. Өз қолыңызбен бірдеңе жасап көруге болады (хендмейд, мүсін, тоқу, сурет салу). «Алу — беру» тепе-теңдігін ұмытпаңыз: көмектің бір бөлігін біз тегін, ресурстан көрсетеміз, бірақ бұл жақындарға күшпен жақсылық жасап, өзін шаршатып, құрбандыққа «құлау» керек дегенді білдірмейді. Медитация мен дене практикалары арқылы махаббат энергиясына толыңыз, өзіңізге қуаныш жасаңыз — мысалы, сізге ресурс беретін жағдайлар мен істердің тізімін жасап, керек кезде соған жүгініңіз."], ["Рухани дамып, адамгершілік заңдарын ұстану", "Бұл жылы әлем заңдары мен рухани әлемді зерттеу маңызды — бұл мұң мен өкпені жеңуге тірек пен күш береді. Адам таратқан бүкіл энергия оған бумерангпен қайтатынын түсіну керек: не таратса, соны алады. Сондықтан өзіне және айналадағыларға адал болып, бетперде мен екіжүзділіктен аулақ болып, өзінің шынайы болмысын көрсету маңызды. Өз эмоциясы мен эгосына тұйықталмай, тек өзі үшін өмір сүрмеуді үйреніңіз — сонда өкпе мен ашуға орын жоқ бүкіл әлеммен бірлік сезімі келеді. Қиындықтарды өмір тәжірибесінің керекті бөлігі ретінде қабылдаңыз. Сонда бұл жыл сізді өмір сүруге, жасауға және өткен әр күн үшін алғыс айтуға деген ниетке толтырады."]], ["Мен алғанымдай беремін бе?", "Мен бергенімдей аламын ба?", "Бір жұмысты істесем — бұл тек менің еңбегім бе? Әлде мұнда айналадағылардың және Құдайдың (Жаратушының, Ғаламның, жоғары күштердің) еңбегі бар ма?", "Мен өзім туралы қандай пікірдемін? Мен өзімді жақсы көремін бе?", "Мені жақсы көру үшін адамдарға бірдеңе дәлелдеуім керек пе?"]], "5": ["", [["Адамдармен жемісті араласуды үйрену", "Бұл жылы араласуға, қоғаммен өзара әрекетке және сөз бен дауыс арқылы өзін көрсетуге қажеттілік пайда болады. Дипломатияны пайдалана отырып, ой, сезім мен эмоцияны дұрыс білдіруді және кез келген адаммен ортақ тіл табуды үйренетін нақ уақыт. Айқай мен дауысыз сындарлы сөйлесіп, ымыраға оңай барып, келісу маңызды, бірақ сонымен бірге өз көзқарасыңызды айтудан және дауыс харизмасымен адамдарға әсер етуден қорықпаңыз. Басқаларды сөзбен баспай, тыңдап, ести білу маңызды. Бұл уақыт араласу дағдыларының жемісін көруге жақсы: келісім жасау, дауды шешу, жоба алу, мәселе шешу."], ["Өзін білдірудің жолдарын табу", "Бұл жыл іште болып жатқанды және өмір сүріп жатқанды білдіруге мүмкіндік береді. Жағымсыз эмоциялардан әңгіме, күнделік немесе әртүрлі тәсілдер (мысалы, нейрографика мен арт-терапия) арқылы арылу әдеті көмектеседі. Бұл энергияның үйлесімді ағуына мүмкіндік беру маңызды — ән айту, диктофонға жазу, жастыққа немесе далаға айқайлау арқылы. Кез келген жағдайда тамақтағы қысылуды жою керек. Шешендік және актёрлық шеберлік курстары мен көпшілік алдында сөйлеу дағдылары пайдалы."], ["Шығармашылықта жүзеге асу", "Бұл жыл өзгенің пікірі үшін емес, өз қалауыңызбен дамуға және шығармашылықта жүзеге асуға қолайлы. Өзіңізге бала немесе жас кезіңізде армандаған нәрсені — ән айтуды, өлең, әңгіме жазуды және т.б. істеуге рұқсат беріңіз. Қабілеттер мен таланттарды көрсете отырып, сіз өз ерекшелігіңіз бен сенімділігіңізді көрсетіп, өзін-өзі бағалауды теңестіресіз. Әлемге өзіңіз туралы айта білуді және естілуді жаттықтырыңыз."], ["Араласуда адамгершілік заңдарын сақтау", "Бұл жылы келісуді және адал әрі әдепті сөйлеуді үйренбесе, дау және заңдар мен ережелерді сақтауда қиындықтар болуы мүмкін. Сондықтан адамдармен және жақындармен араласуда моральдық және этикалық нормаларды сақтаңыз: дауысты көтермеңіз, балағат сөзден аулақ болыңыз. Шындықты айтып, адал болыңыз, бірақ бұл шындықпен және сынмен жараламай, әңгімелесушіден жоғары тұрмаңыз — әдеппен және орынды сөйлеңіз. Бұл жылы мазақ, кекесін, кемсітетін сөздер мен қорлау мүлдем жарамайды."]], ["Менің өзімді жүзеге асыруым неде?", "Мен өз дағдыларымды, білгенімді және таланттарымды қоғамның пайдасына қолданамын ба?", "Мен өз мақсат-мұратыма ерем бе?", "Мен әлемге қандай құндылық бере аламын?", "Мен ойды дұрыс тұжырымдай аламын ба?", "Мен сезім мен эмоцияны ашық білдіре аламын ба?", "Көпшілік алдында сөйлегенде жайсыздық сезінемін бе?"]], "6": ["", [["Ойлауды кеңейтіп, түйсікті тыңдау", "Бұл жыл жаңа дүниетанымға және өмір бағытын өзгертуге жол ашады. Ол үшін қоғам немесе жақындар таңған қалыптар мен ұстанымдардан шығып, ауқымды ойлауды және стратегия құруды үйрену керек. Шешім қабылдағанда ішкі дауыс пен сезімге құлақ асу маңызды — ол үшін ақылды тыныштандырып, талдау мен логиканы тоқтатып, басқа демалыс беріп, денені сезіп, санасыздықты есту үшін уақыт, орын және тәсіл табыңыз."], ["Рухани саналылықты жаттықтыру", "Бұл жылы болып жатқанның себептері мен жоғары мән туралы ойланбаса, өмір сүрудің мәнсіздігі сезімі және өз мақсат-мұратын түсінбеу пайда болуы мүмкін. Сондықтан әлем заңдары мен адамзаттың рухани негізін зерттеу, өз ойын, сезімі мен эмоциясын талдай білу өзекті — бұл әртүрлі жағдайлардың неге және не үшін болатынын түсінуге көмектеседі. Осылай адам өз әрекеттері мен айналадағылардың әрекеттері жай ғана емес, тепе-теңдік пен бумеранг заңы бойынша және ойдың жүзеге асуының салдары ретінде болатынын түсінеді. Бұл әлем заңдарын түсініп, оларды бұзбай, саналы әрекет етіп, ойлана отырып, өмір құруға көмектеседі."], ["Ақыл мен талдау қабілетін дамыту", "Бұл жылы ауқымды ойлау, жаңа білім мен көкірек көзі және оларды басқаларға жеткізу керек болады. Жаңа білім алу, ми шабуылына қатысу, оқу және деңгейді үнемі көтеру пайдалы. Ақылды ашып, күшейтуге басқатырғыштар, сөзжұмбақтар, жұмбақтар мен квесттер көмектеседі."], ["Идея туғызып, оларды жүзеге асыру стратегиясын құру", "Бұл жылы өз ақылы мен интеллектісінің жемісін пайдалана алса, жаңа көкжиектер мен мүмкіндіктер ашылып, өмір сүру мәнін түсіну келеді. Сондықтан көп идея мен арман өлі жүк болып жатпауы үшін әрекет ету керек: идеяларды ұзақ жәшікке салмау және қиялға берілмеу. Ойлағанды жүзеге асырудың кезеңдерін жоспарлап, үлкен мақсатты шағын мақсаттарға бөліп, мерзім белгілеп, құрал таңдаңыз. Күн сайын бірдеңе істеп, практикалық қадам жасап, осылай қалағанды жүзеге асырыңыз."]], ["Мен өзіме шектеусіз армандауға рұқсат беремін бе?", "Мен өз шынайы тілектерімді білемін бе?", "Тілектерімді жүзеге асыруға не кедергі келтіреді?", "Қандай идеялар мен жобалар менің назарымды аударады?", "Жүзеге асырмасам, өмірімнің соңында неге өкінуім мүмкін?", "Достарыммен және пікірлестеріммен қарым-қатынасым қалай?", "Ортам менің дамуыма қаншалықты көмектеседі?"]], "7": ["", [["Рухани дамуға ұмтылу және әлем заңдарын қабылдау", "Бұл жылы алдыңғы орынға Сенімге жету, өз мақсат-мұратын және өмірдегі орнын түсіну мәселелері шығады. Өмірдің өзі — рухани нәрсенің дене арқылы көрінуі екенін түсіну көмектеседі. Сондықтан рухани даму әртүрлі діндер мен карма заңдарын зерттеу арқылы ғана емес, адамдардың әрекеті мен сөзінің себептерін өз ішкі әлемі арқылы ой елегінен өткізу арқылы да жүреді. Бұл жылы әлемде бәрі біртұтас әрі байланысты деген ішкі сенімге ие болу үшін әлем құрылысын, адамгершілік және рухани заңдарды зерттеу маңызды. Осылай адам өз әрекеттері мен айналадағылардың әрекеттері кездейсоқ емес, тепе-теңдік пен бумеранг заңы бойынша және ойдың жүзеге асуының салдары ретінде болатынын түсінеді. Бұл жаңалық өзіне және айналадағыларға адал болуға, бетперде мен екіжүзділіктен аулақ болып, өзінің шынайы болмысын көрсетуге мүмкіндік береді."], ["Өзін-өзі дамытумен айналысу", "Бұл кезең ішкі әлемді тану, түйсікті дамыту және өзін іздеумен байланысты, сондықтан жоғары күштерді, Ғалам белгілерін және түйсікті жоққа шығармаған жөн — оларды зерттеп, бұл білімнен жауап сезініп, ақпаратқа еніп, өз психикасы мен ақылының жаңа мүмкіндіктерін ашқан жақсы. Бұл жыл өзін-өзі жетілдіруге және ең жақсы қасиеттер мен қабілеттерді ашуға өте қолайлы. Санасыздық пен денеге құлақ аса отырып, түйсікті дамытыңыз."], ["Эмоциялық тепе-теңдік табу", "Өз Күш Орныңызды — энергия беретін қайнар көзді табыңыз: сенім, шығармашылық, әлем туралы дәстүрлі емес білім мен ғылымдар (психология, философия, нумерология және т.б.). Медитация, табиғат стихиялары және оңашалық арқылы ішкі диалогты тоқтатуды үйреніңіз. Психологпен жұмыс істеп, психологиялық құралдар мен тәсілдерді пайдаланыңыз. Бұл жылы сын мен айыптаудан аулақ болып, өзіңіздегі тәкаппарлық пен мақтаншақтықты байқап, тоқтатқан жөн."], ["Өз ерекшелігін көрсету", "Бұл жылы өзіңіздің өзгешелігіңізді, креативтілігіңізді және ерекше тәсіліңізді қабылдап, жемісті пайдалану мүмкіндігі пайда болады. Ол үшін тек материалдықпен емес, жоғары құндылықтармен және басқаларға көмекпен байланысты мақсат қойыңыз, бірақ елестерге кетіп, шындықпен байланысты жоғалтып, материалдықты толық жоққа шығармаңыз. Өз даралығыңыз бен өзгешелігіңізден қорықпай, идеяларыңызды әлемге ашып, сенуді үйреніңіз. Жыл шығармашылық ойлау мен креативті ұсынуға ықпал етеді, бірақ ойлағанды жүзеге асыруды ұмытпаңыз. Бұл уақыт болашақта басқаларға тәлімгер әрі көмекші болу үшін рухани және адамгершілік тұрғыдан өсуге көмектеседі."]], ["Мен адамдарға, әлемге, Құдайға (Жаратушыға, Ғаламға) сенемін бе?", "Менің түсінігімде жоғары күштер деген не?", "Қартайғанда ештеңеге өкінбеу үшін өмірді қалай өткізгім келеді?", "Өзіме болашақтан (мысалы, 10–20 жылдан кейін) кеңес бере алсам, олар қандай болар еді?", "Менің қандай күш орындарым бар?", "Маған демалыс керек екенін қалай түсінемін?", "Мен үшін ең тиімді демалыс қандай?"]], "8": ["", [["Құрбан рөлінен шығу", "Бұл жылы көңілсіз және апатиялы көңіл-күй, өмір сүрудің мәнсіздігі мен бекерлігі сезімі келуі мүмкін. Адам бұл күйзелістерді өзі бірнеше есе күшейтіп, үрлейтінін түсіну маңызды. Мұны жеңуге әлем мен адамдар бізге ештеңе қарыз емес екенін түсіну көмектеседі: үміт неғұрлым аз болса, көңіл қалу мен өкпе соғұрлым аз. Жағымсыз ойлар мен өзін құрту сәттерін уақытында байқап, олармен — өзіңіз немесе психологпен — жұмыс істеңіз. Психология, эзотерика, философия және әлем заңдарын (бумеранг заңы, «ұқсас ұқсасты тартады», энергия тепе-теңдігі заңы және т.б.) зерттеу көмектеседі. Қуаныш пен шабыт әкелетін істерді, орындарды немесе жағдайларды тауып, оларға үнемі жүгініңіз."], ["Қиындықтарды жақсы өмірге апаратын саты ретінде қабылдау", "Бұл жылы мінезді шыңдайтын, шешімдегі батылдықты және өз әлеуетін ашуға деген күшті ниетті дамытатын жағдайлар болуы мүмкін. Сондықтан өз сезімі мен әрекеті үшін жауапкершілікті алу маңызды. Жағдайды өзгерте алсаңыз — өзгертіңіз! Өзгерте алмасаңыз — бейімделіп, оған көзқарасыңызды өзгертіңіз. Ауыр ойлар азырақ, сындарлы шешімдер мен әрекеттер көбірек болсын. Бастама, жағдайды бақылауға алып, оны шешу үшін өз стратегиясын қолдана білу көмектеседі. Салауатты өмір салтын ұстанып, тамақтануды қадағалаңыз, аскеза мен шектеулерді жаттықтырыңыз — дәм әдеттерін өзгертіп, сау денеге алғашқы қадам жасайтын нақ уақыт. Спорт, дене және күш жүктемелері, күнделікті күш салу бекер кетпейді: олар өзін жеңу және күш салу арқылы әрекет ету әдетін қалыптастырады, бұл жылы ол өте пайдалы."], ["Өмірдің рухани жағын қабылдау", "Бұл жыл материалдық және рухани дамудың жаңа деңгейіне және өмір бағытын жақсыға өзгертуге серпін береді. Ол үшін әлем заңдарын түсініп, тұлға мен өмірдің рухани жағын қабылдап, саналы әрекет етіп, ойлана отырып, өмір құру маңызды. Жоғары мақсаттар мен мақсат-мұратқа еру шектен тыс материалдыққа берілуден және тұрмыстық ұсақтықтан алыстап, өмір сүру мәнін түсініп, өз құнын сезінуге көмектеседі."], ["Көшбасшылық қасиеттер мен тұлғаны дамыту", "Айналадағыларға құрметпен әрі әдепті қарай отырып, табандылық пен шешімділік, өз қажеттіліктерін түсіну және қанағаттандыру көмектеседі. Жаңа білім мен ақпарат, ерік-жігері мен харизмасы мықты адамдармен танысу — мұның бәрі бұл жылы өсуіңізге көмектеседі. Қоғамдағы жетістіктерге және мансаптық өсуге, қажет болса — істі толық ауыстыруға ұмтылыңыз. Бұл кезеңде өз бетінше шешім қабылдауды және өзін басқаруды үйрену маңызды."]], ["Мен қиындықтарды қалай қабылдаймын?", "Жеке және кәсіби өмірімде не болып жатыр? Мен ризамын ба? Риза болмасам — неге?", "Менің мақсаттарым қандай және оларға қалай жете аламын?", "Мен көшбасшылық пен шешімділікті қалай көрсете аламын?", "Батыл болуыма не кедергі келтіреді?", "Өзгерістер мені неге қорқытады?", "Менің көлеңкелі жақтарым қандай және олармен қалай достасып, оларды басқаруға болады?"]], "9": ["", [["Өз күшін басқаруды үйрену", "Бұл жыл агрессия мен күш қолдануға, оның ішінде өзіне қатысты да итермелеуі мүмкін. Сондықтан энергияны дұрыс басқарып, оны жасампаз арнаға — әлеуметтік белсенділікке, шығармашылыққа, басқаларға жобаларды жүзеге асыруға көмектесуге бағыттауды үйрену маңызды. Ашу мен агрессияны жеңіп, олардан жұмсақ арылуды үйрену маңызды. Спорт және тұрақты дене белсенділігі, энергиялылық пен ұлы істерге ұмтылыс көмектеседі. Эмоцияны басқаруды және ішкі тепе-теңдікті сақтауды дамытыңыз — бұған жеке шекаралар, ортаны мұқият таңдау, дене практикалары және психологпен жұмыс көмектеседі."], ["Өзін-өзі дамыту және жетілдіру жолын таңдау", "Бұл жылы дүниетаным мен басымдықтарды өзгертетін дағдарыс жағдайлары болуы мүмкін. Сондықтан өзімен үнемі және жан-жақты жұмыс, әртүрлі салада — дене, интеллект, шығармашылық және эмоция салаларында ең жақсы қасиеттерді дамыту керек. Өзін-өзі дамыту ерік бостандығымен және өзін бақылаумен қатар жүруі керек, адам сырттан қысымсыз жаңаны үйреніп, оны іс жүзінде қолданады. Бұл кезеңде жаңа білім, оқу, дағдыларды жетілдіру және әртүрлі салада жалпы сауаттылықты арттыру керек."], ["Рухани бағдарлар мен адамгершілік құндылықтарды қалыптастыру", "Бұл жылы бумеранг заңы өте тез іске қосылады, сондықтан өз әрекеттеріңіз үшін ерекше жауапкершілік керек. Бұл кезеңді жақсы жағынан өмір сүруге өзін-өзі талдау, әлем құрылысының заңдарын тану және ішкі рухани негіз жасау көмектеседі. Оның үш тірегі — алғыс, махаббат және жеке жауапкершілік. Алғыс айта білу жағымсыз эмоциялар мен өкпеден аулақ болуға көмектеседі. Өз әрекеті үшін жауапкершілікті дамыту маңызды — бұл саналы өмір сүруге, жақсара түсуге және адамгершілік жағынан кемелденген адам болуға — айналадағыларға адал, моральдық және этикалық нормаларды ұстанатын, шекарадан аспайтын және жақсылықтан әрекет ететін адам болуға мүмкіндік береді. Рухани қағидаларды түсінудің арқасында сенім әрдайым ішіңізде қалады, ал бұл үмітсіздікке берілмеуге, әлемді тануға ұмтылуға және құмарлықтан, тәуелділіктен және бұзушы ойлардан еркін болуға көмектеседі. Бұл жыл ерекше назарды талап етеді: тоғыздық өз күшімен адамның өз әрекеттері қайда бағытталғанына қарай теріс жаққа да, жыл кодының екінші санының ең жақсы қасиеттерін дамытуға да жұмыс істеуі мүмкін."]], ["Қандай жағдайларды, істерді және байланыстарды аяқтайтын уақыт келді? Мүмкін, олардың кейбірі маңызын жоғалтқан шығар?", "Дамуыма кедергі келтіретін ескірген әдеттер жоқ па?", "Менің әрекеттерім мен ойларым айналадағы әлемге қалай әсер етеді?", "Мен жауапкершілік алудан қорқамын ба? Қорықсам — неге?", "Өз әлеуетім мен күшімді қоғамның пайдасына қалай қолдана аламын?", "Мен күн сайын не үшін алғыс сезінемін?"]]}, "dest": {"1": [["Батылдық", "Өзгенің бағасын немесе көмегін күтпей, қорықпай шешім қабылдауды үйреніңіз. Өмір жолында ішкі қорқыныш пен сенімсіздікке тап боласыз — оларды жеңу маңызды."], ["Тәуелсіздік", "Пікірдің дербестігі мен өзіне-өзі жеткіліктілікті дамытыңыз. Мақтау, алғыс пен мақұлдау үшін емес, өз өсуіңіз үшін әрекет етіңіз."], ["Даму", "Өзіңізді, ерекшеліктеріңіз бен таланттарыңызды зерттеуге уақыт табыңыз. Табиғи қабілеттерді ашып, идеялылық пен өзгешелікті дамытыңыз. Оларды міндетті түрде іс жүзінде қолданып, энергияңызды әлемге беріңіз."], ["Бастама", "Істе көбірек бастама алыңыз, қозғалыста болыңыз және мәселе мен жаман көңіл-күйде ұзақ қалып қоймаңыз. Қателіктерден қорытынды жасап, тәжірибеге сүйене отырып, қозғалыс бағытын түзетіңіз."], ["Сабыр", "Қырсықтық, өзімшілдік пен қатып қалған көзқарас істерге қатты зиян келтіруі мүмкін. Сондықтан сабырға және адамдармен икемді, жемісті араласуға үйрену маңызды. Айналадағыларға тым жоғары талап қоймаңыз — олардың басқа қарқыны мен басқа мүмкіндіктерін қабылдаңыз."], ["Ерекшелік", "Басқалардың пікірі мен тілегіне қарамай, өзіңіздің қайталанбас жолыңызды табыңыз. Көпшілікке сіңіп кетпей, өзгенің құндылығымен өмір сүрмеңіз. Өзіңізге және тәжірибеңізге сенуді, өз тарихыңызды жасауды үйреніңіз."], ["Көшбасшылық", "Жаңа жобалар мен бағыттарды ұйымдастырып, бастап көріңіз, идеяларыңызды ұсынып, айтыңыз. Соңынан ерте алатын және бұл үшін жауап бере алатын көшбасшы болыңыз."]], "2": [["Дипломатия", "Түсінбеушілік пен дауды шеше отырып, үйлесімді қарым-қатынас құруды және бейбіт мақсаттарды ұстануды үйреніңіз. Есіңізде болсын: кез келген мәселені бейбіт келіссөзбен шешіп, жағдайдан пайдалы тәжірибе алуға болады."], ["Орта", "Серіктестер мен адамдармен өзара әрекет сізге барлық салада керек, өйткені ортаға тек жетістіктеріңіз ғана емес, ішкі күйіңіз бен эмоциялық тепе-теңдігіңіз де байланысты. Сондықтан өмір жайлы әрі үйлесімді болуы үшін — достықта, махаббатта және жұмыста — қасыңызда қандай адамдар болуы керектігін түсіну маңызды."], ["Түйсік", "Өзіңізді, сезімдеріңіз бен қажеттіліктеріңізді естуді үйреніңіз. Түйсікті дамытып, дене сигналдарына мұқият болыңыз."], ["Шекаралар", "Жақындар мен айналадағыларға көмектескенде, күшіңізді өлшеп, өзіңізді ұмытпаңыз және айла-шарғыға (манипуляция) көнбеңіз. Уақытында «жоқ» деп, өз шекараңызды белгілеп, жұмсақ қорғай білу маңызды. Өз өміріңіз үшін жауапкершілікті өз қолыңызға алыңыз."], ["Таңдау", "Мақсаттылықты, сөзіңіз бен таңдауыңызға адалдықты дамытыңыз. Күмәннің жетегінде кетпей — жағдайды талдап, түйсікке құлақ асыңыз."], ["Шешімділік", "Мақсат қойылса, шегінуге сылтау іздемей немесе бәрін кедергі келтіретін жағдайға жаппай, керекті әрекеттерді орындау маңызды. Ұзақ ойланбаңыз — бірден, шағын тұрақты қадамдармен және күшпен әрекет етіңіз."], ["Түрлену", "Бірдеңе болмаса, үміт үзбеңіз, өткенге қарамаңыз және өзіңізді сатпаңыз. Қандай қарым-қатынас пен әрекет тәсілдері ескіргенін талдап, олармен қоштаса біліңіз, жаңа әрі жақсыға орын босатыңыз. Ескіге жабысып, әрі қарай дамуға жолды өзіңіз жабасыз."]], "3": [["Әрекет", "Жоспарлар туралы айтып, қиялдап, армандап қана қоймай, әрекет ету — іс жасау және нақты қадамдар жасау маңызды. Құнды ой келгенде, оны жазып алып, бірден жүзеге асыру стратегиясын таңдаңыз."], ["Шығармашылық", "Креативті идеялар мен жобаларыңызды шығармашылық дағдылар арқылы жылжытып, бұған басқаларға да көмектесіңіз. Қиял мен елестетуге сүйене отырып, жасау сыйыңызды пайдаланыңыз."], ["Кәсібилік", "Өмір бойы оқып, әртүрлі тәжірибе жинап, дамыңыз. Дағдыларды кәсіби деңгейге дейін жетілдіріңіз. Жаңа білімді мүмкіндігінше тез іс жүзінде қолданып, адамдармен бөлісудің кез келген мүмкіндігін пайдаланып, оны табысқа айналдыруға тырысыңыз."], ["Сенім", "Рухани даму мен жоғары күштердің әсерін ұмытпай, әлем заңдарына сай әрекет етіңіз. Сізді әрдайым сенім, ішкі адамгершілік бағдар және өмірге құштарлық қолдайды."], ["Адамгершілік", "Заңсыз және адамдарға зиян келтіруі мүмкін нәрсенің бәрінен аулақ болыңыз. Басқаның қолымен жасалғанды сынамаңыз және бұзбаңыз."], ["Тәртіп", "Табыс үшін жағдайды дұрыс бағалай білуді, айналадағыларды тыңдауды және ішкі тәртіп құруды дамыту маңызды. Нақты жоспарлау, мақсаттарға уақытында жету, тұрақты әрі тиімді әрекет «сәтпен өмір сүру» және бір күндік танымал қағидадан гөрі жүзеге асуыңызға көбірек көмектеседі."], ["Шабыт", "Шабытты жоғалтпау және шаршап-шалдықпау үшін бір сарындылықтан аулақ болып, жұмыс пен демалысты кезектестіріңіз. Күшті уақытында толтыру үшін сізді шабыттандыратын нәрсені табыңыз."], ["Өмірге құштарлық", "Тіпті көңіл қалған сәттерде де мұңға, жалқаулыққа және пессимизмге берілмеңіз. Сіздің күшіңіз — өмірге деген махаббатта, сарқылмас оптимизм мен энергияда. Бұл қуанышпен айналаңыздағылардың бәрімен бөлісіңіз."]], "4": [["Түйсік", "Өзіңізге және сезімдеріңізге жиі құлақ асып, ішкі сезіміңізге сеніңіз."], ["Стратегия", "Сәтсіздік кезінде қол қусырмаңыз. Әрі қарайғы жолдың нақты стратегиясын құра беріп, жоспарлап, лезде табыс күтпей, нәтижеге ұмтылыңыз."], ["Руханилық", "Өмірде әрекет ететін себеп-салдар байланыстарын түсініп, бізге түсініксіз көрінетін немесе әзірге қабылдауға дайын емес нәрсе бар екенін мойындау маңызды — тіпті ол таңғаларлық, әдеттен тыс және кәдімгі қабылдаудан тыс болса да."], ["Үйлесім", "Елестерден арылып, рухани мен материалдықтың, практикалық пен икемділіктің үйлесіміне ұмтылыңыз. Қиялға жердегі қолданыс тауып, армандарды нақты әрекетке айналдырыңыз."], ["Қаржыдағы тепе-теңдік", "Аяқта берік тұру маңызды: қаржылық сауаттылық негіздерін меңгеру, қоғамда берік орын және материалдық молшылық болуы керек. Ақша таба білу аз — оны ақылмен жұмсап, көбейтіп, жинау да керек. Сонымен бірге ақшаны жоғалтудан қорқып өмір сүрмей, капиталдың үстінде дірілдемеңіз, өйткені ақша қозғалысты жақсы көреді."], ["Сенімділік", "Өз қорқынышыңыз бен күмәніңізбен жұмыс істеуді және себепсіз мазасыздыққа «тоқта» деп айта білуді үйреніңіз. Алға жылжуға және мақсатқа жетуге кедергі келтіретін сәтсіздіктер мен қателіктерді анда-санда талдап отырыңыз."], ["Икемділік", "Ойлағанды жүзеге асыруға дөрекілік, қаттылық пен өзімшілдіктен бас тарту көмектеседі. Адамдарды қандай болса, солай қабылдай білуді, оларды түсінуді және әртүрлі пікірлерді ескеруді дамытыңыз."]], "5": [["Тереңдік", "Ішкі энергияңызды басқаруды және бірден көп іске шашыратпауды үйреніңіз. Қызығушылықтарыңыз кең және көп нәрсені біліп, байқап көргіңіз келсе де, тереңге бойлап, таңдаған тақырыптың мәніне үңіле білу маңызды."], ["Өзін-өзі дамыту", "Философия, психология және эзотериканы да зерттей отырып, үнемі дамыңыз. Өмірдің әртүрлі жақтарын, оның барлық қырларын танып, олардан шабыт, жаңару және жаңа әсер көзін көріңіз."], ["Жауапкершілік", "Өзіңізде тәртіпті, жауапкершілік сезімін және ойлағанды, уәде бергенді міндетті түрде орындауды тәрбиелеу маңызды. Сөзіңізде тұрып, өзіңізге қойған мерзімді сақтаңыз."], ["Эмпатия", "Сындарлы сөйлесуді, басқаларды естіп, түсінуді және дауда азырақ қасарысуды үйреніңіз. Асығыстық пен әбігерден аулақ болып, эмоциялық тұтану мен жүйкелікті ұстауды үйреніңіз."], ["Оптимизм", "Мұңнан, өзіңізді және айналадағыларды сынаудан аулақ болып, мәселеде ұзақ қалып қоймаңыз — шешімді осында және қазір батыл іздеңіз. Азырақ күңкілдеп, өмірге шағымданып, бекер әбігерленбеңіз. «Осында және қазір» алғыспен өмір сүріңіз."], ["Өзгешелік", "Әдеттегі нәрселерге жаңаша қараудан және «ессіз» идеяларыңызбен әлеммен бөлісуден қорықпаңыз. Дәл осылай сіздің тапқыр ақылыңыз көрініп, табыс келеді."], ["Еркіндік", "Таланттарды ашу үшін қалыптар мен шектеулерден аулақ болыңыз. Өзгеріс пен қозғалыс — ішкі еркіндігіңіздің маңызды бөлігі. Тәуекелден қорықпай, жаңаны байқап көріп, белгісізге баруға өзіңізге рұқсат беріңіз. Бірақ мұны дәстүрлерді бұзбай және адамгершілік құндылықтар мен еліңіздің заңдарына қарсы шықпай істеңіз."]], "6": [["Өз құндылығы", "Осы әлемдегі маңызыңыз бен құндылығыңызды сезіне отырып, махаббатты, ресурсты және ішкі күшті өзіңізден табыңыз. Басқалармен мейірім мен қабылдау энергиясымен бөлісіп, рухы жақын адамдарды табыңыз. Өзіңіздің керек екеніңізді араласу және қоғамда жүзеге асу арқылы бекітіңіз. Бірақ ең бастысы — өзіңізге-өзіңіз керек әрі маңызды болыңыз. Өзіне-өзі жеткілікті болуға және өзгенің пікірі мен бағасына тәуелсіздікке ұмтылыңыз."], ["Түйсік", "Ішкі дауысты міндетті түрде тыңдап, түйсікті дамытыңыз. Сезімдеріңізге құлақ асып, денеңіздің әртүрлі оқиғаларға қалай жауап беретінін байқаңыз."], ["Тәлімгерлік", "Тәлімгер мен ұстаз сыйыңызды міндетті түрде пайдаланыңыз: айналадағыларды бағыттап, олардың әлемге көзқарасын өзгертуге көмектесіңіз. Бірақ жақсылықты күшпен жасамай және өз шындығыңызды таңбай — басқалардың өз пікіріне құқығын мойындап, сұраған кезде көмектесіңіз."], ["Сенімділік", "Санасыз қорқыныштар мен ішкі шектеулерді жеңіп, өзін-өзі бағалау мен өзіне сенімділікпен жұмыс істеңіз. Жалқаулықтан, зиянды әдеттер мен тәуелділіктерден аулақ болып, мәселе мен қарым-қатынастағы алауыздықта құрбан рөліне кетпеңіз."], ["Өзін-өзі дамыту", "Рухани және тұлғалық өсу мен ең жақсы қасиеттерді (махаббат, жанашырлық, мейірім, кешірім) көрсету неғұрлым көп болса, өмірдің барлық саласындағы дамуыңыз соғұрлым сәтті болады."], ["Өкпеге жоқ", "Өкпешілдікпен жұмыс істеп, өкпелеу немесе өкпелемеу — тек сіздің таңдауыңыз және жауапкершілігіңіз екенін түсініңіз. Өкпенің орнына сөйлесіп, талқылап, сіз үшін не қабылданбайтынын түсіндіріңіз. Әр жолы осалдығыңызды көрсеткеннен немесе өмірді уландыратын қарым-қатынастан шыққаннан гөрі, шекараңызды алдын ала белгілеген дұрыс."]], "7": [["Өзгешелік", "Пікірлеріңіз бен ниеттеріңіз көбіне басқаларға ұқсамайды, сондықтан мақсат-мұраттың бір міндеті — өз ішкі әлеміңізді зерттеу. Түсінілмей қалудан қорықпай, өз жолыңызбен жүріп, түйсік пен психологиялық әдістерді батыл пайдаланыңыз. Идеялар келгенде (көбіне санасыздықтан келгендей), бірден әрекет етіп, оларды жүзеге асыруға кірісіңіз. Оларды бос әрі керексіз деп сілтемеңіз — олардың пайдасы мен өзгешелігін түсініңіз."], ["Шынайылық", "Даму жолында азғыру мен тәуелділік кедергі болуы мүмкін, сондықтан шындықтан елес әлеміне апаратын нәрсенің бәрінен (ойындар, ішімдік, тыйым салынған заттар) аулақ болыңыз. «Жерге байланып», шындықпен байланысты жоғалтпауға дене практикалары, йога, массаж, шынығу, спорт, табиғат стихияларымен араласу көмектеседі."], ["Өзін-өзі дамыту", "Басты міндеттердің бірі — материалдық пен руханидың тепе-теңдігін сақтай отырып, өмір бойы өзін-өзі дамытумен айналысу, әртүрлі халықтардың философиясын, психологиясын және діндерін зерттеу. Атеизмге және сенімді жоққа шығаруға кетпеңіз. Мына сұрақтарға жауап іздеңіз: менің өмір сүруімнің мәні неде? Бұл әлемдегі менің міндеттерім қандай? Бұған психикалық процестерді зерттеу, эзотерикалық білім, гипноз тәсілдері — тереңдігіңізді танып, таланттарыңызды ашуға мүмкіндік беретін нәрсенің бәрі көмектеседі."], ["Талдау", "Сәтсіздікке тап болғанда, айналадағыларды кінәламай, ең алдымен оның себебін өзіңізден іздеп, ішкі ұстанымдарды өзгертіңіз. Сіз кез келген жағдайды бөлшекке бөліп, дұрыс қорытынды жасай аласыз — бастысы, шектен тыс сыншылдыққа түспеу."], ["Дербестік", "Шектен шықпай және өзгенің пікірі мен ықпалына тәуелді болмай — шешімді өзіңіз қабылдаңыз. Көрегендігіңіз әрдайым дұрыс таңдауды меңзейді."], ["Жемісті оңашалық", "Құбылыстарды, оқиғалар мен кездесулерді ой елегінен өткізе отырып, өзіңізбен оңаша күш жинауды үйреніңіз, бірақ жалғыз жүруге кетпей, араласудан оқшауланбаңыз. Өзіңізге жақын және қасында психологиялық та, энергетикалық та жайлы адамдармен байланысты сақтаңыз."]], "8": [["Кешірім", "Ең маңызды міндеттеріңіздің бірі — айналадағыларға әділдік пен адалдық таныта отырып, кешіре білу және ескі өкпеге оралмау. Басқаларға қатысты сезімталдық пен төзімділікке үйреніңіз."], ["Мейірімділік", "Кекесіннен, цинизмнен және сынау әдетінен аулақ болып, жақындардың сезіміне көбірек жанашырлық пен түсіністік танытыңыз. Жұмыста билік пен мүмкіндік, отбасында махаббат пен ықылас алғанда, оларды пайдакүнемдікке пайдаланбаңыз — адамдарды баспаңыз, билік көрсетпеңіз және айла-шарғы жасамаңыз. Бірдеңе ұнамаса, сылтаусыз және кінәламай, өзгерісті ең алдымен өзіңізден бастаңыз."], ["Төзімділік", "Табандылық танытыңыз, қиындық алдында бас имеңіз және алғашқы күмәнда немесе мәселеде бастағанды тастамаңыз. Есіңізде болсын: неғұрлым көп кедергі мен сынақты жеңсеңіз, соғұрлым көп мүмкіндік пен марапат аласыз. Сонымен бірге мейірімді болып қалыңыз, тағдырға шағымданбаңыз және «не үшін?» деп сұрамаңыз. Талдап, тактика мен әдістерді өзгертіп, мінездің ең жақсы қырларын дамытыңыз. Өзіңізден былай сұраған дұрыс: «Бұл жағдай маған не үшін берілді және мен неге үйрене аламын?»"], ["Материалдық пен руханидың тепе-теңдігі", "Берік материалдық жағдай сіз үшін маңызды болса да, ақшаға шектен тыс байланбаңыз және оны мақсат етпеңіз. Шектен тыс материалдыққа берілу, қатыгездік, қаттылық пен өзімшілдік мүмкіндіктеріңізді жауып, адамдармен қарым-қатынасты бұзып, мақсатқа жетуге кедергі келтіреді. Әлеуетіңізді тек мүмкін пайда үшін емес, жоғары рухани-адамгершілік мақсаттар үшін де жүзеге асырыңыз."], ["Икемділік", "Жағдайға бейімделуді үйреніңіз. Есіңізде болсын: иілгіш сынбайды! Өзіңізді және эмоцияңызды ұстап, салмақты шешім қабылдай отырып, сіз міндетті түрде қоғамда жоғары орынға ие боласыз."], ["Күш", "Сізге тоқтауға, өзіңізді аяуға, әлсіздігіңізге беріліп кетуге және ұзақ жаман көңіл-күйде болуға болмайды (құлдыраулар көңілсіздікке әкелуі мүмкін). Бұл жалқаулыққа итермелеп, күш пен дамуға деген ниетті алады. Өз әрекетіңіз үшін жауапкершілікті қабылдап, әлсіздігіңізге жол беруді тоқтатсаңыз, адамдарды, оқиғаларды және материалдық әлемді оңай басқара аласыз."], ["Ерік", "Өмірдің қандай да бір саласында (араласуда, тамақта, зиянды әдеттерде, ойын-сауықта) аскеза ретінде өзіңізді шектеп, ерік күшін жаттықтырған өте пайдалы. Мұны саналы түрде — мінез бен мақсаттылықты нығайту және сыртқы жағдайларға билігіңізді сезіну үшін істеңіз."]], "9": [["Оңашалық пен араласудың тепе-теңдігі", "Жалғыздықтан қорқуды және жан жараларын басқа адамдармен және артық араласумен толтыру әдетін жеңу маңызды. Жеке кеңістік пен өз аумағыңызға құқығыңызды сақтай отырып, оңашалықты да, айналадағылармен жағымды араласуды да жақсы көріңіз."], ["Эмоцияны бақылау", "Кейде дөрекілікке ұласатын ішкі күш пен қызбалықты жеңе отырып, эмоцияны басқаруды үйреніңіз. Өмірлік қиындықтар мен көңіл қалу сізге төзімділікті, өзіне сенімділікті және өзін ұстауды дамыту үшін берілген. Ұшқалақтықты ұстап, «алдымен ойла, сосын істе» ережесін ұстаныңыз. Әбігер мен асығыстықтан аулақ болып, тоқтауды және баяулауды үйреніңіз."], ["Энергияны жүзеге асыру", "Энергияны шығарып, шиеленісті жою үшін дене белсенділігі, спорт (тіпті экстремалды), көлік жүргізу, толыққанды жақын өмір пайдалы. Бұл энергия тоқырап қалмауы үшін керек — әйтпесе тоқырау артық салмақ, агрессия, дауға бейімділік және қызу айтыс болып көрінуі мүмкін. Сіз өзіңізге ең ауқымды мақсаттар қоя аласыз: әлеуетті дұрыс қолданып, серпіндерді тежей білсеңіз, ішкі рух күшіңіз ойлағанның бәріне жетеді."], ["Адамгершілік", "Кез келген істе өмір мен адамгершілік заңдарына қарсы шығуға болмайды. Әр жағдай — қабылдау керек тағдыр сабағы екенін есте сақтаңыз. Өз құмарлығыңыз бен тілегіңізден басқа, жақындардың сезімі мен қажеттілігін ескеріп, тек өз пайдаңызды ғана ойламай, мейірім, рақым, түсіністік пен даналық таныту маңызды."], ["Басқаларға көмек", "Сізде басқаларға қарағанда ең өршіл ойларды сәтті жүзеге асыру мүмкіндігі әлдеқайда көп — бірақ олар тек өз қажеттілігіңіз бен пайдаңызға емес, қоғамның игілігі мен адамдарға көмекке бағытталса ғана."], ["Үйлесім", "Әлем мен адамдарға позитивті көзқарасты дамытып, айналадағы сұлулық пен үйлесімді байқап, жасаңыз. Өз стиліңізді және даралықты білдірудің өз түрін іздеңіз."], ["Батылдық", "Өзгерістен қорықпаңыз — оларды ашық әрі қорықпайтын жүрекпен қарсы алыңыз. Өмірде бәрі бір кезде аяқталатынын қабылдау ғана жаңа мен белгісізден қорқуды жеңуге көмектеседі."]]}, "typ": {"1": "Жаңашыл. Туғаннан сізде көшбасшының қасиеттері бар, ал жылдар өте оларға ұйымдастырушылықтың күшті таланты қосылады.\nСізге назардың ортасында болу жайлы. Сіз әртүрлі процестерді басқара аласыз, адамдарды шабыттандырып, олардың арасында өз идеяларыңызды жылжыта аласыз. Айналадағыларды мінез күшімен және харизмамен тарта отырып, сіз сонымен бірге көбіне оңашалықты таңдайсыз — және онда өзіңізді табиғи әрі тыныш сезінесіз. Бұған айқын даралық және болып жатқанның бәріне өз, тәуелсіз көзқарасыңыз көмектеседі.\nҚоғамда танылу және қаржылық табыс сіз үшін үлкен мәнге ие. Тұлға ретінде өсуге мақсаттылық, өзгешелік және өзіне-өзі жеткіліктілік көмектеседі. Өмірде сіз көбіне тек өзіңізге сүйенесіз: сіз үшін ең салмақты бедел — өзіңіз. Мақсатқа сізді жеке тәжірибе, шешімдегі батылдық және маңызды істерге шығармашылықпен қарау мүмкіндігі жетелейді. Сіз үнемі алда болуға, бірінші орын алуға және жетекші рөл атқаруға ұмтыласыз.\nСіз — дербестігімен және ерекше ой жүйесімен тартатын терең адамсыз. Сізге жалғыз әрекет еткен ыңғайлырақ, айналадағылардың мақұлдауы сізге қажет емес. Өз тәжірибеңізді жинау маңызды, ал адамдар немесе жағдайлар тарапынан тәуелділік пен қысым дамуыңызды қатты тежейді. Сонымен бірге сіз мақтау мен еңбегіңізді көпшілік алдында мойындауды өте бағалайсыз. Жауап пен алғыс болмаса, айналадағылар себебін түсінбейтін ашу пайда болуы мүмкін.\nСізде іскерлік қасиеттер күшті: табандылық, іске орасан зор берілу (кейде жұмысқа шектен тыс берілуге дейін жетеді), қуатты энергия, көп процесті бір мезгілде бастап, оларды сапасын жоғалтпай бақылауда ұстай білу. Жұмыста серпінділік, әртүрлілік пен жаңа әсерге құмарлық, сондай-ақ өзіңіз жүргізетін немесе жетекшілік ететін барлық жобаға шынайы қызығушылық көмектеседі. Сіз үшін бастысы — түпкі нәтиже. Сізді ерекшелік, басқара білу және жұмысқа жаңашыл тәсілдер мен ең заманауи технологияларды енгізуге деген ниет ерекшелейді.\nСізде кез келген істі нөлден бастап жасауға және кез келген ауқымдағы бизнесті басқаруға үлкен әлеует бар. Адамдарды сіздің ықпалдылығыңыз, кәсіби сарапшылық тәсіліңіз, дербестігіңіз, жауапкершілігіңіз, креативтілігіңіз және шабыттандыра білуіңіз тартады.\nСабырға және ұшқалақтықты дұрыс арнаға бағыттай білуге үйрену маңызды. Сонда әртүрлі жағдайда энергияны артық эмоцияға шашпай, пайдалы жұмсайсыз.", "2": "Бітімгер. Сіздің нәзік қабылдағыштығыңыз — әрі күш, әрі осал тұс. Сіз әр оқиға мен әр құбылысты өзіңізден өткізуге бейімсіз. Адамдарға терең жанашырлықпен қарап, олардың табысын, қуанышы мен қайғысын жүрегіңізге жақын қабылдайсыз.\nСіз берік байланысқа, шынайы қамқорлық пен жанашырлыққа қабілеттісіз.\nАлайда сезімталдық пен басқалардың күйзелісін бірінші орынға қою әдеті өзіңізді, тілектеріңіз бен сезімдеріңізді естімей қалуыңызға әкелуі мүмкін. Өз ішкі дауысыңыз айналадағылардың мұқтажы мен мәселесіне батып кетеді.\nСізде түйсік пен жанашыр болу қабілеті жақсы дамыған, сондықтан адамдарды, олардың ойы мен сезімін нәзік түсінесіз. Сіз ойланып әрекет ете аласыз және көп қадам алға стратегия құра аласыз. Араласуда сіз дипломат, әдепті, жұмсақ және өзіңізге сабырлы сенімдісіз — бұл тіпті ең шатасқан және шешімсіз сияқты көрінетін жағдайларды бейбіт шешуге көмектеседі. Істе сіз үшін серіктестік пен сырттан қолдау үлкен мәнге ие. Сізге дана әрі кемел серіктеспен ынтымақтастық күш береді, сондықтан ортаны ерекше мұқият таңдаған жөн. Сіз шығармашылық шешімдер таба аласыз, айналадағыларға және маңызды шешімдерге әсер ете аласыз — көбіне байқатпай, біртіндеп. Араласуда сізге ішкі жинақылық, ақыл-парасат және әркіммен ортақ тіл таба білу көмектеседі. Сіз айналаңызда жайлы атмосфера жасап, қасында өзіңізді сенімді сезінетін рухы жақын адамдармен қоршала аласыз. Дәл осындай қамқорлық пен қорғаныс энергиясын айналадағыларға сыйлайсыз. Адамдарда өзіңізде бар нәрсені бағалайсыз: мейірім, шынайылық, адалдық, сабыр, дипломатия, салмақты шешім қабылдай білу және объективтілік. Сіз басқа адамның орнына тұра аласыз, сондықтан өзгенің тілегі мен ниетін жақсырақ түсінесіз, кез келген адамды өзіңізге оңай тарта аласыз. Барлық қиындықты жалғыз жеңуге тырыспау маңызды — керісінше, керекті саладағы мамандарға көмек сұраған пайдалы.\nШектен тыс сенгіштік, эмоционалдылық пен әсершілдік сізге қарсы жұмыс істеуі мүмкін. Сондықтан ішкі дауысыңызды тыңдап, өзіңізді айла-шарғыға (манипуляция) көндірмеу маңызды. Жеке шекараны жұмсақ, бірақ сенімді қорғауды, сондай-ақ өз қажеттіліктеріңізді кінә сезімімен бірге таңылуы мүмкін өзгенің қажеттіліктерінен ажыратуды үйрену керек.", "3": "Жасампаз. Сізді өмірге жеңіл қарау және әрдайым позитивті көңіл-күй ерекшелейді. Сіз әлемдік мәселелер туралы бас қатыруға және таңдау сұрақтарымен азаптануға бейім емессіз — сізге өмір бойы оптимизммен және бәрі жақсы болады деген сеніммен жүру жақынырақ.\nТаңғаларлық түрде сіз жағдайды өз пайдаңызға бұра аласыз, бұл жұмыста да, жеке өмірде де айтарлықтай көмектеседі.\nСізде оқиғалардың табиғи барысына кедергі келтірмей, тағдырдың өзі бәрін орнына қоюына мүмкіндік беретін сирек қабілет бар. Ғаламға деген мұндай сенім әдетте алдыңыздан көп мүмкіндік ашады.\nАдамдардың сізге тартылатыны таңқаларлық емес — олардың көзінше сіз өмірге құштар «жолы болғыш» адамсыз.\nСіз өте ашық әрі іскерсіз. Сіз — ақылы ұшқыр қызықты әңгімелесуші, сонымен бірге мұқият тыңдай аласыз.\nСіздің қасыңызда адамдарға жеңіл, өйткені олар өздеріне деген шынайы қызығушылығыңызды сезеді.\nСіз жомарт әрі кеңпейілсіз, басқалардың қатесін оңай кешіресіз, өйткені өз қатеңізге де жай қарайсыз. Сіздің ұраныңыз көбіне «Қарапайым бол!» деп естіледі. Позитивті көңіл-күйіңіз айналадағыларға өмірлік қиындықтардан жеңілірек өтуге көмектеседі. Сәтсіздікті сабырмен қабылдап, одан керекті тәжірибені көресіз және одан болашақ жеңістердің басын көре аласыз.\nӨзін білдіру еркіндігі, сарқылмас оптимизм, кез келген жаста жанның жастығы, қозғалыс пен өзгеріске құмарлық — сіздің жарқын қасиеттеріңіз. Сіз жеңіл қозғаласыз және жаңа жағдайға тез бейімделесіз. Бақыт пен үйлесім үшін сізге шығармашылықта жүзеге асып, ішкі күмәндар сынағынан өту керек. Жұмыс шабыттандырып, көңіл-күйге қарай еркін әрекет етуге мүмкіндік беруі керек. Қысым, бір сарындылық пен күнделікті әдет ашылуыңызға кедергі келтіреді. Серпінмен және жүйесіз әрекет ету әдетіне байланысты сіз жаңа идеяға оңай тұтанып, жаңа жобаларды бастайсыз, содан кейін олардан тез суынасыз. Бұл шығармашыл адамға нәтижеден гөрі процестен алатын ләззат маңыздырақ болғандықтан да болады. Жұмыста тоқырау мен кейінге қалдыру кезеңдері болады, сосын қысқа мерзімде бүкіл көлемді орындайсыз. Сізде кез келген жобаны шығармашылық жолмен жылжытудың ерекше сыйы бар — сіз ұстаған нәрсенің бәрі танымал әрі сұранысқа ие болады. Сіз әртүрлі міндеттердің ерекше шешімдерін оңай табасыз.\nДаму үшін сізге өмір бойы оқу керек: жаңа білім алып, оны шығармашылық арқылы іс жүзінде қолдану.\nСіздің талғамыңыз жақсы, әдемі нәрсенің бәрін бағалайсыз. Шабыт — өмірдегі басты қозғаушы күшіңіз бен бағдарыңыз.\nСізді айналадағылардың шектен тыс қысымы, нұсқаулары мен сұралмаған кеңестері тежеуі мүмкін. Сынды жиі ауыр қабылдайсыз. Сізге үнемі жаңаны байқап көріп, тәжірибе жасап, нөлден бастаудан қорықпау маңызды. Тек осылай, өз тәжірибеңізбен және өз күшіңізбен сіз ең көп ләззат әкелетін және ұзақ уақыт қызықтыратын істі табасыз. Бұған өзіңізге деген сенім, шығармашылық қиял, әртістік және кез келген адамға жол таба білу көмектеседі. Өмір ісі ретінде таңдаған кез келген бағытта дерлік сізге сәттілік серік болуы мүмкін.", "4": "Құрушы. Қайда болсаңыз да, тәртіп орнатып, жүйе құруға ұмтыласыз. Сіз практикалық, жинақы және тұрақтысыз. Шешімді тез қабылдайсыз, жақсы талдайсыз, есте сақтауыңыз тамаша, ақылыңыз ұшқыр.\nБұл қасиеттер көбіне жоғары басшылық лауазымдарға ие болуға көмектеседі. Мұндай адамға — жауапты, ниеті берік, адал және тамаша ұйымдасқан — кез келген істі дерлік сеніп тапсыруға болады.\nТіпті ең күрделі және шатасқан жағдайда да тәртіп орната білетін құнды қабілетіңіз сізді бизнесте қалаулы серіктес етеді.\nСіз еңбекті бағалайсыз, өте жұмысқа қабілеттісіз және нәтижелісіз. Тағдырға, сәттілікке немесе жағдайлардың тоғысуына емес, өзіңізге сенесіз. Кейде тым оңай келген нәрсені тіпті бағаламауға бейімсіз.\nӨз табандылығыңызбен, еңбегіңізбен, ақылыңызбен және таланттарыңызбен жеткен нәрсеге ең көп сенесіз, сондықтан сіз жасағанның бәрі сапалы әрі берік болады. Кез келген міндетке ең алдымен ақылмен және техникалық тұрғыдан сауатты қарайсыз: жоспар құрып, бәрін сөреге қойып, қадам-қадаммен әрекет етесіз. Процесте сіз үшін бақылау өте маңызды.\nСіз қиындықтан қашпайсыз және қойылған міндеттерді әрдайым орындайсыз. Нәтижеге жету үшін сізге көбіне ұзақ әрі табанды еңбек етіп, өзіңізді жеңуге тура келеді. Сізде берік адамгершілік өзек және өмірде сенімді жүруге, ұқсас адамдарды тартуға көмектесетін өз қағидалар жүйеңіз бар. Сіз үшін ұсақ-түйекке дейін ойластыру, бөлшектерге назар, өз ісіңізге және жақындарыңызға адалдық, адалдық пен әділдік, кез келген жағдайдағы төзімділік пен сенімділік маңызды.\nСенімділік пен жайлылықты сезінгенде ең көп табысқа жетесіз, сондықтан өзіңізге тұрақты әрі қауіпсіз жағдай жасауға ұмтыласыз. Әдетте сіз тез ақша мен оңай табысқа қумайсыз, сабырмен жұмыс істеп, бәрін елеулі күшпен табасыз.\nҰзақ мерзімді мақсат және оған жетудің нақты жүйесі болғанда, бәрі мінсіз қалыптасады. Мақсат үшін көп нәрсеге дайынсыз және өмір бойы бір идеяға адал болып, соған жұмыс істей аласыз. Кез келген ойды өмірге енгізуге қабілеттісіз, бүкіл жолды — жобадан өндіріс пен жылжытуға дейін қамтамасыз етесіз.\nЕртеңгі күнге деген сенімді сізге жұмыста да, өмірде де ережелерді, заңдарды және тәртіпті ұстану береді. Осының арқасында сіз сияқты адамдар әдетте табысқа жетеді: сіз ақшамен жұмыс істей аласыз және тіпті шығармашылық жобаларды да жүзеге асыруға дейін жеткізесіз (бұл аз ұйымдасқан шығармашыл адамдарда жиі болмайды). Сізге өзіңіз болып қалу, тұрақты қаржылық жағдай және жақсы бедел маңызды. Бұған тәртіп, бәріне құрылымдық және жүйелі тәсіл, кез келген жағдайда ақыл-парасат пен сабырды сақтай білу көмектеседі. Сіз кез келген идеяға аяқталған пішін беріп, ой қағазда немесе арманда қалмай, нақты сезілетін нәтижеге айналатындай процестерді құра аласыз. Сіз ұзақ ойлануға бейім емессіз: алдымен жүзеге асыру стратегиясын ойластырып, сосын жоспар бойынша әрекет етесіз. Сізге сәттілік пен жолдың болуына емес, өз жұмысқа қабілетіңіз бен табандылығыңызға сену маңызды.", "5": "Өнертапқыш. Сіз өте ашық әрі іскерсіз, әуестіктеріңіз бен қызығушылықтарыңыз көп, керемет энергиялы әрі белсендісіз. Үнемі өзгеріс пен жаңаруды, оның ішінде саяхатты жақсы көресіз. Жаңалық сізді қорқытпайды — шытырман оқиғаға, кейде тәуекелдіге де батыл барасыз.\nӨмірде сізді өте көп нәрсе қызықтырады, бірақ қызығушылықтың кеңдігінен нәрселерді түсіну кейде үстірт қалады.\nБіліміңіз тереңге бойлаудан гөрі кеңге жайылады. Өмір сіз үшін — тәжірибе алаңы және мүмкіндігінше көп нәрсені байқап, сезінгің келетін қызықты саяхат.\nТабиғи икемділігіңіздің арқасында әртүрлі жағдайлар мен ахуалға тамаша бейімделесіз.\nТіпті елеулі қиындықтар мен тағдыр соққыларынан кейін де өзіңізге тез келесіз. Бұл қабілет харизма мен күшті ішкі энергиямен бірге адамдарды сізге шынымен тартады, сондықтан сізде, сірә, пайдалы таныстықтар мен мүмкіндіктер көп, әлеуметтік белсендісіз.\nСізге авантюризм, шынайы оптимизм, өмірге құштарлық, ақыл икемділігі және ішкі еркіндік тән. Энергиялылығыңыздың арқасында бір мезгілде көп іс жүргізе аласыз. Жалығу, тыныштық және қатаң жоспармен өмір сүру — сіз үшін емес. Сізді таңдау еркіндігі, жаңа мүмкіндіктер, шығармашылық және үздіксіз идеялар ағыны шабыттандырады. Қазіргі жағдайға мәңгі көңілі толмау жаңа істерге итермелейді.\nСізге сәттілік серік: тәуекелге барсаңыз да, әдетте кез келген жағдайдан шығынсыз шығасыз. Бірақ жағымсыз тәжірибе сізге сақтықты үйретпеуі мүмкін — сіз қайтадан авантюраға, кейде заңды немесе моральдық нормаларды бұзумен байланыстыға араласуыңыз мүмкін.\nБір тырмаға қайта баспай, қорытынды жасап, құмарлықтан аулақ болу маңызды. Қиындықты жеңуге мақсаттылық, табандылық және мақсатты анық көру көмектеседі. Сіз өзіңізге сенімге толысыз, ынтамен және құлшыныспен әрекет етесіз — осының арқасында істеріңізге керекті адамдар тартылып, жағдайлар дәл өзіңізге керектей қалыптасады. Сіз айналадағыларды батыл әрі ерекше істерге шабыттандырасыз. Бұған шешендік сыйы мен сендіре білу, үнемі алға жылжуға, дамуға және жаңаны білуге, кез келген араласудан пайда мен мүмкіндік алуға ұмтылыс көмектеседі.", "6": "Тәлімгер. Сізде ерекше табиғи магнетизм бар: адамдарды даналықпен, мейіріммен және айналадағыларға мұқият бола білумен тартасыз. Алайда бұл қасиеттер уақыт өте ашылады.\nЖас кезде өзіне сенімсіздік, өзгенің пікіріне тым құлақ асу әдеті, осалдық пен өкпешілдік, сондай-ақ алға жүруге, дамуға және шешім қабылдауға кедергі келтіретін сақтық көрінуі мүмкін.\nКөбіне тек қиындықтардан өтіп, тәжірибе жинағаннан кейін ғана сіз орасан зор мүмкіндіктерге ие болып, әлеуетіңізді ашасыз. Сіз сенімдірек, ашығырақ және шешімдірек боласыз. Сіз адамдардың көзқарасы мен ойлау тәсілін өзгерте отырып, басқаларға тәлімгер, өзіндік ұстаз бола аласыз.\nСізде жауапкершілік сезімі дамыған, басқаларға қамқорлық жасағанды ұнатасыз. Сіздің ерекше қасиетіңіз — жеке пайдаға ұмтылмау, шынайы өзін құрбан етуге және мейірімділікке қабілеттілік. Ең ұсақ бөлшекке назар аударуыңыздың арқасында басқалардан тереңірек көріп, көбірек түсінесіз.\nТабиғат сізге дамыған түйсік пен ішкі дауысқа ере білуді мол берген, бұл сізді табысқа жетелейді.\nСіз әрдайым отбасында да, өзіңіз жүрген кез келген ұжымда да үйлесім мен тепе-теңдікті сақтауға, дау мен келіспеушілікті жұмсартып, шешуге ұмтыласыз.\nСіз — тамаша тыңдаушы әрі қызықты әңгімелесуші, ұсақ-түйекті байқап, тіпті бейтаныс адамдардың да сенімін тудырасыз. Сұлулықты, өнер мен шығармашылықты жоғары бағалайсыз және осы салаларда жүзеге аса аласыз. Сізге жалпы үлкенірек бір нәрсенің — отбасының немесе қауымдастықтың бөлігі екеніңізді сезіну маңызды: бұл тірек, күш және сенімділік, өміріңіздің маңыздылығы сезімін береді. Әдетте сіз отбасының немесе ұжымның игілігі үшін қамқорлық пен берілгендік таныта отырып, көп күш жұмсайсыз. Сірә, сіз идеалистсіз және мінсіз қарым-қатынасты армандайсыз. Бірақ шын жақын адамды және құндылықтары ұқсас адал достарды әдетте есейген шақта табасыз. Жақындарыңыздың қателесіп жатқанын көрсеңіз де, оларға өз көзқарасыңыз бен қағидаларыңызды таңбауға тырысыңыз. Сіздің міндетіңіз — көмек қолын созып, сұраса, әдеппен, жұмсақ түзету.\nСізге өмірдің әртүрлі саласында тепе-теңдікті сақтау маңызды: рухани мен материалдық арасында (толықтай философияға немесе тек пайдаға кетпей), сондай-ақ бере білу мен ала білу арасында (басқалардан тым көп талап етпей және сонымен бірге өзіңіз құрбан болмай).\nТабиғат сізге берген өзіне-өзі жеткіліктілікті, даналық пен турашылдықты әрдайым сақтаңыз.\nСізді ерекше жылы, қоршап алатын энергия, адамдарға әсер ете білу, адалдық пен өзін аямау ерекшелейді.", "7": "Зерттеуші. Сізді берік адамгершілік өзек пен дамыған ақыл ерекшелейді. Сіз кез келген құбылыстың мәніне терең үңіліп, оны зерттеп, маңызды бөлшектерді таба аласыз. Болған оқиғаны жиі талдап, бастысына шоғырланып, ақылға қонымды қорытынды жасайсыз. Осының арқасында мәселенің оңтайлы шешімін және тиімді құралдарды әрдайым табасыз.\nӨміріңіздегі қиындықтар мен кедергілер кездейсоқ емес — олар өзін-өзі дамыту мен тұлғалық өсу үшін берілген.\nАйналадағылармен араласуда сіз өзіне-өзі жеткілікті және көзқарасыңыз тәуелсіз, сондықтан өз ұстанымыңызды қорғап, жиі дауласасыз. Көбіне тек өз қағидаларыңыз бен әдістеріңізді мойындайсыз. Сіз оңашалық пен жеке кеңістікті жақсы көресіз, кейде өзіңізге үңілесіз — дәл осы күйде шоғырлану және ең салмақты нәтиже алу оңайырақ. Әдетте өмірден не қалайтыныңызды нақты білесіз.\nТабысқа талдау қабілетінің, байыптылықтың, кең білімдарлық пен түйсіктің арқасында жетесіз. Жақсы бағытта дамысаңыз, кеңпейілділік танытып, адамдарға көмектесіп, біліміңіз бен даналығыңызбен бөлісесіз. Бірақ шекараңызды бұзғанда немесе пікіріңізбен санаспағанда, кесіп айтатын және салқын бола аласыз. Сізде өзін-өзі дамытуға және әртүрлі салада табысқа жетуге орасан зор ресурс бар. Дамыған түйсігіңіздің арқасында болашақ оқиғаларды алдын ала сезіп, адамдарды энергетикалық тұрғыдан сезе аласыз. Көбіне «өз толқыныңызда» өмір сүретіндіктен, айналадағылар сізді «бұл дүниенің адамы емес» деп санауы мүмкін, ал өзіңіз кейде өзіңізді «ақ қарға» сезінесіз.\nЕрекше сезімталдығыңыздан сіз дөрекілік пен әдепсіздікті көтере алмайсыз, бірақ өз мінезіңіз құбылмалы әрі қайшылықты.\nЖоғары ақыл, шоғырлана білу және қорытынды жасау ұзақ мерзімді жобалар мен елеулі зерттеулермен жұмыс істеуге мүмкіндік береді. Ынтымақтастықта сізді біліксіздік пен жауапсыздық ашуландырады — оларға тап болғанда, сіз қатты, тіпті кекесінмен айтып, сынауыңыз мүмкін. Өзіңізге тұйықталғанда, айналадағылар сізден алыс «жалғыз жүрушіні» көруі мүмкін — осылай сіздің өзіне-өзі жеткіліктілігіңіз бен адамдарға тұрақсыз қызығушылығыңыз көрінеді. Ал шын мәнінде сіз өте көреген әрі жанашыр бола аласыз. Болып жатқанның бәрінің терең мәні мен әлеуеті бар екенін жақсы түсінесіз, сондықтан эзотерикаға, психологияға және түсініксіз құбылыстарға қызығасыз.\nСізде бай қиял мен шығармашылық ойлау бар.\nТөзім, табандылық және өзгеріске бейімделе білу дағдарыстардан өтуге көмектеседі. Осы қасиеттердің арқасында өз ісіңізде үлкен биікке жете аласыз. Әрекеттеріңіз тек материалдыққа ғана сүйенбесе, мақсат пен танылуға апаратын жол сәтті болады. Ойлағанды жүзеге асыру үшін сізге үнемі өзіңізді танып, жетіліп, жаңа білім алып, өзіңізден жаңа таланттар ашу керек.", "8": "Реформатор. Даму үшін сізге үздіксіз қозғалыс, өзін жүзеге асыру және өзгерістер керек. Бірқалыпты әрі тым жайлы өмір тоқырауға және серпіннің жоғалуына әкеледі. Түсіну маңызды: тек қиындықтар мен күмәндарды жеңу арқылы ғана сіз барлық таланттарыңызды ашып, барлық мүмкіндікті пайдалана аласыз. Сіз сәтсіздік пен құлаудан кейін тез тұрып, қорытынды жасап, жаңа идеялар мен мақсаттарға одан да қатты тұтанып, әрі қарай жүре аласыз. Сізде көшбасшылық қасиеттер, жеңіске деген ерік және айналадағының бәрін қозғалысқа келтіретін қуатты энергия бар.\nЖағдай мен қадамдарды алдын ала есептей білу, стратегиялық ойлау және іскерлік епшілдік алдыңыздан шексіз мүмкіндіктер ашады.\nСіз кедергілерге қарамастан қайта бастап, қалпына келе аласыз. Мінезіңіздің қалыптасуы мен болашағыңыз қиындықтарды қалай жеңетініңізге байланысты.\nІскерлік епшілдік, ерік күші мен еңбекқорлықтың арқасында сіз кез келген іске дерлік кірісіп, онда үлкен табысқа жете аласыз.\nАйналадағыларға сізге жай ғана жолы болатындай көрінуі мүмкін, бірақ шын мәнінде сіздің «сәттілігіңіз» — тынымсыз еңбектің, жауапкершіліктің, табандылықтың, молшылыққа ұмтылыстың, кәсібиліктің, адалдық пен шешімділіктің нәтижесі. Басқалар шегінген жерде сіз кедергіні жеңесіз; басқалар күмәнданған жерде ерік пен тәуелсіздік танытасыз; басқалар демалғанда сіз бүгінгі және болашақтағы молшылығыңыз, жайлылығыңыз бен табысыңыз үшін табанды еңбек етесіз. Сіз қоғамда берік орын алуға, кәсіпқой ретінде қалыптасуға, жақсы табыс табуға және қаржылық тәуелсіз болуға ұмтыласыз. Табиғи қасиеттеріңіз ірі жобалар жасауда, ауқымды процестерді басқаруда және өз бизнесіңізді құруда жақсы ашылады. Үлкен мақсаттар мен елеулі міндеттер сізді қорқытпайды. Ойлағанды жүзеге асыру үшін керекті адамдар мен мамандарды тауып, кәсіпқойлардың үйлесімді командасын жинай аласыз. Дамыған түйсік сізге пайданы көруге, сәтті мүмкіндіктерді ұстауға және мақсатқа апаратын ең жақсы жолдарды таңдауға көмектеседі. Сіз өршіл әрі кәсіпқойсыз және басқалардан да дәл осындай біліктілікті күтесіз, немқұрайдылықты, шала білгірлікті және сапасыз ынтымақтастықты көтермейсіз. Көбіне өзіңізге жұмыс істеу үшін өз ісіңізді таңдайсыз. Энергияны дұрыс қолданғанда әлеуетіңіз соншалықты күшті, сіз жұмыс істейтін жердің бәрінде айқын өзгерістер мен өсу болады.\nСізге бір нәрсеге жай ғана сену қиын — сіз тәжірибеге және нақты сезілетін нәтижеге сенесіз. Сондықтан адамдарды да, жағдайларды да дәл нәтиже мен жеке тиімділік бойынша бағалайсыз. Сіз ақылмен тәуекелге бара аласыз, соңыңыздан ертіп, жеке үлгіңізбен шабыттандырып, ынталандыра аласыз.\nСіз қысымды, не істеу керектігі туралы нұсқауды және міндеттеме таңуды көтермейсіз.\nСіз иілмейтін әрі мақсаттысыз, сондықтан жақсы бағытта дамысаңыз, көбіне билікке, қоғамдағы ықпалға және кәсіби беделге жетесіз.", "9": "Данышпан. Сіз сияқты адамдар іштей өте күшті әрі өзіне-өзі жеткілікті, бірақ сонымен бірге әрдайым өзгеріске, жаңа білімге ашық және әлем туралы түсінігін кеңейтуге дайын.\nСіздің күшіңіз — кеңпейілділікте, мейірімде, жанашыр бола білуде, шынайылық пен табиғилықта. Сіз адамдарға терең жанашырлық танытасыз, сондықтан эмоцияларыңыз тез ауысуы мүмкін — күлкі көз жасына, қуаныш мұңға. Айналадағылармен қарым-қатынаста сізге туа біткен батылдық, шынайылық пен турашылдық тән. Сіздің қызықты қасиетіңіз — қолайлы сәтті сезіп, бақытты мүмкіндікті жібермеу.\nЖүрегіңіздің дауысына ерсеңіз, өмірде үлкен табысқа жете аласыз. Сіз өз ішкі әлеміңізді де, сыртқы жағдайларды да зерттейсіз, жан дүниеңізде идеалистік тілектер мен жарқын үміттер көп. Кейде әлем туралы елестеріңізден шындықты байқамай қалуыңыз мүмкін. Сіз — бәрін жақсыға өзгерткісі келетін, көбіне бүлікшіл мінезі бар нағыз альтруистсіз. Сізде адамдар мен тұтас қауымдастықтарды біріктіру, бірдеңеге шын берілгенде шабыттандырып, соңыңыздан ерту, сендіре білу тамаша қабілеті бар.\nСізге үнемі дамып, ескірген нәрсенің бәрін босата білу, жаңару мен алға жылжу үшін байланыстарды, қарым-қатынастар мен процестерді бұзып, қайта құру маңызды. Бұған нәрселерге кең, сырттан қарағандай қарай білу, ұсақ-түйекте қалып қоймау көмектеседі.\nӨмірлік міндеттеріңіздің бірі — адамдарға көмектесу. Сіздің қызметіңіз басқалардың өмірін жақсартуға, ауқымды жобаларға және қоғамды дамытуға неғұрлым көп бағытталса, соғұрлым көп табысқа жетесіз. Сізге өмір мен әлем құрылысының заңдарын түсініп, себеп пен салдарды ұғынып, соларға сай әрекет ету керек. Қателік үшін «тағдыр бумерангы» сізге басқалардан тезірек әрі сезілерліктей қайтады. Сонымен бірге пайдакүнемсіз көмек те ақылға қонымды болуы керек: адамдарды түсініп, кімге және не үшін көмектесіп жатқаныңызды білу маңызды. Әйтпесе күш пен ресурсты лайықсыз мақсатқа шашып, өмірді бекер өткізуге болады. Бас тартуды, «алу» мен «беру» арасында тепе-теңдікті сақтауды үйреніңіз, өз тілегіңіз бен қажеттілігіңізді ұмытпай, өзіңізге жиі құлақ асыңыз. Сіз сияқты адамдар сараңдықты көтермейді және әрдайым ар-ожданымен, қағидалары мен сенімдерімен үйлесімде өмір сүреді. Сізге өмірге сәл философиялық, бейбітшіл көзқарас тән.\nСіз практиктен гөрі теоретиксіз. Сіздің талғамыңыз тамаша, эстетикалық сезіміңіз нәзік, әсемдікті түсінесіз.\nСіз оқуға, білім алуға және өз ісінің интеллектуалдары мен кәсіпқойларымен араласуға ұмтыласыз.\nҚызығушылықтарыңыздың ауқымы кең: даму үшін бәрі туралы аздап білуді ұнатасыз. Осының арқасында көп нәрсеге үңіліп, әлемге басқаның көзімен қарап, өзгенің көзқарасы мен ерекшелігін айыптамай қабылдай аласыз.\nСіз демократсыз, адамдардың әлсіздігі мен кемшілігіне сабырмен қарайсыз, өйткені бәрі дамудың әртүрлі сатысында екенін түсінесіз.\nСіз әлемді жақсартуға жиі ұмтыласыз, тез беріліп кетесіз және эмоциямен өмір сүресіз. Жеңіс немесе өзін бекіту үшін емес, пікірталасты өзін көрсету және ұстанымыңыздың әділдігін дәлелдеу тәсілі деп көргендіктен, қызу дауласа аласыз. Сірә, сізге күрес, бәсекелестік және жарқын сезімдер ұнайды. Сізге өзіңізге және жолыңызға сенімді болу маңызды — күмән қатты кедергі келтіріп, тежеп, ішкі күш пен ресурсты алады. Күмән азайып, сенім көбейуі үшін өзін-өзі бағалаумен жұмыс істеу керек. Сіз, сөзсіз, оңашалықты бағалайсыз — ол сізге ауыр емес және табиғи, бірақ бұл жалғыз жүру емес. Сіз өзіңізге жеңіл әрі шын қызықты адамдардың ортасынан ләззат алып, үлкен топта да уақытты қуана өткізесіз. Жалғыз болғысы келу әдетте кітап оқуды, сабырлы ойлануды және жаңа білім алуды жақсы көрумен байланысты, бірақ сіз әр әңгімеден, жағдай мен оқиғадан да жаңалық аша аласыз. Тағдыр сізге материалдық әл-ауқатқа және жағымды сыйлықтарға жиі мүмкіндік береді, бірақ сонымен бірге елеулі сынайды: таңдау алдына қояды, жоспарлардың күйреуі мен оңай емес оқиғалар болады. Әрдайым ар-ожданмен әрекет етіп, әр шешімде тек өзіңізді ғана емес, оның басқаларға қалай әсер ететінін де ойлау маңызды. Қағидаларыңызды сақтап, нағыз рухани құндылықтарға сүйеніңіз. Өзгеріс пен жоғалтудан қорықпаңыз — олар ерекше әрі керекті тәжірибе беріп, өзіңізден жаңа қасиеттерді, таланттар мен қабілеттерді ашуға көмектеседі."}, "profs": {"1": "креативті және шығармашылық мамандықтар, басқарушы, директор, менеджер, дизайнер, оқытушы, инженер, нысан басшысы, тәлімгер және куратор, механик, жазушы, заңгер, прокурор, әскери қызметкер, коуч және мотиватор, спикер, іс-шаралар ұйымдастырушысы, контент-менеджер, мемлекеттік қызметкер, саясаткер, логистика маманы.", "2": "қаржыгер, экономист, психолог, коуч, дипломат, мұғалім, тәрбиеші, PR-менеджер, хатшы, басшының көмекшісі, дәрігер, медициналық көмекші, медбике, дизайнер, интерьер дизайнері, кеңесші, сатушы, бағбан, телебағдарлама жүргізушісі, астролог, нумеролог, таролог, туристік агент.", "3": "психолог, нумеролог, астролог, таролог, заңгер, адвокат, оқытушы, жазушы, журналист, копирайтер, менеджер, мейрамхана иесі, бас аспаз, іс-шара жүргізушісі, әнші, актёр, PR-менеджер, дизайнер, турагент, редактор, сатушы, өнертанушы, сыншы.", "4": "басқарушы, өндіріс бастығы, ғалым, музыкант, әскери қызметкер, археолог, бухгалтер, заңгер, экономист, прокурор, талдаушы (аналитик), бағдарламашы, электрик, жобалаушы, инженер, саясаткер, эколог, химик, дәрігер, рухани ұстаз, дін қызметкері, фермер, құрылысшы, жаттықтырушы.", "5": "PR-менеджер, мұғалім, лингвист, аудармашы, журналист, бухгалтер, қаржыгер, саясаткер.", "6": "массажист, зергер, парфюмер, флорист, косметолог, шаштараз, дизайнер, суретші, иллюстратор, психолог, фитнес-жаттықтырушы, фермер, сәулетші, мұғалім, хореограф, безендіруші, ветеринар, кондитер, фотограф, тарихшы, эколог, биолог, ғалым.", "7": "ғалым, заңгер, дизайнер, талдаушы (аналитик), зерттеуші, сыншы, жазушы, мұғалім, астролог, нумеролог, музыкант, инженер, дәрігер, психолог, философ, бағдарламашы.", "8": "қаржыгер, экономист, заңгер, судья, инженер, баспагер, мемлекеттік қызметкер, эзотерик, саясаткер, журналист, басқарушы, директор, әкімші, жазушы, археолог, менеджер, дәрігер, диагност.", "9": "актёр, суретші, дәрігер, хирург, мұғалім, жазушы, драматург, кадр маманы, басқарушы, бөлім басшысы, директор, судья, заңгер, прокурор, турагент, пошта қызметкері, тергеуші, музыкант."}, "spheres": {"1": "жеке бизнес, банк саласы, заңгерлік, саясат, медицина, жылжымайтын мүлік, дизайн, білім беру және оқыту, баспа ісі, кино индустриясы, өнертапқыштық, ақпараттық технологиялар, журналистика, әскери қызмет, ТЖМ және құтқару қызметтері, әкімшілік жұмыс.", "2": "дипломатия, қызмет көрсету саласы, сұлулық индустриясы, тамақ өнімдерімен жұмыс (мейрамханалар және т.б.), өнер, музыка, сән, туризм және қонақ үй бизнесі, медицина және психология, коучинг және тұлғалық өсу, банк ісі және қаржы, PR және жарнама, оқыту, эзотерика, нумерология, астрология, журналистика, сауда, ауыл шаруашылығы және бағбандық, қоғамдық қызмет.", "3": "сауда, сұлулық саласы, өнер, ойын-сауық индустриясы, шығармашылық қызмет, продюсерлік, туризм, баспа ісі, жазушылық, дизайн, журналистика, заңгерлік, психология және тәлімгерлік, ғылым, жылжымайтын мүлік, эзотерика, білім беру, медицина, қайырымдылық, саясат.", "4": "зерттеулер, IT саласы, экономика, психология және психиатрия, медицина, ғарыш техникасы, радио, теледидар және БАҚ, жылжымайтын мүлік, құрылыс және сәулет, дін, нақты ғылымдар, бизнес және сауда, спорт, заң қызметі, саясат, музыка, әскери қызмет, эзотерика, әзірлемелер, зерттеулер мен өнертабыстар, табиғи ресурстармен жұмыс.", "5": "импорт және экспорт, қаржы, шығармашылық қызмет, баспа ісі, жазушылық, оқыту, эзотерика, саясат, БАҚ және журналистика, кино индустриясы, дизайн, жылжымайтын мүлік, медицина, ақпараттық технологиялар, туризм, логистика, сауда, ойын-сауық саласы, лингвистика.", "6": "өнер, жазушылық, сән, сұлулық саласы, дизайн және сәулет, қолөнер (хендмейд), ғылым, жануарлармен және балалармен жұмыс, дін, психология, эзотерика, тамақ өнеркәсібі, өндіріс, фотография, фермерлік, оқыту, денсаулық сақтау.", "7": "ғылыми қызмет, әдебиет, музыка, білім беру және оқыту, эзотерика және емшілік, заңгерлік, зерттеу жұмысы, дін, медицина, психология, химия, PR, дизайн, бағдарламалау және IT-технологиялар, кино индустриясы, философия, өнертапқыштық, талдаумен, зерттеумен және есептеумен байланысты кез келген бизнес, техникалық және ғылыми сала, дәл аспаптар, нәзік қол жұмысы.", "8": "жеке бизнес, саясат, ғылым, қаржы, банк ісі, желілік бизнес, білім беру және оқыту, медицина, заңгерлік, аналитика, жылжымайтын мүлік, жерлеу қызметтері, антиквариат, баспа ісі, БАҚ, халықаралық қатынастар, сатылым.", "9": "кино және театр, көркем сала, білім беру және оқыту, күш құрылымдары (силовые структуры), ТЖМ, заң шығару саласы, медицина және психология, HR, тамақ өнімдері, саяхат, логистика, мемлекеттік құрылымдар, әскери іс."}, "karma_now": {"1": ["Муладхараның ерекшеліктері", "жақсы жағында — жүзеге асыру қабілеті жоғары, денсаулық мықты, төзімділік, кедергілерді жеңе білу.", "әлсіз жағында — денсаулық әлсіз, өмір аман қалу және қиындықтардан өту режимінде, жалқаулық."], "2": ["Свадхистананың ерекшеліктері", "жақсы жағында — ата-ананың арасында тамаша қарым-қатынас болған, араласа білу, өмірден ләззат алу және демалу, бұл сізге берілген.", "әлсіз жағында — ата-ананың арасында оңай емес қарым-қатынас немесе серіктестікте және адамдармен араласуда қиындықтар болған, бұл сізге қарсы жыныспен немесе отбасында кейбір қиындықтар ретінде берілген."], "3": ["Манипураның ерекшеліктері мен міндеттері", "жақсы жағында — ерік пен рух күші, ақша таба білу, көшбасшылық дағдылар, харизма, көшбасшылыққа ұмтылыс.", "әлсіз жағында — еріктің әлсіздігі мен жұмсақтық, ресурстарды басқара алмау, харизманың болмауы, осы чакра аймағында денсаулық мәселелері."], "4": ["Анахатаның ерекшеліктері", "жақсы жағында — жылы жүректілік, қолмен жұмыс істей білу, адамдарды құтқару, емдеу және сауықтыру, сүйе білу.", "әлсіз жағында — эмоциялық күйзелістер мен жан жаралары, махаббаттың жетіспеуі."], "5": ["Вишудханың ерекшеліктері", "жақсы жағында — шығармашылық таланттар, өзін көрсете білу, ашықтық, білім, сондай-ақ карманы осы салалар арқылы шешу.", "әлсіз жағында — дауға бейімділік, тұйықтық, қысылу."], "6": ["Аджнаның ерекшеліктері мен міндеттері", "жақсы жағында — жақсы ақыл, жоспарлай және талдай білу, түйсік, бейнелі ойлау, жұмбақ нәрселерге қызығу.", "әлсіз жағында — тәкаппарлық, қасаңдық (догматизм), интеллектуалдық мүмкіндіктердің әлсіздігі, жоспарлай және бейнемен ойлай алмау, алаңғасарлық, «қиялға берілу»."], "7": ["Сахасрараның психосоматикадан тыс ерекшеліктері", "жақсы жағында — руханилық, саналылық, эзотерикаға қызығу, даналық, нәзік қабылдау, тұлғаның ерекшелігі ретіндегі өзгешелік.", "әлсіз жағында — психологиялық қиындықтар, стресс, шектен шығатын өзгешелік."], "8": ["Себеп денесі мен өмір мәнінің психосоматикадан тыс ерекшеліктері", "жақсы жағында — материалдық және рухани күш, терең мағыналар.", "әлсіз жағында — өмірдің мәнсіздігін сезіну, азап, сергелдең."], "9": ["Карманың ерекшеліктері", "жақсы жағында — талант, данышпандық.", "әлсіз жағында — күрделі кармалық міндеттер, сынақтар мен оқиғалар."]}, "risk": {"1": ["мазасыздық, қорқыныш, алаңдаушылық, сенімсіздік, агрессия, дауға бейімділік, жалқаулық, енжарлық, бос жүрушілік.", "сүйек жүйесі, омыртқа, қан, аяқ, бұлшықеттер, тіс, шаш, иммунитет, ішек, салмақтың қосылуы немесе азаюы, жарақаттар, жаңа өскіндер."], "2": ["жалқаулық, жауапсыздық, ұшқалақтық, сенімсіздік, қызғаныш, бірге тәуелділік (созависимость), тәуелділіктер, кешендер (комплексы), ұят сезімі, кінә сезімі, сезімді көрсетуге тыйым, аналық инстинкттің әлсіреуі, серіктестермен дау, опасыздық, шектен тыс қамқорлық.", "лимфа, несеп-жыныс, ұрпақ өрбіту және бөліп шығару жүйелері."], "3": ["қызғаныш, ашу, басқаларға қысым жасау, алаңдаушылық, шыдамсыздық, ашуланшақтық, мақтаншақтық, ысырапшылдық, сараңдық, дауға бейімділік, апатия, жалқаулық, енжарлық, шешімсіздік, ұят, тәуелділіктер, бірге тәуелділік, материалдыққа берілу, өзін-өзі бағалаудың төмендеуі, қаржылық қиындықтар, ақшадағы шектеулер.", "ас қорыту жүйесі, асқазан-ішек жолы, зат алмасу, тамақтану тәртібі мен сипатының бұзылуы, терінің күйі."], "4": ["өшпенділік, ашу, кінә, салқындық, құрбандыққа бейімділік, алаңдаушылық, менмендік, тәкаппарлық, ашуланшақтық, талапшылдық, фанатизм, сенімсіздік, немқұрайдылық, бақылау, мазасыздық, көңілсіздік, қанағаттанбау, жүрек азабы, опасыздық.", "жүрек-қантамыр жүйесі, жүрек, үрей ұстамалары (панические атаки), өкпе, бронхтар, қан айналымы, омыртқаның кеуде бөлігі, кеуде қуысы, сүт бездері және қолтықасты аймағы, айырша без (тимус)."], "5": ["эмоция мен ойды білдіре алмау, сезімді көрсетуге тыйым, эмоцияны ұстай алмау, тілі келмеу, сөзуарлық, тұйықтық пен ұялшақтық, көпшілік алдында сөйлеуден қорқу, өзін көрсетуден және шындықтан қорқу, дауға бейімділік, өз пікірін қорғап айқайлағысы келу, келісімге барғысы келмеу, шығармашылық дамудың болмауы, тәуелділіктер, заң бұзу, адамгершілік қағидаларды сақтамау, арандатушы мінез-құлық.", "тамақ, көмей, мұрын-жұтқыншақ, қалқанша және қалқанша маңы бездері, дауыс байламдары, өкпенің жоғарғы бөлігі, тіс, жақ, тіл, сөйлеу."], "6": ["ұйқысыздық, оқудағы қиындықтар, қорқыныш пен фобиялар, көңілсіздік, елестер (иллюзии), қалыптасқан үлгімен ойлау, пессимизм, алаңдаушылық, менмендік, фанатизм, материалдыққа берілу, бір нәрсеге байланып қалу.", "ми, көз, құлақ, мұрын, бет нерві, бет, бас сүйек, тіс, жақ, есте сақтау, психосоматика."], "7": ["апатия, көңілсіздік, үрей ұстамалары, психикалық және психологиялық қиындықтар, долылық (истерика), стресс, фанатизм, «Құдай кешені», өзін «ақ қарға» сезіну.", "орталық жүйке жүйесі, психика, шаш, психосоматика."], "8": ["көңілсіздік, мазасыздық, қорқыныш, өзін-өзі бағалаудағы қиындықтар, сараңдық, ашуланшақтық, қатыгездік, дауға бейімділік, кекшілдік, қызғаныш, апатия, пессимизм, материалдыққа берілу, кекесін (цинизм).", "психика, жарақаттар, жаңа өскіндер, өзіне зиян келтіретін мінез-құлық."], "9": ["агрессия, ашуланшақтық, ашу, сенімсіздік, өзімшілдік, сараңдық, сенімнен бас тарту, құрбандыққа бейімділік, әділдік іздеу.", "диагноз қоюдағы қиындықтар, бала көтеру мен оны сақтаудағы қиындықтар, жарақаттар, күтпеген сырқаттар, психологиялық қиындықтар."]}, "neg": {"1": "Икемсіздік, шектен тыс тәкаппарлық пен қырсықтық араласуға және жемісті ынтымақтастыққа кедергі келтіреді.\nӘлсіз жағында мұндай адам жалғыз — түсінілмеген және бағаланбаған күйде қалуы мүмкін.\nБұл ол тек өз шындығын мойындап, басқалардың пікірін, мұқтажы мен ұстанымын ескермегенде болады.\nКелісе алмау, өткірлік, бағалаудағы шектен тыс тіке сөйлеу мен алшақтық адамдарды алыстатады. Сонымен бірге оның дербестігі мен тәуелсіздігін айналадағылар салқындық пен өзімшілдік деп қабылдауы мүмкін.\nҚырсықтық пен тәкаппарлық онда көбіне ашуланшақтықпен, жасырын немесе ашық агрессиямен ұштасады.\nОған өзіне тұйықталып, ұзақ жаман көңіл-күйде жүру тән.\nОл абдырап, жауапкершілік алудан қорқып, шешімнен қашқанда, істер тоқтап қалуы мүмкін. Ал өсу перспективасы болмаса, мұндай адам шығатын жол жоқ сияқты сезініп, апатия мен жалқаулыққа одан да қатты беріледі.", "2": "Жоғары сезімталдық мұндай адамды тым осал, тіпті балаша өкпешіл етуі мүмкін.\nМұнда екі шеткі жағдай болуы мүмкін. Біріншісі — ызалану, ренжіткендерге ашу, басқаларға ұсақ-түйекке бола жабыса беру әдеті, цинизм. Екіншісі — кез келген жолмен дауды болдырмауға ұмтылу, мәселе мен өкпе айтылмай, іште жинала береді.\nНәтижесінде жағымсыз нәрсе жиналып, эмоциялық тұтану болып жарылады (реакция жағдай талап еткеннен әлдеқайда күшті болады) немесе көңілсіз күйге ауысады.\nМұндай адамның әл-ауқаты көбіне айналадағы психологиялық атмосфераға байланысты.\nҚасында ниеті түзу, сабырлы адамдар болса, ол өмірде үлкен табысқа жете алады.\nЖәне керісінше — ұрыс, жүйкелі және шиеленісті жағдай оның ішкі күйін қатты шайқалтып, мүмкіндіктерін тарылтады.\nАдам көп ауыртпалық пен көңіл қалуды бастан өткерсе, ол озбыр болып, күшті тәуелділікке түсуі мүмкін. Оқып, дамып, алға жүруге оған кез келген жаңа тәжірибе мен ақпаратқа сенбеу мен күдікшілдік кедергі келтіреді.\nӘлсіз жағында шектен тыс күдікшілдік, таңдау мен шешім қабылдаудағы қиындықтар да көрінеді. Көбіне адам жай ғана әрекет етуден бас тартады немесе жауапкершілікті басқаларға артады (бәрі өзінен-өзі шешіледі немесе таңдауды басқа біреу жасайды деп күтеді).\nШеткі жағдайларда өзіне және жақындарына немқұрайдылық пайда болады. Басқалардың әрекетінен қайта ауыртпалық пен күйзеліс көргісі келмей, мұндай адам салқын болып, айла-шарғы мен қулық арқылы әрекет ете бастайды.", "3": "Мұндай адам шығармашылықта өзін көрсетпесе, қиналады, ал оның дамуы баяулайды. Жүзеге асу мен ынтасыз ол жалқаулап, өзімшіл әрі ашуланшақ болуы мүмкін.\nӘлсіз жағында жоғары белсенділік жеңілтектікке, тұрақсыздыққа және бір іске ұзақ шоғырлана алмауға айналады.\nСондықтан істер тұрып қалады, өйткені жұмыс жүйесіз жүреді: біресе ұзақ уақыт ештеңе болмай, бәрі бір орында тұрады, біресе орасан көп көлемді бірден орындап, мерзімге үлгеруге талпыныс басталады. Нәтижесінде бұл шамадан тыс шиеленіске, жүйкенің тозуына және күштің көп жоғалуына әкеледі.\nБәріне бірден кірісіп, адам салмақты нәтиже алмай, өзін стресс пен шаршап-шалдығуға душар етеді.\nСонымен бірге ол сәтсіздігіне басқаларды кінәлап, не мұң мен қайғыға түсуі, не агрессия көрсетуі мүмкін. Мұндай сәттерді байқап, үзіліс жасап, өз әрекеттерін талдау маңызды.\nКөбіне мұндай адамдар істе де, тұрмыста да практикалық емес (ысырапшылдыққа және үй шаруашылығын жүргізе алмауға дейін). Сонымен бірге олар тіпті айқын мәселелерді де байқамауы мүмкін.\nЕкінші шеткі жағдай да кездеседі: адам күмәннан азаптанып, таңдау жасай алмайды. Сондықтан істер алға жылжымайды, ал іште дұрыс істеп жатырмын ба деген сұрақ үнемі мазалайды. Нәтижесінде ол әртүрлі эмоцияларды, оның ішінде апатияны сезінуі немесе көңілсіздікке жақын күйге түсуі мүмкін.\nМұндай адам мақсатқа жету тәсілдерін таңдамауы — әдепсіздік танытып, өсек пайдаланып, фактілерді бұрмалауы мүмкін.", "4": "Мұндай адам дауға бейім және өте қырсық болуы мүмкін — соншалықты, қоғамдық тәртіпке, ережелер мен шектеулерге қарсы шығуға қабілетті (әсіресе олар ыңғайсыз, ескірген немесе жасанды түрде таңылған болса).\nСонымен бірге оның өз көзқарасын қорғап, қоғамда бірдеңе өзгертуге энергиясы мен мақсаттылығы жетеді.\nӘлсіз жағында бұл өзімшілдікке және тек өз тілектеріне жол беруге, қырсықтыққа және кесіп айтуға айналуы мүмкін.\nМұндай адам түнерген әрі тұйық болуы мүмкін. Өз мақсаты үшін ол тіпті шындықты айтпай, орындамайтын нәрсесін уәде етуге қабілетті.\nТұрақтылық пен сенімді жағдайға шектен тыс құмарлық дамуға кедергі келтіретін консерватизмге және тіпті ойлаудың шектеулілігіне айналуы мүмкін.\nОл өзгеріс қажеттілігін байқамауы немесе жаңадан бас тартуы мүмкін, сондықтан бәсекелестерден ұтылады. Ішінара себебі — мұндай адамдар мұқият жасыратын өзіне сенімсіздік.\nҚызғаныштан және басқаларға теңесу әдетінен аулақ болу ерекше маңызды. Сенімсіздік пен өз өміріне көңілі толмау адамның айналадағыларды жолы болғыш деп санауына немесе оларды қулық пен адалсыздыққа күдіктенуіне әкеледі. Ол әбігерленіп, өзгенің қадамын қайталауға тырысады, ал бұл сөзсіз қателікке әкеледі.\nМұндай адамның өз жолы бар, ол басқаларды көшіргеннен гөрі әлдеқайда үлкен табысқа әкелуі мүмкін.\nКейде өсуді шектен тыс жауапкершілік сезімі тежейді. Сонда адам әртүрлі қиындықтың алдында тығырыққа тіреліп, шешім қабылдай алмай, бұл мазасыздық пен жүйке шиеленісін тудырады.\nӨз өмірі мен жұмысын аман қалу күресіне айналдыруға немесе жоқ жерден өзіне қиындық жасауға болмайды.\nӘлсіз жағында адам тұрақтылыққа ұмтылыстан мүмкіндіктерін тым тарылтады. Бұл белсенділік пен шығармашылық серпінді сөндіріп, оны бастамасыз, ауыр қозғалатын және шешімсіз етеді.", "5": "Қызығушылықтың кеңдігінен мұндай адамға өмірде бағыт анықтау, өз ісін табу немесе бір әуестікті таңдау қиын. Жүзеге аспағандықтан немесе ұшқалақтықтан мінез бұзылуы мүмкін — күңкілдеу және басқаларды сынау әдеті пайда болады.\nСонымен бірге көзқарас еркіндігі көбіне адамның пікірін күрт қарама-қарсыға өзгертуіне әкеледі. Тіпті басты мәселелердегі мұндай ішкі тұрақсыздық ұзақ жобаларда, қарым-қатынаста және іскерлік ынтымақтастықта қиындық туғызады.\nӘлсіз жағында энергияның үлкен қоры да зиян келтіруі мүмкін: ештеңені соңына дейін жеткізбей, жаңа істерге жармаса беру әдеті пайда болады. Адам міндеттің мәніне үңілмейді, ал бірдеңе болмаса, жауапкершілікті басқаларға артуға тырысады.\nЕрекшеленіп, байқалуға деген ниет тәкаппарлыққа, мақтаншақтыққа және көзбояушылыққа айналуы мүмкін.\nМұндай адам көбіне ақылмен емес, ішкі серпін мен құбылмалы сезімнің әсерімен әрекет етеді.\nАлдымен істеп, сосын ойлау әдеті оның өмірін қатты қиындатады.\nНәтижеге, өміріне немесе оқиғалар барысына алаңдаушылық пен наразылық пайда болуы мүмкін. Бірдеңе ұнамаса, бұл типтегі адамдар өздеріне ұнамайтын нәрседен (заттардан бастап адамдарға дейін) өте оңай қоштасады, осылайша сенімсіздік пен үстірттікті көрсетеді.\nМінезде шектен тыс қозғыштық, жүйкелік, ашуланшақтық көрінуі мүмкін. Солардың әсерімен адам көбіне ойланбаған шешім қабылдап, өз көзқарасын кез келген жолмен таңуға ұмтылып, дауға араласады (тіпті қате екенін түсінсе де).\nМұндай адамдарға шама жетпейді, ал әуесқойлық басым түседі, сондықтан әртүрлі жағдайда олар уақытында тоқтап, істегенін немесе айтқанын ой елегінен өткізуге үлгермейді — айналадағылармен қиындықтар осыдан.", "6": "Адам өмірде, отбасында және жақындарының арасында өз құнын, маңызы мен қажет екенін сезінбесе, өзіне тұйықталып, жалғыздық пен апатияға кетуі мүмкін. Әлсіз жағында ол шектен тыс сынауға, ақыл үйретуге және өзгенің тағдырына араласуға бейім.\nМұндай адам өз пікірінен өзгеше пікірлерді нашар көтереді. Ол қатаң, басып-жаныштайтын және тәкаппар болуы мүмкін. Менмендік пен қырсықтық оған өзіне сырттан қарап, жақындарына қысым жасауды тоқтатуға кедергі келтіреді.\nКөбіне ол сенімсіздік, осалдық пен өкпешілдіктен, тіпті ұсақ-түйекті жүрегіне жақын қабылдап, шиеленісте өмір сүреді.\nӨзгенің пікіріне тәуелді болғандықтан, мұндай адам өзіне сенбей, уәде беріп, оны орындамауы мүмкін.\nӨз кәсібін таппаса, жиі мазасызданып, өзіне күмәнданады.", "7": "Әлсіз жағында адам өз пікірін қатқыл әрі кекесінмен айтып, басқалардың әрекетін сынап, адамдармен қарым-қатынасты қиындатуы мүмкін. Қырсықтық пен үнемі дауласқысы келу болуы мүмкін.\nАлшақтық, жасырындық пен тұйықтық жалғыздыққа және жақындар тарапынан түсінбеушілікке әкеледі — айналадағылар оның немқұрайдылығы мен салқындығын сезеді.\nМұндай адамға көбіне өзін, өз ісі мен мақсат-мұратын табу қиын. Сондықтан көңіл-күйдің ауытқуы, көңілсіздік, қатты абдырау, болашақтан қорқу және мазасыздық пайда болады. Ол мәселені жоқ жерден ойлап шығарып, ұсақ-түйектен үрлеуі мүмкін.\nӨзін-өзі дамытумен айналыспаса және өмірдің рухани жағына қызықпаса, материалдыққа байланып, есепшіл әрі қатыгез болуы мүмкін.\nАқылы дамыған, бірақ өзін-өзі бағалауы төмен мұндай адам өз табысын көзге көрсетіп, басқаларды төмендетіп, кемсіткенді ұнатады.", "8": "Материалдыққа шектен тыс құмарлық адамды есепшіл, өз мүддесіне байланған және тек ақша табуға шоғырланған етуі мүмкін.\nМолшылықты ол еркіндік пен мүмкіндікке апаратын жол ретінде емес, мақсат ретінде қабылдайды. Ол үшін кез келген нәрсе, оның ішінде қатаңдық, айла-шарғы, дөрекілік, билікқұмарлық пен қысым қолданылады.\nТабысқа жеткен соң, мұндай адамдар тәкаппар әрі мақтаншақ болады. Олар нағыз озбырға айналып, басқаларды пайдаланып, бағындырып, олардың шекарасын бұзуы және еңбегі мен оңай болмаған жолы үшін өздеріне көп нәрсеге рұқсат бар деп санауы мүмкін.\nМұндай адам өзін ғана ойлайтын (эгоцентрик) болуы мүмкін, сынды көтермейді және қатесін мойындай алмайды. Ол басқаларға талапшыл және ымыраға келмейді.\nМақсатқа жетпесе, апатия мен көңілсіздікке түсу тәуекелі бар. Сонымен бірге қырсықтық айқын қателерді көруге немесе сырттан берілген кеңесті тыңдауға мүмкіндік бермейді.\nӘлсіз жағында ол сондай-ақ шағымдануға және әрекеттен бас тартуға бейім, өз өмірі үшін жауапкершілік ала алмай, жалқаулыққа беріліп, әлсіздігіне жол беріп, әртүрлі тәуелділікке түсуі мүмкін.\nШешімсіздік, жалқаулық пен үнемі күмән оны тоқтатып, жүзеге асуына кедергі келтіріп, айналадағылармен қарым-қатынасты бұзады.", "9": "Мұндай адам өз мейірімінен зардап шегіп, адамдар мен жағдайларға тәуелді болуы мүмкін. Көбіне ол өзін құрбан еткен адам бұған лайықсыз болып шығады.\nОл бәріне жағуға және ұнауға ұмтылады, сондықтан бетперде киіп, өзі емес, өзін көргісі келетін адам болуы мүмкін. Басқаларға ыңғай жасап, өз қажеттілігін ұмытады.\nМұндай артық, ешкімге керек емес құрбандыққа бейімділік көңіл қалуға, апатияға және кейін түзету өте қиын қателіктерге әкеледі.\nНәтижесінде адам тіпті өзіне қамқорлық жасауды тоқтатып, өз әлеміне тұйықталып, айналадағылардан алыстап, өзі жасаған әлемге, өмірге және жағдайларға наразылықты жинай беруі мүмкін.\nШеткі жағдайда тәуелділіктер, эмоциялық тұрақсыздық және елеулі психологиялық қиындықтар болуы мүмкін.\nӘлсіз жағында мұндай адамда өмірде шынайы, нақты мақсат қоюға кедергі келтіретін елестер көп. Маңызды шешімдерді көбіне қызбаланып, ойланбай, мазасыздық пен серпінге беріліп қабылдайды.\nЕкінші шеткі жағдай да болуы мүмкін — өзін басқаның орнына қоя алмаудан қатаңдық пен төзбеушілік. Сонда ол дауды өз қағидаларын қорғау үшін емес, қырсықтықтан және сынау әдетінен тудырады.\nҚарым-қатынаста мұндай адам тек өз пайдасын ойлап, тәкаппар әрі өзімшіл болуы мүмкін."}, "rel": {"1": "Сізді өзіңізге сенімділік, мақсаттылық, мақсатқа жетудегі табандылық және ерлерге тән ойлау мәнері ерекшелейді. Сондықтан іскерлік салада ер адамдармен ортақ тіл табу сізге оңай. Ал жеке өмірде бәрі оңай бола бермейді.\nҚарым-қатынаста сіз бас болып, маңызды шешімдерді қабылдағыңыз келеді, сондықтан дәл осындай көшбасшының қасында дау тұтануы мүмкін. Бірақ жағынып, кез келген еркелікті орындайтын тым жұмсақ ер адам да сізді ұзақ қызықтыра алмайды.\nМықты мінез жұпта белсендірек болуға және қарым-қатынастың үнін белгілеуге мүмкіндік береді.\nКөбіне сіз не қалайтыныңызды нақты білесіз, өз дұрыстығыңызға сенімдісіз және қырсық боласыз — осымен мұндай кедергілерді жеңуді ұнататын ер адамдарды тартасыз.\nЖеке өмірде сіз үшін махаббаттың денелік жағы да, жан жайлылығы да, таңдаған адамның ақылы да маңызды.\nСонымен қатар оның қоғамда лайықты орны болып, жарқын, бай өмірді жақсы көріп, мансапта табысты болғаны жақсы. Мұндай адамды табу шынымен оңай емес.\nСонымен бірге өзіңізде ерлерге тән қасиеттер көп: турашылдық, тек өзіне сену әдеті, өршілдік. Сізге әйелдік даналық, жұмсақтық пен жол бере білу жетпеуі мүмкін.\nСіз соншалықты дербес әрі өзіңізге-өзіңіз жеткіліктісіз, бір сәтте ер адамдардан мүлде көңіліңіз қалып, жалғыздықты таңдауыңыз мүмкін — және онда сізге ыңғайлы әрі тыныш болады, өйткені көп нәрсені өзіңізге өзіңіз бере аласыз.\nБірақ қысым жасамайтын және дамуыңызға мүмкіндік беретін мінезі мықты, дана әрі харизмалы ер адамды кездестірсеңіз, мұндай одақ берік әрі ұзақ болады.\nСіз үшін ең алдымен қоғамда жүзеге асу және мансаптағы өсу маңызды. Әйтпесе бүкіл энергияңызды отбасына бағыттап, үйдегілерге әмір жүргізе бастауыңыз мүмкін.\nСізде тек үй шаруасындағы әйел, ана және жар болу үшін ішкі күш пен идея тым көп.", "2": "Сіздің екі жақты болмысыңыз әрі күрделі, әрі тартымды: тұрақтылық болжап болмайтынмен, ал ішкі тереңдік жеңіл, үстірт эмоциялармен қатар жүреді. Сіз өте әйелдік, тартымдысыз және ер адамдар үшін көбіне нағыз жұмбақ болып қаласыз.\nСіз — қонақжай үй иесі, адал жар, жанашыр әрі мейірімді адамсыз.\nҚарым-қатынас үйлесімді болуы үшін әрекетіңізде жүйелірек, табиғирақ болып, отбасында сенім атмосферасын жасаған жөн. Сіз — адал серік: серіктесіңізге шын жанашырлық танытып, жақындарыңыздың өміріне араласып, оларға қамқорлық жасайсыз, көбіне өз тілектеріңізді ұмытасыз. Мейірім, шыдамдылық пен нәзіктік сүйікті адамыңыздың кемшілігін кешіруге және басқаларға көну қиын нәрсені байқамауға көмектеседі.\nАл жанжал мен ұрысты ұнатпауыңыз — сізді көп ер адамға қалаулы ететін тағы бір артықшылығыңыз.\nСіз сезімталсыз, романтика мен әдемі қамқорлықты жақсы көресіз. Сіз үшін серіктеспен жан және рухани жақындық, сенім мен адалдық маңызды — өзін-өзі бағалауыңыз бен сенімділігіңіз осыған байланысты. Сіз айналадағылардың көңіл-күйіне нәзік жауап беріп, серіктестің серпініне өте сезімталсыз.\nАгрессия, арсыздық, дөрекілік пен шектен тыс екпін сізге жағымсыз, ал ер адамдағы әдептілік пен ұстамдылықты міндетті түрде бағалайсыз. Сіз қарым-қатынас, әдемі роман мен махаббат туралы көп армандап, серіктес сәйкес келуі керек мінсіз ер адамның бейнесін ойыңызда жасауға бейімсіз.\nКөбіне бұл елестер құлап, көңіл қалып, сезім сөнеді.\nҚарым-қатынаста сіз серіктеске толық сіңіп, оның барлық күйзелісін жүрегіңізге жақын қабылдап, оның өмірімен өмір сүруіңіз мүмкін. Сондықтан өзіңізді бөлек, тұтас тұлға ретінде көруді, өзгенің эмоциясынан алшақтай білуді және даралығыңызды көрсетуді үйрену маңызды.\nСізді жұмбақ, белгісіз, құпия және мистикалық нәрсенің бәрі тартады. Сіз бәрінен ерекше белгілерді байқап, ішкі дауысқа құлақ асып, түйсікке сене аласыз. Қатты әсершілдігіңізден көңіл-күйіңіз бен сезімдеріңіз құбылмалы: тіпті фильм, музыка немесе кездейсоқ естіген сөз шешіміңізге, көңіл-күйіңізге және әрекетіңізге әсер етуі мүмкін.\nСізде жұмсақ әйелдік энергия, көрегендік және терең сезіне білу таңғаларлық түрде ұштасады.", "3": "Сіз — назардың ортасында болуды және жарқын эмоция алуды жақсы көретін өмірге құштар, белсенді әрі тартымды әйелсіз.\nТіпті қарым-қатынаста болсаңыз да, сіздің сәл қылымсуыңыз (флирт) таңқаларлық емес — сізді жеңіл ойын мен өз тартымдылығыңыздың расталуы қатты қызықтырады. Сіз байыпты әрі іскерсіз, жұмыста да, отбасында да көбіне көп міндетті өз мойныңызға аласыз.\nСіз өмірге әрдайым оптимизммен қарайсыз, болашаққа жоспар мен үмітке толысыз. Шынайылық, табиғилық пен белсенділік сізге ұзақ уақыт энергиялы болып, жасыңыздан жас көрінуге көмектеседі. Сізбен ешқашан жалықтырмайды, сондықтан үйлесім үшін сізге лайық серіктес керек: мақсатты, ақылды, энергиялы әрі жеңіл қозғалатын ер адам.\nҚарым-қатынаста сіз көбіне ең алдымен өз мүддеңізді ойлайсыз, сондықтан түсінбеушіліктен қиындықтар болуы мүмкін — серігіңіздің тілектері екінші орынға ысырылуы мүмкін. Сүйкімді әрі тәуелсіз сіз өзін білдіру еркіндігін бағалайсыз, бақылау мен шектеуді нашар көтересіз.\nСізде өмірлік жоспар көп, кенеттен пайда болған тілектерді де орындауға тырысасыз. Түйсік пен шабытпен әрекет ете отырып, мансап құрып, материалдық молшылыққа жете аласыз. Сіз дос бола білесіз, жақын қарым-қатынаста адал серіктессіз. Алайда бірдеңе көңіліңізге жақпаса, қарым-қатынасты үзуден қорықпай, ұшқалақ әрі кенет әрекет етуіңіз мүмкін — өйткені жалғыздықтан қорықпайсыз, жалғыз да сирек әрі аз уақыт қаласыз. Серіктестің пікіріне құлақ асып, оның қажеттілігін ескеріп, оған жетекші рөл берсеңіз немесе ең болмаса шешімді бірге қабылдасаңыз, берік одақ қалыптасады. Тапсыруды үйреніп, бәрін өз мойныңызға артпаңыз — сонда жұмыста да, үйде де шаршап-шалдығудан аулақ боласыз. Жеңілдігіңіз бен оптимизміңізді сақтап, оларды серігіңізбен бөлісіп, оны ұлы істерге шабыттандырыңыз.\nСізге шығармашылық және интеллектуалдық таланттарды ашуға болатын қоғамда жүзеге асу керек — сонда серіктеспен қарым-қатынас та үйлесімді әрі берік болады.", "4": "Сіз сияқты әйел көбіне мансапта табысты, жиі жақсы табыс табады, практикалық әрі ұйымдасқан.\nШынайы көзқарас пен ақыл-парасат сізді аяғында берік тұрған және сіз үшін жауапкершілікті алуға дайын қамтамасыз етілген серік іздеуге итермелейді.\nҚарым-қатынаста сізге болашаққа сенім, тұрақты молшылық және үйреншікті өмір деңгейін сақтау мүмкіндігі маңызды.\nАлайда жеке өмірде қиындықтар да болуы мүмкін: қызғаныш, дау, түсінісу немесе жалғыз қалмау үшін ер адамға шыдауға дайын болу. Мұның бәрі сіз тұрақтылықты жақсы көріп, тәртіпке, анықтыққа және бірқалыпты өмірге үйреніп кететініңізден.\nСізге ер адамның өз сезімін іс-әрекетпен үнемі растап отырғаны маңызды. Өзіңіз ұстамды болып, шынайы сезіміңізді көрсетпеуіңіз мүмкін, өйткені махаббат пен нәзіктікті ашық әрі жиі көрсетуге үйренбегенсіз. Сіз сенімділікпен, ақыл-парасатпен және тұрақтылықпен тартасыз. Серіктесте жауапкершілікті, қаржылық тұрақтылықты, адамгершілікті және өсу перспективасын бағалайсыз. Сіз үйіңізді жақсы көресіз, шаруашылықты ақылмен жүргізіп, отбасы бюджетін практикалық басқарасыз.\nСізге жайлылық пен жан тыныштығы, отбасындағы тәртіп пен дәстүр керек. Сіз күйеуіңізді әрдайым қолдауға дайынсыз, оның әуестіктері мен құндылықтарын бөлісіп, мансапта өсуіне көмектесесіз. Мұндай серіктің қасында мақсатқа жүру әлдеқайда оңай. Қиындықтар нақты жағдайды көргіңіз келмей, наразылықты сезіне тұра, ештеңе өзгертпей, әдетпен жүре бергенде басталады.\nСізге сезімді көрсетуде және қарым-қатынасқа көзқараста сізге ұқсас жауапты, сенімді әрі мақсатты ер адам келеді. Дәл осындай серіктес сізге қауіпсіздік пен тұрақтылық сезімін сыйлап, мейірімді әрі ыстық жүрегіңізді сезіп, бағалайды.", "5": "Сіз сүйкімділікпен, табиғилықпен және керемет энергиямен тартасыз. Араласуды өте жақсы көресіз және назардың ортасында болғанды ұнатасыз.\nСізге ер адамдардың ортасы ұнайды, ер адамдарға әрдайым жол табасыз, сәл қылымсып, мақтау сөзден ләззат алуға қарсы емессіз.\nСіз сенімділік пен тәуелсіздік таратасыз, бірақ сонымен бірге айналадағы атмосфераға және жақындардың эмоциясына өте сезімталсыз.\nСізге айналадағылардың құрметін, қолдауы мен мақұлдай қарағанын сезіну маңызды. Сіз әрдайым қоғамда жүзеге асуға және дамуға ұмтыласыз. Еңбекқорлық пен адамдарды түсіне білудің арқасында көбіне ер әріптестеріңізден табысты жұмыс істейсіз. Сондықтан келіссөзді сәтті жүргізу немесе қарсыластарды өз жағыңызға тарту керек болса, дәл сізді шақырған дұрыс: сіз мұны соншалықты жеңіл, жағымды әрі епті істейсіз, айналадағылар барлық мүмкіндік пен бонусты сізге қалай бергенін байқамай қалады. Көбіне өзіңізге ыңғайлы адамдарды таңдайсыз: қолдай алатын, жүзеге асуға көмектесетін немесе ең болмаса өзіңіз болып қалуға кедергі келтірмейтін. Шешімде дербессіз және ешкімге мінез-құлқыңыз бен әрекетіңізді басқаруға жол бермейсіз. Сүйіктілеріңізбен шын жүректен сөйлесіп, жылы сезім танытып, қолдап, шын қамқорлық жасайсыз. Сізге ашық әрі сенімді қарым-қатынас ұнайды, серіктестен тек сүйіктіні және досты ғана емес, жан жарын да көргіңіз келеді.\nӨз тарапыңыздан қарым-қатынасқа өмірге деген махаббат, болжап болмайтындық, табиғилық пен сезімді көрсетудегі еркіндік әкелуге әрдайым дайынсыз.\nСіз дос бола білесіз және ұзақ қарым-қатынас құра аласыз, бірақ жақындарыңызға ойыңызда не бар және келесі минутта қалай әрекет ететініңіз әрдайым түсінікті бола бермейді.\nИмпульсивті шығармашыл болмысыңызды теңестіріп, серпіндеріңізді бағыттауға көмектесетін практикалық, өзіне-өзі жеткілікті ер адаммен берік одақ құрылады. Бірақ оған сіздің өзгеріс пен әртүрлілікті жақсы көретініңізді есте ұстап, күнделікті бір сарыннан аулақ болып, анда-санда сізді таңғалдырып, артықшылықтарыңызға тәнті болған жөн.", "6": "Сіз мейіріммен, сезімталдықпен және пайдакүнемсіздікпен баурайсыз, бірақ алғашқы көзқараста алыс әрі ұстамды көрінуіңіз мүмкін.\nСіз романтиканы жақсы көресіз, жиі елес құрып, армандарға кетесіз — сізде тамаша қиял мен бай фантазия бар.\nСіздің түйсігіңіз мықты әрі қабылдағышсыз, сондықтан әлсіз жағында көбіне айналадағылардың пікіріне тәуелді болып, өзгенің бағасына тым үлкен мән бересіз.\nСіз отбасын құрғыңыз келеді және байыпты қарым-қатынасқа ұмтыласыз. Махаббатқа өте жауапты қарайсыз, бір адаммен өмір бойы некеде болуды армандайсыз. Бақытыңызға таңдауыңызға деген күмән, сондай-ақ тартымдылығыңыз бен сұлулығыңызға сенімсіздік кедергі келтіруі мүмкін.\nӨзгенің пікіріне азырақ сүйеніп, айналадағылардың бағасына азырақ тәуелді бола отырып, өзін-өзі бағалаумен жұмыс істеу маңызды. Әдетте туыстарыңызбен қарым-қатынасыңыз жылы: олардың өміріне араласып, оларға қамқорлық жасайсыз, өйткені отбасы, неке мен балалар сіз үшін әрдайым бірінші орында. Тіпті ер адаммен ажырассаңыз да, өкпе мен өзара наразылықсыз қалыпты, достық қарым-қатынасты сақтауға тырысасыз.\nСіз — әрдайым көмектесуге, қолдауға және пайдалы кеңес беруге дайын сенімді досыңыз. Дамыған түйсіктің арқасында сізді пайдаланып жатқанын сезіп, мұндай араласуды тоқтатасыз. Көбіне сіз қарапайымсыз, бірақ баурап алып, ер адамдарда құштарлық оята аласыз. Көбіне махаббаттың әр сәтінен ләззат алып, назар аударғанды, қылымсығанды ұнатасыз. Қарым-қатынаста сіз үшін сезімталдық пен өзара сезім көп нәрсені білдіреді.\nӘлсіз жағында жүйесіздік, өкпешілдік пен тіпті ұсақ-түйекке бола эмоцияның тұтануы болуы мүмкін. Сізге өзіңізді қауіпсіз әрі ер адамның қорғауында сезіну, оның сезімдеріңізге назарын және шынайы қамқорлығын сезіну өте маңызды. Әбігер мен тұрмыс сізді тартып әкетуі мүмкін, сондықтан таңдаған адамыңызға жиі романтикалық кездесулер ұйымдастырып, сезімін еске салып отырған жөн. Сізге үйлесімді қарым-қатынасты тек шын сезімтал, адал әрі сүйетін ер адам ғана сыйлай алады.", "7": "Сізді ерекше ақыл, тартымдылық пен жұмбақтық ерекшелейді. Түйсігіңіз дамыған, ішкі дауысыңызды естіп, адамдарды нәзік сезесіз, сондықтан сізді алдау оңай емес. Сізді құпия, мистикалық және белгісіз нәрсенің бәрі тартады, сондықтан эзотерикаға, психологияға және әртүрлі философиялық ілімдерге қызығуыңыз мүмкін. Сіз — сүйкімді әрі тәуелсіз әйелсіз және өзіңізді ең жақсы жағынан көрсете аласыз.\nӘдетте сіз аяғында берік тұрған, сізге тірек бола алатын және сонымен бірге жеке кеңістігіңізге басып кірмейтін қамтамасыз етілген әрі ықпалды ер адамды іздейсіз. Сіз ерекше сүйкімділікпен, әдептілікпен және даналықпен тартасыз. Өмірде себебі өзіңізде екенін және ой мен әрекетті өзгерту керек екенін толық түсінбегендей, бір қатені қайталауға бейімсіз. Бірақ себебін түсінсеңіз де, көбіне елестермен қоштасқыңыз келмей, әрекетсіз қалып, сылтау іздейсіз. Көбіне қарым-қатынаста бас болғанды қалайсыз, көп әрі жемісті жұмыс істеп, табысқа жете аласыз. Өзіңізге-өзіңіз жеткілікті болсаңыз да, жан түкпіріңізде жалғыздықты сезінуіңіз мүмкін. Сонымен бірге жай ғана ер адамның көлеңкесі болуға дайын емессіз және тәуелсіздігіңіз бен таңдау еркіндігіңізді әрдайым қорғайсыз. Сізге қамқор, адал әрі некеге бейім ер адамдар ұнайды.\nСіз серігіңізге өз шектеулеріңізді, қорқыныштарыңыз бен кешендеріңізді беруге қабілеттісіз. Әлсіз жағында ер адамды бағаламауыңыз немесе оның шынайы ниеті мен серпінін түсінбеуіңіз мүмкін. Қарым-қатынаста үйлесімге келу үшін серіктеске өз бетінше шешім қабылдауға мүмкіндік беріп, оның пікірін құрметтеп, маңызын мойындаңыз. Өзіңізге сенімділікті нығайтып, өзін-өзі бағалауды көтере отырып, азырақ бақылап, ер адамға көбірек сеніңіз.", "8": "Сізде харизма, ішкі күш пен шешімділік бар. Сіз мақсатты әрі екпіндісіз, бәрін өзіңіз жеңуге үйренгенсіз және қиындықтан қорықпайсыз. Кедергілерге қарамастан, алға оптимизммен қарап, әрекет ете бересіз. Жаман көңіл-күйде ұзақ қалмайсыз, айналадағыларды шабыттандырып, оларды табиғи энергияңызбен қуаттай аласыз. Сіз көп жұмыс істеп, табыс тауып, аяғыңызда берік тұруға ғана емес, рухани дамуға да ұмтыласыз.\nСіз шектен шығуға бейімсіз: біресе бәріне жағуға тырысасыз, біресе керісінше, басқалардың сезімі мен қажеттілігін байқамай, тек өз пайдаңыз бен тілегіңіз үшін әрекет етесіз. Сізде ерікті, нағыз күрескер, ерлерге тән мінез бар. Сырттай эмоция мен сентименталдылықта ұстамды болуыңыз мүмкін, бірақ оның артында махаббат пен қамқорлықты, құрмет пен қабылдауды армандайтын сезімтал, құштар әрі осал болмыс жасырынып жатыр. Сізде құштарлық пен сезімталдық практикалық пен тұрақтылықпен таңғаларлық үйлеседі.\nМахаббатта сіз өзіңізді толық бересіз: қолдау, қамқорлық, қаржылық көмек. Сізге ұнамайтын нәрсеге ұзақ шыдап, кейін бәрін өкінбей бірден үзуіңіз мүмкін. Жұпта қажеттіліктеріңіз, қорқыныштарыңыз бен күйзелістеріңіз туралы айта бастау маңызды — әйтпесе айтылмаған эмоциялар мен мазасыздық жиналып, сізді іштей бұза бастайды. Әлсіз жағында қарым-қатынасты жоқ жерден қиындатып, өзіңіздің және ер адамыңыздың өмірін бұзу әдеті пайда болуы мүмкін. Серіктеске сізден тергеу алмаған, қызғанбаған, кемшілігіңізді алға шығармаған және серпініңізді тежеуге тырыспаған жөн. Сізге сенім мен құрмет керек, өйткені сіз өте адал әрі сенімді серіксіз.\nСіз үшін мінсіз серіктес — мінез күші мен табандылық жағынан сізден кем түспейтін, өзіне-өзі жеткілікті және өмірлік қиындықтардан қорықпайтын, әзілді түсінетін ақылды ер адам. Мұндай серікті сіз құрметтеп, онымен бақытты бола аласыз.", "9": "Сіз — іскер, жан-жақты әрі ерік-жігері мықты әйелсіз. Өмірде сізге көбіне қиындықтарды жеңіп, өз пікіріңіз бен көзқарасыңызды қорғауға тура келеді. Сізді өмірді мағынаға толтыратын және оны әртүрлі ететін нәрсе қызықтырады: саяхат, өзін тану, рухани даму, қызықты адамдармен араласу. Сіз жақсылыққа, мейірімнің жамандықты жеңетініне, ал жанашырлық пен өзара көмектің адам өмірінің негізі екеніне шын сенесіз.\nЖоғары сезімталдығыңыздан қарым-қатынаста қызғанып, ұсақ-түйекке бола ұрысып, дау бастауыңыз мүмкін. Даналық пен серпіндеріңізді жеңе білу тек жылдар өте келеді. Көпшілік алдында сіз ұстамдысыз және өз эмоцияңызды да, айналадағылардың жағымсыз көңіл-күйін де басуды білесіз. Бірақ бір сәтте ешкімге аз көрінбейтіндей жауап беруіңіз мүмкін — бұл «жанартауды» оятпаған жақсы.\nСіз өзіңізге қамқорлық жасап, жақсы көрінуге тырысасыз және нәзік талғамыңызға сай әдемі заттармен қоршайсыз.\nӨмір бойы шынайы өзіңізді, стиліңізді табу және өзіңізді жақсы көру оңай емес, сондықтан көзқарас пен таңдауда бір жақтан екінші жаққа ауытқуыңыз мүмкін. Сіз мәдениет пен өнерді түсінетін ақылды, дамыған адамдармен араласқанды ұнатасыз.\nКөбіне сізді дәл осындай тәуелсіз әрі шығармашыл адамдар қоршайды. Сізді ерекше ойлау, өзіне-өзі жеткіліктілік және шығармашылық ойды жүзеге асыра білу ерекшелейді. Сіз әрдайым қызықты идеяларға толысыз және бірге дамып, қоғамдық өмірге қатысуға болатын қызығушылықтары ұқсас ер адамды таңдауға тырысасыз. Серіктеске үнемі ақыл үйретіп, біліміңізді көрсетіп, одан жоғары тұруға тырыссаңыз, қарым-қатынас қиындауы мүмкін. Сіз сияқты әйелдердің болашақ күйеуге талабы көбіне жоғары, сондықтан өз адамыңызды табу айтарлықтай қиын. Жалғыздықтан қорқып, өзіңізді толық беріп, бірақ шынайы махаббатты танымай, жай ғана қарым-қатынас үшін қарым-қатынасқа түсуіңіз мүмкін.\nСәтсіз қарым-қатынас пен махаббаттан көңіл қалғаннан кейін тәуелділікке түсуіңіз немесе өзіңізге тұйықталып, жалғыз жүрушідей өмір сүруіңіз мүмкін. Отбасында сіз уақытыңызды, ақшаңызды және ыңғайыңызды құрбан етіп, әрдайым көмектесуге, қолдауға және жәрдемге келуге дайынсыз. Сізге төлқұжаттағы мөрден гөрі бірлік, адалдық пен өзара түсіністік маңыздырақ одақ қызық. Сіз серіктестердің еркіндігін шектемей, дамуға мүмкіндік беретін, сенім мен жан туыстығына құрылған қарым-қатынас іздейсіз. Сіз үшін жақындықтағы үйлесімділік пен дене тартылысы үлкен рөл атқарады.\nСенімді, құштар әрі адал ер адаммен үйлесімді қарым-қатынас құрылады. Тек материалдық жайлылық пен тұрақтылықты ғана емес, еркіндік пен жарқын, әртүрлі өмір сезімін де сыйлайтын серіктес сіздің бүлікшіл жүрегіңізді мәңгі жаулап алады."}, "skills": {"1": "Сізге мүмкіндігінше дербес — қатаң нұсқау мен қысымсыз жұмыс істеу маңызды.\nЖүзеге асуыңыз бен мансабыңызды сын, кәсіби өсудің болмауы және еңбегіңіздің мойындалмауы тежеуі мүмкін.\nБір сарынды кеңсе жұмысы мен күнделікті әдет сізді шабыттандыра қоймас.\nЖұмыста сіз үшін идеяны жүзеге асырудағы еркіндік және шешімді өзіңіз қабылдау құқығы ерекше маңызды.\nСіз әртүрлі адамдармен оңай ортақ тіл табасыз.\nАйналадағылардың бәрін қозғалуға және әрекет етуге итермелеп, ынталандырып, жұмыс процестерін реттеуге көмектесе аласыз.\nКүшті ұйымдастырушылық қабілет пен жұмыста заманауи технологияларды қолдануға ұмтылыс сізге бәсекелестерден айқын артықшылық береді.\nСіз көзқарасыңызда дербес әрі тәуелсізсіз, бірақ сонымен бірге тұрақты әрі жауаптысыз.\nСізге әрдайым сенуге болады, алайда сіз іске немқұрайды қарауды, айналадағылардың баяулығы мен жалқаулығын көтермейсіз.\nСіз еңбекқорсыз, орасан зор ішкі күшіңіз бар және тіпті күрделі міндеттерге де құлшыныспен кірісесіз.\nІскерлік епшілдік, жылдам шешім және мақсатқа жету тәсілдерін таңдаудағы нақтылық сізге көшбасшы болуға және басқалар үшін жауап беруге мүмкіндік береді.\nСіз үшін белгіленген мақсатқа жетіп, нәтижені көру маңызды.\nСонымен бірге сізге толық әрекет еркіндігі керек: шешімді өз бетінше қабылдап, нәтижеге апаратын жолды таңдау мүмкіндігі.\nБірдеңе жоспар бойынша жүрмесе, сіз ашуланып, көңілсіз күйге түсуіңіз мүмкін.\nТамаша басшылық қабілетіңізге қарамастан, көбіне көмекшілер мен командаға сенбей, жалғыз жұмыс істегенді қалайсыз.\nҰшқыр ақыл, белсенділік пен креативті идеялар бизнестің кез келген бағытын дамытуға, оның ішінде стартаптар бастауға көмектеседі.\nСізге күмән мен қорқыныштан бас тартып, көбірек әрекет етіп, жұмыста шешімділік пен бастама танытып, тәжірибеден қорықпау маңызды.\nЖұмыста сізге серпін, араласу және шығармашылықпен өзін көрсету мүмкіндігі ләззат әкеледі.\nАл күш-жігеріңізді лайықты бағаламаса, сірә, мұндай орынды ұстамай кетесіз — мүмкін, өз ісіңізді ашасыз.\nЖұмыста сізді бәсекелестік және үнемі жаңа тауашалар мен позицияларды жаулап алу қуантады.\nБасқарғанда сізді дағдарыс пен форс-мажор қорқытпайды: бірдеңе дұрыс болмаса, тез тәртіп орнатып, жұмыс процестерін реттейсіз.\nСізге табысты адам және өз саласындағы кәсіпқой әсерін қалдыру ұнайды.\nСізбен жұмыс істеу әдетте жеңіл әрі жағымды — сізбен байланыс және ортақ нүкте табу оңай.\nСіз айналадағыларды өз энергияңызбен, мақсаттылығыңызбен және оптимизміңізбен қуаттайсыз.\nСіз үшін мінсіз нұсқа — жеке бизнес немесе серіктестермен бірге бизнес. Ірі компаниядағы немесе басқару саласындағы басшылық лауазым да келеді.\nБелсенділігіңіз бен ұйымдастырушылық талантыңызды көрсетуге болатын мемлекеттік немесе саяси құрылымдардағы жұмыс та тамаша келеді.", "2": "Сіз көбіне туа біткен психолог әрі дипломатсыз: өткір бұрыштар мен қайшылықтарды жұмсартып, дауды басуды білесіз.\nСізге өзіңізге ғана емес, айналадағыларға, оның ішінде әріптестерге де жайлы атмосфера жасау маңызды — және бұл сізде тамаша шығады!\nСондықтан жұмыстың сіз үшін екінші үйге айналуы таңқаларлық емес.\nСіз ұжымға қатты байланасыз: жұмыста бәрі жақсы болса, жаныңыз да тыныш.\nСізде қуатты түйсік бар — сіз адамдарды, олардың көңіл-күйі мен қажеттілігін шынымен сезесіз және мәселені шешудің жолын әрдайым табасыз.\nСізге араласумен және адамдарға көмекпен байланысты жұмыс келеді. Жайлы жағдайда сіз өзіңізді іске толық арнап, жұмысқа шектен тыс берілген адам болуыңыз мүмкін. Сіз айқын көшбасшы емес, өз идеяларын байқатпай жылжытып, басшылыққа ықпал ететін өзіндік «сұр кардинал» болуыңыз мүмкін.\nӨзгенің ойын шынымен «оқи» білу және өзін басқаның орнына қоя білу ұжымды біріктіруге көмектеседі.\nӨз ісіңізді ашсаңыз, сізге міндетті түрде кәсіпқойлар командасының қолдауы керек.\nЖақын адамдармен және туыстармен жұмыс та мүмкін — бұл сізге тұрақтылық пен жайлылық сезімін береді.\nСізге ішкі тыныштық, тұрақтылық пен бірқалыптылыққа деген сүйіспеншілік тән.\nСіз ұсақ-түйекке мұқиятсыз және жұмысқа әрдайым өте жауапты қарайсыз. Сіз ісіңізді жақсы көресіз және процеске толық енесіз.\nСізге істе де, араласу ортасында да қолдауды, маңызыңыз бен керек екеніңізді сезіну өте маңызды.\nСізді құрметтейтін, бағалайтын, пікіріңізге құлақ асатын және шабыттандыратын кері байланыс беретін жақсы командада сіз нағыз серпіліс пен жетістікке қабілеттісіз.\nЖұмыста қасыңызда тәжірибелірек әрі дана тәлімгер — беделін мойындайтын, күмән сәтінде қолдайтын, сенім беріп, батылырақ әрекетке итермелейтін адам болса, тамаша.\nКейде сізге күмән, шешімсіздік, көңіл-күйдің ауытқуы, шектен тыс эмоционалдылық және бәрін жүрекке жақын қабылдау әдеті кедергі келтіреді.", "3": "Сізге өзіңізді және тұтандырып, шабыттандыратын ісіңізді табу өте маңызды.\nТек сонда ғана сіз ынта, еңбекқорлық, шынайы қызығушылық танытып, әлеуетіңізді толық аша аласыз.\nЖұмыстың ақшалай жағы да маңызды, бірақ іске деген сүйіспеншілік пен берілгендіксіз тіпті ең лайықты жалақы да сізді берілгендікпен еңбек етуге мәжбүрлемейді.\nАл өз салаңызды тапсаңыз, онда үнемі оқып, өсіп, білім мен кәсіби дағдыларды жетілдіру маңызды.\nАшықтық пен ерекше ойлау табысыңызға көмектеседі.\nБайланыс орнату сізге оңай, сізде шешендік сый мен жоғары ақыл бар.\nСіз командада да, басшылық лауазымда да сәтті жұмыс істей аласыз.\nСіз ірі жобаларға және шығармашылық идеяларды жүзеге асыруға қуана кірісесіз. Бағынғанды ұнатпайтындықтан, әдетте компанияда жоғарырақ орынға ие болуға немесе өз ісіңізді құруға ұмтыласыз.\nСізге табыс пен өз маңызыңыз маңызды, сондықтан мақтау мен кәсіби еңбегіңіздің мойындалуына немқұрайды емессіз.\nСіз басқаларға қуана көмектесіп, олардың идеялары мен шығармашылық серпінін қолдап, айналадағылардың табысы мен гүлденуіне ықпал етесіз.\nСіз бір мезгілде бірнеше істі — сәтті әрі өнімділікті жоғалтпай жүргізе аласыз.\nШабыттанғанда сізде әрдайым көп жоспар, мақсат пен қиял болады, және оларды қалай жүзеге асыруды нақты білесіз. Көбіне басыңызға тұрарлық ой келгенде, «Неге байқап көрмеске?!» қағидасымен іске бірден кірісесіз.\nСіз бизнесте сенімді серіктессіз, бірақ сізге құрметтейтін және бағалайтын адамдармен жұмыс істеу керек.\nСізге өршілдік, жаңаны байқап көруге, ерекшеленуге және байқалуға ұмтылыс тән.\nСіз үшін мінсіз жұмыс — шешендік қабілет пен басқару дағдыларын қолдануға, ерекше шығармашылық тәсілді дамытуға және ерекше міндеттерді шешуге болатын жұмыс. Сонымен бірге әрдайым өсу перспективасы болғаны маңызды.\nАл дамусыз, қатаң кестесі мен қатаң иерархиясы бар күнделікті бір сарынды жұмыс сізді тез жалықтырып, мезі етуі мүмкін.", "4": "Сізде талдау ақылы, дамыған логика және практикалық бар.\nСіз кез келген жобаның құрылымын құрып, сауатты жоспарлап, схемалар мен жүзеге асыру жолдарын жасай аласыз.\nСізге салмақты шешімді, бөлшекке назарды және қарқынды ой еңбегін талап ететін нәрсенің бәрі жақсы шығады.\nСіз — барынша ақылға сүйенетін әрі практикалық, сенімді әрі тұрақты адамсыз.\nСонымен бірге сіз жасырын әлеует пен өсу мүмкіндіктерін байқап, оларды уақытында, белсенді пайдаланасыз.\nСіз үшін шешілмейтін міндет пен жеңілмейтін кедергі дерлік жоқ.\nСізді жоғары жауапкершілік және жобаның перспективасын басқалардан жақсырақ көріп, бастағанды нәтижеге жеткізе білу ерекшелейді.\nТабыс үшін сізге түйсікті дамытып, позитивті ойлауды үйреніп, адамдарға түсіністікпен қараған жөн.\nКөбіне сіз ерекше ойлайсыз және өзіндік бүлікшіл боласыз.\nӘлсіз жағында бұл басшылыққа бағынбауға, әріптестермен дау мен айтысқа айналады.\nӨзіңіз және өмір туралы күрделі сұрақтарды түсінуге сенім және әлем құрылысының басты заңдарын түсіну көмектеседі.\nӨзіңізге немесе шағын компанияда, міндеттер шеңбері нақты белгіленген тар салада жұмыс істеген жақсы.\nӘріптестер мен бастықтың араласуынсыз әрекет етіп, шешім қабылдауға болса, тамаша, өйткені сіз сияқты адамдардың біліктілігі әдетте жоғары.\nЛайықты жұмыс орнын тапсаңыз, онда ұзақ қала аласыз — сіз жиі өзгерісті ұнатпайсыз және таңдауыңызда көбіне консервативсіз.\nБірақ сіз практикалықсыз, сондықтан материалдық жағынан тиімдірек ұсынысқа келісесіз.\nСіз кәсіби өсуге ұмтыласыз және қызықты жоба үшін басқа қалаға немесе елге көшуге дайынсыз.\nАйтпақшы, тамаша мүмкіндіктер мен табыс сізге көбіне дәл орын ауыстыру мен көшу арқылы келеді.\nСізге тәлімгерлік пен оқыту жақсы келеді, өйткені бұған сарапшылық біліміңіз бар.\nЖұмыста сіз мінсіздікке (перфекционизм) бейімсіз, бастысына шоғырланып, ұсақ-түйекке алаңдамайсыз.\nСіз мұқият әрі жүйелі еңбек етіп, айналадағыларға сенімділік пен сабырды шынымен жұқтырасыз, сондықтан сізге жиі көмек пен кеңес сұрап келеді.\nСіз тырысқақ әрі жауаптысыз, жалықтыратын, бір сарынды жұмыстан және күнделікті міндеттерден қорықпайсыз.\nСіз сияқты адамдар мансапты сәтті құрып, өз саласында салмағы мен беделі бар. Сіз тамаша бағынушы да, сауатты басшы да бола аласыз.\nКөбіне жүзеге асу қаржы, басқару, құрылыс және саясат саласында болады.\nСіз өз ісіңізді жүргізуіңіз немесе жалдамалы жұмыс істеуіңіз мүмкін — бірақ сонда сізге өз міндеттер шеңберіңіз бен сырттан араласу барынша аз өз кеңістігіңіз керек.", "5": "Сіз — түйсігі тамаша дамыған өте харизмалы әрі ашық адамсыз.\nОсының арқасында кез келген адамға оңай жол тауып, жаңа ортаға тез үйренесіз.\nШешендік сый мен тапқырлықтың арқасында кез келген нәрсені кез келген адамға сата аласыз.\nСіз сияқты адамдар — дамуға және қозғалысқа бағытталған тамаша кәсіпкерлер мен делдалдар.\nСіздің араласу ортаңыз кең, істе сізге көбіне дәл пайдалы таныстықтар мен байланыстар көмектеседі.\nСізде кез келген салада «өз», сенімді адамдарыңыз бен мамандарыңыз бар, сондықтан әрдайым керекті көмек пен кеңес ала аласыз.\nСіз адамдардың қажеттілігі мен ішкі ниетін түсінетіндіктен, тіпті қарсыластарды да шеберлікпен әрі байқатпай өз жағыңызға тарта аласыз.\nСіз өз көзқарасыңызды қорғап, келісімшартқа өзіңізге ең тиімді шартпен қол қойдыра аласыз.\nСізге ең күрделі әрі ерекше міндеттерді креатив пен ерекше ақыл арқылы шешу ұнайды.\nСіз — өзгеріс пен дағдарыстан қорықпайтын және ең қиын жағдайда да судың бетінде қала білетін жолы болғыш адамсыз.\nБұған табиғи икемділік, туа біткен түйсік және шешімді тез, кейде ойланбай қабылдай білу көмектеседі.\nСіз адамдарды жақсы түсінесіз және керек сәтте салқынқандылықты сақтай аласыз, сондықтан өзгенің ықпалы мен айла-шарғысына көнбейсіз.\nСіз тәуекел мен өзгерісті жақсы көресіз, сондықтан жылдар бойы жоспар құрғаннан гөрі «осында және қазір» өмір сүріп, қысқа мерзімді жобалар жүргізгенді қалайсыз.\nСізге әртүрлілік, қозғалыс пен саяхат ұнайды — жұмысты да соны ескеріп таңдауға тырысасыз.\nКөбіне сізде ақша табуға және іскерлік байланыс құруға көмектесетін бірнеше қосалқы нұсқа болады.\nБизнестегі табыс уақыттың тамырын басып отыру, өзгеріске тез жауап беру және ең сұранысқа ие нәрсені таңдай білудің арқасында келеді.\nСіз бір мезгілде бірнеше бағыт жүргізіп, әртүрлі табыс көзіне ие болып, қаражатты әртүрлі активтерде сақтай аласыз.\nСізге қабілеттеріңіздің бүкіл әртүрлілігін — белсенділікті, ұшқыр ақылды, түйсікті, сендіру сыйын, дипломатияны, креативті ойлау мен тапқырлықты көрсетуге болатын жерде даму маңызды.\nСізге қатаң ережелер мен шектеусіз, әрекет еркіндігі бар жұмыс келеді, өйткені сіз үшін жаңа құралдар мен жүзеге асу жолдарын үнемі тәжірибе жасай отырып байқап көру маңызды.\nСондықтан жалдамалы жұмыстан гөрі өзіңізге, жеке бизнесте жұмыс істеу сізге жайлырақ болады.\nСізді сауда, шарт пен келісімшарт жасау, логистикамен байланысты салалар тартуы мүмкін.\nБұл интеллектуалдық және шығармашылық қабілеттер белсенді қолданылатын бизнес те болуы мүмкін.\nСондай-ақ сізге саяхатпен байланысты барлық мамандық және араласу, коммуникация мен зерттеуші дағдылары керек барлық бағыт келеді.", "6": "Сіз адамдарды терең сезінесіз және олардың әрекетінің себептерін, терең тілектері мен қажеттіліктерін тамаша түсінесіз.\nОсының арқасында клиентке толық бағдарлана отырып, ең жақсы өнім немесе ерекше қызмет жасай аласыз.\nТіпті аз таныс адамдармен де әдетте жақсы қарым-қатынас қалыптасады, өйткені сіз әмір жүргізуге, басуға, өз еркіңізді таңуға немесе дауласуға бейім емессіз. Сіз дау-жанжалдан аулақ болуға тырысып, жұмыста сұлулық, қауіпсіздік пен жайлылық атмосферасын жасайсыз.\nСіз қамқорлық жасағанды, қамқорға алғанды және кеңес бергенді ұнатасыз. Шын жүрегіңізбен байланған адамдар үшін өзіңізді ұмытуға дайынсыз және нағыз альтруистке айналасыз.\nТамаша тәлімгерлік қабілет, шыдамдылық, ішкі тыныштық пен өзіне-өзі жеткіліктілік жинаған тәжірибеңізді беруге және біліміңізбен бөлісуге көмектеседі. Сіз — әртүрлі міндеттердің ең жақсы шешімін әрдайым табатын және клиенттің сұранысын барынша толық қанағаттандыратын маман.\nЖұмыста сіз сәл консервативсіз, әрдайым адал, әдепті және кәсіби этиканы сақтайсыз.\nСізге әділдік және таланттарды қатаң кесте мен қалыпсыз көрсету мүмкіндігі маңызды.\nСіз таңылған міндеттерді, шектен тыс қатаңдықты және авторитарлық басқару мәнерін ұнатпайсыз. Сондықтан жоғары лауазымда болғанда өзіңіз дана әрі жұмсақ басқарасыз. Табиғат сізге мықты ақыл мен тұрмыстық тапқырлық берген, сондықтан бәсекелестердің жоспарын шешіп, өзгенің ойын айналып өте аласыз, бұл істі ілгерілетуге көмектеседі. Сіз бірлескен бизнесте тамаша серіктессіз, істі өз бетіңізше де жүргізе аласыз, бірақ сізге жалдамалы жұмыс та келеді.\nАраласуда сіз өте әдепті әрі сезімталсыз, ашу немесе наразылықты дерлік көрсетпейсіз және ымыраға дайынсыз.\nЖұмыс көңіліңізге жақпаса, жағымсыз міндеттерден оларды басқаларға шебер «тапсырып», жалтаруыңыз мүмкін.\nСіз кез келген іске үйлесім мен сұлулық әкеле аласыз, өйткені сізде стиль сезімі бар және сапаны бағалайсыз — қызмет болсын, тауар болсын. Көбіне шығармашылық тәсіл, дипломатия және тәлімгерлік дағдылар бағаланатын қызметті таңдайсыз.", "7": "Жас кезде кәсіби жолыңыз оңай болмауы мүмкін: айналадағылар сіз сияқты ерекше тұлғаны әрдайым түсініп, бағалай бермейді. Бірақ өзіңізге адал болып, өз жолыңызбен жүрсеңіз, болашақта сізді мойындау, атақ пен материалдық молшылық күтеді.\nСіз көп талдауға және ойлануға бейімсіз, байқағышсыз.\nСіз оңашалықты жақсы көресіз, бірақ әрдайым пікірлестер іздейсіз.\nСондықтан сізге өзіңізге, фрилансте немесе шағын тату ұжымда жұмыс істеген жақсы.\nТүйсік, өз бетінше оқи білу, үнемі даму және қиын сұрақтарға жауап іздеу көбіне сізді ерекше, өзгеше қызмет саласына алып келеді.\nСіз әлі аз зерттелген және ерекше, қоғам өмірінде енді ғана пайда болып жатқан нәрсемен айналысқанды жақсы көресіз.\nБұл ғылым, зерттеулер, цифрлық немесе биотехнологиялар, көбіне IT саласы болуы мүмкін.\nБайқағыштық, тамаша көру жады және икемді ақыл тез оқуға және кез келген көзден ақпарат алуға көмектеседі.\nСізде өнертапқыштыққа, фактілерді талдауға, өз теорияңызды және пайдалы қорытындылар жасауға қабілет бар. Бір салаға басымен кетпей, жан-жақты дамыған пайдалы.\nЖұмыс негізінен ой еңбегі болса, бос уақытта спортпен айналысып, денеге қамқорлық жасаған жөн.\nТаланттарыңыз жеке бизнесте жақсы ашылады, өйткені сізге өз қарқыныңызбен жұмыс істеу тән, ал мұны әр басшы түсіне бермейді.\nӨзіңізге жұмыс істегенде мақсатты анық қойып, мақсатты нақты, орындалатын міндеттерге бөле отырып, жоспарды ұстану маңызды. Бастағанды әрдайым соңына дейін жеткізіп, алғашқы қиындықтың алдында шегінбеңіз. Жаңа тәжірибе мен дағды ала отырып, үнемі дамып, жетіліңіз.\nӨз салаңызда және сабақтас салаларда білім неғұрлым көп болса, соғұрлым көп мүмкіндік ашылады.\nӘріптестерді сыни көзқарасты пайдаланып, сауатты баға бере отырып, жұмсақ әрі әдепті бағыттай аласыз.\nКөбіне табысқа тезірек жету үшін сізге өзіңізге дана әрі тәжірибелірек тәлімгер керек.\nДостық, көмекке келуге дайындық және мейірімді қарым-қатынас адамдарды сізге тартады.\nСонымен бірге сіз өзгешесіз, тәуелсізсіз және әрдайым өзіңіз болып қаласыз. Сіз ақпаратты басқалардай ойламайсыз және қабылдамайсыз.\nСондықтан айналадағылар ештеңе түсінбейтін нәрсені оңай түсініп, кез келген құбылыстың түп мәніне дейін жетесіз.\nСіз тек жұмыс істеп қана қоймай, көпшілікке әдеттен тыс, ерекше өмір сүресіз.\nСіз идеяларыңызды, қызметтеріңізді және өнертабыстарыңызды табысқа оңай айналдыра аласыз.", "8": "Сізде табысқа керектің бәрі бар: ақыл, өршілдік және жоғары жұмысқа қабілеттілік.\nЖұмыс пен мансап сізге ең жақсы шығады. Сіз бәсекелестер азғырғысы келетін теңдесі жоқ сарапшы әрі алмастырылмайтын қызметкер болып, жалдамалы жұмыс істей аласыз, немесе басшылық лауазымдарда болып, жеке бизнес құра аласыз.\nСіз — іске соншалықты берілген нағыз еңбекқорсыз (трудоголик), кейде өмірдің басқа жақтарын ұмытасыз.\nСіз өзіңізге де, адамдарға да талапшылсыз, өйткені бәрінде кәсібилік пен терең білімді бағалайсыз.\nҚиындықтар сізді қорқытпайды: басқалар іске кірісуден бас тартқан жерде сіздің құмарлығыңыз бен әрекет етуге деген ниетіңіз тек күшейе түседі.\nСіз күрделі міндеттерді жақсы көресіз және оларды шешуде нағыз шеберлік танытасыз.\nСізде жұмысты жақсарту және бизнесті өсіру үшін не таңдау керектігін меңзейтін тамаша іскерлік епшілдік пен сезім бар.\nСіз — жауапты, сенімді әрі адал маман, әрдайым мерзімге сыйясыз және көбіне тіпті нашар сезінсеңіз де немесе қатты эмоциялық және дене шаршауында да жұмыс істейсіз.\nСіз табыс пен мойындауды жақсы көресіз, ақшаны басқара білесіз, бірақ жоғары табысты бәрінен жоғары қоймайсыз. Әдетте ақша сізге идеяны жүзеге асыру және мақсатқа жету үшін керек.\nӘлсіз жағында мұндай күшті қасиеттері бар адам үлкен мақсатсыз, өзін түсінбей, басқаларға тым көп көмектесіп, өз қажеттілігін ұмытып, кәдімгі жұмыспен айналысып, жалақыдан жалақыға дейін өмір сүруі мүмкін.\nЕкінші шеткі жағдай да кездеседі — материалдыққа кету, адам ақша үшін біреудің басын басып өтуге дайын болады.\nСіз — қоғамда елеулі өзгерістерді бастап, ең ірі компанияларды басқаруға қабілетті тамаша ұйымдастырушы әрі туа біткен көшбасшысыз.\nӨмірдегі көп нәрсе сізге көбіне ұнамайды, ымыраға бару қиын — сізге тек ең жақсысы керек. Көбіне ең үлкен күш пен мойындауға есейген шақта жетесіз.\nСынақтар мен қиындықтардан өтіп, сіз мансап пен мамандықта үлкен биікке көтеріле аласыз!", "9": "Жүзеге асу үшін сізге өз миссияңызды түсініп, маңызды бір нәрсеге қатыстылықты сезіну маңызды.\nБұған қоғамды, шындықты немесе адамдардың өмірін терең өзгерте алатын ауқымды жобаларға қатысу көмектеседі.\nСонда осындай үлкен міндеттерге ерекше мүмкіндіктер келіп, керекті мамандар, пайдалы таныстықтар және тағы көп нәрсе пайда болады.\nСіз іскер әрі белсендісіз, мақсаттысыз және қиындықтан қорықпайсыз.\nСіз әрдайым нәтиже алуға және мақсатқа жетуге ұмтыласыз, көбіне ойлағанды жүзеге асырғанша демалыссыз жұмыс істейсіз.\nӨршілдік сізге ең жоғары позицияларға жетуге және басшылық лауазымдарға ие болуға көмектеседі.\nСіз сияқты адамдар өз ісін ашады, өйткені ұзақ бағынышты болып, нұсқау мен сынды (әсіресе негізсіз әрі іске зиянды) тыңдай алмайды.\nСіз тәуелсізсіз, басқарғанды және әмір бергенді жақсы көресіз, сондықтан басшылыққа барған немесе өз ісіңізді құрған жақсы.\nСізге бәрі бір отбасындай, ал сіз — даусыз бедел болатын шағын тату ұжымдағы жұмыс ұнауы мүмкін.\nСіз энергия мен өсу мүмкіндіктерін қиындықтарды жеңіп, тәуекелге бел буып аласыз.\nСіз нәтижені көргенді жақсы көресіз, сондықтан бәрін қысқа мерзімде істеуге тырысасыз. Сізге үнемі қозғалып, жаңа тәжірибе алу тән.\nСізге әртүрлілік пен шығармашылық қабілеттерді қолдану мүмкіндігі ұнайды. Көбіне өзгерістер мен түрленулермен бірге бизнеске жаңа мүмкіндіктер де ашылады.\nСіз сырттан араласуды ұнатпайсыз және бәрі сіздей ойлап, ұстанымыңызды бөлісуі керек деп санап, өз еркімен кетуіңіз мүмкін.\nСонымен бірге сіз тамаша тактик әрі ұйымдастырушы, шын мәнінде — рухани көшбасшысыз.\nСізге кедергі келтірмесе, өзіңіз дамитын салаға көп нәрсе бере аласыз.\nПрактикалық тәжірибе, іскерлік епшілдік, оптимизм, практикалық және қиындықтан қорықпау сіздің басшылығыңыздағы бизнеске әрдайым жоғары позицияны сақтауға көмектеседі.\nБасқаларды қолдап, тәлімгер болып, көмектесу мүмкіндігі болғанда, алдыңыздан шексіз дерлік ресурстар ашылады.\nСіз өз заманыңыздың мәдени, саяси және қоғамдық өміріне айтарлықтай әсер ете аласыз."}, "life_act": {"0": "Кезең кодының екінші санының сипаттамасын қараңыз.", "1": "денемен байланысты кез келген жұмыс, спорт, өз денеңмен жұмыс (спортшы, пауэрлифтинг, йога, би), денені көрсету (фотомодель, бодибилдер), басқалардың денесімен жұмыс (массажист, тату-шебер, маникюр және педикюр шебері және т.б.), шыдамдылық, төзім, ұқыптылық, тәртіп пен режим маңызды мұқият жұмыс, экология және еңбекті қорғау, өндіріс, әскери қызмет, құрылыс, фермерлік және бағбандық, сапармен және саяхатпен байланысты дене жұмысы.", "2": "балалармен және отбасылармен жұмыс, сұлулық және спа саласы, ойын-сауық және әртістік керек нәрсенің бәрі, сексология, психология, әйелдермен көп араласатын салалар, икемділік керек спорт — гимнастика, мәнерлеп сырғанау, балет, йога, кез келген би, ер адамдар үшін — шығыс жекпе-жектері, үйде жайлылық жасау, клубтар, кафе мен барлар, суда белсенділік — жүзу, сёрфинг және т.б.", "3": "қоғамдағы табыс пен мансаптық жетістіктерге байланысты нәрсенің бәрі, табыстың өсуі, инвестициялар, маркетинг, қаржы және банк саласы, спорт және жаттықтырушылық, саясат, сатылым және жылжыту, жеке бизнес, көшбасшылық, коучинг, нутрициология, тамақ әзірлеу және тамақтану саласы.", "4": "медицина, ветеринария, психология, коучинг, эзотерика, нумерология, таро, руналар, массаж, қол шеберлігі, емшілік, қолөнер, оқыту және тәрбиелеу, аспаздық, косметология, қайырымдылық және волонтёрлық.", "5": "шығармашылық әуестіктер, дауыспен жұмыс, актёрлық және музыкалық қызмет, шешендік және дәріс оқу, оқыту, жазушылық, көркем қызмет, заң саласы, көпшілік алдында сөйлеу және блогинг, коучинг және тәлімгерлік, психология, сатылым.", "6": "оқыту және тәлімгерлік, психология және психиатрия, өнертапқыштық және зерттеулер, жазушылық және сценарийлер, бағдарламалау және IT, креативті идеялар мен шешімдер табу керек нәрсенің бәрі, интеллектуалдық және ғылыми қызмет.", "7": "шығармашылық жұмыс немесе хобби, өнермен байланыс, ғылыми қызмет, зерттеулер, философия және дін, психология және адам санасы мен әлем құрылысының заңдары туралы әртүрлі ілімдер, эзотерика және энергетикалық практикалар, оқыту және тәлімгерлік, астрология.", "8": "медицина және психология, тәлімгерлік және коучинг, басқару және басшылық, көшбасшылық, жеке бизнес, эзотерика және өзін-өзі тану жүйелері, экстрасенсорика және регрессология, дін және рухани қызмет.", "9": "өнер, актёрлық қызмет, шығармашылық, музыка, саяхат, тәлімгерлік, оқыту, спорт, медицина, емшілік."}, "life_str_act": {"1": "спорт және созылу жаттығулары, дене практикалары мен массаж, денеге қамқорлық, өзіне сенімділікті дамыту, саяхат пен сапарлар, қорқыныш пен мазасыздықпен жұмыс, арт-терапия және нейрографика, көшбасшылық қасиеттерді дамыту, жарыстар, табиғатпен және стихиялармен араласу, шыдамдылық, төзім, ұқыптылық, тәртіп пен режим маңызды мұқият бір сарынды жұмыс, құрылыс, бағбандық және фермерлік.", "2": "балалармен араласу, жалпы араласу және үйлесімді қарым-қатынас, әйелдермен араласу, анамен қарым-қатынасты реттеу, дене практикалары, спа және массаж, ойын-сауық және әртістік керек нәрсенің бәрі, шығармашылық, сексология мен психологияны оқу, икемділік керек спорт — гимнастика, мәнерлеп сырғанау, балет, йога, кез келген би, ер адамдар үшін — шығыс жекпе-жектері, үйде және жұмыс орнында жайлылық жасау, суда белсенділік — жүзу, сёрфинг және т.б., стилистпен жұмыс және өз стилін жаңарту.", "3": "қоғамдағы табыс пен мансаптық жетістіктерге байланысты нәрсенің бәрі, қаржылық стратегиялар мен жобалар, мақсат қою және жоспарлау дағдыларын дамыту, спорт және жаттықтырушылық, саясат, сатылым және жылжыту, коучинг, нутрициология, тамақтану саласы — мысалы, аспаздық немесе мейрамхана бизнесі, салауатты өмір салты, аскеза (өзін шектеу) және саналы тұтыну.", "4": "психология мен коучингті оқу, эзотериканы оқу, нумерология, таро, руналар, массаж, қол шеберлігі мен хендмейд, емшілік, қолөнер, оқыту және тәрбиелеу, аспаздық, косметология, қайырымдылық және волонтёрлық.", "5": "шығармашылық әуестіктер, дауыспен жұмыс, музыкалық және актёрлық қызмет, оқыту және тәлімгерлік, жазушылық, көркем қызмет, блогинг және көпшілік алдында болу, психология және коучинг, сатылым, медиация (даулардағы делдалдық).", "6": "оқыту және тәлімгерлік, өнертапқыштық және зерттеулер, жазушылық және сценарийлер, бағдарламалау және IT, креативті идеялар мен шешімдер табу керек нәрсенің бәрі, интеллектуалдық және ғылыми қызмет, ми шабуылы мен интеллектуалдық жарыстар, стратегия және жоспарлау, медитация және ақылды тыныштандыру тәсілдері, басқаларға өмірлік міндеттерді шешуге және шешім іздеуге көмектесу, құндылықтарды қайта бағалау және жаңа дүниетаным қалыптастыру.", "7": "шығармашылық жұмыс немесе хобби, өнермен байланыс, белгісіз және жасырын нәрсеге қызығушылық, ғылыми қызмет пен зерттеулер, философия және дін, психология және адам санасы мен әлем құрылысының заңдары туралы әртүрлі ілімдер, эзотерика және энергетикалық практикалар, тәлімгерлік және білім беру.", "8": "психология мен философияны оқу, көшбасшыларға арналған коучинг пен тренингтер, басқару және басшылық дағдыларын дамыту, өз бизнесін құру, эзотерика мен өзін-өзі танудың әртүрлі жүйелерін оқу, экстрасенсорика мен регрессологияны оқу, дінді тану және рухани қызмет, терең ұстанымдарды анықтау және жан жараларымен жұмыс істеу үшін психологпен жұмыс, спорт, оның ішінде экстремалды — парашют, тау шаңғысы және т.б., тамақ пен ішімдікті саналы шектеу.", "9": "өнер және шығармашылық, актёрлық қызмет, саяхат, тәлімгерлік, спорт, психологияны оқу, медицина."}, "exit_": {"1": "Шешімді Муладхараның қасиеттері арқылы іздеу: денсаулыққа көңіл бөлу, саналы белсенділік таныту, қимылды өмір салтын ұстану, спортты қосу, «барып шешу», әрекет ету. Муладхара төмен болса, жүктеме тек жұмсақ болуы керек — күштісі жағдайды тек нашарлатуы мүмкін. Ал жақсы толы болса, спорт кейде назарды мәселеден шешім іздеуге аударуға шынымен көмектеседі.", "2": "Шешімді отбасының қолдауы, бала туу және тәрбиелеу, отбасылық мәселелерді шешу арқылы іздеу. Ұрпақ өрбіту мүшелерінің, бүйректің және кіші жамбас мүшелерінің денсаулығын қадағалау. Қарсы жыныспен қарым-қатынасты реттеу, отбасы, туыстық байланыстар және балалар көмектеседі.", "3": "Шешімді қиын жағдайларда ерікті қосу арқылы іздеу. Денсаулық мәселелері болса — тамақтануды қайта қарау, лайықты рацион таңдау, тамаққа немесе дәріге тәуелділік мәселесін шешу. Ерікті шешім қабылдау, басқару дағдылары мен қаржылық сауаттылықты дамыту, тұлғалық және әлеуметтік өсумен айналысу. Режим, жоспар мен мақсатты қосу. Зиянды әдеттер мен тәуелділіктерге берілмей, үштіктің әлеуетін мансап пен жұмысқа бағыттау.", "4": "Шешімді эмоциялар, адамдарға көмек және шартсыз махаббат арқылы іздеу. Өзін аяу пайда болса — назарды әлемге аудару, әлемді, өзін және адамдарды қабылдау практикаларын, жүректі ашуға арналған медитацияларды қосу. Денеге жүрек белсендірек жұмыс істеуі үшін кардио жүктеме пайдалы. Өкпе, ашу, өшпенділік пен ауырсынумен жұмыс істеу, мүмкін психологпен. Татуласуды, дос пен таныс табуды, айналадағыларға жұмсақ қарауды, өзін және әлемді айыптамауды, басқаларға көмектесуді және алғыс айтуды үйрену.", "5": "Шешімді сөйлесу, келісім, уағдаластық, дипломатия және дауды шешу арқылы табуға болады. Қандай қағазға қол қойып жатқаныңызға мұқият қарап, сізді өзгенің ережесімен ойнатуға тырысып жатқанының белгілерін байқау маңызды. Келісе білетін делдалдардан көмек сұрау. Дене деңгейінде — қалқанша безді және гормондық тепе-теңдікті тексеру.", "6": "Кезеңді өмір сүруге саналылық, білім, кітаптан жауап іздеу көмектеседі: тоқтап, ойлану. Бұл — өзімен психологиялық жұмыс та. Ми тамырларын және оның оттегімен қамтамасыз етілуін тексеру. Әдетте Аджна жұмысқа өте оңай жауап береді, бірақ өмірге тек материалдық көзқарастан алыстап, әлемді біртіндеп нәзік жағынан тану маңызды.", "7": "Кезеңді өмір сүруге рухани даму мен дұға көмектеседі. Өзінің психикалық күйін басқаруды үйреніп, рухани практикаларға жүгініп, кез келген қиын жағдайда өзін ұстай білу маңызды. Түйсік пен нәзік қабілеттерді дамытуға, сенім, нумерология, астрология, йога, дұға мен медитация арқылы рухани өсуге болады әрі керек. Екінші жағынан, жетілік — психикаға сезілетін жүктеме, өзін мәңгі іздеу және дүниетанымның үнемі өзгеруі, неврологиялық немесе психологиялық қиындықтар болуы мүмкін. Ал әлеуетінде бұл — жоғарғы энергетикалық арнаның — жоғары күштермен байланыстың ашылуы.", "8": "Сегіздік арқылы шығу адамға әлемді өзі үшін қайта ашу, өмірді қайта ой елегінен өткізу, құндылықтарды қайта бағалаудан өту, өткенді босату, жаңа мағыналар табу, дүниетанымы мен бәріне көзқарасын өзгерту және өмірдің мәнін жоғалтпау үшін алғыс айтуды үйрену керектігін білдіреді. Сегіздік румен және дүниеден өткен ата-бабалармен жұмысты да меңзейді. Эзотерикаға қызыққан пайдалы — өз қиындықтарын тереңірек түсіну келеді (әсіресе таро мен психология жарасады). Кез келген міндетті оң жаққа бұрған дұрыс: қиындық өмірдің белгілі бір саласына назар аударып, оны түсініп, тәжірибе алу үшін беріледі. Ал өзін құртатын ойлар мен көңілсіздік тек жоғарғы сан бойынша қиындықты күшейтеді.", "9": "Бұл — жүктеменің ең жоғары дәрежесі: жоғарыда әлсіз чакра бойынша міндет тұрса, міндетті түрде бірдеңе болады деп саналады — жоғарғы санның чакрасы жауап беретін мүшелердің денсаулығында мәселелер болуы мүмкін. Бірақ дәл осы балл жоғарғы чакра мен жетекші чакра бойынша ең жоғары даму кезеңін де білдіреді. Тоғыздық адамның жасырын таланттарына жауап береді — тоғыздық неғұрлым көп болса, адам соғұрлым талантты. Бірақ талант өмір алдында өте жоғары жауапкершілікті талап етеді: адам оны ашпаса, жоғары күштер оған күшті серпін береді, мұндай адамнан нәзік және дене деңгейіндегі белгілі бір қиындықтар түрінде сұралады."}, "life_opp": {"0": "нөлдену (обнуление), түбегейлі өзгерістер, сәттілік пен жолдың болуы.", "1": "тұрақтылық пен орнықтылыққа жету, базалық қажеттіліктер мен қауіпсіздіктің қамтамасыз етілуі, төзімді дене және мықты денсаулық, өзін ру жүйесінің қажетті буыны ретінде сезіну, көшбасшылық қасиеттер мен сенімділікті дамыту, үй мен тамыр табу, ішкі тірек беретін өзгерістерге батылдық, жаңа сезім мен мүмкіндік іздеу ретіндегі саяхат пен көшу, дене белсенділігі, шыдамдылық пен тәртіпті қалыптастыру.", "2": "отбасын құру және бала туу, туыстармен қарым-қатынасты реттеу, қоғамда көріну және араласу, балаларды үйлесімді тәрбиелеу, жарқын жақын өмір және сезімталдықтың өсуі, өзіне-өзі жеткіліктілік пен тәуелсіздікті дамыту, сау өзін-өзі бағалау, өкпемен жұмыс, өз денесін қабылдау және өзін жақсы көру, шығармашылық қабілеттерді дамыту, өзін көрсетуге және білдіруге деген ниеттің өсуі.", "3": "мансаптық өсу, өршілдікті жүзеге асыру, қаржылық табыс, ақшаны көбейту, мақсаттарға жету, салауатты өмір салты, ой және қаржы тәуелсіздігі, харизма мен көшбасшылық қасиеттерді дамыту, әлеуметтік белсенділік, басқару дағдыларын дамыту, өз ісін немесе бизнесін дамыту, таңдау ретіндегі саналы тамақтану, шешім қабылдауға және ол үшін жауап беруге батылдық.", "4": "үйлесімді қарым-қатынас, ғашықтық пен махаббат, жұп пен отбасын құру, эмоциялық тепе-теңдік, алғыс пен қабылдау сезімі, айналадағылардың адалдығы мен әділдігі, өзін жақсы көруді дамыту, сенімділік пен ішкі тірек, адамдарға сену, өзін және айналадағыларды қабылдау, жаңа достар, шығармашылық идеяларды жүзеге асыру, көмектесетін мамандықта жүзеге асу, сезімталдық пен жұмсақтықты дамыту, өз сезімі мен эмоциясын өзгенікінен ажырата білу, артығынан және молшылықтан көмектесуге ниет.", "5": "таланттар мен қабілеттердің ашылуы, үйлесімді араласу, дипломатия мен шешендік қабілеттерді дамыту, келісе білу және ымыра табу, шығармашылық даму, жазушылық, музыкалық және вокалдық қабілеттерді дамыту, әлеуметтік белсенділік пен жемісті өзара әрекет, мықты өзін-өзі бағалау және өзгенің пікіріне тәуелсіздік, әрекеттегі адалдық пен әділдік, ашықтық пен достық, өмірге құштарлық, сөзді бақылау, ішкі еркіндік пен сенімділік.", "6": "интеллектуалдық жүзеге асу, жемісті оқу, тәлімгерлік пен оқытуда өзін көрсету мүмкіндігі, жазушылық қабілет пен креативтіліктің өсуі, түйсікті дамыту және ішкі дауыс пен тағдыр белгілеріне сену, жағдайды талдап, қорытынды жасай білу, ой-өріс пен ойлаудың кеңеюі, саналы өмір мен рухани дамудың маңызын түсіну, әлем заңдарын зерттеу және өмір мәнін табу, қорқынышпен жұмыс және сенімділікке жету, ақыл арқылы бірдеңе жасай білу, талдап, себеп-салдар байланыстарын көре білу.", "7": "өмір мәнін табу, өз мақсат-мұратын анық көру, зерттеу және таным жұмысы, экстрасенсорлық және эзотерикалық қабілеттердің ашылуы, жан тыныштығы мен эмоциялық тепе-теңдік, күшті түйсік, орнықты психика, психологиялық қиындықтарды шешу, жан жараларымен жұмыс, жаңалықтар мен көкірек көзінің ашылуы, сенімге жету және әлем заңдарын түсіну, ішкі өзек пен тірек қалыптастыру.", "8": "құндылықтарды қайта бағалау, өмір мәнін табу, ішкі өзек пен тірек қалыптастыру, көшбасшылық және басқару дағдыларын дамыту, харизма мен соңынан ерте білуді дамыту, рухани негіз қалыптастыру, өз өміріне және ортаға әсер ете білу, оң өзгерістер, ішкі еркіндік пен күшке жету, шешімдегі батылдық, қаржылық табыс, мақсаттарға жету және тілектердің орындалуы.", "9": "әлеуметтік белсенділік пен маңыздылық, танымалдық пен атақ, құндылықтарды қайта бағалау, жақсыға қарай тағдырлы өзгерістер, сәттілік пен жолдың болуы, керекті кездесулер мен жағдайлар, мақсаттарға жету және тілектердің орындалуы."}, "life_risk": {"0": ["Кезеңнің тәуекелдері мен ұсыныстарын кезең кодының екінші саны бойынша қараңыз.", "", ""], "1": ["тұрақтылықтың, қауіпсіздік пен тіректің жетіспеуі, дербес болмау және шешімсіздік, өмір үшін қорқыныш және жақындарды жоғалтудан қорқу, аман қалуға шоғырлану, ертеңгі күн туралы мазасыздық пен алаңдаушылық, туыстармен байланыстың үзілуі, рудан алыстау және оның заңдарын қабылдамау, енжарлық немесе агрессия, құрбан рөлі немесе озбырлық, өзгергісі және ескіні босатқысы келмеу, өзіне сенбеу, өмірге сенбеу және одан көңіл қалу, денеге немқұрайды қарау және соның салдарынан жарақаттар мен әлсіреген иммунитет.", "мазасыздық, қорқыныш, алаңдаушылық, сенімсіздік, агрессия, дауға бейімділік, жалқаулық, енжарлық, бос жүрушілік.", "сүйек жүйесі, омыртқа, қан, аяқ, бұлшықеттер, тіс, шаш, иммунитет, ішек, салмақтың қосылуы немесе азаюы, жарақаттар, жаңа өскіндер."], "2": ["серіктеспен дау мен ұрыс, отбасындағы түсінбеушілік, өзін-өзі бағалаудың төмендеуі, анаға өкпе және оған тәуелділік, бірге тәуелді (созависимые) қарым-қатынас, өзін-өзі сынау, кінә сезімі, басылған эмоциялар, басылған сезімталдық, жалғыздық және жеке өмірдің болмауы, өмірді ысырап ету және бетімен кету, сараңдық және үнемі үнемдеу, балалармен дау және шектен тыс қамқорлық, бала көтеру, оны сақтау және босанудағы қиындықтар.", "жалқаулық, жауапсыздық, ұшқалақтық, сенімсіздік, қызғаныш, тәуелділіктер, кешендер, ұят сезімі, кінә сезімі, сезімді көрсетуге тыйым.", "лимфа, несеп-жыныс, ұрпақ өрбіту және бөліп шығару жүйелері."], "3": ["мансаптағы кедергілер, ақша шығыны, әртүрлі тәуелділіктер, өзіне сенімсіздік, өзін толыққанды емес сезіну, материалдыққа шектен тыс берілу, кешендер, өзін көрсетудегі қиындықтар, басқаның жетегінде жүру және құрбандыққа бейімділік, тамақтану әдеттерінің бұзылуы, толықтық немесе арықтық, бәрін бақылағысы келу, ерік күшінің әлсіреуі, жауапсыздық, өмірді «кейінге» қалдыру әдеті, жаңа тәжірибе мен жаңа міндеттерден қорқу.", "қызғаныш, ашу, басқаларға қысым жасау, алаңдаушылық, шыдамсыздық, ашуланшақтық, мақтаншақтық, ысырапшылдық, сараңдық, дауға бейімділік, апатия, жалқаулық, енжарлық, шешімсіздік, ұят.", "ас қорыту жүйесі, асқазан-ішек жолы, зат алмасу, тамақтану тәртібі мен сипатының бұзылуы, терінің күйі."], "4": ["жақындармен дау, серіктестерге тәуелділік, қарым-қатынаста құрбандыққа бейімділік, эмоционалдылық пен жылауықтық, долылық пен эмоциялық тұрақсыздық, ажырасу мен опасыздық, айтылмаған өкпенің жүгі, кінәлау мен айыптау, эмоциялық салқындық — сіздің немесе серіктестің, жүрек күйзелістері мен кешендер, жауапсыз махаббат, махаббат үшбұрыштары, қысым мен кемсіту бар қарым-қатынас, жақындардың алғыссыздығы, екіжүзділік пен шындықтың жоқтығы — сіздің немесе жақындардың, жалғыздық, махаббатқа лайық емеспін деген сезім, жабысқақтық, тұйықтық пен салқындық.", "өшпенділік, ашу, кінә, салқындық, құрбандыққа бейімділік, алаңдаушылық, менмендік, тәкаппарлық, ашуланшақтық, талапшылдық, фанатизм, сенімсіздік, немқұрайдылық, бақылау, мазасыздық, көңілсіздік, қанағаттанбау.", "жүрек-қантамыр жүйесі, жүрек, үрей ұстамалары (панические атаки), өкпе, бронхтар, қан айналымы, омыртқаның кеуде бөлігі, кеуде қуысы, сүт бездері және қолтықасты аймағы, айырша без (тимус)."], "5": ["айналадағылармен дау, айтыс пен түсінісу, өкпені іште сақтау және айтылмай қалғандар, қоғамдағы қиындықтар мен тұйықтық, сөйлеу мәселелері, тұтығу, көпшілік алдында сөйлеуден қорқу, заңға қатысты қиындықтар, мансаптық өсуден қорқу, «өзін лайықсыз сезіну синдромы» (синдром самозванца), шығармашылықта өзін көрсете алмау, ұнамайтын жұмыс, темекі және басқа тәуелділіктер, эмоция мен ойды білдіре алмау немесе оларды дұрыс білдірмеу, өзін көрсетуден және шындықтан қорқу, өз пікірін қорғап айқайлағысы келу, келісімге барғысы келмеу.", "ашуланшақтық, дауласқысы келу, қырсықтық, тілі келмеу, сөзуарлық, тұйықтық, ұялшақтық, дауға бейімділік, екіжүзділік, шыншыл болмау, қорқыныш, алаңдаушылық.", "тамақ, көмей, мұрын-жұтқыншақ, қалқанша және қалқанша маңы бездері, дауыс байламдары, өкпенің жоғарғы бөлігі, тіс, жақ, тіл, сөйлеу."], "6": ["тәкаппарлық пен менмендік, материалдыққа шектен тыс берілу, түйсікке сенбеу, білімін қолдана алмау және интеллектуалдық жүзеге аса алмау, шектеулі және қалыпқа салынған ойлау, шектейтін ұстанымдар, жүзеге аспайтын армандар мен елестер, әлемді жақсы мен жаманға бөлу, руханилықты жоққа шығару, ой мен әрекетті талдамау, оқу мен есте сақтаудағы қиындықтар, әлемді тек логика арқылы қабылдау, қорқынышты үрлеп-ұлғайту.", "ұйқысыздық, оқи алмау немесе оқығысы келмеу, қорқыныш пен фобиялар, көңілсіздік, елестер, қалыпқа салынғандық, пессимизм, алаңдаушылық, менмендік.", "ми, көз, құлақ, мұрын, бет нерві, бет, бас сүйек, тіс, жақ, есте сақтау, психосоматика."], "7": ["әртүрлі салалардағы өмірлік дағдарыс, өзін түсінудегі қиындықтар, өмір мәнін жоғалту, мұң мен көңілсіздік, психикалық тұрақсыздық, әрекетсіздік пен жалқаулық, өзімен және айналадағылармен алауыздық, оңашалану, сенімсіздік — өзіне де, жоғары күштерге де, екіжүзділік пен алдау, түйсікке сенбеу, материалдыққа берілу, шындықтан алшақтау.", "апатия, көңілсіздік, үрей ұстамалары, психикалық және психологиялық қиындықтар.", "орталық жүйке жүйесі, психика, шаш, психосоматика."], "8": ["өмір үшін қорқыныш, өзгерістен және әрекеттен қорқу, өзін-өзі бағалаудың төмендеуі, мазасыздық, өзіне сенімсіздік, өмірдің мәнсіздігі туралы ауыр ойлар, жақындармен ажырасу, жұмыстан айырылу, ақша шығыны, өзін құрту, тәуелділіктер, өзіне зиян келтіру, ақталмаған тәуекел, мақсаттан бас тарту, апатия және құрбан позициясы, басқаларға қысым және ашуланшақтық, материалдыққа шектен тыс берілу және тек материалдық мақсаттар.", "көңілсіздік, мазасыздық, қорқыныш, өзін-өзі бағалаудағы қиындықтар, сараңдық, ашуланшақтық, қатыгездік, материалдыққа берілу, кекесін (цинизм).", "психика, жарақаттар, жаңа өскіндер, өзіне зиян келтіретін мінез-құлық."], "9": ["дау-жанжалды жағдайлар, агрессия және күш қолдану, күтпеген кедергілер мен сәтсіздіктер, адамдардан көңіл қалу және сатқындық, өмір мәнін жоғалту, қорқыныш пен мазасыздық, күшпен қысым жасау, құрбан рөлі немесе озбырлық, ауыр өкпе мен кекшілдік, адамгершілік заңдарын сақтамау, шынайы мақсаттарды түсінбеу, оңашалану және тұйықтық, денсаулыққа кенеттен соққы, өзін жүзеге асыра алмау.", "агрессия, ашуланшақтық, ашу, сенімсіздік, өзімшілдік, сараңдық, сенімнен бас тарту.", "диагноз қоюдағы қиындықтар, жарақаттар, күтпеген сырқаттар, психологиялық қиындықтар."]}, "kar_scen": {"1": "Өткен өмірде сізге тұрақтылық, қауіпсіздік пен тірек қатты жетіспеген, өмір үшін қорқыныш және жақындарды жоғалтудан қорқу күшті болған.\nСіз базалық қажеттіліктерді қамтамасыз етумен, аман қалумен және дербес болуға ұмтылумен айналысқансыз. Ертеңгі күн туралы мазасыздық пен алаңдаушылықта өмір сүргенсіз.\nӘрекетте батылдық пен жүрек жетіспеген, сәтсіздіктен қорқу кедергі болған. Сірә, ру байланыстары бұзылған: туыстармен байланыс үзілген, сіз рудан алыстап, оның заңдарын қабылдамағансыз.\nСізге шектен шығушылық тән болған — енжарлық немесе агрессия, құрбан рөлі немесе озбырлық. Өзгергісі және ескіні босатқысы келмеу, өзіне сенбеу, өмірге сенбеу және одан көңіл қалу болған.\nСіз өз денеңізге немқұрайды қарауыңыз мүмкін, бұл жарақаттарға және иммунитеттің әлсіреуіне әкелген.", "2": "Өткен өмірде үйлесімді отбасылық қарым-қатынас құру болмаған: отбасылық қиындықтар, ажырасу, опасыздық, серіктеспен дау болған.\nАналар мен балалардың қарым-қатынасында қиындықтар болған — дау, алыстау, аналық инстинкттің әлсіреуі немесе керісінше, балаларға байланып қалу және шектен тыс қамқорлық.\nӨмірде еркіндік пен шығармашылықпен өзін көрсету жетіспеген.\nБала көтеру, оны сақтау және босануда қиындықтар болуы мүмкін.\nМүмкін сіз жалғыздыққа тап болып, жеке өмірде бақыт таппағансыз.\nӘртүрлі тәуелділіктің — адамдарға да, қоздырғыштарға да — ықтималдығы жоғары. Тек ләззат үшін өмір сүру, өзін ысырап ету және өзін құрту. Шектен шығушылық болуы мүмкін: жақындықты қабылдамау мен ұялшақтықтан бастап бетімен кетуге дейін.", "3": "Өткен өмірде ерік күшінде, жоспарлауда және бастама көтеруде қиындықтар болған.\nТәуелділікке бейімділік (ішімдік, тыйым салынған заттар, дәрі-дәрмек), өзін бақылаудың бұзылуы және материалдыққа шектен тыс берілу болған.\nСізде ақшамен — табумен, жинаумен және көбейтумен қиындықтар болған.\nӨмір ақшаның жетіспеуімен, мансаптағы және мақсатқа барар жолдағы кедергілермен қатар жүрген.\nҚиындыққа төзбеушілік, ашуланшақтық және бәрін бақылағысы келу көрінуі мүмкін.", "4": "Өткен өмірде сізде өзіңізді және жақындарыңызды сүю қабілеті бұзылған.\nҚатты өкпе мен өзін аяу пайда болған. Сіз махаббатты және өзіңізді жақсы көретінінің дәлелін іздегенсіз. Шектен шығушылық болуы мүмкін: өкпешілдікке, қызғанышқа және ашуланшақтыққа айналған шектен тыс құрбандыққа бейімділік,\nнемесе қатаңдыққа, суықтыққа және өмір мен адамдарға сенбеуге әкелген эмоциялық салқындық пен немқұрайдылық.\nМұндай мінез-құлықтың себебі — өзін жақсы көрудің жетіспеуі, өзін қабылдамау, бұзылған ішкі үйлесім және жоғалған шартсыз махаббат күші. Осы жан жаралары мен теңгерімсіздіктің салдары ретінде өкпенің ауыр аурулары да болуы мүмкін.", "5": "Өткен өмірде қоғамда өзін көрсетуде және өзін білдіруде қиындықтар болған.\nЗаңға қатысты қиындықтардың — мысалы, бас бостандығынан айырылу, алаяқтық, дау-жанжал мен қоғамдық қозғалыстарға қатысудың ықтималдығы жоғары.\nСіз бүлікшіл және революционер — қоғамдық нормалар мен ережелерге қарсы шыққан адам болуыңыз мүмкін.\nШығармашылықпен өзін көрсеткісі, адамдармен дипломатиялық араласқысы және келіскісі келмеген.\nСіз түсінісуге, дауласуға, қырсықтыққа, айқай мен жанжалға бейім болғансыз.\nЖүзеге аспаған шығармашылық энергияны басқа арнаға бұрудың тәсілі ретінде әртүрлі тәуелділіктер болуы мүмкін.", "6": "Өткен өмірде сізде интеллектуалдық қабілеттерді жүзеге асыруда қиындықтар болған. Шектеулі, қалыпқа салынған ойлау және байлайтын ұстанымдар болған, пессимизм мен жаманға шоғырлану басым болған.\nСіз санасыз өмір сүріп, жаңаны үйренгіңіз келмеуі мүмкін, жалпы білім алуға және ақпаратты мұқият зерттеуге ерініш болған.\nИдеялар идея күйінде қалып, жобалар тоқтап қалған. Руханилықты және онымен байланысты бәрін жоққа шығарудың ықтималдығы жоғары.\nТүйсікті жоққа шығарған немесе оған ергісі келмеген. Өткен өмірде санасыз деңгейде қалыптасқан көп қорқыныш пен шектейтін сенімдер болған. Шындықты бұрмаланған, елес түрінде қабылдау мүмкін.", "7": "Өткен өмірде Сенімге жетумен, өз мақсат-мұратын және өмірдегі орнын түсінумен байланысты қиындық болған.\nСіз қоғамнан алыстаған жалғыз жүруші (отшельник) ретінде көрінгенсіз, немесе қоғам сізді «бұл дүниенің адамы емес» деп қабылдамаған.\nӘдетте дәстүрді ұстануда қиындықтар, дінді жоққа шығару, сенімсіздік болған. Сіз өзіңізбен және айналадағылармен алауыздықта болып, тірек таба алмай, өзіңізге де, Құдайға да, ештеңеге де сенбегенсіз. Мұның бәрі өзіне зиян келтіруге талпынысқа және әртүрлі тәуелділіктерге әкелуі мүмкін болған.", "8": "Өткен өмірде сіз елеулі кедергілерге тап болғансыз, жолыңыз оңай болмаған.\nСіз өзіңізге сенбей, көп нәрсеге күмәнмен қарағансыз. Өмірде тірек, энергия беретін және өмірге мән беретін тұрақты қызығушылықтар мен мақсаттар болмаған. Өмір үшін қорқыныш және кез келген өзгерістен қорқу күшті болған.\nЕкінші шеткі жағдай — өмірді бағаламай, шектен тыс және мағынасыз тәуекелге бару. Кейде өз денесіне зиян келтіруге бейімділік (тіпті байқамай, не үшін екенін түсінбей) көрінген — татуировка, тыртық салу немесе экстремалды спорттан болған жарақаттар.\nБұл кармалық сценарийге басқа адамдарға дене зиянын келтіру де жатады.\nҚиындықтан немесе өмір мәнін жоғалтудан өзін құртатын мінез-құлық пен өмірге қауіпті әрекеттер тәуекелі болған.\nҚирау тек дене деңгейінде емес, ой деңгейінде де көрінген: апатияға, көңілсіздікке, пессимизмге және мұңға бейімділік болған.\nКедергілер мен қиындықтар қорқыныш тудырып, мақсаттан бас тартуға әкелген.", "9": "Өткен өмірде агрессия мен қатыгездікке бейімділік болған — сіз осылай өз қорқынышыңыз бен сенімсіздігіңізді жасыруға тырысқансыз. Сізге жанашырлық пен мейірім жиі жетіспеген. Ерекшелігі — агрессия сізге де бағытталуы мүмкін болған: сіз үнемі күш қолдануға тап болғансыз.\nКек алуға, жазалауға және тек өзіңізге түсінікті әділдікті орнатуға бейімділік болған. Сіз адамгершілік заңдары мен қағидаларына қарсы, оңай пайда табу жолымен жүруіңіз мүмкін.\nМамандықта жүзеге асуда және идеяларды жүзеге асыруда қиындықтар, сүйікті ісімен жұмыс істей алмау болған. Өмірде және жан дүниеде белгісіздік, жолдың дұрыстығына күмән және өз мақсат-мұратын түсінбеу болған.\nСіздің шынайы ұмтылыстарыңыз бен мақсаттарыңыз қоғамда қабылданбаған немесе айыпталған. Сондықтан сіз өзіңізге тұйықталып, жалғыз жүріп, тіпті жақындарыңыздан да оқшаулануыңыз мүмкін болған."}, "rod_scen": {"1": "Руда тұрақтылық, қауіпсіздік пен тірек қатты жетіспеген, өмір үшін қорқыныш және жақындарды жоғалтудан қорқу күшті болған.\nАта-бабалар базалық қажеттіліктерді қамтамасыз етумен, аман қалумен және дербес болуға ұмтылумен айналысқан. Олар ертеңгі күн туралы мазасыздық пен алаңдаушылықта өмір сүрген.\nОларға әрекетте батылдық пен жүрек жетіспеген, сәтсіздіктен қорқу кедергі болған. Сірә, ру байланыстары бұзылған: туыстармен байланыс үзілген, адамдар рудан алыстап, оның заңдарын қабылдамаған.\nРуға шектен шығушылық тән болған — енжарлық немесе агрессия, құрбан рөлі немесе озбырлық. Өзгергісі және ескіні босатқысы келмеу, өзіне сенбеу, өмірге сенбеу және одан көңіл қалу болған.\nАта-бабалар өз денесіне немқұрайды қарауы мүмкін, бұл жарақаттарға және иммунитеттің әлсіреуіне әкелген.", "2": "Руда үйлесімді отбасылық қарым-қатынас құруды білмеген: отбасылық қиындықтар, ажырасу, опасыздық, серіктестермен дау болған.\nАналар мен балалардың қарым-қатынасында қиындықтар болған — дау, алыстау, аналық инстинкттің әлсіреуі немесе керісінше, балаларға байланып қалу және шектен тыс қамқорлық.\nӨмірде еркіндік пен шығармашылықпен өзін көрсету жетіспеген.\nБала көтеру, оны сақтау және босануда қиындықтар болуы мүмкін. Мұндай руда жеке өмірде бақыт таппаған жалғыз адамдар жиі кездеседі.\nӘртүрлі тәуелділіктің — адамдарға да, қоздырғыштарға да — ықтималдығы жоғары. Тек ләззат үшін өмір сүру, өзін ысырап ету және өзін құрту. Шектен шығушылық болуы мүмкін: жақындықты қабылдамау мен ұялшақтықтан бастап бетімен кетуге дейін.\nӨмір салты мен ұстанымдар несеп-жыныс жүйесінің ауруларына, гормондық бұзылыстарға және бала көтеру мен оны сақтаудағы қиындықтарға әкелуі мүмкін.", "3": "Руда ерік күшінде, жоспарлауда және бастама көтеруде қиындықтар болған.\nТәуелділікке бейімділік (ішімдік, тыйым салынған заттар, дәрі-дәрмек), өзін бақылаудың бұзылуы және материалдыққа шектен тыс берілу болған.\nРуда ақшамен — табумен, жинаумен және көбейтумен қиындықтар болған.\nӨмір ақшаның жетіспеуімен, мансаптағы және мақсатқа барар жолдағы кедергілермен қатар жүрген.\nҚиындық пен кедергіге төзбеушілік, ашуланшақтық және бәрін бақылағысы келу көрінуі мүмкін.\nӨмір салты асқазан-ішек жолының, зат алмасу мен ас қорытудың бұзылуына әкелген.", "4": "Руда өзін және жақындарын сүю қабілеті бұзылған.\nҚатты өкпе мен өзін аяу болған. Адамдар махаббатты және өздерін жақсы көретінінің дәлелін іздеген. Шектен шығушылық болуы мүмкін: өкпешілдікке, қызғанышқа және ашуланшақтыққа айналған шектен тыс құрбандыққа бейімділік,\nнемесе қатаңдыққа, суықтыққа және өмір мен адамдарға сенбеуге әкелген эмоциялық салқындық пен немқұрайдылық.\nМұның себебі — өзін жақсы көрудің жетіспеуі, өзін қабылдамау, бұзылған ішкі үйлесім және жоғалған шартсыз махаббат күші.\nӨмір салты мен ұстанымдар жүрек, өкпе және бронх ауруларына, тыныс жүйесінің созылмалы ауруларына, бронх демікпесіне және т.б. әкелуі мүмкін.", "5": "Руда қоғамда өзін көрсетуде және өзін білдіруде қиындықтар болуы мүмкін.\nЗаңға қатысты қиындықтардың ықтималдығы жоғары: біреу бас бостандығынан айырылуы, алаяқтықпен айналысуы, дау-жанжал мен қоғамдық қозғалыстарға қатысуы мүмкін.\nРуда бүлікшілдер мен революционерлер — қоғамдық нормалар мен ережелерге қарсы шыққан адамдар болуы мүмкін.\nШығармашылықпен өзін көрсеткісі, адамдармен дипломатиялық араласқысы және келіскісі келмеген.\nАта-бабалар түсінісуге, дауласуға, қырсықтыққа, айқай мен жанжалға бейім болған.\nЖүзеге аспаған шығармашылық энергияны басқа арнаға бұрудың тәсілі ретінде әртүрлі тәуелділіктер болуы мүмкін.\nСондықтан тамақ пен жоғарғы тыныс жолдарының аурулары, қалқанша без жұмысының бұзылуы, сөйлеу бұзылыстары, дауыстың жоғалуы немесе тұтығу болуы мүмкін. Ішімдікке, тыйым салынған заттарға және темекіге тәуелділік тәуекелі болған.", "6": "Ата-бабаларда интеллектуалдық қабілеттерді жүзеге асыруда қиындықтар болған. Ұрпақтан ұрпаққа берілген шектеулі, қалыпқа салынған ойлау және байлайтын ұстанымдар болған, пессимизм мен жаманға шоғырлану басым болған.\nРуда санасыз өмір сүріп, жаңаны үйренгісі келмеген, жалпы білім алуға және ақпаратты мұқият зерттеуге ерініш болған.\nИдеялар идея күйінде қалып, жобалар тоқтап қалған. Руханилықты және онымен байланысты бәрін жоққа шығарудың ықтималдығы жоғары.\nТүйсікті жоққа шығарған немесе оған ергісі келмеген. Руда санасыз деңгейде қалыптасқан көп қорқыныш пен шектейтін сенімдер болған. Шындықты бұрмаланған, елес түрінде қабылдау мүмкін.\nСондықтан ми, көру және есту мүшелерінің аурулары, мигрень және ми қан айналымының бұзылуы, бас айналу және үйлестірудегі (координация) мәселелер пайда болуы мүмкін.", "7": "Руда Сенімге жетумен, өз мақсат-мұратын және өмірдегі орнын түсінумен байланысты қиындық болған.\nЖалғыз жүрушілер немесе шеттетілгендер — қоғамнан алыстаған немесе қоғам «бұл дүниенің адамы емес» деп қабылдамаған адамдар болуы мүмкін.\nӘдетте дәстүрді ұстануда қиындықтар, дінді жоққа шығару, сенімсіздік болады, адам өзімен және айналадағылармен алауыздықта болып, тірек таба алмай, өзіне де, Құдайға да, ештеңеге де сенбейді. Мұның бәрі өзіне зиян келтіруге талпынысқа және әртүрлі тәуелділіктерге әкелуі мүмкін болған.\nСалдарынан психикалық және психологиялық қиындықтар, жүйке жүйесі жұмысының бұзылуы, стресс, долылық пен көңілсіздік пайда болуы мүмкін.", "8": "Ру елеулі кедергілерге тап болған, оның жолы оңай болмаған.\nАта-бабалар өзіне сенбей, көп нәрсеге күмәнмен қараған. Олардың өмірде тірегі, энергия беретін және өмірге мән беретін тұрақты қызығушылықтары мен мақсаттары болмаған. Өмір үшін қорқыныш және кез келген өзгерістен қорқу күшті болған.\nЕкінші шеткі жағдай — ру өкілі өмірді бағаламай, шектен тыс және мағынасыз тәуекелге барады. Кейде өз денесіне зиян келтіруге бейімділік (тіпті байқамай, не үшін екенін түсінбей) көрінеді — татуировка, тыртық салу немесе экстремалды спорттан болған жарақаттар.\nБұл ру сценарийіне басқа адамдарға дене зиянын келтіру де жатады.\nҚиындықтан немесе өмір мәнін жоғалтудан өзін құртатын мінез-құлық пен өмірге қауіпті әрекеттер тәуекелі болған.\nРу өкілдерінде қирау тек дене деңгейінде емес, ой деңгейінде де көрінген: апатияға, көңілсіздікке, пессимизмге және мұңға бейімділік болған.\nКедергілер мен қиындықтар қорқыныш тудырып, мақсаттан бас тартуға әкелген.", "9": "Ата-бабалар өз қорқынышы мен сенімсіздігін осылай жасыруға тырысып, агрессия мен қатыгездікке бейім болған. Оларға жанашырлық пен мейірім жетіспеген. Ерекшелігі — агрессия олардың өздеріне де бағытталуы мүмкін болған: олар үнемі күш қолдануға тап болған.\nРуда кек алуға, жазалауға және тек өздеріне түсінікті әділдікті орнатуға бейімділік болған. Адамдар адамгершілік заңдары мен қағидаларына қарсы, оңай пайда табу жолымен жүрген.\nМамандықта жүзеге асуда қиындықтар, сүйікті ісімен жұмыс істей алмау болған, өз идеяларын жүзеге асыру қиын болған.\nӨмірде және жан дүниеде белгісіздік, жолдың дұрыстығына күмән және мақсат-мұраттың анық болмауы болған.\nШынайы ұмтылыстар мен мақсаттар қоғамда түсінбеушілікке немесе айыптауға тап болған. Сондықтан ата-бабалар өзіне тұйықталып, жалғыз жүріп, тіпті жақындарынан да оқшаулануы мүмкін болған.\nМұндай ру сценарийінен ұрпақ жалғастыру мен бала көтеруде қиындықтар, сондай-ақ анықтау мен емдеу қиын аурулар болуы мүмкін.\nДенсаулыққа кенеттен соққы мен күтпеген сырқаттану болуы мүмкін."}, "key": {"1": ["Шыдамдылық пен төзімділікті дамыту. Асықпай, әбігерден аулақ болу. Өзгерістер мен түрленулер кезінде тұрақтылықты сақтау үшін бар күшті салу. Саналы ойлау мен ақыл икемділігін дамыту. Өзіне және оқиғалардың жақсы аяқталатынына сенімді болу. Шешім қабылдап, идеяларды батыл жүзеге асыра білу.\nАдамдармен араласуда икемді, жеңіл қозғалатын болу, бір орында тұрып қалмау, жалқаулық пен апатияда қалып қоймау.\nДамудың әрі қарайғы жолы үшін базалық қажеттіліктерді міндетті түрде қамтамасыз ете отырып, өмірде орнығуға және жүзеге асуға ұмтылу. Өз өмірінің ағысына сену.\nӨз руын құрметтеу, өзін және ру жүйесіндегі орнын түсіну. Өмір адамның жиналып, оларды жеңуі үшін денсаулықта қиындықтар, кедергілер мен сынақтар жіберуі мүмкін — күш дәл жеңу арқылы келеді. Сондықтан таңдау мынадай: не адам өзі өседі, не оны бұған Ғалам «итермелейді».", "дене белсенділігі — йога, аяққа кез келген жүктеме, жерде жасалатын жаттығулар, бағбандық және жермен жұмыс, ру байланыстарын нығайту: туыстарды біріктіру, ру кітабы мен шежіре ағашын жасау, ашу мен агрессияны жұмсақ түрде өзгерту тәсілі, саяхат пен қозғалыс.", "денемен байланысты кез келген жұмыс, спорт, өз денеңмен жұмыс (спортшы, пауэрлифтинг, йога, би), денені көрсету (фотомодель, бодибилдер), басқа адамдардың денесімен жұмыс (массажист, тату-шебер, маникюр және педикюр шебері және т.б.), шыдамдылық, төзім, ұқыптылық, тәртіп пен режим керек мұқият жұмыс, экология және еңбекті қорғау, өндіріс, әскери қызмет, құрылыс, фермерлік және бағбандық, сапармен және саяхатпен байланысты дене жұмысы."], "2": ["Серіктеспен, жақындармен және адамдармен үйлесімді қарым-қатынас құру. Ең алдымен өзіңізбен жұмыс істеу: өзіңізге сұрақ қою — мен қарым-қатынастан не қалаймын, бұл серіктес маған не үшін керек, бұл қарым-қатынас маған нені үйретеді.\nӘлемді сезім арқылы қабылдауды үйрену. Тәуелділікке — қоздырғыштарға да, адамдарға да — түспей, өмірден ләззат алу. Жақын өмірді және қоғамда көрінуді реттеу.\nӨзіне-өзі жеткілікті және тәуелсіз болуды дамыту, бірақ сонымен бірге басқаларға көмектесіп, оларды қолдап, жақындарға қамқорлық жасау.\nБалалармен және анамен қарым-қатынасты реттеу.", "дене практикалары, массаж, сумен және су стихиясымен байланыс, аналық немесе әкелік рөлде жүзеге асу, өкпемен жұмыс, өзін-өзі бағалаумен жұмыс, өзіне және өз денесіне деген махаббатты дамыту, шығармашылық пен өзін білдіруге кеңістік.", "балалармен және отбасылармен жұмыс, сұлулық және спа саласы, ойын-сауық және әртістік керек нәрсенің бәрі, сексология және отбасы психологиясы, әйелдермен көп араласатын салалар, икемділік керек спорт — гимнастика, мәнерлеп сырғанау, балет, йога, кез келген би, ер адамдар үшін — шығыс жекпе-жектері, үйде жайлылық жасау, клубтар, мейрамханалар, кафе мен барлар, суда белсенділік — жүзу, сёрфинг және т.б., шопинг."], "3": ["Жауапкершілікті дамытып, мақсат қоюды жаттықтыру.\nМіндетті орындауға мансаптық өсу мен өршілдікті жүзеге асыру, сондай-ақ басшылық пен басқару көмектеседі.\nАқшаны бөлуді және қаржымен сауатты жұмыс істеуді үйрену.\nДұрыс тамақтанып, жалқаулық пен тәуелділікке түспеу.\nҚолайлы сәтті күтіп, әдетпен өмір сүрмеу — бәрі өз қолыңызда екенін түсіну.\nСаналы тұтынуға келу: «сен — не жесең, солсың».\nТөзімділік пен ерік күшін дамыту.\nӨзгенің көзқарасын қабылдай отырып, адамдармен ортақ тіл табу және жұмсақ пікірталасуды үйрену.\nӨзіне сенімділікті нығайтып, көшбасшылық қасиеттер мен харизманы дамыту.", "уақытты басқару (тайм-менеджмент) және жоспарлау, азырақ ойламай істеу және көбірек стратегия, қаржылық сауаттылық, нақты күн тәртібі, тұрақты спорт, эмоциялық интеллектті дамыту, салауатты өмір салты және дұрыс тамақтану, өзіне сенімділік үшін қиындықтарды жеңу, ашу мен жағымсыз эмоциялардан өзіне де, айналадағыларға да қауіпсіз түрде арылу.", "қоғамдағы табыс пен мансаптық жетістіктерге байланысты нәрсенің бәрі, инвестициялар, маркетинг, қаржы және банк саласы, спорт және жаттықтырушылық, саясат, сатылым және жылжыту, коучинг, нутрициология, тамақтану саласы — мысалы, аспаздық немесе мейрамхана бизнесі."], "4": ["Өзіне және жақындарға қамқорлық жасау, бірақ жақсылықты таңбай, сұраған кезде көмектесу.\nЭмоциялық саланың құрылымын зерттеп, ішкі әлемді теңестіре білу.\nӨзіне адал болып, адамгершілік заңдарын ұстану. Бұл жүкті жүректе көтеріп жүрмей, өкініп, кешірім сұрау.\nБасқаларға ресурстан — махаббат пен жанашырлықтың молдығынан көмектесу.\nӨзіндегі өзін ғана ойлауды (эгоцентризм) және мұңды жеңу.\nӨз құндылығын сезінуді арттыру.", "дос тауып, ашық әрі мейірімді адамдармен араласу ортасын қалыптастыру, үй жануарын асырау, аспаздық курсынан өтіп, жақындарға және өзіне сүйіспеншілікпен тамақ әзірлеу әдетін қалыптастыру — мысалы, демалыста немесе бос уақытта, өз қолымен бірдеңе жасап, шығармашылықпен айналысу — хендмейд, мүсін, тоқу, сурет салу, үйде тәртіп орнатып, қала немесе аула тазалығына волонтёр ретінде көмектесу, қайырымдылыққа қатысу, ұнамайтын нәрсеге шоғырлануды тоқтатып, барына алғыс айта бастау, өзін қабылдау — себепсіз махаббатқа алғашқы қадам: өзіне деген махаббат өзгерістерге немесе айналадағыларға байланысты болмауы керек, эмоциямен жұмыс істеу тәсілдерін байқап көру — нейрографика, сезімді қағазға түсіру, эмоция күнделігін жазу, өзінің «ішкі баласымен» жұмыс істеу.", "медицина, ветеринария, психология, коучинг, эзотерика, нумерология, таро, руналар, массаж, қол шеберлігі, емшілік, қолөнер, оқыту және тәрбиелеу, аспаздық, косметология, қайырымдылық және волонтёрлық."], "5": ["Адамдармен және пікірлестермен араласа отырып даму маңызды.\nСезім мен ойды іште ұстамай, олардан арылуды немесе оларды өзгертуді үйрену.\nАраласу дағдыларын пайдалана отырып, қоғамда байланыс құруды үйрену: пікірді жұмсақ айту, келісу, ынтымақтасу, тәжірибе мен біліммен бөлісу.\nШығармашылықта, оның ішінде шешендік өнер арқылы жүзеге асуға тырысу.\nӘлемге өз ықпалыңызды түсіну және таланттарды ашу үшін өзін білдірудің жолдарын тауып, қабілетіңізді көрсету.", "айналадағыларға жұмсақ әрі қауіпсіз түрде істей алсаңыз — сөйлеу және талқылау, айта алмасаңыз — сезгеніңіздің және ренжігеніңіздің бәрін қағазға немесе диктофонға жазу, жағымсыз эмоцияларды ең болмаса айнаның немесе ойыншықтың алдында айту, дипломатиялық түрде дауласуды үйрену, артық қырсықтықтан бас тартып, қарсыласқа сөйлеуге мүмкіндік беру, эмоция жиналып, ұрысқысы келгенде — жастыққа айқайлау немесе адамсыз жерге барып, дауысты сол жерде шығару, караокеде ән айту немесе вокалмен айналысу, мәтін жазу, шығарма шығару, тіл үйрену, тамаққа және басқа қоздырғыштарға тәуелді болмай, дұрыс тамақтану, өміріне шығармашылықты кіргізу, шешендік пен көпшілік алдында сөйлеу дағдысын шыңдау, айналадағыларды сынаудан, кекесіннен және мазақтаудан аулақ болу.", "шығармашылық әуестіктер, шешендік өнер, блогинг, актёрлық және музыкалық қызмет, дәріс оқу және оқыту, жазушылық, көркем қызмет, заң саласы, көпшілік алдында сөйлеу, коучинг және тәлімгерлік, психология, сатылым, медиация (даулардағы делдалдық)."], "6": ["Өмірді әдетпен өмір сүрмей, әр жағдайды ойланып, өз қорытындысын жасау маңызды. Талдау қабілетін дамытып, білімді үнемі толықтыру. Шектеулілікке, қалыпқа салынған ойлауға және жалған ұстанымдарға жол бермеу.\nБелгілер мен ішкі дауысқа құлақ аса отырып, түйсікті дамыту.\nБейнелі ойлауды жаттықтыру.\nӘлем құрылысының заңдарын зерттей отырып, рухани саналылық пен сауаттылықты жаттықтыру.\nӨмір сүрудің мәнін тауып, шынайы мақсат-мұратты табу.\nЖағымсыз ойларды шеңбер бойымен айналдыруды және осы ойды «шайнай беруді» тоқтату.\nДағдылар мен ақылды жетілдіре отырып оқу және шәкірттен ұстазға дейінгі жолдан өту.\nӨмірдегі орнын түсініп, әлемге сене отырып, өзіне сенімділікті дамыту.", "білімді әртүрлі жолмен алу — курстар, кітаптар, тәлімгерлік, коучинг, мақала, өлең, очерк жазу, медитация мен күш орындарына сапарды жаттықтыру, рухани әдебиетті оқу, қайырымдылыққа қатысу, өз білімі мен көкірек көзін басқаларға жеткізу, сөзжұмбақ пен шарада шешу, интеллектуалдық ойындарға қатысу, саяхаттап, басқа қалалар, елдер мен халықтар туралы әсер мен білім жинау, идеяларды жүзеге асырып, оларды соңына дейін жеткізу, ойлағанды бейнелеу және жүзеге асыру тәсілдері арқылы позитивті ойлауды жаттықтыру, дене практикалары арқылы назарды денеге аудару, ми белсенділігін үнемі дамыту, күрделі есептер мен басқатырғыштарды шешу, қиял мен ерекше ойлауды қолдану.", "оқыту және тәлімгерлік, өнертапқыштық және зерттеулер, жазушылық және сценарийлер, бағдарламалау және IT, креативті идеялар мен шешімдер табу керек нәрсенің бәрі, интеллектуалдық және ғылыми қызмет."], "7": ["{R} қиындықтары мен міндеттерін шешу үшін рухани даму керек: әлем құрылысының заңдарын, карма заңдарын және әлем құрылысының негіздерін тану.\nӨзіне көбірек сеніп, түйсікке құлақ асу. Ерекше қабілеттер мен сезімдер болса, олардан қорықпай және оларды жоққа шығармай, табиғи сыйды игілікке пайдалану.\nСонымен бірге ішкі тепе-теңдікке ұмтыла отырып, өз психикасы мен эмоциялық күйін басқару маңызды.\nКез келген жағдайда сенімділік пен тепе-теңдікті сақтау үшін ішкі өзек пен күшке ие болу.\nӨз сенімі мен білімін айналадағыларға жеткізу.\nРухани мен материалдық арасында тепе-теңдік табу.", "өз Күш Орнын — энергия беретін қайнар көзді табу: сенім, шығармашылық, әлем туралы дәстүрлі емес білім мен ғылымдар (психология, философия, нумерология және т.б.), өзін-өзі жетілдірумен айналысу, ең жақсы қасиеттер мен қабілеттерді ашу, түйсікті дамыту, медитация, табиғат стихиялары және оңашалық арқылы ішкі диалогты тоқтатуды үйрену, сын мен айыптаудан аулақ болу, өзіндегі тәкаппарлық пен мақтаншақтықты байқап, тоқтату, сана шекарасын кеңейтіп, қалыпқа салып ойлауды тоқтату, тек материалдықпен емес, жоғары құндылықтармен байланысты мақсат қою, бірақ елестерге кетіп, шындықпен байланысты жоғалтып, материалдықты толық жоққа шығармау, өз даралығы мен өзгешелігінен қорықпау, өз идеяларын әлемге ашып, сенуді үйрену, шығармашылық ойлауды дамытып, ауқымды жоспарларды жүзеге асыру, жалғыз жүруші болмай, болашақта басқаларға тәлімгер әрі көмекші бола алатындай өсу.", "шығармашылық жұмыс немесе хобби, өнермен байланыс, ғылыми қызмет, зерттеулер, философия және дін, психология және адам санасы мен әлем құрылысының заңдары туралы әртүрлі ілімдер, эзотерика және энергетикалық практикалар, оқыту және тәлімгерлік."], "8": ["Туыстарды сыйлап, құрметтеу, ата-бабаларды есте сақтау және жас ұрпаққа тәжірибесі мен кеңесімен көмектесу.\nӨзін және өз мақсат-мұратын табу өте маңызды, онсыз даму да, алға жылжу да жоқ екенін түсіну керек.\nӨмірге позитивті қарауды үйреніп, басқаларды да соған үйрету.\nКүшті қасиеттерін ашып, табиғи таланттарын дамыту. Өз өмірін, денесін және жанын бағалау.\nӨзіне сеніп, батылдық, шешімділік пен көшбасшылық қасиеттерін көрсете отырып, ақталған тәуекелге бару.\nБасқаларды соңынан ертіп, оларды өзін жеңуге және қорқыныш пен жалқаулықтан арылуға шабыттандыру.\nӨзін шектемей, өзіне шекара қоймай, мақсатқа жететіндей әрекет ету, бірақ жұмсақ — басқаларға зиян келтірмей және өзгенің мүддесін аяқасты етпей.\nӨзінің көлеңкелі қасиеттерін қабылдап, оларға жол беріп, өзіне де, айналадағыларға да зиян келтірмей, оларды жұмсақ өзгерту.\nҚиындықтарды қорықпай қарсы алып, оларды жеңу арқылы тек күшейіп, саналы бола түсу.\nӨзін басқара біліп, белгілі бір аскезаны — пайдалы өзін-өзі шектеулерді сақтау.", "отбасылық құндылықтар мен дәстүрлерді қалпына келтіріп, қолдау, шежіре жүргізу, естелік жазу, ру ағашын жасау, отбасылық альбомдарды безендіріп, сақтау, есте қалатын күндер мен жылдықтарды ұмытпау, тірілерді ғана емес, дүниеден өткен ата-бабаларды да құрметтеу, олардың зиярат орындарына қамқорлық жасау, өзіне мұқиятырақ болуға уақыт табу, өз тілектеріне құлақ асып, өзіне үңілу, өз болмысын түсіну үшін өмірде әртүрлі бағыттарды байқап көру, жалығу мен мұңнан аулақ болып, өмірді жарқын сәттер мен есте қалатын істерге толтыру, рухани даму, адамгершілік және рухани заңдарды, карма негіздерін және себеп пен салдардың байланысын зерттеп, осының негізінде өз құндылықтар жүйесін құру, саяхат, хобби және әртүрлі ғылымдарды оқу арқылы ерекше қабілеттерді ашу, мақсат қою және жоспарлау жүйесін пайдалану, денені де, ерікті де жаттықтыра отырып, спортпен айналысу, материалдық та, рухани да жомарт болу, жылылық пен жанашырлық таныту, көшбасшы болып, адамдарды жеке үлгісімен және ішкі күшімен соңынан ерту, жеке және кәсіби өсуге ұмтылатындардың бәріне дана тәлімгер болу.", "медицина және психология, тәлімгерлік және коучинг, басқару және басшылық, жеке бизнес, эзотерика және өзін-өзі танудың басқа жүйелері, экстрасенсорика және регрессология, дін және рухани қызмет."], "9": ["Азғыру мен екіұшты жағдайларға тап болғанда, адамгершілік пайдасына маңызды таңдау жасау — әрі қарайғы даму осыған байланысты.\nАдамгершілікті іс жасап, адамдарға терең түсіністікпен және қолдаумен — өзіңізге қалай қарағанын қаласаңыз, дәл солай қарау.\nӘр сәтті барынша саналы өмір сүру: бүгінге сүйеніп, өткеннен қорытынды жасап, болашаққа сеніммен қарау.\nҚателіктерінен қорытынды жасап, олардан тәжірибе ала білу.\nСын мен кектен аулақ болып, өзін және эмоцияларын ұстауды үйрену.", "адамгершілік тұрғыдан даму, сөзі мен ойын қадағалау, алғыссыздыққа, мұңға, жағымсыз ойға, жалаға және күмәнға жол бермеу, адамдарды баспау және оларға ақыл үйретпеу, өз құндылықтары мен ой жүйесін таңбау, пайдакүнемдіктен, агрессиядан және қырсықтықтан аулақ болу, психологияны зерттеп, өз әрекеттерін талдау, әр күнді қуанышпен және оптимизммен қарсы алып, өмірге алғыс айтудан шаршамау, тек өз өмірін емес, айналадағы қоғам мен жалпы адамдардың өмірін жақсартуға тырыса отырып, мақсатқа жүру, істі соңына дейін жеткізу, ал болмаса, оны сәтсіздік деп санамай, жаңа жолдар іздеу, сәтсіздік пен қиындық жүгінен иілмеу, шектен тыс құрбандыққа бармай, жақындарға қамқорлық жасау, материалдыққа байланбау және кез келген істе оның адамдарға қандай пайда әкелетініне сүйену, қайырымдылықпен айналысып, мұқтаждарға, жануарларға және қолдау керек барлық адамға көмектесіп, одан шынайы қуаныш алу, стиль сезімі мен әлемге кең көзқарасты дамыта отырып, өнерді зерттеп, насихаттау.", "өнер, актёрлық қызмет, шығармашылық, музыка, саяхат, оқыту және тәлімгерлік, спорт, медицина және психология, емшілік."]}, "real": {"1": [[["Базалық қажеттіліктерді қанағаттандыру", "Жеткілікті тамақ пен қауіпсіздік арқылы қамтамасыз етіледі: адам тоқ болып, өзіне жайлы және ештеңе қауіп төндірмейтін жерде болуы керек."], ["Тұрақтылық пен орнықтылық", "Дене жаттығулары мен спорт арқылы денені және төзімділікті нығайту арқылы сақталады. Тұрақтылық өзін ру жүйесінің бөлігі ретінде сезіну арқылы да келеді: румен байланысты сақтау, берік отбасы, мықты туыстық байланыстар мен дәстүрлер. Орнықтылық сезімі үшін жерге байлану (заземление) да керек — оны дене практикалары, массаж, жермен және табиғатпен жұмыс береді."], ["Дене мен ақылдың икемділігі мен қозғалғыштығы", "Қимыл белсенділігі, саяхат және жаңа әсерлер арқылы дамиды."], ["Өмірге сену және өз болмысына сенімділік", "Базалық қажеттіліктерге байланысты қорқыныш пен сенімсіздікпен жұмыс істеу арқылы жетеді. Сондай-ақ ашу мен агрессияны жұмсақ түрде өзгертудің жолын тапқан маңызды."]], "денемен байланысты кез келген жұмыс, спорт, өз денеңмен жұмыс (спортшы, пауэрлифтинг, йога, би), денені көрсету (фотомодель, бодибилдер), басқалардың денесімен жұмыс (массажист, тату-шебер, маникюр және педикюр шебері және т.б.), шыдамдылық, төзім, ұқыптылық, тәртіп пен режим маңызды мұқият жұмыс, құрылыс, өндіріс, бағбандық және фермерлік, сапармен және саяхатпен байланысты дене жұмысы."], "2": [[["Сезімталдық", "Берік үйлесімді қарым-қатынас пен жайлы жақын өмір арқылы сақталады. Өмірдің бұл жағынан алыстамай, бірақ оған тәуелді де болмай, өз денеңді және серіктестің денесін тану маңызды."], ["Ұрпақ жалғастыру", "Аналық немесе әкелік рөл және балалармен, ата-анамен үйлесімді қарым-қатынас арқылы жүзеге асады. Жыныс жүйесінің денсаулығын сақтап, бала көтеруді жауапты әрі сауатты жоспарлау маңызды."], ["Ләззат пен денелік", "Өз денеңді қабылдау, орнықты өзін-өзі бағалау және өзіңді жақсы көру, өзіңді еркелете білу және өмірдің қуанышын сезіну арқылы ашылады. Бұл қасиеттерді спорт, би, су процедуралары, спа, массаж және дене практикалары дамытады. Өзіңізге демалуға, босаңсуға және эмоцияны шығаруға рұқсат беріңіз, бірақ тәуелділіксіз және үнемі жалқаулықсыз."], ["Жасампаздық пен шығармашылық", "Шығармашылық жобалар мен идеяларды жүзеге асыру, өнермен және өмірдің барлық көрінісіндегі сұлулықпен байланыс арқылы жүзеге асады."]], "балалармен және отбасылармен жұмыс, сұлулық және демалыс саласы, ойын-сауық және әртістік керек нәрсенің бәрі, сексология және отбасы психологиясы, икемділік керек спорт — гимнастика, мәнерлеп сырғанау, балет, йога, кез келген би, ер адамдар үшін — шығыс жекпе-жектері, үйде жайлылық жасау, әйелдермен көп араласатын салалар, клубтар, мейрамханалар, кафе мен барлар, суда белсенділік — жүзу, сёрфинг және т.б., шопинг."], "3": [[["Ерік күші мен сенімділік", "Аскеза мен өзін-өзі шектеу, күн тәртібі және тамаққа саналы қарау, төзімділікті және жеңу арқылы әрекет ете білуді дамытатын спорт пен жүктеме арқылы нығаяды. Істі соңына дейін жеткізіп, міндеттемені кейінге қалдырмай орындау маңызды."], ["Әлемге әсер ете алу қабілеті", "Көшбасшылық қасиеттерді, ішкі энергия мен харизманы дамыту арқылы көрінеді. Адам өз шешімі, сөзі және әрекеті үшін жауапкершілікті алғанда, адамдарға басшылық ету және басқару тәжірибесімен нығаяды. Айналадағыларды бағыттай, шабыттандыра және тек өзіне емес, басқаларға да пайдалы мақсаттарды жеткізе білумен сақталады. Тек ойлап, армандап қоймай, әрекет жасау маңызды."], ["Сау өршілдік пен ниет күші", "Мақсаттылық, жоспарлау және мақсат қою дағдылары арқылы дамиды. Шынайы тілектер мен қажеттіліктерді анықтап, мақсаттар мен өмірлік жоспарларға негіз беретін практикалар көмектеседі. Ойлағанды нәтижеге жеткізіп, идеялар мен жобаларды жүзеге асыра отырып, еңбекқорлықты дамыту маңызды, бірақ сонымен бірге тәуекел мен пайданы салыстыра білу, біреудің басын баспай, әрекеттеріңіздің қаншалықты жұмсақ екенін бағалау, мақсат үшін ғана мақсатқа жетпей, түпкі нәтиже не үшін керек екенін түсіну керек."]], "қоғамдағы табыс пен мансаптық жетістіктерге байланысты нәрсенің бәрі, инвестициялар, маркетинг, қаржы және банк саласы, спорт және жаттықтырушылық, саясат, сатылым және жылжыту, коучинг, нутрициология, тамақтану саласы."], "4": [[["Эмоциялық өзара әрекет пен алмасу", "Үйлесімді орта құру және жақындармен, достармен мейірімді, сенімді қарым-қатынаста көрінеді. Аяушылықтан емес, таза жүректен жанашыр бола және бірге күйзеле білу арқылы дамиды. Жағымсыз эмоциялармен жұмыс істеу, ашуды жұмсақ шығару тәсілдері, келісе білу, ымыра табу және алғыс айта білу арқылы жетеді."], ["Өмір мәні мен өз пайдасын іздеу", "Адамдар мен жануарларға көмектесу, қайырымдылық пен волонтёрлықта — жауап пен алғыс күтпей, ресурстан және өзіне зиян келтірмей көрінеді. Тек материалдық игілікпен өлшенбейтін өмір мәні мен өз миссиясын табу маңызды. Шығармашылық, хендмейд, тамақ әзірлеу және өз қолымен бірдеңе жасау арқылы да табылады."], ["Ішкі тұтастықты сақтау", "Өзіне-өзі жеткілікті болуды дамыту арқылы жүзеге асады: адам өзін-өзі бағалау үшін өзгенің үмітін ақтауға ұмтылмай, мейірімді әрі ашық болады. Тәуелсіздікпен және өз сезімі мен эмоциясын өзгенікінен ажырата білумен сақталады. Кінәламай және сынамай, кешіре білу арқылы дамиды."]], "медицина және ветеринария, психология және коучинг, эзотерика, нумерология, таро, руналар, массаж, қол шеберлігі, емшілік, қолөнер, оқыту және тәрбиелеу, аспаздық, косметология, қайырымдылық және волонтёрлық."], "5": [[["Шынайылық пен өзін білдіру еркіндігі", "Шешендік және актёрлық шеберлік, көпшілік алдында сөйлеу, қоғамдағы белсенділік пен жүзеге асу арқылы дамиды. Шығармашылықта, креативтілікте және ерекше көзқараста көрінеді. Адам әлемге сене отырып, өз тілектері мен эмоциялары туралы адал айтқанда ашылады. Кез келген эмоцияны, тіпті жағымсызын да, басқаларға ыңғайлы тәсілмен (әңгіме, хат, диктофон, жазушылық және т.б.) білдіру арқылы сақталады."], ["Жұмсақ араласу және адамдармен жемісті өзара әрекет", "Ол үшін өзгенің пікірін тыңдауды және — егер дау мүлде керек болса — әдепті дауласуды үйрену керек. Дипломатиямен, ымыраға ұмтылумен және үйлесімді шешім іздеумен сақталады. Адамдарға білім жеткізуге, өз идеяларымен шабыттандыруға және қызықтыруға деген ниетте көрінеді."], ["Адалдық және адамгершілік негіздерді ұстану", "Қоғам заңдарын сақтау, сөйлеу мәдениеті және ымыраға негізделген араласу арқылы жүзеге асады. Этикалық және моральдық нормаларды сақтаумен — кекесінсіз, цинизмсіз, айқай мен балағатсыз нығаяды. Өзіне және басқаларға адал болу, шындықты мойындап, айта білу арқылы дамиды."]], "шығармашылық әуестіктер, дауыспен жұмыс, актёрлық және музыкалық қызмет, шешендік және дәріс оқу, оқыту, жазушылық, көркем қызмет, заң саласы, көпшілік алдында сөйлеу және блогинг, коучинг және тәлімгерлік, психология, сатылым, медиация (даулардағы делдалдық)."], "6": [[["Ақпаратты бақылау және талдау", "Әртүрлі жоспарлау, болжау және стратегия әзірлеу арқылы дамиды. Ойлау жүйесі, құндылықтары, басымдықтары мен жетістіктері әртүрлі адамдармен араласу арқылы нығаяды. Зерттеулер және өз ой еңбегінің өнімін жасау (кітап, курс, тәлімгерлік, дәрістер, бағдарлама және т.б.) арқылы жүзеге асады. Оқып, өмірдің әртүрлі сұрақтарына жауап табу, тіл үйрену керек."], ["Ақылды сақтау және дамыту", "Оқу, жаңа дағдылар, кітап оқу және әлемнің әртүрлі жүйелерін зерттеу арқылы жүзеге асады. Ақылды жаттықтыру — құрастыру, басқатырғыштар, есептер, пазлдар және т.б. арқылы нығаяды. Жаңа идеялар туғызу және оларды жүзеге асыру арқылы дамиды."], ["Түйсікке сену", "Ой ағынын тоқтата білу және дененің белгілері мен сигналдарын байқау арқылы келеді, бұған табиғат та көмектеседі. Оңашалықта, дене практикалары мен медитация кезінде, ниет күші немесе сұраныс арқылы дамиды. Ішкі әлемнің көрінісі ретінде қиял мен елестетуді дамытатын шығармашылық жазу арқылы ашылады."]], "оқыту және тәлімгерлік, өнертапқыштық және зерттеулер, жазушылық және сценарийлер, бағдарламалау және IT, креативті идеялар мен шешімдер табу керек нәрсенің бәрі, интеллектуалдық және ғылыми қызмет."], "7": [[["Тұлғалық өсу және өзін-өзі дамыту", "Әртүрлі білім алу, жасырын ілімдерге — эзотерика мен энергетикалық практикаларға қызығу, психология мен философияны зерттеу арқылы жүзеге асады. Адам өз ерекшелігін анықтап, таланттары мен күшті қасиеттерін дамыту арқылы өмірлік стратегиясын құрғанда ашылады. Адам өз өмірі, сөзі мен әрекеті үшін жауапкершілікті алғанда дамиды."], ["Өмірдің рухани жағын дамыту", "Әртүрлі діни ілімдер мен нанымдарды зерттеу және өзін Құдайлық бастаудың бөлшегі ретінде тану арқылы жүзеге асады. Ғалам заңдарымен өмір сүру — тағдыр бергенді қабылдау және ол үшін алғыс айта білу арқылы жетеді. Әлем заңдары мен өмірдің кармалық негіздерін түсіну арқылы нығаяды."], ["Саналылық пен таңдау еркіндігі", "Өз ойлары мен әрекеттерінің күшін, бағыты мен түпкі мақсатын түсіну арқылы нығаяды. Өзін болашақты осында және қазір жасайтын өз өмірінің жасаушысы ретінде сезіну арқылы жүзеге асады. Меншікке құмарлық пен материалдық құндылықтарға байланушылық болмағанда дамиды."]], "шығармашылық жұмыс немесе хобби, өнермен байланыс, ғылыми қызмет, зерттеулер, философия және дін, психология және адам санасы мен әлем құрылысының заңдары туралы әртүрлі ілімдер, эзотерика және энергетикалық практикалар, оқыту және тәлімгерлік."], "8": [[["Өз мақсаттарын түсіну және оларға жету", "Әрекеттегі табандылық пен төзімділік, өзгерістер мен қиындықтарды қабылдау және оларды жеңу (мысалы, дене жүктемесі мен спорт арқылы) арқылы жүзеге асады. Мақсат қою және әрекеттегі жүйелілік арқылы нығаяды. Көшбасшылық қасиеттер және айналадағыларды шабыттандыруға деген ниет арқылы жетеді."], ["Рухани даму", "Әртүрлі діни ілімдерді зерттеу және өзін Құдайлық бастаудың бөлшегі ретінде қабылдау арқылы жүзеге асады. Ғалам заңдарымен өмір сүру — тағдыр бергенді қабылдау және ол үшін алғыс айту арқылы жетеді. Адам өз әрекеті мен ойы үшін жауапкершілікті алғанда нығаяды."], ["Ішкі тұтастықты сақтау", "Өзіне-өзі жеткілікті болуды дамыту және өмір мәнін табу арқылы жүзеге асады. Өзін болашақты осында және қазір жасайтын өз өмірінің жасаушысы ретінде сезіну арқылы жүзеге асады. Өткенді босатып, апатия мен жалқаулықта қалып қоймау арқылы нығаяды."]], "психология және философия, тәлімгерлік және коучинг, басқару және басшылық, жеке бизнес, эзотерика және өзін-өзі танудың басқа жүйелері, экстрасенсорика және регрессология."], "9": [[["Саналылық пен әлемге сенім жолы", "Әртүрлі, кейде терең өзгерістерден өтіп, олардан алғыспен пайдалы тәжірибе ала білу арқылы қалыптасады. Сана мен санасыздық психологиясын, философияны және өмірдің терең ақиқаттарын зерттеу арқылы нығаяды — бұл әр жолы нақты жағдай үшін ең жақсы шешімді таңдауға көмектеседі. Адалдық пен әділдіктің өз ішкі кодексіне және жеке жауапкершілікке негізделеді."], ["Адамгершілік және басқаларға көмек", "Өзін, басқаларды және өмір жағдайларын қабылдау, адамдарға көмектесу және оларды бағыттау арқылы өмір сүру арқылы дамиды — бұл волонтёрлық та, қандай да бір саладағы тәлімгерлік те болуы мүмкін. Себеп пен салдарды түсіну, байқағыштық және ұсақ-түйекке назар аудару арқылы қалыптасады. Әртүрлі жағдайларды, ішкі және сыртқы дауларды шешуге көмектесетін жанашырлықпен нығаяды."], ["Ішкі күшті басқару", "Айналадағыларға агрессия мен төзбеушіліктен бас тарту және жағымсыз эмоциялармен жұмсақ жұмыс істеу арқылы жетеді. Адам бәрінде шектен шығудан — құрбан болуға дайындықтан да, озбырлыққа, өз еркімен кетуге және басқаларды басуға бейімділіктен де — аулақ болғанда нығаяды. Ішкі тәртіп пен дене күйіне қамқорлық (мысалы, спорт пен жүктеме) арқылы қалыптасады."]], "өнер, актёрлық қызмет, шығармашылық, музыка, саяхат, тәлімгерлік және оқыту, спорт, медицина, емшілік."]}, "life_scen": {"0": "0 саны бар кезең — нөлдену, «таза парақ» уақыты. Оның қалай көрінетінін болжау қиын.\nМұндай кезеңде өз шындығын тек адамның өзі қалыптастырады — жаңа, жинаған тәжірибесіне немесе бұрынғы өмірлердің тәжірибесіне сүйене отырып.\nБұл кезең керемет сәттілік және судан құрғақ шыға білуді әкелуі мүмкін, ал бетбұрыс оқиғалары мен дағдарыстар уақыты да болуы мүмкін.\n0 кезеңін жақсы жағынан өмір сүру үшін адамның санасында адамгершілік және рухани негіз қалыптасып, өмірлік міндеттер мен бағдарлар анықталып, мақсаттар қойылған болуы керек.\nСонда кезең сәттілікке толып, мақсаттар айқын пішінге ие болады, адам қалағанын тез алады. Керек уақытта керек адамдар келіп, керек таныстықтар пайда болып, ресурстар табылып, оны әртүрлі салаларда жаңа деңгейге шығаратын оқиғалар болады.\n### Әсер ету нұсқалары\nнөлдену және түбегейлі өзгерістер, сәттілік пен жолдың болуы, өз бағдарынсыз ағынмен өмір сүру. Көбіне 0 саны бар кезең кодтың екінші санының қасиеттері мен оқиғаларымен жұмыс ретінде көрінеді.", "1": "Бұл кезең дене дамуымен, дененің мүмкіндіктері мен төзімділігін тексерумен тығыз байланысты. Бірақ сонымен бірге ол өзіне ұқыпты қарауды, жайлылыққа, ыңғайлылыққа және денсаулыққа қамқорлық жасауды талап етеді.\nРумен өзара байланыс, отбасылық құндылықтар мен дәстүрлерді түсіну өте маңызды болады.\nКезең адамға тұрақтылық пен өз күшіне сенімділік береді — немесе соларға деген күшті ұмтылыс.\nБазалық қажеттіліктерді — баспана, тамақ, отбасын құруды қамтамасыз ету үшін жұмыс істеп, даму қажеттілігі пайда болады.\nБұл уақытта адам табиғатпен және жермен байланысын ерекше сезінеді, бұл оған белсенділік пен дене күшін көрсетуге көмектеседі.\nКезең батылдықты, шешімділікті және дау мен дағдарыстан сауатты әрі тиімді шыға білуді талап ететін жағдайлар туғызуы мүмкін.\nАдам өзі қозғалмай, бір орында тұрып қалса, тағдыр оны алға итермелеп, сынақтар жібере бастайды.\nАдамда өз өмірін өз бетінше құрып, ол үшін жауапкершілікті алу мүмкіндігі пайда болады.", "2": "Бұл кезең отбасылық және серіктестік қарым-қатынаспен байланысты. Алдыңғы орынға үйлесімді байланыстар, жеке өмір және ұрпақ жалғастыру шығады.\nСабақтастық, отбасының бірлігі, бір-біріне қамқорлық, қолдау және өзара құрмет тақырыптары ерекше назар мен тексеруді талап етеді.\nОсы кезеңде берік отбасына, достыққа және туыстармен шынайы жылы қарым-қатынасқа келу маңызды. Сондықтан дәл осы уақытта қарым-қатынас құруға, берік отбасы құруға, бала сүюге (балалы болуға) деген ниет күшеюі мүмкін. Алайда көп нәрсе қазіргі жағдайға байланысты: серіктеспен қарым-қатынас өте шиеленісіп, улы (токсичные) болып кетсе, мүмкін, ажырасатын уақыт келген шығар.\nБұл кезеңде мына сұрақтар өзекті: «Мен өз денемді жақсы көремін бе?», «Мен өзімді қабылдаймын ба?», «Өзіме жай ғана босаңсып, ләззат алуға рұқсат беремін бе?». Олардың бәрі өзін, өз сезімталдығын зерттеумен және өз құнын түсінумен байланысты.\nЖасауға, жаңа нәрсе құруға және өзінің жарқын даралығын білдіруге деген ниет пен қажеттілік пайда болады.\nӨз шекарасын қорғап, бірге тәуелділіктен аулақ болып, қарым-қатынасты сау өзара әрекетке құруды үйрену керек болатын жағдайлар қалыптасуы мүмкін.\nАдамда өзін қабылдау, өз сезімталдығын тану және тәуелділікке басымен кетпей, босаңсуды үйрену мүмкіндігі пайда болады.", "3": "Бұл кезең ерік күші мен өзін-өзі тәртіпке салуды дамытумен байланысты. Адам ойлана бастайды: «Мен қайда барамын?», «Менің мақсаттарым қандай?», «Мен әр әрекетті не үшін жасаймын және әлемге қалай әсер етемін?», «Мен іштей қаншалықты күшті әрі орнықтымын?».\nБұл уақытта жоспарлау мен мансаптық өсу өзекті, бастама көтеру қажет болады.\nАқша табу және көбейту қажеттілігі пайда болады, кезең бұған ықпал етіп, өсуге мүмкіндік береді.\nБұл кезеңнің қиындықтары мінезді шыңдап, рухани да, ой жағынан да өсу үшін сенімділікті сезінуге көмектеседі.\nБұл уақытта билік көрсеткісі және басқаларға қысым жасағысы келуі мүмкін — немесе мұндай қасиеттерді адамның өзіне қатысты көрсетеді.\nТәуелділікке, бақылаусыз тамақтануға және тамақтану әдеттерінің бұзылуына итермелейтін жағдайлар болуы мүмкін.\nКез келген жағдайда кезең өзін бақылауды, қоғамда жүзеге асуды, нақты мақсаттар мен оларға жетудің ойластырылған тактикасын талап етеді. Әйтпесе мансапта кедергілер, ақшаның жетіспеуі және қиындыққа төзбеушілік болуы мүмкін.\nБұл кезеңде адам ішкі күш, табандылық және тамаққа, ақпаратқа, заттар мен қызметтерге саналы қарау арқылы өз тағдырын басқаруды үйреніп, жағдайдың иесі бола алады.", "4": "Бұл кезең адамдармен қарым-қатынас және өзін қабылдаумен байланысты.\nБұл уақыт ең алдымен өзін шартсыз жақсы көруді үйрену, содан кейін адамдарға көмектесіп, оларға қамқорлық жасай отырып, адамдарға деген махаббатты дамыту үшін берілген.\nБұл — жүректің ашылу және ішкі тірек табу кезеңі. Кешіруге, алғыс айтуға және жанашыр болуға үйрететін жағдайлар туындауы мүмкін.\nБұл уақытта адам өкпеге немесе бүкіл әлемге ашуға, өзімшілдікке және өзін қабылдамауға тап болуы мүмкін. Ол жан қанағаты мен бақытқа ұмтылып, серіктестер мен эмоциялық қолдау іздеуі мүмкін.\nӘлемге өз сезімін, эмоциясын және шығармашылығын беру, көмектесу және қолдау қажеттілігі пайда болады. Көмектесетін мамандықты меңгергісі, хендмейдпен айналысқысы, қайырымдылыққа қатысқысы келуі мүмкін.\nҚарым-қатынас беріктікке — дәлірек айтқанда, серіктес пен жақындарды босата білуге, оларға байланып қалмауға тексерілуі мүмкін.\nКезең шектен шықпай — салқындыққа да, құрбандыққа да бармай, эмоциялық тепе-теңдік тауып, өзін және айналадағыларды жақсы көруге және қабылдауға үйренуге мүмкіндік береді.", "5": "Бұл кезең қоғамда өзін көрсетумен және өзін білдірумен байланысты.\nАраласуға, шығармашылық немесе қоғамдық қызмет арқылы жүзеге асуға қажеттілік пайда болады.\nКезең көпшілік алдында болуды, сөз бен дауыс арқылы өзін көрсетуді, шешендік қабілет пен дипломатияны талап етеді.\nБұл уақыт іште болып жатқанды және өмір сүріп жатқанды білдіруге, қабілеттер мен таланттарды көрсетуге батылдық табуға, міндеттерге шығармашылықпен қарауға, араласу дағдыларын жетілдіруге, жаңа байланыстар орнатуға және әртүрлі адамдармен кездесуге мүмкіндік береді.\nАдам келісуді және адал әрі әдепті сөйлеуді үйренбесе, дау және заңдар мен ережелерді сақтауда қиындықтар болуы мүмкін.\nБұл кезеңде адам жұмсақ әңгіме мен ымыра арқылы ой мен эмоцияны еркін әрі сенімді білдіруді үйрене алады. Ол өзгенің пікірі үшін емес, өз ішкі қалауымен даму мен шығармашылық жүзеге асуға ұмтылады.", "6": "Бұл кезең ақылды дамыту және қолдану, өзін және әлемді тану және оқумен байланысты.\nНегізгі шешімдер мен қиындықтарды жеңу кезінде түйсік пен саналылыққа сүйену керек болатын жағдайлар туындауы мүмкін.\nАдам өзін және әлемді танымаса, болып жатқанның себептері мен жоғары мән туралы ойланбаса, өмір сүрудің мәнсіздігі сезімі және өз мақсат-мұратын түсінбеу пайда болуы мүмкін.\nКезең оқуға, жаңа дүниетаным қалыптастыруға, өмір бағытын өзгертуге жол ашады және білімді өзі жеткізіп, тәлімгер болу қабілетін береді.\nБұл уақытта ауқымды ойлау, жаңа білім мен көкірек көзін алу және оларды басқаларға жеткізу қажет болады. Сенім мен руханилық, өзін іздеу және мен кіммін деген түсінік мәселелері өзекті болады.\nАдам өміріне жаңа білімді кіргізіп, өз ақылы мен интеллектісінің жемісін пайдалана алса, жаңа көкжиектер мен мүмкіндіктер ашып, өмір сүру мәнін түсінеді.", "7": "Бұл кезең өз ішкі әлемін тану, түйсікті дамыту және өзін іздеумен байланысты.\nАлдыңғы орынға Сенімге жету, өз мақсат-мұратын және өмірдегі орнын түсіну мәселелері шығады.\nРухани білімді, психологияны, эзотериканы, өнерді зерттеу қажеттілігі пайда болады. Санасыздық пен психикалық процестер қатты әсер етеді.\nБұл кезеңде саналылықты дамытатын, жоғары деңгейдегі білім алуға, оқуға және әртүрлі зерттеулермен айналысуға көмектесетін жағдайлар туындайды.\nБұл уақыт тұрмыстық даналыққа, жан тыныштығы мен эмоциялық тепе-теңдікке жетуге мүмкіндік береді.\nАдам өзіне тұйықталып, әлемнен оқшауланбай, бұзушы өмір салты мен басып-жаныштайтын қарым-қатынастан аулақ болса, өзінің өзгешелігін, түйсігін, креативтілігін және ерекше тәсілін қабылдап, жемісті пайдалана алады.", "8": "Бұл кезең өмір мәнін іздеумен және қиындықтар мен өзгерістерді жеңу арқылы тұлғалық өсумен байланысты.\nМінезді шыңдайтын, шешімдегі батылдықты және өз әлеуетін ашуға деген күшті ниетті дамытатын жағдайлар болуы мүмкін.\nБұл уақытта көңілсіз және апатиялы көңіл-күй, өмір сүрудің мәнсіздігі мен бекерлігі сезімі келуі мүмкін. Көбіне адам бұл күйзелістерді өзі бірнеше есе күшейтіп, үрлеп жібереді.\nБірақ бұл тек бір мақсатпен болады — адам күшейіп, жағдайға даму тұрғысынан қарап, дағдарыстан өзі шығуы үшін.\nӨзін жүзеге асыру және мақсат-мұрат мәселелері өткір қойылады: мен кіммін және бұл әлемде не үшін бармын.\nАдам өз өмірі үшін жауапкершілікті алып, құрбан рөлінде қалып қоймай, өзгерістер мен құндылықтарды қайта бағалауға ішкі күш тапса, кезең әртүрлі салаларда орасан зор мүмкіндіктер береді.\nБұл уақыт материалдық және рухани дамудың жаңа деңгейіне және өмір бағытын жақсыға өзгертуге серпін болады. Бірақ мұның бәрі адам өзімен жұмыс істеп, ерік күші мен шешімділігін нығайтып, тәуелділікке, жалқаулыққа және істі кейінге қалдыруға кетпесе ғана болады.", "9": "Бұл кезең ерекше назарды талап етеді: өз күшімен ол адамның өз әрекеттері қайда бағытталғанына қарай теріс жаққа да, кезеңнің төменгі санының ең жақсы қасиеттерін дамытуға да жұмыс істеуі мүмкін.\nКез келген жағдайда тоғыздықта бумеранг заңы өте тез іске қосылады, сондықтан өз әрекеттері үшін ерекше жауапкершілік керек.\nАдам дүниетанымы мен басымдықтарын өзгертетін дағдарыс жағдайларына тап болуы мүмкін. Бірақ бұл уақыт бойындағы таланттар мен қабілеттерді барынша ашуға да жақсы, жағдайлардың сәтті тоғысу уақыты болуы мүмкін.\nӘрі қарай жүруге кедергі болған артық жүкті тастап, жаңарып, өткенді қайта ой елегінен өткізу мүмкіндігі пайда болады.\nӨмірден қуаныш әкелмеген адамдар кетуі, қанағат бермеген жұмыс пен бүкіл іс өзгеруі мүмкін.\nБірақ тоғыздықтың дәл өз кезінде бұл өзгерістердің бәрі жақсылыққа екені түсінілмеуі мүмкін.\nБүкіл әрі қарайғы өмір соған байланысты болатын маңызды тағдырлы таңдау жағдайлары болуы мүмкін. Кезең агрессия мен күш қолдануға, оның ішінде өзіне қатысты да итермелеуі мүмкін."}, "life_task": {"0": [["Кезеңді жақсы жағынан өмір сүру", "Ол үшін адамның санасында адамгершілік және рухани негіз қалыптасып, өмірлік міндеттер мен бағдарлар анықталған болуы керек. Сонда кезең сәттілікке толып, мақсаттар айқын пішінге ие болады, қалаған нәрсе тез келеді. Керек уақытта керек адамдар пайда болып, керек таныстықтар орнап, ресурстар табылып, әртүрлі салаларда жаңа деңгейге шығаратын оқиғалар болады. Кезеңнің қосымша міндеттерін кезең кодының екінші саны бойынша қараңыз."]], "1": [["Шыдамдылық пен төзімділікті дамыту", "Тәртіп және кез келген тұрақты дене белсенділігі көмектеседі."], ["Асықпай, әбігерден аулақ болу", "Өзгерістер кезінде тұрақтылықты сақтау үшін бар күшті салу. Бұған саналы ойлау мен ақыл икемділігі, табиғат, медитация және энергетикалық практикалар көмектеседі."], ["Өзіне және оқиғалардың жақсы аяқталатынына сенімді болу", "Шешім қабылдай білу және идеяларды жүзеге асыруға батылдық көмектеседі. Әрі қарай даму үшін базалық қажеттіліктерді міндетті түрде қамтамасыз ете отырып, орнығып, жүзеге асуға ұмтылу және өз өмірінің ағысына сену маңызды."], ["Денеден белсенді және энергияға толы болу", "Дене белсенділігі, саяхат пен сапарлар көмектеседі. Араласуда икемді, жеңіл қозғалатын болу, бір орында тұрып қалмау және жалқаулықта қалып қоймау маңызды."], ["Жерге байлану (заземление)", "Табиғат стихияларымен байланыс, бағбандық, жерде және жермен жұмыс, дене практикалары мен массаж көмектеседі."], ["Өз руын құрметтеу және өзін ру жүйесінің бөлігі ретінде сезіну", "Ру байланыстарын нығайту көмектеседі: туыстарды біріктіру, ру кітабы мен шежіре ағашын жасау, туыстармен араласу, ата-баба мекені мен бала кезгі жерлерге барып, кездесу, туыстарға шама келгенше көмектесу."]], "2": [["Серіктестермен және жақындармен үйлесімді қарым-қатынас құру", "Ең алдымен өзімен жұмыс істеп, сұрақ қою: мен қарым-қатынастан не қалаймын, бұл серіктес маған не үшін керек, бұл қарым-қатынас маған нені үйретеді. Өкпемен жұмыс істеп, өз шекарасын құрып, өзгенікін құрметтеу. Өзіне-өзі жеткілікті және тәуелсіз болуды дамыту, бірақ сонымен бірге басқаларға көмектесіп, қолдап, жақындарға қамқорлық жасау. Балалармен және анамен қарым-қатынасты реттеу."], ["Әлемді сезім арқылы қабылдауды үйрену", "Тәуелділікке — қоздырғыштарға да, адамдарға да — түспей, өмірден ләззат ала білу, дене сигналдары мен өз тілектеріне назар аудару, дене практикалары, массаж, сумен және су стихиясымен байланыс көмектеседі."], ["Жақын өмірді реттеу", "Өзін-өзі бағалаумен жұмыс, өзіне және өз денесіне деген махаббатты дамыту, өзіне қамқорлық көмектеседі. Жақындықты өз күйінде қабылдау, ұят сезімімен және интимдік салаға қатысты ата-ана ұстанымдарымен жұмыс істеу, өзіне толыққанды әрі сау сезімталдықпен білдіруге рұқсат беру маңызды. Өз сезімталдығын зерттеу, би, дене белсенділігі, пластика және созылу жаттығулары пайдалы."], ["Өзін шығармашылықпен білдіріп, қоғамда көріну", "Шығармашылық дағдыларды дамытатын әртүрлі істер және өзін білдіру еркіндігі, ішкі серпін шығатын шабыттандыратын жобалар, әлемнің шығармашылық сұлулығына жанасу процесінен алатын қуаныш көмектеседі."]], "3": [["Жауапкершілікті дамыту", "Мақсат қою және жоспарлау практикалары көмектеседі. Өз сөзі мен әрекеті үшін жауап беріп, уәдесінде тұру маңызды. Бұл — ішкі кемелдікті дамыту: қолға үйреткендері үшін жауап беру, әлемге, адамдарға және кеңістікке әсер ететініңді түсініп, бұл әсердің дұрыс болуына қамқорлық жасау."], ["Өршілдік пен әлеуметтік белсенділік таныту", "Басшылық пен басқару дағдылары, коучинг пен шешендік өнердегі жаңа білім көмектеседі. Қоғамдағы жетістіктер, көшбасшылық қасиеттер, пікір мен мінез-құлықтың тәуелсіздігі мансаптық өсуге ықпал етеді."], ["Қаржыны сауатты басқару", "Қаржылық сауаттылықты дамытып, ақша ағындарымен дұрыс жұмыс істеу, қаражатты сауатты жоспарлап, бөле отырып, қарыз бен несиесіз ақша жинауды және көбейтуді үйрену."], ["Саналы тұтынуды жаттықтыру", "Бұл — тек дұрыс тамақтану, күн тәртібі және «тамақ қоқысынан» бас тарту ғана емес, саналы шығын да: шкафты киім мен косметикаға толтырмау, не және не үшін сатып алатыныңызды түсіну, табиғатқа ұқыпты қарау — су мен жарықты үнемдеу, қоқысты сұрыптау. Бұған сөздің саналылығы да жатады: не және не үшін айтатынымыз, сөздің тазалығы мен әдептілік, ашу мен ызаны өзіне және адамдарға бағыттамай, оны жеңе білу."], ["Төзімділік пен ерік күшін дамыту", "Әртүрлі аскеза мен шектеулер, тоқырауы мен әдеттік қозғалыссыз дене және ой белсенділігі, күту режимінен шығу көмектеседі. Спорт, ынталандыратын жаттығулар мен жарыстар сенімділік пен табандылыққа жетуге көмектеседі."]], "4": [["Өзін жақсы көруді және қабылдауды үйрену", "«Ішкі баламен» жұмыс істеу практикалары және туғаннан бар өз құндылығыңды сезіну, ата-анамен қарым-қатынаспен жұмыс көмектеседі. Сізді қолдайтын, шабыттандыратын және позитивті ойлайтын жайлы араласу ортасын қалыптастырыңыз. Сізді сынауға, жетістігіңізді кемсітуге жол беретін және пікіріңізді бағаламайтындармен қоштасыңыз. Улы (токсичные) адамдардан аулақ болып, қысым мен кемсітуге жол бермеңіз."], ["Эмоциялық тепе-теңдік табу", "Қуаныш әкелетін нәрсеге шоғырланып, айналадағы жақсыны көру. Алғыс айтуды жаттықтырып, оны әдетке айналдыру (алғыс күнделігі, алғыс хаттары). Өкпе мен жағымсыз эмоциялармен жұмыс істеу тәсілдерін (арт-терапия, нейрографика және т.б.) жаттықтыру, эмоция күнделігін жазу. Эмоциялық интеллектті және өзімен, айналадағылармен қарым-қатынастың психологиялық негіздерін зерттеу. Өкпе — сіздің таңдауыңыз және жауапкершілігіңіз екенін қабылдап, өкініп, кешірім сұрап, өзі де өкпе сақтамау."], ["Басқаларға көмектесу және қамқорлық жасау", "Қайырымдылық пен волонтёрлық көмектеседі. Үй жануарын асырап, оған қамқорлық жасау, аспаздық курсынан өтіп, өзіне және жақындарға сүйіспеншілікпен тамақ әзірлеу әдетін қалыптастыру — мысалы, демалыста, өз қолымен бірдеңе жасау (хендмейд, мүсін, тоқу, сурет салу) пайдалы. «Алу — беру» тепе-теңдігін ұмытпаңыз: көмектің бір бөлігін біз тегін, ресурстан көрсетеміз, бірақ бұл жақындарға күшпен жақсылық жасап, өзін шаршатып, құрбандыққа «құлау» керек дегенді білдірмейді. Медитация мен дене практикалары арқылы махаббат энергиясына толыңыз, өзіңізге қуаныш жасаңыз — мысалы, сізге ресурс беретін жағдайлар мен істердің тізімін жасап, керек кезде соған жүгініңіз."], ["Рухани дамып, адамгершілік заңдарын ұстану", "Әлем заңдары мен рухани әлемді танитын адам мұң мен көңілсіздікке берілмейді, өйткені бәрі бумерангпен қайтатынын түсінеді: не таратсам, соны аламын. Тек өзі үшін өмір сүрмеуді, өз эмоциясы мен эгосына тұйықталмауды үйрену маңызды — сонда өкпе мен ашуға орын жоқ бүкіл әлеммен бірлік сезімі келеді. Қиындықтарды өмір тәжірибесінің керекті бөлігі ретінде қабылдау. Бұл өмір сүруге, жасауға және өткен әр күн үшін алғыс айтуға деген ниет туғызады. Өзіне және айналадағыларға адал болып, бетперде мен екіжүзділіктен аулақ болып, өзінің шынайы болмысын көрсету маңызды."]], "5": [["Адамдармен жемісті араласуды үйрену", "Бұған ой, сезім және эмоцияны дұрыс білдіру және кез келген адаммен ортақ тіл таба білу арқылы жетеді. Айқай мен дауысыз сындарлы сөйлесуді, ымыраға оңай баруды және келісуді үйрену — бірақ сонымен бірге өз көзқарасын айтудан және дауыс харизмасымен адамдарға әсер етуден қорықпау. Басқаларды сөзбен баспай, тыңдап, ести білу. Араласу дағдыларының жемісін көру: келісім жасау, дауды шешу, жоба алу, мәселе шешу."], ["Өзін білдірудің жолдарын табу", "Жағымсыз эмоциялардан әңгіме, күнделік немесе әртүрлі тәсілдер (мысалы, нейрографика мен арт-терапия) арқылы арылу әдеті көмектеседі. Бұл энергияның үйлесімді ағуына мүмкіндік беру маңызды — ән айту, диктофонға жазу, жастыққа немесе далаға айқайлау арқылы. Кез келген жағдайда тамақтағы қысылуды жою керек. Шешендік және актёрлық шеберлік курстары мен көпшілік алдында сөйлеу дағдылары пайдалы."], ["Шығармашылықта жүзеге асу", "Өзіңізге бала немесе жас кезіңізде армандаған нәрсені — ән айтуды, өлең, әңгіме жазуды және т.б. істеуге рұқсат беріңіз. Қабілеттер мен таланттарды көрсете отырып, сіз өз ерекшелігіңіз бен сенімділігіңізді көрсетіп, өзін-өзі бағалауды теңестіресіз. Әлемге өзіңіз туралы айта білуді және естілуді жаттықтырыңыз."], ["Араласуда адамгершілік заңдарын сақтау", "Адамдармен және жақындармен араласуда моральдық және этикалық нормаларды сақтау: дауысты көтермеу, балағат сөзден аулақ болу. Шындықты айтып, адал болу, бірақ бұл шындықпен және сынмен жаралап, әңгімелесушіден жоғары тұрмай, әдеппен және орынды айту. Мазақ, кекесін, кемсітетін сөздер мен қорлауды қолданбау."]], "6": [["Ойлауды кеңейтіп, түйсікті тыңдау", "Қоғам немесе жақындар таңған қалыптар мен ұстанымдардан шығу. Стратегия құра отырып, ауқымды ойлауды үйрену. Шешім қабылдағанда ішкі дауыс пен сезімге құлақ асу — ол үшін ақылды тыныштандырып, талдау мен логиканы тоқтатып, басқа демалыс беріп, денені сезіп, санасыздықты есту үшін уақыт, орын және тәсіл табу."], ["Рухани саналылықты жаттықтыру", "Әлем заңдарын және адамзаттың рухани негізін зерттеу, өз ойын, сезімі мен эмоциясын талдай білу көмектеседі — бұл әртүрлі жағдайлардың неге және не үшін болатынын түсінуге көмектеседі. Осылай адам өз әрекеттері мен айналадағылардың әрекеттері жай ғана емес, тепе-теңдік пен бумеранг заңы бойынша болатынын және олар ойдың жүзеге асуының салдары екенін түсінеді. Бұл әлем заңдарын түсініп, оларды бұзбай, саналы әрекет етіп, ойлана отырып, өмір құруға көмектеседі."], ["Ақыл мен талдау қабілетін дамыту", "Жаңа білім алу, ми шабуылына қатысу, оқу және деңгейді үнемі көтеру пайдалы. Ақылды ашып, күшейтуге басқатырғыштар, сөзжұмбақтар, жұмбақтар мен квесттер көмектеседі."], ["Идея туғызып, оларды жүзеге асыру стратегиясын құру", "Көп идея мен арман өлі жүк болып жатпауы үшін әрекет ету керек: идеяларды ұзақ жәшікке салмау және қиялға берілмеу. Ойлағанды жүзеге асырудың кезеңдерін жоспарлап, үлкен мақсатты шағын мақсаттарға бөліп, мерзім белгілеп, құрал таңдау. Күн сайын бірдеңе істеп, практикалық қадам жасап, осылай қалағанды жүзеге асыру."]], "7": [["Рухани дамуға ұмтылу және әлем заңдарын қабылдау", "Сенім мен рухани тірекке жетуге өмірдің өзі — рухани нәрсенің дене арқылы көрінуі екенін түсіну көмектеседі. Сондықтан рухани даму әртүрлі діндер мен карма заңдарын зерттеу арқылы ғана емес, адамдардың әрекеті мен сөзінің себептерін өз ішкі әлемі арқылы ой елегінен өткізу арқылы да жүреді. Әлем құрылысын, адамгершілік және рухани заңдарды зерттей отырып, адам әлемде бәрі біртұтас әрі байланысты деген ішкі сенімге ие болады. Ол өз әрекеттері мен айналадағылардың әрекеттері кездейсоқ емес, тепе-теңдік пен бумеранг заңы бойынша және ойдың жүзеге асуының салдары ретінде болатынын түсінеді. Бұл жаңалық өзіне және айналадағыларға адал болуға, бетперде мен екіжүзділіктен аулақ болып, өзінің шынайы болмысын көрсетуге мүмкіндік береді."], ["Өзін-өзі дамытумен айналысу", "Жоғары күштерді, Ғалам белгілерін және түйсікті жоққа шығармай, оларды зерттеу. Бұл білімнен жауап сезініп, ақпаратқа еніп, өз психикасы мен ақылының жаңа мүмкіндіктерін ашу. Ең жақсы қасиеттер мен қабілеттерді аша отырып, жетілу. Санасыздық пен денеге құлақ аса отырып, түйсікті дамыту."], ["Эмоциялық тепе-теңдік табу", "Өз Күш Орнын — энергия беретін қайнар көзді табу: сенім, шығармашылық, әлем туралы дәстүрлі емес білім мен ғылымдар (психология, философия, нумерология және т.б.). Медитация, табиғат стихиялары және оңашалық арқылы ішкі диалогты тоқтатуды үйрену. Психологпен жұмыс істеу, психологиялық құралдар мен тәсілдерді пайдалану. Сын мен айыптаудан аулақ болу, өзіндегі тәкаппарлық пен мақтаншақтықты байқап, тоқтату."], ["Өз ерекшелігін көрсету", "Тек материалдықпен емес, жоғары құндылықтармен және басқаларға көмекпен байланысты мақсат қою, бірақ елестерге кетіп, шындықпен байланысты жоғалтып, материалдықты толық жоққа шығармау. Өз даралығы мен өзгешелігінен қорықпау, өз идеяларын әлемге ашып, сенуді үйрену. Ойлағанды жүзеге асыруды ұмытпай, шығармашылық ойлау мен креативті ұсынуды дамыту. Болашақта басқаларға тәлімгер әрі көмекші болу үшін рухани және адамгершілік тұрғыдан өсу."]], "8": [["Құрбан рөлінен шығу", "Әлем мен адамдар бізге ештеңе қарыз емес екенін түсіну көмектеседі: үміт неғұрлым аз болса, көңіл қалу мен өкпе соғұрлым аз. Жағымсыз ойлар мен өзін құрту сәттерін уақытында байқап, олармен — өзіңіз немесе психологпен — жұмыс істеңіз. Психология, эзотерика, философия және әлем заңдарын (бумеранг заңы, «ұқсас ұқсасты тартады», энергия тепе-теңдігі заңы және т.б.) зерттеу көмектеседі. Қуаныш пен шабыт әкелетін істерді, орындарды немесе жағдайларды тауып, оларға үнемі жүгініңіз."], ["Қиындықтарды жақсы өмірге апаратын саты ретінде қабылдау", "Өз сезімі мен әрекеті үшін жауапкершілікті алыңыз. Жағдайды өзгерте алсаңыз — өзгертіңіз! Өзгерте алмасаңыз — бейімделіп, оған көзқарасыңызды өзгертіңіз. Ауыр ойлар азырақ, сындарлы шешімдер мен әрекеттер көбірек болсын. Бастама, жағдайды бақылауға алып, оны шешу үшін өз стратегиясын қолдана білу көмектеседі. Салауатты өмір салтын ұстанып, тамақтануды қадағалаңыз, аскеза мен шектеулерді жаттықтырыңыз — дәм әдеттерін өзгертіп, сау денеге алғашқы қадам жасайтын нақ уақыт. Спорт, дене және күш жүктемелері, күнделікті күш салу бекер кетпейді: олар өзін жеңу және күш салу арқылы әрекет ету әдетін қалыптастырады, бұл кезеңде ол өте пайдалы."], ["Өмірдің рухани жағын қабылдау", "Әлем құрылысының заңдары мен рухани әлемді танитын адам мұң мен көңілсіздікке берілмейді, өйткені бәрі бумерангпен қайтатынын түсінеді: не таратсам, соны аламын. Бұл әлем заңдарын түсініп, оларды бұзбай, саналы әрекет етіп, ойлана отырып, өмір құруға көмектеседі. Жоғары мақсаттар мен мақсат-мұратқа еру шектен тыс материалдықтан және тұрмыстық ұсақтықтан алыстап, өмір сүру мәнін түсініп, өз құнын сезінуге көмектеседі."], ["Көшбасшылық қасиеттер мен тұлғаны дамыту", "Айналадағыларға құрметпен әрі әдепті қарай отырып, табандылық пен шешімділік, өз қажеттіліктерін түсіну және қанағаттандыру көмектеседі. Жаңа білім мен ақпарат, ерік-жігері мен харизмасы мықты адамдармен танысу — мұның бәрі өсуіңізге ықпал етеді. Қоғамдағы жетістіктерге және мансаптық өсуге, қажет болса — істі толық ауыстыруға ұмтылыңыз. Өз бетінше шешім қабылдауды және өзін басқаруды үйрену маңызды."]], "9": [["Өз күшін басқаруды үйрену", "Энергияны дұрыс басқару оның әлеуетін жасампаз арнаға — әлеуметтік белсенділікке, шығармашылыққа, басқаларға жобаларды жүзеге асыруға көмектесуге бағыттауға көмектеседі. Ашу мен агрессияны жеңіп, олардан жұмсақ арылуды үйрену маңызды. Спорт және тұрақты дене белсенділігі, энергиялылық пен ұлы істерге ұмтылыс, ерік күшін дамыту, аскеза мен шектеулер, салауатты өмір салты көмектеседі. Эмоцияны басқаруды және ішкі тепе-теңдікті сақтауды үйрену маңызды — бұған жеке шекаралар, ортаны мұқият таңдау, дене практикалары және психологпен жұмыс көмектеседі."], ["Өзін-өзі дамыту және жетілдіру жолын таңдау", "Бұл — өзімен үнемі және жан-жақты жұмыс істеу, әртүрлі салада — дене, интеллект, шығармашылық және эмоция салаларында ең жақсы қасиеттерді дамыту. Өзін-өзі дамыту ерік бостандығымен және өзін бақылаумен қатар жүреді, адам сырттан қысымсыз жаңаны үйреніп, оны іс жүзінде қолданады. Бұл процесте жаңа білім, оқу, дағдыларды жетілдіру және әртүрлі салада жалпы сауаттылықты арттыру керек."], ["Рухани бағдарлар мен адамгершілік құндылықтарды қалыптастыру", "Өзін-өзі талдау, әлем құрылысының заңдарын тану және ішкі рухани негіз жасау көмектеседі. Оның үш тірегі — алғыс, махаббат және жеке жауапкершілік. Алғыс айта білу жағымсыз эмоциялар мен өкпеден аулақ болуға көмектеседі. Өз әрекеті үшін жауапкершілік сезімі саналы өмір сүруге, жақсара түсуге және адамгершілік жағынан кемелденген адам болуға — айналадағыларға адал, моральдық және этикалық нормаларды ұстанатын, шекарадан аспайтын және жақсылықтан әрекет ететін адам болуға мүмкіндік береді. Рухани қағидаларды түсінудің арқасында сенім әрдайым ішіңізде қалады, ал бұл үмітсіздікке берілмеуге, әлемді тануға ұмтылуға және құмарлықтан, тәуелділіктен және бұзушы ойлардан еркін болуға көмектеседі."]]}, "contours": {"Сангвиник-Флегматик": "Мұндай адамдар жерге берік басқан: оларға өмірдің берік негізі мен тұрақты қаржылық жағдай керек. Олар бәрінде жайлылық пен ыңғайлылықты бағалайды, сондықтан мақсатқа жету үшін еңбекқорлық пен табандылығы жетеді.\nОлар үшін ең маңыздысы — молшылық және кәсіби жүзеге асу мүмкіндігі. Мұндай адамдар таланттары мен табиғи қабілеттерін шығармашылықта да, дене күші керек жерде де көрсете алады.\nМұндай адам байыптылық пен парасаттылықты сақтай отырып, бір сарынды, тіпті күнделікті жұмысты ұзақ орындай алады. Ол бәрінде жүйе мен тәртіпті қалайды. Бұлар — дау мен агрессияға бейім емес, араласуға бейім сабырлы әрі өмірге құштар адамдар, сондықтан әдетте олардың достары көп, таныстар шеңбері кең. Сенімділік пен ақыл-парасаттың арқасында ол күтпеген жағдайда және қиын ахуалда өзін ұстай алады.\nОл әртүрлі қиындықты жеңе алады, өйткені басымдықтарды дұрыс қойып, көп жұмыс істеп, стратегиялық дұрыс жоспар құра біледі. Не болса да, ол қол қусырмай, ісін жалғастырып, нәтиже үшін күте біледі.\nАлға жылжуға оған өмірге әрдайым позитивті көзқарас, шыдамдылық, ықылас, мақсаттылық, бірдеңені құрбан етіп, өзін шектей білу көмектеседі. Мұндай адам араласқанды жақсы көреді, адамдардан оқшауланбайды, эмоцияны әдепті әрі орынды білдіре алады, көзқарасы, басымдықтары мен әдеттерінде тұрақты. Ол сирек шаршайды, өйткені энергияны сауатты бөліп, шаршап-шалдықпайды.\nОл бастағанды соңына дейін жеткізе алады — бұған күшті ақылмен бөлу және әлеуетті тиімді пайдалану көмектеседі.\nӘлсіз жағында істе және қорытындыда асығыстық, басқаларға төзбеушілік, агрессия мен қысым болуы мүмкін. Адам түнерген, мінезі ауыр болуы мүмкін, және бұл ауырлық тіпті дене деңгейінде — тығыршық, толық денеде, ауыр аяқта, толуға бейімділікте көрінеді.\n### Ұсыныстар\nДене күшін дамытып, жүзеге асыру маңызды: белсенді өмір салтын ұстану, жиі қозғалу, саяхаттау, спортпен айналысу. Негізгі жұмыс көп қозғалуға мүмкіндік берсе, тамаша. Бұл әлсіз жағында жиналып қалуы мүмкін дене күші мен энергияға жол береді. Оны дұрыс қолдану керек, әйтпесе агрессиялы күйлер, «жұдырығы қышу», айналадағыларды арандатып, дауға түсуге деген ниет болуы мүмкін.\nТым асығу әдеті болса, «жерге түсіп», өзін тоқтату маңызды: айналадағылардың ырғағымен өмір сүріп, әрекетін ойластырып, эмоцияға, серпінге және ойланбаған қадамға берілмей, тек салмақты шешім қабылдау.\nЖұмысыңыздан жақсы әрі жағымды нәрсені тауып, жаңаны байқап көріп, жақсы ортада араласу.\nБәрінде — денеде де, өмірге көзқараста да жеңілдікке ұмтылу. Бірақ тепе-теңдікті сақтау: өзіңізді шамадан тыс жүктемей, байыпты болып, демалыс пен жағымды сәттерге орын қалдыру. Бұл жақсы көңіл-күйде болып, оны айналадағылармен бөлісуге көмектеседі.", "Сангвиник": "Бұл — ұсақ-түйекке де қуана білетін нағыз оптимист. Көп нәрсе мен құбылысқа қызығатын белсенді адам. Әдетте оның араласу ортасы кең, хоббиі мен әуестігі көп. Эмоциясын жарқын әрі табиғи білдіреді, көңіл-күйі тез өзгеруі мүмкін.\nМұндай адам сәтсіздік пен қиындықтан кейін тез өзіне келеді және жағымсыз нәрсеге байланып қалмайды. Мақсаттылық оған ұсақ қателер үшін тоқтауға мүмкіндік бермейді, ал бейімделудің жоғары қабілеті кез келген жағдайда абдырамай, қалағанына жетуге көмектеседі.\nБұл — мәселеге жеңіл қарайтын және өзгерістен қорықпайтын энтузиаст.\nКөбіне ол энергиялы және денесі жақсы дамыған. Ол өте нәтижелі және өз бетінше де, командада да жұмыс істей алады. Онымен араласу жеңіл: барлық ой мен эмоцияны тура білдіреді, бәрі бетінде жазулы тұрады, мимикасы әдетте жанды.\nОны шешімділік пен бастамашылдық ерекшелейді — оны көруге және естуге болады, ол ортаны басқарып, оған әсер ете алады. Ол өте жұмысқа қабілетті, тез үйренеді және бәрін іс жүзінде қолданғанды жақсы көреді.\nОған қанық өмір — көп оқиға, өзгеріс, жалықтыратын және күнделікті бір сарынды істердің болмауы маңызды.\nСондықтан ол көп қозғалып, саяхаттап, ішкі энергиясын шамасыз жұмсайды. Бірнеше іске бірден кірісіп, бірақ оларды соңына дейін жеткізбей, шаршап-шалдығудан тастап кетуі мүмкін.\nОның жүйке жүйесі мықты, ол жеткілікті салмақты, бірақ айналадағы өзгеріске тез жауап беруге әрдайым дайын.\nИкемділік пен тұрақтылықтың үйлесімі оған жаңа жағдайға оңай бейімделуге, бәрін тез қағып алуға және стресссіз жоспарды жол-жөнекей өзгертуге немесе жаңа ұжымға қосылуға мүмкіндік береді.\nМұндай адамдар көп араласқанды және назардың ортасында болғанды жақсы көреді, әртүрлі іс-шараларға, жобалар мен оқиғаларға белсенді қатысады. Олар жанашырлықпен, басқалардың кемшілігін қабылдай білумен және көмектесуге деген ниетпен тартады. Жақындармен және серіктеспен қарым-қатынаста оларға жарқын сезім мен эмоция, ортаның өзгеруі және әртүрлі әсер өте маңызды.\nОлар көшбасшы, ынталандырушы немесе ұйымдастырушы рөлін ала алады. Сонымен бірге оларға әрдайым күшті эмоция, жауап, оң кері байланыс және ісіне деген қызығушылық алу маңызды — сонда олар керемет нәтижеге жетеді.\nӘлсіз жағында адам жинақсыз, іштей тәртіпсіз және бір нәрсеге ұзақ шоғырлана алмайтын болуы мүмкін. Нәтижесінде жұмыс пен басқа істер зардап шегіп, мақсатқа жетпейді. Қарым-қатынаста серіктес жалықтыруы мүмкін, күнделікті бір сарын сезімі пайда болады.\nАсығыстық пен үстірттік адамдарға қатынаста да көрінуі мүмкін — сонда ол абайсыз әрекет етіп, ойланбаған шешім қабылдайды.\nАдам эмоциясының жарқындығына тәуелді: жаңа әсер мен өмірдің жаңа бояуынсыз ол апатияға, мазасыздық пен наразылыққа түсуі мүмкін.\n### Ұсыныстар\nБастағанды соңына дейін жеткізіп, тек процестен ғана ләззат алмай, ілгерілеуді және сезілетін түпкі нәтижені көру маңызды. Сондықтан бір-екі мақсатқа шоғырланып, оларға жеткен соң ғана жаңаны бастаған дұрыс. Мақсат қою дағдысын меңгеру.\nҚызығушылықтың шашыраңқылығы мен үстірттікте құнды нәрсені жіберіп алу оңай болғандықтан, өзіңізді және адамдарды тыңдауды, оқиғалар мен реакциялардың себебі мен салдарын түсінуді үйрену маңызды.\nТолық күшпен нәтижелі әрі энергиялы жұмыс істеу үшін шабыттандыратын нәрсемен айналысып, кәдімгіден жарқын әрі маңыздыны көріп, бөлшек пен жаңа ұсақ-түйекті байқау керек.\nӨмірді әртүрлі белсенділікпен түрлендірген жөн: достармен уақыт өткізу, ең болмаса жақынға саяхаттау, табиғатқа шығу және хоббиге уақыт табу. Өйткені күнделікті бір сарында, тоқырауда және бір сарынды жұмыста мұндай адам апатияға түсіп, тіпті ауыр сырқаттануы мүмкін — көңілсіздік пен психосоматикалық бұзылыстарға дейін.\nӨзіңізге байыптырақ әрі сыни қарау керек: тым көп нәрсені мойныңызға алмай, күшіңізді асыра бағаламай, орындалмайтынды уәде етпеу.\nҚателігіңіз бен дұрыс еместігіңізді мойындауды үйрену. Ол үшін анда-санда қызу белсенділікті тоқтатып, істегенді талдап, кері байланыс сұрап, пікіріне құлақ асқыңыз келетін адамдардың реакциясын байқау.", "Сангвиник-Холерик": "Мұндай адам энергия мен күштің, ішкі ынта мен дене әлеуетінің тепе-теңдігінің арқасында өте нәтижелі.\nОның дене күшінің қоры үлкен, белсенді, өзін көрсетіп, әсерлі ұсына алады, ашық әрі оптимист. Ол қиындыққа сабырмен қарайды — олардың алдында бас имей, оларды кезекті керекті міндет ретінде шешеді. Әдетте мұндай адамдардың денесі жақсы құрылған және дамыған, жалқаулануға және ұзақ әрекетсіз жүруге бейім емес. Олар күткенді және бір сарынды істі ұнатпайды, сондықтан тез тұтанып, қызығушылықты жоғалтса, тез суынады.\nОлар жауапкершілік алып, бастама көрсетіп, белсенді әрекет ете алады. Олар жанашыр, көмектескенді жақсы көреді, позитивте болғанда энергия беріп, жан жылуын сыйлайды. Оларды өмірге жеңіл қарау, ашықтық пен оптимизм ерекшелейді, осының арқасында айналасына пікірлестерді жинап, адамдарға әсер етеді.\nЕң екіұшты жағдайдағы тапқырлық, белсенді ұстаным мен көшбасшылық оларға ерекшеленуге көмектеседі. Жеңіл қозғалу мен қызығушылықтың кең ауқымы кез келген дерлік қызмет саласын таңдауға мүмкіндік береді. Мұндай адам нағыз құмарлығы мен терең шынайы қызығушылығы бар нәрседе ең үлкен нәтижеге жетеді. Шабыт пен жасау мүмкіндігі де маңызды — сонда ол іске соншалықты беріліп, демалыс қажеттілігін сезбеуі мүмкін.\nБірақ оған шамадан тыс жүктемеден, әсіресе эмоциялық жүктемеден, шектен тыс жанашырлықтан және өзгенің сезімі мен мәселесіне араласу әдетінен аулақ болу керек.\nӘлсіз жағында адам тым өткір, өкпешіл, күдікшіл және сақ, дауға бейім болуы мүмкін. Ол басқаларды сынап, сонымен бірге өзіне сенбеуі, көп қызығушылыққа шашырап, тіпті жаңаға да тез суынып, бастағанын жарты жолда тастауы мүмкін.\nКөңіл-күйдің ауытқуы болуы мүмкін: позитив сыртқы жағдайлардың әсерімен ашуға, үмітсіздікке, абдырауға немесе көңіл қалуға тез ауысады. Жоғары жылдамдықта өмір сүру, үстірт баға беру және алғашқы әсерге сену әдеті жеке араласуда да, жұмыста да қиындық туғызады.\nОл тәуекелге барып, ойланбаған шешім қабылдап, кейін өкінуі мүмкін. Шектен тыс күдікшілдік те үрей мен көңілсіздікке дейін жеткізуі мүмкін.\n### Ұсыныстар\nӨзіне сүйенуді, құмарлық пен эмоцияның жетегінде кетпеуді, арандату мен айла-шарғыға көнбеуді, тәуелділіктен — тамақтан, эмоциядан, адамдардан, зиянды әдеттерден және т.б. арылуды үйрену маңызды.\nӘлеует пен энергияны басымдықтарды дұрыс қойып, ақылмен пайдалану керек. Бұл кез келген қиын кезеңнен өтіп, күтпеген жағдайда өзін ұстауға көмектеседі.\nКөп бағытқа шашыраудың қажеті жоқ. Жалықпау үшін жаңа жерлерге шығып, шабытты әртүрлі көздерден — кітаптардан, саяхаттан, көрмелерден, фильмдерден, жаңа тағамдардан және жаңа адамдармен араласудан іздеген пайдалы.\nБайқағыштық пен ішкі тепе-теңдікке сүйене отырып, адамдарды жақсырақ түсінуді үйрену.\nӨзіңізге және айналадағыларға азырақ талапшыл әрі сыншыл болу.\nСәтсіздік пен қателікті трагедия жасамай, керекті тәжірибе ретінде қабылдап, мойындауды үйрену.", "Чувствительный Холерик": "Мұндай адамды жарқын белсенділік, энергиялылық пен ұшқалақтық ерекшелейді. Ол сыртқы әсерге өте сезімтал.\nЕрекше берілгендік пен әрекетке деген құштарлық оған шын қызықты салаларда көрінеді. Ол шоғырланып, басқаларды ұйымдастырып, шабыттандырып, соңынан ерте алады.\nОл жаңа ақпаратты оңай меңгеріп, оқыта алады, әртүрлі процестер арасында сапасын жоғалтпай ауыса алады және жылдам, бірақ берілген жағдайда тиімді шешім қабылдай алады.\nОның Муладхарасы әлсіз толы болғандықтан, оған бастама көрсету қиын болуы мүмкін, ал сын өзін-өзі бағалауына соғып, шешімділігін төмендетуі мүмкін. Бұл — оның сырттан әсерге, өзгенің сөзі мен әрекетіне өте қабылдағыш болуының және тіпті ұсақ-түйекке бола ренжуі немесе қапалануы мүмкін екенінің салдары.\nСау бәсекелестік мұндай тұлғаға қосымша ынта беріп, іске деген қызығушылықты тұтандырады. Ал сүйікті істе табандылық пен мақсаттылық осы қасиеттермен бірге ең жоғары нәтижеге жетуге көмектеседі. Бірақ жоғары қозғыштықтан жұмыста шаршап-шалдығу мен сарқылу кедергі келтіруі мүмкін.\nМұндай адам оңай беріліп кетеді, көп қозғалады, жылдам ырғақта өмір сүреді және баяу адамдарға шыдамсыздық көрсетуі мүмкін.\nОл идеяға тез тұтанып, оны бірден жүзеге асыруға ұмтылады. Үнемі әрекет етіп, энергияны шығару ниеті төмен төзімділікпен және дене күшінің аз қорымен ұштасады, сондықтан белсенділік пен енжарлық кезеңдері күрт ауысады. Әлеует жинау үшін оған күшті үнемі қалпына келтіру керек.\nӨзін реттеу мен өзін бақылауда қиындықтар болуы мүмкін: оған күшті біркелкі бөлу қиын. Ол бірден көп беріп, белсенді әрекет етеді, сосын шыдамай, бас тартады. Бұл — өзіндік спринтер: жұмыс пен істе ол қысқа қашықтыққа «жүгіруші». Оған төзімділік, қызығушылықтың тұрақтылығы мен орнықты бейімділік жетпейді.\nПозитивте ол тау қопаруға дайын, ал көңіл-күйі нашар болса, тіпті қарапайым нәрсені де жеңе алмайды — «қолы салбырап қалады». Күш қоры мен жұмысқа қабілет психологиялық күйге қатты байланысты, сондықтан жағымсыз күйде ұзақ қалуға болмайды — әйтпесе психосоматика, күдікшілдік пен мазасыздық тәуекелі жоғары.\nМұндай адамға адамдардың немесе жағдайлардың қысымында болу қиын, өйткені ол үшін еркіндік пен тәуелсіздік маңызды.\nӘлсіз жағында жинақсыздық, жүйкелік пен әбігершілдік қателер мен асығыс шешімдерге әкеледі. Бірдеңе жоспар бойынша жүрмегендегі ашуланшақтық пен тітіркенгіштік айналадағылармен қарым-қатынасты бұзады.\nЖаңаны тез есте сақтап, ол тез ұмытады да, маңыздыны құлақтың сыртынан жіберуі мүмкін.\nСәтсіздік кезінде немесе сынға ұшырағанда ол көбіне жинала алмай, дәрменсіздік пен абдырау сезінеді, апатия мен көңілсіздікке түсуі мүмкін. Осыдан айналадағылардың пікіріне тәуелділік және үнемі оң кері байланыс күту пайда болады.\nЕкінші жағынан, қозғыштық оны өкпешіл, ұшқалақ әрі қырсық етеді — оған тоқтап, тынышталу қиын.\nҚатты қабылдағыштық пен сезімталдықтан ол адамдардан және қоғамнан алыстауы мүмкін, бірақ жалғыздықты ауыр көтереді — араласу мен байланыс ол үшін маңызды. Араласуда қосымша қиындықты ішкі теңгерімсіздік пен серпінмен әрекет ету әдеті туғызады.\n### Ұсыныстар\nӨзін бақылау және өзіне үзіліс бере білу, «буды шығару», эмоцияны, әсіресе қорқатын немесе жол берілмейді деп санайтын эмоцияны көрсету маңызды. Бұл бірқалыпты эмоциялық фон мен жалпы жақсы көңіл-күйді сақтауға көмектеседі.\nАнда-санда қарқынды бәсеңдетіп, тоқтап, өз әрекеттері, жағдайлар, нәтижелер және айналадағыларға әсері туралы ойлану керек.\nОй және дене белсенділігін кезектестіріп, өзіне сапалы демалуға мүмкіндік беру.\nБелсенділіктің қысқа кезеңдерімен жұмыс істеп, бір іске барынша шоғырланып, осы «серпілістердің» арасында үзіліс жасау. Бұл қатысу мен қызығушылықсыз үнемі бір сарынды жұмыстан әлдеқайда тиімді.\nАптаға, айға және күнге жоспар — міндетті түрде демалыс уақыты бар сағаттық кесте құрып көру. Бірдеңе болмаса, уайымдап, үрейленбей, жоспар мен кестені қажетінше түзету.\nЖағымсыз күйде қалып қоймай, өкпе жинамай, үндемей қалмай, ұнамайтын немесе мазалайтын нәрсені айту. Анда-санда жиналған эмоциялардан — спорт, шығармашылық, табиғат, энергетикалық практикалар, йога, медитация және т.б. арқылы жұмсақ арылу. Осылай қалпына келіп, өзіңізді үйлесімге келтіруге болады.\nЖақсы көңіл-күйді сақтау маңызды — эмоциялық күйге өмірде көп нәрсе, мансаптағы табыстан денсаулыққа дейін байланысты. Ортаны мұқият таңдау: улы адамдардан аулақ болып, табысты, бейбітшіл және позитивті адамдармен көбірек араласу.\nДене шамадан тыс жүктелуіне және жүйкенің сарқылуына жол бермеу.\nЭмоцияны білдіруде шамаға, алтын ортаға ұмтылу: ұстамды болған жақсы сәттерді байқау және сонымен бірге орынды болғанда эмоцияны жарқын білдіруге рұқсат беру.\nСөзді қадағалау. Мұндай адамдарда алдымен айтып, сосын ойлау әдеті болады — көбіне олар жанында жаман ниет болмаса да, сәтсіз сөйлеп қояды.", "Меланхолик": "Мұндай адам басқалардан баяу қарқынмен өмір сүреді, өзіне үңілуге бейім және ұсақ-түйекке бола қатты уайымдайды. Ол әсершіл әрі эмоционал, моральдық жағынан тез шаршайды. Оның үлкен дене күші мен белсенді энергиясы жоқ, сондықтан көбіне энергия үнемдеу режимінде болады. Қимылы мен мимикасы қысылған әрі баяу болуы мүмкін.\nӨзгерістер мен күрт ауысулар оны үрейге және көңілсіздікке түсіруі мүмкін. Ол жаңа жағдайға нашар бейімделеді, өзгерісті ауыр көтереді және жаңа ұжымға қосылу немесе бейтаныс адамдармен араласу қажеттілігіне сақтықпен қарайды.\nМұндай адамдар әдемінің бәрін жақсы көреді, олардың талғамы мен шама сезімі тамаша. Сырттай олар сезім мен эмоцияны көрсетпеуі мүмкін, оларды іштей терең өткергенді қалайды. Көбіне бұл жарқын әрі қуанышты нәрседен гөрі ауыр ойлар мен түнерген ойлар.\nОлар бөлшек пен ұсақ-түйекке көп көңіл бөледі, сондықтан бір нәрсеге ұзақ шоғырланып, бір сарынды міндеттерді орындау керек тұрақты жұмыста алмастырылмайды.\nСырттай сабырлы, бірақ іштей мұндай адамдар өте тұрақсыз және тұтас эмоция дауылын бастан өткеруі мүмкін. Олар көбіне өзіне сенімсіз, өткенмен өмір сүруге немесе керісінше арманға кетуге бейім. Оларда қорқыныш пен ішкі шектеу көп, сондықтан әлеуметтік белсенділік пен өзін білдіру зардап шегеді. Бірдеңе істемес бұрын олар салдары мен ықтимал қиындықтар туралы жүз рет ойланады. Мұндай адам сыртқы тітіркендіргіштерге өте сезімтал әрі шешімсіз.\nСонымен бірге мұндай күйде оған іштей жайлы. Оны сергітуге, өмірге позитивті көзқарасты жасанды түрде таңуға, ынталандырып, сілкуге тырысса, ол мұны ұнатпай қабылдайды.\nОл үшін бастысы — тұрақтылық. Ол форс-мажор мен стресссіз, өзін сенімді сезініп, өз ісімен айналыса алатын тыныш ортада жақсы ашылып, нәтижелі жұмыс істейді. Есесіне мұндай адамдар өте тұрақты, қағидалары мен қызығушылықтары орнықты. Олар адамдар мен уақытты шашпайды және ұсақ-түйекке айырбастамайды. Бірдеңе істесе, мұқият әрі негізді, жауапты әрі ұқыпты істейді.\nОлар айналадағылардың көңіл-күйінің өзгеруін сезімтал байқап, адамдардың эмоциялық күйін оқиды.\nМұндай адамды жанашырлықпен «ұстап алу» өте оңай: ол өзгенің ауыртпалығын өткір сезіп, көмектесуге ұмтылады және өзгенің ісіне шектен тыс араласып, көбіне айлакерлердің торына түседі.\nӘлсіз жағында мұндай адамдар тым ұялшақ, бұл оларға өзін көрсетуге мүмкіндік бермейді. Олар жақсы маман болса да, жылдар бойы байқалмай қалуы мүмкін. Оларды атап, ерекшелемейді, нәтижесінде өзін-өзі бағалаудың төмендігі мен өкпе қалыптасады.\nАдам күдікшіл, кекшіл болып, ашуын іште сақтауы мүмкін. Сәтсіздіктен кейін ол өзіне сенімі мен іскерлік көңіл-күйін ұзаққа жоғалтады. Ол сынды нашар көтереді және өзгенің өзі туралы сөзін ауыр қабылдайды, бірақ сонымен бірге өзі басқаларға айтарлықтай талапшыл. Осы қиындықтардың бәрінен оның араласуы шектеулі, шын жақын адамдары аз.\nМазасыздықтың жоғарылығынан мұндай адам тіпті сүйікті ісінде де сәтсіздікке ұшырауы мүмкін. Ол жақсы нәтижеге соншалықты сенбейді, объективті себепсіз — тек әдетте ешнәрсеге негізделмеген ішкі шектейтін сенімдерден жұмысты тастап кетуі мүмкін. Мұндай адамдар жағымсыз эмоцияны білдіріп, аяп, көмектесуі үшін жанашырлық тудырғанды ұнатады. Назар үшін олар өз жағдайы мен күйін шын мәніндегіден әлдеқайда нашар көрсетуі мүмкін.\nШешімсіздік пен өз күшіне сенбеуге қарамастан, оның өзін-өзі бағалауы асыра жоғары болып, өмір оған әділетсіз деп санауы мүмкін.\n### Ұсыныстар\nЭмоциялық орнықтылық пен дене күйін қадағалау өте маңызды, өйткені өмірлік күш қоры аз. Демалыс пен қалпына келу керек.\nОсында және қазір өмір сүруді үйреніп, адамдардан және болашақтан тым көп күтпей, өткенді мінсіз етіп көрмеу.\nТіпті ұсақ-түйек үшін де өмірге алғыс айтуды үйреніп, көп жағдайға жайырақ қарау. Өмірге позитивті көзқарасқа тұлғаның барлық жағымен өзін толық қабылдау көмектеседі.\nАшығырақ болып, ұзақ өзіне тұйықталмау, бірақ сонымен бірге қалпына келу үшін оңаша болуға рұқсат беріп, йогамен және рухани практикалармен айналысып, денеге шамалы жүктеме беріп, оны дамытып, нығайту.\nӘрдайым фактілерге сүйеніп, адамдарды, құбылыстар мен оқиғаларды объективті бағалап, пікірдің тәуелсіздігін дамыту.\nӨзін үйлесімді сезінуге өзіне сенімділік пен жан тепе-теңдігін сақтай білуді дамыту көмектеседі.\nМұндай адамға бәрінде шектен шығудан, экстремалды спорттан және тәуекелді жағдайлардан аулақ болған жақсы. Жан күшін қалпына келтіруге жақындардың жылы ортасында өткізген бос уақыт, табиғаттағы күн, мейірімді фильмдер көмектеседі. Тепе-теңдікте болып, бұл күйді мүмкіндігінше ұзақ сақтау маңызды.", "Флегматик": "Бұл тұлғаның күшті жақтары — сабыр, орнықтылық, тұрақтылық және кез келген дерлік жағдайда тепе-теңдікті сақтай білу. Мұндай адамдар өзін де, жағдайды да байыппен бағалайды, табанды әрекет етеді, шыдамды әрі ұстамды болады. Бұл салмақты шешім қабылдап, ойланып әрекет етіп, қолайлы сәтті күте білу керек болғанда — орасан зор артықшылық.\nКүрт өзгерістер мен жаңа жағдайлар абдырау мен мазасыздық тудыруы мүмкін, бірақ қиын жағдайда мұндай адам артық эмоциясыз іске қосылып, жағдайды тұтас көре алады. Күшті сауатты бөліп, оны дәл керек жерге салып, ол әдетте нәтижеге жетіп, қиындықты жеңеді.\nМұндай адамда сезім күрт қалыптаспайды және көрінбейді, эмоция мен реакциялар басқалардан баяу әрі ойланған. Бірақ бұл асықпауда — сенімділік пен сабыр. Ол ұшқалақ әрі екпінмен әрекет етуге бейім емес.\nОның байланысы мен бейімділігі тереңдігімен ерекшеленеді. Сырттан ол эмоцияға сараң және бейжай — байыпты, ұстамды әрі парасатты болып көрінеді. Сыртқы белгілері бойынша оның жан күйі мен көңіл-күйін түсіну көбіне қиын, өйткені ол бәріне баяу жауап беріп, көп нәрсені іште сақтайды. Бұл эмоциясы бетінде және жанды мимикасында жарқын көрінетін адам емес.\nМұндай адамдар әдетте ниеті түзу және жақсы дос бола алады. Бірақ олар бір ұстанымға ие болса, ол өзгермей, берік қағидаларға сүйенеді. Бұлар — мұқият әрі шын қызығушылық танытатын тамаша әңгімелесушілер. Жақсы дене күші оларға жоғары жұмысқа қабілетті ұзақ сақтауға мүмкіндік береді, ал өзін бақылау, табандылық, сабырлы сенімділік, тұрақтылық пен бірқалыптылыққа деген сүйіспеншілік оларды әртүрлі салада табысты кәсіпқой етеді.\nМұндай адамға эмоция жетпеуі мүмкін, және ол ашығырақ адамдардың энергиясынан қуат алуға бейім. Сондықтан ол анда-санда шулы ортада болып, белсенді қатысушыдан гөрі бақылаушы болып қалуы мүмкін. Сонымен бірге күшті эмоциялық шиеленіс оған зиян және тепе-теңдіктен шығаруы мүмкін.\nЭнергия мен дене күшінің жақсы табиғи қорына қарамастан, қарқынды жұмыс пен үлкен берілгендіктен кейін оған қалпына келуге уақыт керек. Сондықтан күн тәртібін сақтап, түнгі белсенділіктен аулақ болған жөн.\nӘлсіз жағында адам өзгерістен соншалықты қорқып, эмоциялық тербелістен соншалықты оқшауланады, салқын, тұйық, өткір болып, айналадағылардан алыстайды. Шеткі жағдайда ол сыртқы әлемге, адамдарға, жұмысқа және тіпті өзіне қызығушылығын толық жоғалтуы мүмкін.\nЖағдайды ұзақ ойлау көбіне уақытында емес әрекет пен шешімге әкеледі. Бейімделу қабілетінің төмендігі дамуға кедергі келтіріп, мамандықта және жеке өмірде тоқырауға әкеледі.\nЖоспардың бұзылуы мен форс-мажор мазасыздық пен сенімсіздік тудырып, ішкі күйді шайқалтады.\nЖиналған шаршау мен бұзылған ұйқы кезінде агрессияның тұтануы мен дауға бейімділік болуы мүмкін.\n### Ұсыныстар\nӨз сезімі мен эмоциясын білдіруді үйреніп, өзінің әртүрлі көріністерінен қорықпау. Бұл адамдармен байланыс орнатып, өзін жақсырақ түсінуге көмектеседі. Ашығырақ болып, позитивті ойлап, өзіне және мүмкіндіктеріне сенген пайдалы.\nШын қуаттандыратын және эмоциялық жауап тудыратын кәсіп, жанға жақын іс табу маңызды.\nАнда-санда тіпті ұсақ-түйекпен өзін қуантып, ләззат пен жақсы эмоция әкелетін нәрсені істеу.\nАрманнан немесе мақсаттан шабыт тауып, оған қарай жүру, жолдағы жетістіктер үшін өзін көтермелеп, қабілеттерін барынша ашу.\nПікірлестер командасымен қоршалып, адамдармен белсенді жұмыс істеп, өзара әрекет етіп, тұрақты жағдайды сақтау, бірақ анда-санда энергиясымен, тәжірибесімен және идеяларымен бөлісу.", "Холодный": "Іштей мұндай адам әртүрлі эмоцияны бастан өткеруі мүмкін, бірақ оларды сыртқа шығармайды. Сондықтан айналадағылар оны тым салқын, тіпті өзімшіл деп санауы мүмкін. Оның көңіл-күйі мен ой жүрісін түсіну, одан реакция алу және әрекетін алдын ала болжау қиын. Бірақ өзіне істеген ісіне эмоциялық жауап алу өте маңызды.\nОнда эмоцияны білдіруде және адамдарға сенуде белгілі бір қиындықтар бар. Эмпатия мен қабылдағыштықтың төмендігінен немесе бұзылуынан араласуда мәселелер болуы мүмкін. Есесіне стрессті жағдайда салқынқандылық, төзім, мәселеге объективті көзқарас пен сабыр оған бәрін сәтті шешуге көмектеседі. Дәл осындай сәттерде ол көшбасшылық қасиеттерін көрсетіп, айналадағылардың құрметі мен мойындауын жаулап, соңынан ерте алады.\nАдам кез келген эмоцияны — қуанышты да, ашуды да ашық көрсетуден аулақ болады. Сондықтан дау-жанжалдан қашуға тырысады, күшті эмоциялық берілгендікті талап ететін оқиғаларға қатыспайды, көпшілік іс-шараларды ұнатпайды немесе нашар көтереді — олар оны энергетикалық тұрғыдан қатты сарқиды. Оған біраз уақыт өз ойы мен сезіміне шоғырланып, жалғыз болған жақсы. Әлсіз жағында ішкі ұстамдылық эмоциялық сараңдық пен қатыгездікке ауысады. Бірақ шын мәнінде бұл типтегі адамдарға еркелету, назар мен жүрек жылуы басқалардан кем керек емес. Бірақ олар эмоциялық қолдау сұрауға үйренбеген және мәселесін өзі жеңгенді қалайды. Оларға ұзақ эмоциялық жүктеме немесе қысымға төзу қиын — бұл эмоциялық жарылыс пен долылықпен аяқталуы мүмкін.\nМұндай адамды аяушылыққа салу немесе айла-шарғы жасау қиын. Ол тек өзі үшін беделді немесе қандай да бір ортада мойындалған адамдардың пікірін ескереді. Солардың үлгісіне сүйеніп, өзі үшін өзіндік ынталандырушыға айналатын табыстырақ әрі танымал адамнан үйренуі мүмкін.\nӘдетте мұндай адамдар бір рет сүйеді: барлық ішкі күшін бір адамға береді, өйткені оларға ауысу қиын. Оларға әсердің ауысуы мен сезімнің жаңаруы керек емес, сондықтан мұндай дос немесе өмірлік серік тұрақты әрі адал болып шығады. Жаңа адамдармен араласудағы қиындықтар да осыдан. Мұндай адам көбіне тіпті бұзушы және ауыр қарым-қатынастан да шыға алмайды, өйткені онда бәрі таныс әрі үйреншікті, байланыс бар.\nӘлсіз жағында адам өзгенің эмоциясымен қоректенуге қабілетті, бірақ өз эмоциясын бермей, іште ұзақ жинайды. Сондықтан энергия теңгерімсіздігі мен ішкі шиеленіс пайда болып, денсаулық мәселелеріне әкеледі.\n### Ұсыныстар\nЭмоцияны білдіруді үйреніп, жеңілдік пен табиғилықтан қорықпай, жанның ішкі қозғалысын білдіру оңайырақ болуы үшін ым мен мимиканы белсендірек пайдалану.\nШығармашылықпен айналысып, адамдармен араласумен және өзара әрекетпен байланысты хобби болып, өз қолымен бірдеңе жасап, тамақ әзірлеп, жасаған пайдалы.\nЖақындардың қолдауын сезіну маңызды, сондықтан эмоцияны жасырмауға болатын және толық сенуге болатын ниеті түзу әрі түсінетін адамдар шеңбері керек.\nҚайырымдылық, басқаларға көмек пен волонтёрлық жанашырлықты, рақымды және басқалардың сезімін түсіне білуді дамытуға көмектеседі.", "Самоотверженный интегративный": "Мұндай адамға айналаны өзгерткеннен немесе оған әсер еткеннен гөрі өзі бейімделген оңайырақ. Идея көңіліне жақса және маңызды көрінсе, оған оңай тұтанады — сонда жұмысқа басымен кіріп, толық берілгендікпен әрекет етуге дайын. Марапат ол үшін екінші орында, бастысы — процесс.\nБұл — командада жұмыс істеуге мінсіз тип. Кез келген ұжымның бөлігі болып, қоғамға үйлесімді кіре білу мұндай адамдарды ірі компаниялардың құнды қызметкерлері етеді. Мұндай адам айналадағыны өзгертпейді — керісінше, бейімделіп, өзін өзгертуге тырысады. Ол ағысқа қарсы жүруге және қабылданған ережелер мен ұстанымдарды өзгертуге бейім емес.\nОл мейірімді әрі сенгіш, өкпені іште сақтай алмайды, өйткені оны пайдаланып немесе ренжітіп жатқанын әрдайым түсіне бермейді. Ол айла-шарғыға үйренгендердің оңай олжасы болуы мүмкін, күштірек тұлғаның ықпалына және сыртқы қысымға қатты беріледі. Көбіне ол адамдардан жаманды көрмей, олардың әрекетін өзімен өлшейді.\nОл өз қажеттілігі туралы айта алмайды және өз мүддесін бірінші орынға қоя алмайды. Сондықтан мұндай адамның мақсаты басқаларға қызмет ету — ең болмаса отбасы мен балалар үшін өзін құрбан ету болуы мүмкін.\nҚамқорлық пен жол беруге дайындық оған жақсы дос және отбасы мен рудың қамқор мүшесі болуға көмектеседі. Ол жақындардың мүддесін, жайлылығы мен қауіпсіздігін қорғайды. Сонымен бірге ол мінез күшін көрсетіп, іскер әрі өткір болып, өз идеялары мен қағидаларын өмірде жылжытып, тәлімгер және шабыттандырушы бола алады.\n### Әлсіз жағы\nӨзін-өзі бағалау мен өзін білдіруде қиындықтар, айналадағылардың пікіріне тәуелділік болуы мүмкін. Өзіне деген махаббат тек мақтау мен мақұлдаумен нығаяды. Сондықтан ол өз мүддесі мәнін жоғалтатындай дәрежеде өзін құрбан етуге қабілетті.\nМұндай құрбандыққа бейімділік пен серіктеске бәрінде жағуға ұмтылыс айналадағылар үшін де торға айналады: олар өздерін міндетті сезініп, бұл құрбандықтың жүгін көтере алмайды, өйткені әркім бірдей жауап бере алмайды. Тең жауап алмай, адам тез сарқылып, өзін керексіз немесе пайдаланылған сезіне бастайды, жауабына алғыс, махаббат пен адалдық күтіп, талапшыл әрі ашуланшақ болады.\nКейде мұндай адамдар басқа пікірді естімей және ескермей, жабысқақ идеяны қорғап, өте фанатик әрі қасарысқан болады.\n### Ұсыныстар\nӨзі туралы көбірек ойлап, өзіне қамқорлық жасап, сау өзімшілдікті үйрену.\nӨз тілектері мен қажеттіліктерін түсініп, ол туралы ашық айтудан қорықпау. Осылай сіз өзгенің шекарасын бұзбайсыз, тек өзіңіздікін белгілейсіз.\nКез келген айла-шарғыдан аулақ болу: өзгенікіне көнбеу және өзіңіз құрбандықтарыңыз үшін парыз, жауапкершілік пен алғыс сезімін тудырып, адамдарды басқаруға тырыспау.\nБәрін өзі істеп, бәрін бақылауға ұмтылыстан бас тарту. Ақылмен тапсыра білу және басымдықтарды қою жақындарға шектен тыс қамқорлықтан маңыздырақ.\nӨз басымдықтары мен мақсаттары болып, оларға кінә сезімінсіз жүруді үйрену. Өз тілектерін орта мен қоғам таңған және сіздікі ретінде берілетін құндылықтар мен қажеттіліктерден ажыратуды міндетті түрде жаттықтыру. Осылай шын маңызды нәрсеге энергияны сақтауға болады.", "Страстный": "Бұл тип эмоционалдылықпен және жоғары қозғыштықпен ерекшеленеді: ол бәрін жүрекке жақын қабылдап, өткір сезінеді.\nЭмоция оның өмірінде басты рөл атқарады, сондықтан шешімдер көбіне асығыс, көңіл-күй мен серпіннің әсерімен қабылданады. Эмоция тұтануы бірінен соң бірі — тоқтаусыз жұқпалы күлкіден бастап ащы жасқа дейін жүруі мүмкін. Салмақты шешім қиынға соғады, өйткені эмоция өте жарқын көрініп, салқын ақылдан басым түседі. Кейін өзіне келіп, жағдайға байыппен қарағанда, адам таңдауына, сөзіне немесе әрекетіне өкіне бастайды.\nОған бүкіл әлемге көмектесуге дайындық, шынайы жомарттық пен жанашырлық тән. Өз сезімі мен қабылдауы ол үшін әрдайым бірінші орында тұрады, айналадағылар мұны өзімшілдік деп қабылдауы мүмкін.\nМұндай толымдылығы бар адамдарға өзін білдірудің барынша еркіндігі маңызды. Олар шекараны, шеңберді, өзін бақылауды және әсіресе айла-шарғыға талпынысты көтермейді. Бірақ өздері бәрін бақылағысы келеді және эмоция арқылы адамдарға әсер ете алады.\nЭмоциялық байланыс пен сезім арқылы араласу олар үшін өте маңызды. Оларды эмоциялық араласуда өзін жарқын көрсетуге болатын жағдайлар қуаттайды: махаббат, қылымсу, дау, кештер, қоғамдық іс-шаралар және т.б.\nМұндай адам ешқашан жай бақылаушы болып қалмайды — ол әрдайым белсенді қатысушы және оқиғаның ортасында. Тіпті ұсақ-түйекті де ол соншалықты эмоциямен өткеріп, бояп, кез келген адамды шабыттандырып, қызықтыра алады.\nОған шыдамды болып, күту қиын — оған бәрі бірден әрі көп көлемде керек. Бұл көбіне жоқ жерден өкпеге, бірақ тез кешіруге де әкеледі. Бұл — өзіне «тоқта» деп айта алмайтын беріліп кететін болмыс. Бір жағынан, бұл істер мен қызығушылықта жинақсыздық пен үстірттікке әкеледі, екінші жағынан — ынта, идеяға оңай тұтанып, оны басқаларға жұқтыра білу береді.\nБұл — жаңа таныстықтар оңай келетін ашық, жанашыр әрі мейірімді адам. Оған орта, жауап және адамдармен жақындық сезімі маңызды. Көбіне бұл қоғам мен ортаның пікіріне тәуелділікке, мақұлдау қажеттілігіне ұласады.\nБұл типтің бір түрі кездеседі: сырттай адам айтарлықтай сабырлы әрекет етеді, ал оның қызу эмоциясы мен оңай емес мінезін тек өзі ашылатын ең жақын адамдар көреді.\nӘлсіз жағында ол өзгенің шекарасын бұзуға және адамдардың эмоциясы мен тілегін сезбеуге бейім. Ол тек өзін және өз сезімін естиді, айналадағылардың қажеттілігін түсінбей және байқамай. Ол тым эмоционал, болжап болмайтын, ұшқалақ және фанатик болып көрінуі мүмкін. Шешімдер эмоциямен және асығыс қабылданады, ашуланғанда өткір әрі қатты сөйлеуі мүмкін. Өзі көбіне ұстамсыздығы мен көңіл-күйінің күрт ауытқуынан зардап шегеді, бірақ өзін әрдайым жеңе алмайды. Ренжісе, эмоцияны білдіре алмай, тұйықталып, бұл өкпемен өзін «жандыруы» мүмкін.\n### Ұсыныстар\nЭмоцияны бақылауды және басқаруды үйрену, әйтпесе сезім ақылдан басым түсіп, салдары болжап болмайтын болады, ал керекті ымыра болмайды.\nКез келген жағдайда салқынқандылықты сақтап, өзін қолға ала білу маңызды. Қызбаланып шешім қабылдауға болмайды — әрдайым өзіңізге ойлануға, жағдайды байыппен бағалап, талдауға уақыт берген жөн.\nАйла-шарғы жасау және айналадағылардың эмоциясымен қоректену әдетінен бас тартып, өзгенің шекарасын бұзбау.\nЖиналған эмоцияға спорт пен әртүрлі дене белсенділігі арқылы жол беру.\nТек интеллектуалдық пен дене дамуына ғана емес, рухани дамуға да жеткілікті уақыт бөлу.\nӨз эмоционалдылығы мен жүрек энергиясын адамдарға іс жүзінде көмектесуге, қоғамдық белсенділікке, араласу мен байланысқа бағыттау.", "Эгоистичный (лидерский)": "Бұл — күшті ерік пен харизманың, көшбасшы мен басқарушы қасиеттерінің иесі. Табиғатынан ол адамдарды басқару мен әртүрлі процестерді үйлестіру талантымен берілген. Қоғамдағы жоғары орын, материалдық молшылық пен билік ол үшін өте маңызды, сондықтан ол жолында көп нәрсені жеңуге дайын, маңызды шешімдер қабылдайды және жауапкершіліктен қорықпайды. Оның ақылы дамыған, тұрмыстық даналығы, істегі епшілдігі мен кәсіпкерлік қабілеті бар.\nҚуатты ішкі өзек оны айналадағыларға әсер етуге қабілетті тұлға етеді. Өзіне, өз күшіне және дұрыстығына сенімділік, сондай-ақ мақсаттылық оған қалағанына жетуге көмектеседі.\nМұндай адам әлемді өзгертуге қабілетті. Оны не қозғайтыны өте маңызды, өйткені мақсаты үшін ол кедергіні жеңіп, қиындықты жойып, өз мүддесін қорғап, еңбек етуге дайын. Көп нәрсені ол тіпті жалғыз да істей алады.\nАқшамен оның қарым-қатынасы әдетте тамаша: ол жинап, көбейтіп, сауатты басқара алады.\nЖоғары белсенділік пен қозғалысқа деген сүйіспеншілік батылдық пен көшбасшылық қасиеттермен бірге оған қоғамда жоғары орынға ие болып, өзін көрсетуге көмектеседі. Ол жеке бизнес құрып немесе негізгі мәселелерді шешіп, оның дамуына қатты әсер ете отырып, ірі компанияны басқара алады.\nМұндай адамдар айналадағылардан жоғары нәтижелілігімен және ақылға сүйенуімен ерекшеленеді. Бұлар әрдайым ерік-жігері мен ішкі күші мықты іс адамдары.\n### Әлсіз жағы\nАдам өз қасиеттерін жұмыста, мансапта және қоғамда қолданбаса, ол бүкіл энергиясын жақындарын бақылауға және оларға әсер етуге бағыттап, үйдегі озбырға айналуы мүмкін.\nМұндай адамдар қалағанына жетуге және басқаларды өз жағына агрессия мен қысыммен көндіруге бейім. Харизма мен сендіре білу жетпесе, олар озбырлықпен — ашық бопса немесе өз пікірін таңу арқылы әрекет етуі мүмкін.\n### Ұсыныстар\nӨзімшілдіктің шеткі көріністерінен және басқа адамдардың мүддесін аяқасты етуден аулақ болу.\nКүшпен, қысыммен немесе агрессиямен емес, сендірумен және жеке беделмен әрекет ету. Ол үшін адамдарды тыңдап, олардың ниеті мен ішкі қажеттілігін түсінуді үйрену. Шешім қабылдағанда оның айналадағыларға қалай әсер ететінін ескеру.\nӘлемде сіздікінен өзгеше көп ұстаным мен көзқарас бар екенін қабылдау. Барлық адам әртүрлі, мұны дұрыс қабылдауды үйрену маңызды.\nӘлемге ашықтық пен алғыс практикасы жағымсыз күйге азырақ кетуге және айналадағылардың әрекетінен қулық пен жаман ниет іздеуді тоқтатуға көмектеседі.\nҚайырымдылықпен айналысып, адамдарға шын жүректен көмектесіп, тәлімгер, пікір көшбасшысы және шабыттандырушы болған пайдалы.\nӘртүрлі жақсы эмоцияны көрсетуде өзіне белгілі бір еркіндік беру. Ашықтық денедегі кедергілерден, қысылулар мен блоктардан арылуға көмектеседі, ал соның арқасында пайда болған адамдармен жақындық жанашырлық пен бірге күйзелуді дамытады.\nАгрессия мен басқа күшті эмоцияларды қабылдап, оларды жұмсақ білдіруді, мүмкін өзгерте отырып — мысалы, спорт, жарыс, қоғамдық қызмет, пікірсайыс және сау бәсекелестік арқылы — үйрену.", "Сентиментальный": "Мұндай адам әдетте адамдарды «өзімдікі» және «бөтен» деп нақты бөледі. «Өзімдікімен» ол ашық, жанашырлық таныта алады және шын жақын қарым-қатынасты сақтай алады. «Бөтенге» көбіне немқұрайды және сыртқы әдептілік пен сыпайылыққа қарамастан бейжай қалады.\nМұндай тұлғаның жақсы қасиеті — өзін және айналадағыларды құрметтеу, жеке шекараны сақтай білу. Сонымен бірге мұндай адамдар басқалардан әсершіл және ең нәзік эмоциялық белгілерге жауап береді. Олар өте осал әрі өкпешіл, бірақ мұны көрсетпеуі мүмкін.\nОларды оңай толқытуға болады, олар әртүрлі көріністерге жауап береді, жандары нәзік, әлемді терең сезінеді және рухани дамуды жақсы көреді. Көбіне олардың талғамы нәзік, әсемдікті сезінеді, олар — өнердің нағыз бағалаушылары. Фильм, музыка немесе әңгіме оларда қызу эмоциялық реакция — қуаныш, өкініш, мұң тудыруы мүмкін.\nЕң алдымен бұлар — өзіне және өз ішкі күйіне сезімтал, жоғары назар мен махаббат көрінісі керек адамдар. Өзгенің эмоциясы арқылы олар өздеріне керекті сезімдерді алып, өткереді. Олар шын жанашырлық таныта алады, бірақ мұндай контуры бар адамдарды ең алдымен өз эмоциялары қатты алаңдатады және толқытады.\nСонымен бірге олар сыртқы психоэмоциялық жүктемеге төзімді және сырттан әсерге жақсы қарсы тұрады. Мұндай адам эмоцияны ұзақ шыдап, жинап, кейін болмашы себепке бола жарылуы мүмкін, бұл шектен тыс қабылдағыштық, жүйкелік пен қозғыштық ретінде қабылданады.\nОған әділдіктің өте күшті сезімі мен берік адамгершілік өзек тән — бұл өз мүддесі мен жақындарының мүддесін қорғауға және адал, тіпті ерлік істер жасауға күш береді.\nОлар мақтауды жақсы көреді, ол оларды шабыттандырып, рухтандыра алады. Сын мен қысымды көтермейді, өйткені өздерін әрдайым дерлік дұрыс санайды. Ескерту, өткірлік пен дөрекі үн оларды жылатып, қатты жаралауы мүмкін.\nСырттай олар эмоцияны бірден жарқын көрсетпеуі, алыс көрініп, қабылдағыштығын ұзақ көрсетпеуі мүмкін. Сондықтан олардың кенеттен сезім көрсетуі айналадағыларға оғаш әрі ұшқалақ болып көрінуі мүмкін.\n### Әлсіз жағы\nОлар өзін аяуға бейім, бірақ өзіне деген шынайы махаббатты сезінбеуі мүмкін. Сондықтан оны басқалардан талап етіп, ішкі бостықты толтырып, махаббатқа тәуелді болады. Олар назар аудару және өз дегеніне жету үшін адамдарға айла-шарғы жасап, аяушылыққа басып, жылап, құрбанға айналуы мүмкін. Эмоциялық қажеттілігін көбіне айналадағылардың есебінен, олардың назарын иемдену арқылы қанағаттандырады.\n### Ұсыныстар\nАдамдарға көбірек сеніп, біртіндеп ашылуды, эмоция мен сезімді көрсетуден қорқудан арылуды үйрену.\nЖайлылық аймағын біртіндеп кеңейтіп, тар араласу шеңберінен шығу.\nКүйзелісті жанның тереңінде жасырмау, әсіресе жағымсыз эмоцияны жинамау. Салқын болуға, өзін шектен тыс ұстауға және шынайы тұлғаны немқұрайдылық бетпердесінің астына жасыруға ұмтылу тек зиян келтіріп, психосоматикалық көріністер тудыруы мүмкін.\nАйла-шарғы мен өзін аяудан бас тартып, құрбан рөлінен шығу. Ең алдымен өзін жақсы көруді, күш көзі мен тіректі өзінен табуды үйреніп, қиындықты жеңу үшін ішкі ресурстарды пайдалану.\nЕштеңе күтпей, пайдакүнемсіз көмектесе білуді жаттықтыру. Қайырымдылық, волонтёрлық пен басқаларға көмек, оны энергияның молдығынан істесе, өте көмектеседі.\nТолтыратын, сенімділік пен өзіне-өзі жеткіліктілік сезімін беретін істердің тізімін жасап, күйзеліске байланып қалғың келгенде немесе іште тірек жоқ сияқты көрінгенде соған жүгіну.\nӨзін жақсы көру — еркелету, өзіне қамқорлық жасау және басымдықтарды дұрыс қою.\nОртаны іріктеу: қасыңызда кез келген эмоция көрінісін қолдап, түсінетін адамдар болғаны маңызды.", "Эмпатический": "Бұл — қабылдағыштығы жоғары және табиғи эмпатиясы күшті адам. Ол әлемде болып жатқанның бәріне шынымен жауап беріп, оны өзінен өткізеді. Ол адаммен араласпай-ақ, оның көңіл-күйі мен күйін оңай түсінеді.\nКез келген жаңалық, сұмдық оқиғалар мен өзгенің қайғысы оны эмоциялық тепе-теңдіктен шығаруы мүмкін — ол өзгенің қасіретін өзінікіндей шын уайымдайды.\nТабиғатынан жанашыр әрі мейірімді ол әркімге көмектесуге тырысып, рақым энергиясының өзіндік доноры болады. Ол адамның өзімшілдігін, кекшілдігін, қатыгездігі мен немқұрайдылығын түсінбейді және оларды кемшілік санайды.\nАшықтық пен жанашырлықтан айла-шарғы мен интриганың құрбаны болу тәуекелі бар: оның жанашыр бола алатынын пайдаланып, одан көп нәрсе алуға болады.\nОл ортаның — позитивті болсын, апатиялы болсын — энергиясына тәуелді болуға бейім, өйткені ол сырттан қуатты әсерді сезінеді — өзгенің оптимизмін немесе керісінше, көңілсіздігін жұқтырады. Әсер соншалықты күшті болады, адам өз сезімі мен көңіл-күйін жүрегіне жақын қабылдаған өзгенікінен ажырата алмай қалады.\nОл ашық, жанашыр, адамдармен оңай байланыс табады, ал олар өздері оған жанашырлық, қолдау немесе дана кеңес үшін қуана тартылады. Жан жылылығы, ашықтық пен жақсы эмоция сыйлай білу — оның басты қасиеттерінің бірі. Мұндай адамдар басынан басқалардан тек жақсыны, тіпті адамдардың өздері әрдайым байқамайтын және бағаламайтын нәрсені де көреді. Олардың миссиясы осында — адамдарға олардың күшті жақтарын аша отырып, жарық пен жақсылықтың өткізгіші болу.\nЫнтаны олар жақсы ортадан, фильмнен немесе музыкадан оңай табады. Оларды көңілге жағатын ұсақ-түйек пен нәзік тұстар толқытып, әсер етуі мүмкін. Оларды өзгенің табыс тарихы шабыттандырады.\nМұндай адам топтың бейресми көшбасшысы, топтағы немесе ұжымдағы әртүрлі адамдар арасындағы байланыстырушы буын бола алады. Ол эмоцияны жинамай, оларды оңай сыртқа беріп, басқалармен бөліседі. Ым-ишарат жасағанды және эмоцияны сөзбен барынша білдіргенді жақсы көреді.\nӘлсіз жағында мұндай адамдар өзгенің ықпалына оңай беріліп, басқалардың көңіл-күйіне тәуелді болады. Араласуға деген күшті қажеттілік оларды өз мұқтажын ұмытып, ортаға бейімделуге мәжбүрлейді.\nКейде сырттағының бәріне жауап беру әдеті эмоциялық шаршап-шалдығуға және тіпті дене сарқылуына әкеледі.\nБұл процестерді ақылмен бақылау маңызды, әйтпесе құрбандыққа кетуге болады.\nБасқаларды тұйықтық пен жасырындық үшін айыптауға біраз бейімділік бар. Үнемі әділдік іздеу, өзгенің адалсыздығын талқылау мен айыптау болуы мүмкін.\n### Ұсыныстар\nӨз сезімін өзгенікінен ажыратып, басқа адамдардың эмоциялық фонымен тұтасып кетпеу.\nОртаны үнемі іріктеп, оған мейіріміңіз бен көмектесуге деген ниетіңізді пайдаланатындарды жібермеу.\nАйла-шарғыға көнбей, өз эмоциялық күйіңізді бақылау.\nӨзгенің мәселесіне басыңызбен кірмей, болып жатқанның бәріне бірден жауап бермеу. Әйтпесе адамдардан және өзіңізден көңіл қалып, көп энергия мен өмірлік күш жоғалтуға болады.", "Гармоничный художественный": "Мұндай көрсеткіші бар адам білімдар, ойлау жүйесі бойынша — гуманитарий және қызығушылық шеңберін кеңейтуге тырысады. Ол бір тақырыпқа басымен кірмей, бәрі туралы аздап біледі, сондықтан оның үстірт білімі көп болуы мүмкін, бірақ көбіне тереңдік пен сарапшылық жетпейді.\nМұндай адамдарда әңгімеші таланты бар: оларды қуана тыңдайды, өйткені олар сенімді әрі жатық сөйлеп, тіпті толық меңгермеген ақпаратты да әдемі ұсынады. Ол ойды оңай тұжырымдап, білдіреді және оны шығармашылықпен, әртүрлі жеткізе алады.\nОны жоғары ашықтық пен байланысқыштық, жеңілдік пен шығармашыл ақыл ерекшелейді. Кейде оған ойда тәртіп пен логика жетпейді, жауапты немесе әңгіме тақырыбын ұзақ ойлану әдеті жоқ.\nОл жиі қызықты идеялар туғызады, бірақ оларды жүзеге асыруды бастамай және іске асыру туралы ойламай, тек айналадағыларға айтса, әдетте бәрі осымен бітеді. Өйткені ол үшін бастысы — идеяны сөзге түсіріп, оны еркіне жіберу. Сондықтан біреу оның ойын пайдаланып, соның негізінде табысты өнім жасау тәуекелі бар. Демек, ойлану мен әңгімеден басқа, ойлағанды қадам-қадаммен жүзеге асыру маңызды.\nЕң керемет идеяларды қуатты туғызу оған әлемді тұтас көрудің, бейнелі ойлау мен түйсіктің арқасында сәтті шығады.\nСонымен бірге оған араласуда энергиямен үнемі алмасу маңызды, өйткені идеялар көбіне дәл сөйлесуде туады. Ой еркіндігі мен өзін білдіру ниеті шығармашылыққа және дизайнер, суретші, коуч, әртіс, жазушы, кеңесші және т.б. сияқты мамандықтарға бейімділік береді.\nМұндай адам басын артық ойлармен толтырғанды және бірдеңені ұзақ айналдырғанды ұнатпайды. Ол дау-жанжалдан, айтыстан, ұзақ пікірталас пен түсінісуден аулақ болуға тырысады.\nОл араласуда жағымды, әңгімелесушінің немесе аудиторияның көңіл-күйін тамаша сезеді, сонымен бірге өзін-өзі қазбалап жатпайды және міндетті шешудің жеңіл жолын таңдайды.\n### Ұсыныстар\nЛогиканы жаттықтырып, дамытып, идеяларыңызды талдауды және оларды жүзеге асыру жолдарын ойластыруды үйрену.\nЕрекше ой немесе шешім келгенде, нәтиже түсінікті болып, маршруттың басты нүктелері белгіленуі үшін жүзеге асыру жоспары мен стратегиясын құру.\nБәрін жазып, күнделік пен жоспарлағыш жүргізген пайдалы.\nШығармашылық қабілеттерді ең болмаса бос уақытта хобби арқылы жүзеге асырып, қолдану.", "Сверхпродуктивный": "Мұндай адамда ең қуатты ой әлеуеті мен данышпандықтың нышаны бар. Ол шын қызығушылық танытатын кез келген салада сәтті дами алады. Күшті түйсік оған адамдарды көріп-біліп, нәзік сезінуге және тіпті оқиғалар барысын көп қадам алға болжауға мүмкіндік береді. Бұл — тамаша болжаушы әрі стратег.\nОл шығармашылықта өзін көрсете алады, көркемдік қабілеті жоғары, әлемді ерекше көріп, бейнелермен ойлай алады. Сонымен бірге ол ақпараттың үлкен көлемін қабылдап, өңдеп, сақтай алады.\nТалдай және жинақтап ойлай білудің арқасында ол ерекше нәрсе жасап, жаңалық ашуға қабілетті.\nМұндай адамдар командада да тамаша жұмыс істейді, әртүрлі міндеттерді орындай алады және көп міндетті мойнына алудан қорықпайды. Алайда сондықтан олардың шашыраңқылығы мен істерге үстірт қарауы болады. Олар бірден көп іске кірісіп, үлгермей, қатты шаршайды — жұмыстың сапасы зардап шегеді, шаршап-шалдығу болуы мүмкін. Назардың шашыраңқылығы, асығыстық және ұшы-қиырсызды қамтуға деген ниет әлеуетті төмендетіп, ойлау сапасы мен есте сақтауды нашарлатады.\nАдам креативтілігімен және бай қиялымен ерекшеленеді. Онда ерекше қабілеттер — мысалы, көріпкелдік немесе идеяларды шынымен «ауадан», айналадағы ақпараттық өрістен алу қабілеті ашылуы мүмкін.\nБұл типтегі адамдардың мінезі күрделі болуы мүмкін, әсіресе олар жүзеге аспаған болса: олар тура әрі өткір сөйлейді, ымыраға бейім емес және оқиғаларды сыни бағалағанды жақсы көреді.\nМұндай адам данышпан ойшыл және жаңашыл бола алады, идеялар туғызып, оларды әлемге жария етіп, қандай да бір саланың дамуына баға жетпес үлес қоса алады.\n### Ұсыныстар\nӨз ой қабілеттері мен идеяларын міндетті түрде қолдану.\nӨзіндік ерекше тәсілдерді, әдістемелер мен жобаларды әзірлеу.\nӨмір бойы әрдайым жаңаны біліп, дами беру.\nПікірлестерді — қызығушылықтары ұқсас адамдарды табу.\nНегізгі қызмет бағытын анықтап, күшті сонда шоғырландырып, сонда даму.\nМіндеттерді жазып, күшті дұрыс бөлу үшін жоспарлау мен мақсат қоюды жаттықтырып, күнделік жүргізу.", "Гармоничный мыслительный": "Бұл — талдаушы адам. Оның кез келген мәселе бойынша нақты ұстанымы, қағидалары мен өз пікірі бар. Оқиғаларды бағалағанда ол логикаға сүйенеді, алынған ақпаратқа сын көзбен қарап, оған күмән келтіреді.\nОл ішкі диалог пен ойлауға беріліп, болып жатқанға ақылға қонымды түсініктеме жиі іздейді.\nМұндай адамдар құрылымдалған және түсіндірілетін ақпаратты тамаша талдайды, бірақ қиялды қосу, көрінбейтінді елестету және түсіндіру керек болса, бұл оларға оңай болмауы мүмкін. Басында идеялар мен стратегиялар көп болса да, ойды сөзбен білдіру оларға қиын.\nОл сөйлегеннен гөрі көбірек ойлайды, пайымдайды және қорытынды жасайды. Бірдеңе айтса, бұл — ойлаудың дайын, қалыптасқан нәтижесі. Оның нақты пікірі мен берік сенімдері бар, оларды қорғауға дайын және жалғыз дұрыс деп санайды — өйткені ол айтып отырған мәселелерге шынымен негізді әрі мұқият қарап, пәнді мұқият зерттейді және нағыз сарапшылық білімге ие. Ол қарсыласымен келісуі үшін салмақты фактілер мен жоққа шығарылмайтын дәлелдер керек.\nОйды түсінікті баяндаудағы қиындықтан оның және айналадағылардың арасында көбіне түсінбеушілік туындайды.\nАқпараттың үлкен көлемін өңдеп, талдай білу — оның ойлауының күшті жағы, бірақ бұл қабілет әрдайым практикалық қолданыс таба бермейді.\nМұндай контуры бар адамдар философияға, эзотерикаға және психологияға тартылады.\n### Ұсыныстар\nШешендік өнерді үйрену.\nАктёрлық шеберлік сабақтарын алу.\nТек білім жинап, жетіліп қана қоймай, білімді іс жүзінде қолдану.\nАраласу, келіссөз жүргізу және сындарлы сөйлесу дағдыларын дамыту.\nҚиял мен шығармашылық ойлауды жаттықтыру.\nИнтеллектуалдық қабілеттерді зерттеулер мен ғылымда, жобалар мен стратегиялар жасауда қолдану.", "Дискретный": "Мұндай адамның ақылы логикалық, ол бәрін талдап, сынауға бейім.\nОған пән туралы барлық мүмкін деректер мен оларды өңдеуге уақыт керек. Мұндай ойлау бәрін практикалық, пайда және ақылға сыйымдылық тұрғысынан бағалауға мүмкіндік береді.\nОл шеттен ойлауға — бәрін аралық нұсқасыз және екіұштылықсыз ақ пен қараға бөлуге бейім.\nОның ой қабілеті таңғалдырады: ол орасан көп ақпаратты өңдеп, оны есте сақтап, керек сәтте қолдана алады. Оның ойлауында логика мен ережелер мен стандарттарға негізделген тұжырымдар маңызды рөл атқарады.\nОл болжай және құрылымдай алады. Мұндай адамдар үнемі бірдеңені ойлап, талдап жүреді, сондықтан оларға босаңсып, ойынан алаңдау қиын.\nАдам көбіне өзін басқалардан ақылды сезінеді, сондықтан тура әрі айтарлықтай өткір сынауға бейім.\nБұл айналадағылармен араласуды қиындатады, оның үстіне оған ойды білдіріп, сөзге түсіру қиын. Ол әңгімелесушінің деңгейіне бейімделмей, тым күрделі, ақылсынған, терминдер тілімен сөйлеуі мүмкін.\nОл көп сөйлегенді, дауыстап ойлағанды және дауласқанды ұнатпайды. Пікірлердің соқтығысуы оны ашуландырып, төзімсіз етеді. Оның өз ұстанымын дипломатиялық түрде қорғау және дауда ақиқат іздеу дағдысы жоқ. Әлсіз жағында адам өзгенің әлсіздігіне ойнап, әңгімелесушіден жоғары тұру үшін ақылын пайдалануы мүмкін.\nҚарқынды ой еңбегінен, үнемі ішкі диалогтан және ойлардың сыртқа шығу жолын таппауынан көңіл-күйдің ауытқуы, ұйқысыздық, бас ауруы болуы мүмкін.\n### Ұсыныстар\nИнтеллектуалдық әлеуетті міндетті түрде дұрыс бағытта — уақыт пен заманауи технологиялардан озатын жаңашыл әрі ерекше нәрсе ойлап табуда жүзеге асыру.\nШексіз жетіліп, білімді жинап қоймай, оны іс жүзінде қолданып, бөлісу.\nШешендік шеберлік пен дипломатиялық араласуды үйрену.\nАдамдарды сұранысы бойынша нәзік тұстарды түсіндіре отырып, әдепті бағыттау — сынамай, ең алдымен адамның күшті жақтарын алға шығарып.\nӨзгенің көзқарасына төзімділікті қалыптастырып, басқа дүниетанымды қабылдау.\nБасқа демалыс беріп, ойдан ауысуды үйреніп, медитация, йога және тыныс алу тәсілдерін жаттықтыру.\nЖазушылық дағдыларды пайдаланып, ойды қағазға түсіріп, ақылды босату.", "Продуктивный смешанный": "Бұлар — ойлаудың ең нәтижелі типтерінің бірінің өкілдері. Ол мидың екі жарты шарының да біреуі айқын басым болмай, үйлесімді әрі келісті жұмысының арқасында мүмкін. Сондықтан мұндай адамдар құрғақ логикамен шектелмей және шектен тыс қиял мен креативке кетпей, әртүрлі ойлау стратегияларын пайдаланады. Адамның жұмыс немесе өмір қоятын міндеттерге қарай ойлау тәсілін өзі таңдау мүмкіндігі бар.\nБұлар — араласу дағдылары тамаша, психологиялық тұрақты әрі салмақты адамдар. Олар кез келген ақпаратпен жұмыс істей алады, өйткені оны оңай өңдеп, түрлендіріп, нақты әңгімелесушіге ең лайықты түрде басқаларға жеткізеді.\nБірдеңені түсіндіргенде мұндай адам қатаң логика мен фактілерге сүйеніп өте қысқа да, бейнелі де сөйлей алады. Шығармашылықпен ойлау және жағдайды мұқият талдау қабілеті оған кез келген істе жүзеге асуға көмектеседі.\nОйлаудың мұндай түрі өзін ұстай алатын, жұмысқа жиналып, қажет болса ауысып, босаңси алатын адамдарға тән.\nКөбіне мұндай адамдарда психолог таланты бар, өйткені олар басқаларды жақсы сезініп, түсінеді және бәрімен ортақ тіл таба алады.", "Продуктивный мыслительный": "Бұлар — талдау қабілеті дамыған ойшылдар. Олар тек мықты теоретик қана емес, өз идеялары мен жобаларын іс жүзінде жүзеге асыра да алады. Олар ақпараттың үлкен көлемін тамаша есте сақтап, тез өңдейді, егжей-тегжейлі талдауға да, тиімді жинақтауға да қабілетті. Олардың қосымша артықшылығы — ұсақ-түйек пен бөлшекке назар және сөздің жақсы мағынасында ақпаратты сыни ой елегінен өткізу.\nОлар ғылыми ойлау мен логика керек салаларда дами алады. Жүйемен — белгілермен, схемалармен, стратегиялармен және символдармен жұмыс оларға оңай келеді.\nМұндай адам берілген параметрлер бойынша жаңаны құрастырып, іргелі негізде кең практикалық қолданысы бар өзіндікін жасай алады. Оған жүйеге сыни көзқарас керек жерде жұмыс істеген жақсы: ол процестердегі әлсіз және тиімсіз жерлерді тамаша анықтап, оларды көрсетіп, түзете алады.\nОл бар жағдайда сапалы жаңа нәрсе ұсына алады, басқа жүйе жасай алады немесе барын керекті параметрлерге қайта құра алады.\nОнда ақпаратты өңдеуде, беруде және сөзбен баяндауда қиындық жоқ. Ол өз бетінше де, ұжымда да жұмыс істей алады. Артық сөзсіз нақ мәнін жеткізіп, ең күрделі нәрсені қарапайым әрі түсінікті түсіндіре алады.\nБұлар — тамаша әңгімелесушілер, бірақ сонымен бірге аз нәрсеге көзсіз сенеді. Оларды эмоцияға әсер ету немесе бейнелер арқылы сендіру қиын — логика әрдайым бірінші орында. Тамаша табиғи есте сақтау мен шоғырлану оларға әңгімелесушіні мұқият тыңдап, мәселенің мәніне үңілуге мүмкіндік береді.\nМұндай адамдар көреген, байқағыш және басқаларға мұқият. Олар үшін араласудың өзі немесе «әңгімелесу» мүмкіндігі емес, дәл оның сапасы маңызды. Олар бос әңгімені ұнатпайды және бір мақсатпен — жаңа тәжірибе немесе қызықты ақпарат алу, кәсіпқой ретінде ашылу немесе ойлануға себеп табу үшін араласқанды қалайды.\nБұлар — интеллектуалдық дамыған ақылды әрі қызықты әңгімелесушілер, сондықтан кез келген дерлік тақырыпта әңгімені қолдай алады.", "Продуктивный художественный": "Бұлар — қиял мен шығармашылыққа бейім, елестетуі жақсы жұмыс істейтін интеллектуалдық дамыған адамдар. Бұлар — өзі де көріне алатын, өзгенің идеяларын да сапалы, тың әрі айналадағыларға түсінікті жеткізе алатын креативті адамдар.\nОлар күрделі ақпарат пен ойды танымал, бейнелі түрде жеткізу, қарапайым әрі түсінікті түсіндіру керек барлық салада мінсіз.\nМұндай адамның сөзі сауатты, талғамы мен шама сезімі жақсы, сонымен бірге ерекше ойлап, ең күтпеген идеяларды ұсына алады. Оның өзін тиімді таныстыру, ой мен логикалық тізбекті оңай құру таланты бар. Оған әртүрлі адамдармен араласу оңай, әркімге жол мен ортақ тіл табады. Ол әңгімелесушінің назарын иемденіп, өзіне қызығушылық тудыра алады. Ол араласуда дипломат және әртүрлі жағдайда бітімгер бола алады.\nОқу мен кез келген ақпаратты өңдеу оған оңай келеді. Сонымен бірге оның сау сыни ойлауы бар: ол ештеңеге сөзбен сенбейді, бәрін қайта тексеріп, қолымен ұстап, қабылдаудың мүмкіндігінше көп арнасы арқылы өзі сезінуге тырысады. Мұндай адамдар өзін бағдарламалап, ой мен сенім күшімен өмірлеріне қатты әсер ете алады.", "Прикладной мыслительный": "Мұндай адамдардың ақылы талдауға бейім. Дайын ақпаратпен жұмыс, оны талдау мен жинақтау оларға оңай келеді. Олар ой қызметіне бейім және ойлануға көп уақыт жұмсайды. Әдетте бұлар — аз сөйлейтін және энергиясын сыртқы әлемге беруге, өзін көрсетуге бейім емес тұйығырақ адамдар (интроверттер).\nОйлану үшін оларға асықпайтын қарқын керек. Олар пайдалы кеңес беріп, сындарлы сынай алады. Олар тар маман ретінде жақсы ашылады — мұндай тәсіл ішкі энергияның шағын қорын шашпай, белгілі бір салада мақсатты түрде сарапшы болуға мүмкіндік береді. Дәл пәнге терең ену және оған байыпты қарау кәсіби мойындалуға жетуге көмектеседі.\nОлар өзіндік, шығармашылық нәрсе жасау немесе зерттеу жүргізу қажет емес жұмысты қалайды. Олар үшін мінсіз сала — қатаңдық, тәртіп, нақтылық, нормативтер және дайын үлгімен әрекет ету мүмкіндігі бар жер. Сонда бұлар — дәл өз тар учаскесінде ең тиімді мінсіз әрі сауатты орындаушылар. Оларға қарапайым қолданбалы міндеттер мен құрылған алгоритм бойынша әрекет жақсы шығады.\nМұндай адамдар онша ашық емес, бірақ анда-санда серік пен әңгімелесушіге мұқтаж. Бірақ ортақ әңгімеде олар көбіне бақылаушы әрі тыңдаушы болады. Олар өтірік айта алмайды, өйткені ол үшін стратегия ойлап, қиялды қосу керек, ал бұл оларға оңай емес. Олар философиялауды және армандауды ұнатпайды және әрдайым бар жағдайда, осында және қазір барына сүйене отырып жұмыс істейді. Олар өзгенің идеясын жетілдіріп, басқалар тек армандайтын нәрсені іс жүзінде мұқият жүзеге асыра алады.", "Прикладной смешанный": "Мұндай адам әрдайым қазіргі сәтке көбірек шоғырланады. Оған нақты мысалдармен ойлау — теория мен пайымдаумен айналыспай, бірден бірдеңені әрекетте дамыту оңайырақ.\nКөбіне ол өзгенің ойын өзінікінен жақсырақ түсініп, оны нақтырақ, сенімдірек әрі бейнелірек білдіреді.\nСүйенетін нәрсе — лайықты үлгі, беделді адамдар, стратегиялар, формулалар, әрекет жоспары болса, ол белгілі бір қызмет түрлерінде шығармашылықпен де өзін көрсете алады.\nОл жаңаны кітаптан емес, тәжірибе беру арқылы — қарап, сіңіріп, үйреніп, қайталау арқылы білгенді қалайды. Оған ақпаратты өмірлік оқиғалар, мысалдар мен үлгілер арқылы қабылдау оңайырақ.\nОл өзін-өзі дамытумен айналысып, таланттарына қолданыс іздейді және бір орында тұрмайды.\nОл құрылған схема мен әдістеме бойынша әрекет етуге болғанда ең жоғары тиімділік көрсетеді.\nАлған білімді қолдану және өзгенің тәжірибесін немесе теориясын іс жүзінде жүзеге асыру оған тамаша шығады. Бөлшекке жоғары назар не пайда әкелетінін және неден табыс табу мүмкін емес екенін тез түсінуге мүмкіндік береді. Бұл әрдайым іс адамы, ол бос сөзді ұнатпайды және айналадағылардан да соны күтеді. Ол нақтылықты қалайды және көбіне идеядан емес, өз қолымен жасағанынан табыс табады.\nКөбіне бұлар — өз көзқарасын қорғайтын және араласуда сын мен бағалауды қолданатын қырсық адамдар.", "Аналоговый": "Бұл адамдар көбіне ашық (экстраверт) ретінде көрінеді: ашық, дипломат, дауға бейім емес және ойды еркін білдіреді. Мұндай контуры бар адам көбіне өзгенің тәжірибесіне сүйеніп ойлап, шешім қабылдайды және үйреншікті стратегиялармен әрекет етеді.\nМінез-құлық пен дағдыларды ол көбіне өзі үшін бедел әрі еліктеу үлгісі болған адамнан алады. Оның келіссөз жүргізу дағдысы күшті — сөзімен мәселені шешіп немесе дауды жұмсарта алады. Оның сырт келбеті, мимикасы мен ым-ишаратынан көңіл-күйін түсіну оңай. Сөзі өте дамыған, сондықтан ол өзіне тартады, ашық әрі қарым-қатынасқа бейім.\nМұндай адамға өзіндік бірдеңе ойлап шығару қиын. Оған дайын схемалар мен алгоритмдер бойынша жұмыс істеу немесе соның негізінде жетілдірілген бірдеңе жасау жақсырақ шығады. Кейде ол өзгенің ойы мен идеясын өзінікі ретінде «иемденуге» бейім — бірақ жаман ниетпен емес, жаңа идеялар мен үрдістерді тез қағып алып, нәтижесінде оларды өз ойының жемісі деп қабылдайтындықтан.\nШектен тыс сөзуарлық, қатты әрі өткір дауыс, ашулы сөздер пайда болуы мүмкін, әңгімеде немесе дауда тоқтау қиын. Оған есте сақтау мен шоғырланудағы қиындықтар қосылады. Ол көбіне тыңдай алмайды және әңгімелесуші айтқанды дұрыс қабылдай алмайды. Сондықтан мазасыздық пен айтылмаған немесе әлі болмаған нәрсені ойдан қосу әдеті пайда болады. Ойлаудың мұндай ерекшелігі адамдармен араласуда түсінбеушілік туғызуы мүмкін.\n### Ұсыныстар\nШығармашылық қабілеттерді дамытып, өнермен айналысу. Көркем, бейнелі көзқарас идеялылық пен өзгешелікті дамытуға көмектеседі.\nӨзгенің идеясын әдемі сөзге түсіріп қана қоймай, өзіндікін жасап, ойлаудың дербестігі мен әлемге өз көзқарасын жаттықтыру.\nНәтижелілік пен даму үшін көп оқып, қосымша білім мен тәжірибе алу — бұл үстірттіктен аулақ болуға көмектесіп, сарапшылықты арттырады.\nӘрдайым мәнін зерделеп, зерттелетін пәнге тереңдеуге тырысып, ол туралы қиялға емес, фактілерге, логика мен талдауға негізделген өз пікірін қалыптастыруды үйрену.", "Аналаговый": "Бұл адамдар көбіне ашық (экстраверт) ретінде көрінеді: ашық, дипломат, дауға бейім емес және ойды еркін білдіреді. Мұндай контуры бар адам көбіне өзгенің тәжірибесіне сүйеніп ойлап, шешім қабылдайды және үйреншікті стратегиялармен әрекет етеді.\nМінез-құлық пен дағдыларды ол көбіне өзі үшін бедел әрі еліктеу үлгісі болған адамнан алады. Оның келіссөз жүргізу дағдысы күшті — сөзімен мәселені шешіп немесе дауды жұмсарта алады. Оның сырт келбеті, мимикасы мен ым-ишаратынан көңіл-күйін түсіну оңай. Сөзі өте дамыған, сондықтан ол өзіне тартады, ашық әрі қарым-қатынасқа бейім.\nМұндай адамға өзіндік бірдеңе ойлап шығару қиын. Оған дайын схемалар мен алгоритмдер бойынша жұмыс істеу немесе соның негізінде жетілдірілген бірдеңе жасау жақсырақ шығады. Кейде ол өзгенің ойы мен идеясын өзінікі ретінде «иемденуге» бейім — бірақ жаман ниетпен емес, жаңа идеялар мен үрдістерді тез қағып алып, нәтижесінде оларды өз ойының жемісі деп қабылдайтындықтан.\nШектен тыс сөзуарлық, қатты әрі өткір дауыс, ашулы сөздер пайда болуы мүмкін, әңгімеде немесе дауда тоқтау қиын. Оған есте сақтау мен шоғырланудағы қиындықтар қосылады. Ол көбіне тыңдай алмайды және әңгімелесуші айтқанды дұрыс қабылдай алмайды. Сондықтан мазасыздық пен айтылмаған немесе әлі болмаған нәрсені ойдан қосу әдеті пайда болады. Ойлаудың мұндай ерекшелігі адамдармен араласуда түсінбеушілік туғызуы мүмкін.\n### Ұсыныстар\nШығармашылық қабілеттерді дамытып, өнермен айналысу. Көркем, бейнелі көзқарас идеялылық пен өзгешелікті дамытуға көмектеседі.\nӨзгенің идеясын әдемі сөзге түсіріп қана қоймай, өзіндікін жасап, ойлаудың дербестігі мен әлемге өз көзқарасын жаттықтыру.\nНәтижелілік пен даму үшін көп оқып, қосымша білім мен тәжірибе алу — бұл үстірттіктен аулақ болуға көмектесіп, сарапшылықты арттырады.\nӘрдайым мәнін зерделеп, зерттелетін пәнге тереңдеуге тырысып, ол туралы қиялға емес, фактілерге, логика мен талдауға негізделген өз пікірін қалыптастыруды үйрену."}, "harm": {"mul": {"low": "Толыққанды, тұрақты жақын өмір.\nРационда ет және басқа ақуызды өнімдер.\nСау тамақтану.\nЖеткілікті мөлшерде толыққанды ұйқы (қажет болса және мүмкіндік болса — күндізгі демалыспен).\nАуыр жүктемесіз және кәсіби спортсыз әуесқой дене белсенділігі: би, жаяу жүру, созылу, йога. Экстремалды және қауіпті түрлерден аулақ болған жақсы — жарақат тәуекелі жоғары.\nТабиғатта уақыт өткізу, жермен және өсімдіктермен жұмыс.\nСаяхат, дәстүрге жүгіну және бүкіл денені біркелкі қамтитын әрі қуаныш әкелетін белсенділік.\nҚорқыныш пен шектейтін сенімдермен жұмыс, оларды жеңу. Өзін естіп, шынайы қажеттіліктерді тауып, оларды таңылған ережелер мен стереотиптерден ажырата білу.\nОтбасы мен туыстық байланыстарды нығайту, ру мүшелерімен жақсы қарым-қатынасты қалпына келтіру, үлкендерді құрметтеу, олардың тәжірибесін алу, отбасы туралы білімді сақтап, кіші буынға беру.\nОртамен жұмыс: араласу үшін үйренетін нәрсесі бар табысты, белсенді, мақсатты, позитивті және тәуелсіз адамдарды таңдау.\nБәріне белсенді қарау: тек армандап, жоспар құрып қоймай, дәл қазір — аздап, бірақ тұрақты әрекет ете бастау.\nДене мен үйге күтім жасау, энергияның тоқырауына жол бермеу, заттар мен кеңістікті жаңарту, өмірдің әртүрлі саласында өсуге ұмтылу.\nТастар: агат, гематит, гранат, қызыл маржан, рубин, қызыл яшма.\nХош иістер: самырсын, қалампыр, майқарағай, пачули, сандал, даршын, шалфей.\nТамақтану: кез келген ақуыз, әсіресе табиғи ет.\nЧакраның түсі — қызыл. Энергияның жетіспеуін толтыру үшін негізгі түске қоңыр немесе қара қосылады.", "high": "Энергияны үйлестіру үшін дене дамуына және денеге жеткілікті уақыт бөлу маңызды. Дененің барлық бөлігі біркелкі жұмыс істейтін, іш бұлшықеті мен аяққа ерекше көңіл бөлінетін спорт түрлері жақсы. Кардио жүктеме, жүгіру және жаяу серуен тамаша келеді.\nӨзін және айналадағыларды дененің барлық ерекшелігімен қабылдап, құрметтеу маңызды.\nТек материалдыққа ғана емес, рухани дамуға да уақыт бөліп, өмірдің жоғарырақ мәнін көріп, даму.\nМәселені күшпен емес, ақылмен шешу: келісу, ымыра және ең жақсы шешім табу.\nӨмірді жоспарлап, уақыт пен мақсатты басқарудың негіздерін меңгеріп, өмірге тайм-менеджментті енгізу.\nШаршағанда, ортаны және іс түрін ауыстыру үшін табиғатта болып, жермен жұмыс істеп, бақпен айналысқан пайдалы.\nМассаж және өзін-өзі уқалау, спа-процедуралар.\nРационды реттеу. Тамақтың артықтығынан дене сылбыр әрі апатиялы болады, сондықтан ауыр тамақтан және артық жеуден аулақ болған жөн.\nҚалыптан жоғары Муладхараны теңестіру үшін ақуызды тек еттен ғана емес, өсімдік және басқа көздерден: жаңғақтан, бұршақ тұқымдастардан, жұмыртқадан, сүт пен сүт өнімдерінен алу маңызды.", "max": "Дене күйі мен денсаулыққа қамқорлық жасап, хал-жағдайға мұқият қарап, шамадан тыс жүктемеге де, жалқаулыққа да жол бермей, денеге және оның қажеттіліктеріне құлақ асу.\nДененің төменгі бөлігі мен аяққа жүктеме беретін спортпен немесе кез келген дене белсенділігімен айналысу: би, жүгіру, велосипед, жаяу жүру, шаңғы, іштің төменгі бұлшықетіне арналған жаттығулар. Сондай-ақ бүкіл денені біркелкі қамтитын сабырлы спорт түрлерімен (мысалы, йога) және күнделікті серуенмен.\nТабиғатта болып, жермен жұмыс істеп, өсімдік отырғызып, оларға күтім жасау.\nМассаж және өзін-өзі уқалау, спа-процедуралар.\nӨмірге жеңіл қарауды және жеңіл қозғалуды үйрену.\nЭнергия тоқырап қалмауы үшін саяхаттап, жаңаны ашып, жаңа әсер жинау.\nӨз денесін және оның кемшілігін толық қабылдап, басқаларға да солай қарау.\nДенелік нәрсеге байланып қалмай, тепе-теңдікті сақтап, рухани даму.\nӨзіне, адамдарға және болып жатқанға ақылға қонымды әрі саналы қатынас қалыптастыру. Мәселені күшпен шешпей және дауға араласпай — келісіп, ымыра мен ең жақсы шешімді табу.\nЭмоциямен жұмыс істеп, жағымсыз сезім мен агрессияны жұмсақ көрсетуді үйреніп, оларды іште жинамау.\nУақытпен қарым-қатынасты реттеу: жоспарлауды үйреніп, белсендірек әрекет етіп, бастағанды әрдайым нәтижеге жеткізу.\nРационды реттеу. Тамақтың артықтығынан дене сылбыр, әлсіз әрі апатиялы болады. Қалыптан жоғары Муладхараны теңестіру үшін тек ет жемей, ауыр тамақтан және артық жеуден аулақ болып, ақуызды өсімдік және басқа көздерден: жаңғақтан, бұршақ тұқымдастардан, жұмыртқадан, сүт пен сүт өнімдерінен алу маңызды."}, "sva": {"low": "Өз денесіне деген махаббатты тәрбиелей отырып, өзін-өзі бағалауды көтеру. Өмірге позитивті қарауды үйреніп, шағымданбау және құрбан позициясын ұстанбау.\nДене мен ойды бақылауды дамытып, қарапайым инстинкттердің басым түсуіне жол бермей, саналы өмір сүріп, әрекет етіп, зиянды құмарлыққа берілмеу.\nАғзадағы тепе-теңдікті сақтай отырып, жеткілікті су ішу. Сумен үнемі байланыста болу: душ немесе ванна қабылдау, жүзу, су жағасында демалу.\nНесеп-жыныс жүйесінің денсаулығына қамқорлық жасау. Серіктестерді мұқият таңдап, энергияны олардың санымен толтырмау.\nСезімталдық пен тартымдылықты ашып, өз денесі мен оның қажеттіліктерін бағалап, құрметтеу. Жақындыққа ішкі тыйым болса (мысалы, қатаң тәрбиеден), оны психологпен шешіп, жақын өмірді реттеу.\nАзапты ұят сезімінсіз өзін еркелетуді үйрену. Тәуелділікке кетпей, денсаулыққа зиян келтірмейтін нәрсемен өзін қуанту.\nӨзіне ұнайтын нәрсеге рұқсат беру: хоббиге, сатып алуға, спортқа, сүйікті фильмдерге және энергия мен қуанышқа толтыратын нәрсенің бәріне уақыт табу.\nЖанасуға сезімталдықты, сезім мүшелері арқылы ләззат ала білуді дамыту: өзін-өзі уқалау, массаж, хош иіс терапиясы, айналадағы әдемі заттар, өзіне және кеңістігіне күтім.\nҚозғалып, энергияның тоқырауына жол бермеу. Саяхаттап, жаңа жерлерді ашып, адамдармен танысқан пайдалы.\nОсы сәтте өмір сүруді және сәттен ләззат алуды үйрену. Эмоция мен әсерді әртүрлі жолмен алып, оларды білдіруден, оның ішінде шығармашылықта қорықпау.\nТуыстық байланыстарды реттеп, отбасындағы, әсіресе анамен және әйел туыстармен қарым-қатынасты жақсарту.\nТүсінбеушілік пен өкпені босатып, отбасының ықпалынан дана түрде, алғыспен бөліну. Сонымен бірге туыстарды ұмытпай, олармен араласып, көмектесіп, құрмет көрсету.\nДене белсенділігін сақтау: жүзу, би, пилатес, йога, жүгіру, серуен, ер адамдарға — жекпе-жек.\nТастар: янтарь, сердолик, турмалин, ай тасы, қызғылт сары гранат, яшма, күн тасы, сардоникс.\nХош иістер: ащы апельсин, сандал, иланг-иланг, ваниль, мирра.\nТамақтану: чакраның үйлесімді жұмысы үшін жеткілікті су мен басқа сұйықтық — тәулігіне кемінде 1,5–2 литр ішу маңызды. Морс, табиғи шырын, шөп шайы және таза ауыз су ең жақсы келеді.\nЧакраның түсі — қызғылт сары. Бұл — күш пен сергектік беретін, көңіл-күйді көтеретін, құштарлықты күшейтетін және қарсы жыныстың назарын аударуға көмектесетін күшті, позитивті, өмірге құштар әрі өте белсенді түс.", "high": "Дене мен ойды бақылауды дамытып, қарапайым инстинкттердің басым түсуіне жол бермей, саналы өмір сүріп, әрекет етіп, зиянды құмарлыққа берілмеу.\nАнамен қарым-қатынасты махаббат пен алғыстан құрып, ата-анадан ішкі бөлінуді аяқтап, өзінде тәуелсіздік пен жауапкершілікті өсіру.\nСапалы қарым-қатынасты таңдап, серіктес таңдауға мұқиятырақ қарап, қарсы жыныспен қарым-қатынасты үйлестіру.\nАта-ана рөлінде (ана немесе әке болып) жүзеге асу.\nАктёрлық шеберлікте, модельдік істе, фотосурет түсірілімінде модель рөлінде өзін байқап көру.\nБосаңсуды үйреніп, демалысқа жеткілікті уақыт бөлу, денеге күтім жасап, спа-процедуралар мен массажға бару.\nДене практикалары, би, шығыс жекпе-жектері, жүзу арқылы өз денесін басқаруды үйрену. Әйелдерге пластика, би бағыттары, созылу және босаңсуға арналған жаттығулар жақсы келеді.\nЖеткілікті су ішу — сумен кез келген байланыс өте пайдалы.\nПсихологиялық күйді реттеу: жеке шекараны құрып, уыттылық пен өзімшілдіктен алыстау немесе керісінше, құрбан рөлінен шығу.\nШығармашылық әлеуетті ашу: жанға жақын іске немесе ең болмаса күш беретін хоббиге рұқсат беру.\nИдеялар арман болып қалмай, тұрақты, тіпті шағын қадамдармен біртіндеп жүзеге асуы үшін бәрінде тепе-теңдік пен сау белсенділікті сақтау.\nЭмоция мен ләззатқа деген шөлді саяхатта және жаңа, позитивті адамдармен араласуда қандыру. Жаңаны байқап көріп, ашық әрі табиғи әрекет етіп, босаңсу тәсілдерін меңгеру.\nӨз тілектеріңізге көбірек құлақ асып, бірақ құмарлықтың құлы болмау. Қажеттіліктерді уақытында қанағаттандырып, тәуелділікке түспеу.\nҚарым-қатынастағы тәуелділіктен бас тартып, ересек адам болып, өз өмірі үшін жауапкершілікті алу. Сонымен бірге қамқорлық пен құрмет көрсете отырып, серіктеспен үйлесімді араласуды сақтау."}, "man": {"low": "Теңгерімді тамақтану, жеңілдету күндері, үзіліссіз сау тамақтың тұрақты түсуі. Аскеза практикасы пайдалы.\nТұрақты спорт пен дене жүктемесі — бірақ тәуекелсіз және шамадан тыс жүктемесіз.\nЭнергияға толу үшін күн ваннасы мен күнде сақтықпен, таңертең болған пайдалы.\nАқшамен қарым-қатынасты реттеу: ысырапшылдықты алып тастап, табыс пен шығысты салыстыра отырып, шығындағы тепе-теңдікті табу.\nҚаржылық сауаттылық негіздерін меңгеріп, соны ұстанып, ресурстарды ақылмен бөлуді үйрену.\nКүн мен тамақтану тәртібін сақтау.\nЖоспарлау дағдысын дамыту: шағын міндеттер қойып, ұзақ мерзімді мақсаттарға стратегия құру. Күнге, аптаға және айға басымдықтарды дұрыс қойып, істер тізімін жасау.\nПозитивті көңіл-күйді сақтап, шағымданбай, нақты жағдайда нені өзгертуге немесе неге үйренуге болатынын өзіңізден сұрау.\nБасқаларға көмектесіп, адамдарды өзіне көмекке тартып, жемісті серіктестікті үйрену. Сонда ішкі күш пен энергия жетпесе де, белсенді дами беруге болады.\nҚиындықтан қорықпай және одан қашпай, керісінше, әртүрлі өмірлік мәселені шеше білуді дамыту. Бұл ерік күшін, мінезді және белсенді ұстанымды нығайтады.\nЖаңаны байқап көріп, жайлылық аймағынан шығу — дәл соның артында жаңа мүмкіндіктер мен перспективалар басталады.\nКөбірек оқып, жаңа салаларды меңгеру.\nӘртүрлі эмоцияны, оның ішінде қоғамда жол берілмейді деп саналатын эмоцияны, мысалы ашу мен тітіркенуді көрсетуден қорықпай, оларды білдіруді үйрену. Бірақ оларды басқаларды құрбан етпей және өзі сол күйге кетпей, жұмсақ білдіру.\nБасқалар шекараны бұзғанда «жоқ» деп, бас тарту.\nӨзіне қамқорлық жасап, қажеттілігін қанағаттандыру. Оларды өз бетінше толтыра отырып, адам сенімдірек болып, сыртқы жағдайларға азырақ тәуелді болады.\nТастар: сары және алтын түсті тастар, сары рубин, янтарь, жолбарыс көзі, сары топаз, цитрин, сары турмалин, пирит, сары яшма.\nХош иістер: арша, бергамот, розмарин, лаванда, түймедақ, лимон, анис.\nТамақтану: Манипура тез әрі оңай сіңетін тамақты — негізінен көмірсуларды, дәнді дақылдарды жақсы көреді. Баяу пайдалы көмірсуларды көбірек қосып, тездерін шектеу маңызды, өйткені олар оңай жанып кететін көп тез энергия береді.\nМанипураның түсі — оның барлық жылы реңктерімен сары, сондай-ақ алтын түсті.", "high": "Оқып, үнемі дамып, тек материалдық салада ғана емес қызығушылықтар болып, рухани өсу.\nТөзімділікті, әртүрлі көзқарас пен ұстанымды қабылдай білуді дамытып, өз көзқарасы мен қағидаларын таңбау.\nҚиындықта қасарысып алға баспай, тоқтап, болып жатқанды талдай біліп, икемдірек болып, стратегияны уақытында өзгерту.\nМақсат қою дағдысын дамытып, оларға шашырамай, кезең-кезеңімен жүру.\nӨзін бақылап, агрессияның әріптестермен және жақындармен қарым-қатынасты бұзуына жол бермеу. Ашу мен жағымсыз эмоциялармен жұмыс істеу: олардан қашпай және оларды баспай, шынайы себебін түсініп, жұмсақ білдіріп, өзгерту.\nСалауатты өмір салтын ұстанып, дұрыс тамақтану: зиянды өнімдерден бас тартып, жеңілдету күндерін өткізіп, әртүрлі аскезаны жаттықтыруға болады.\nМіндетті түрде спорт пен дене белсенділігі. Іш арқылы тыныс алумен тыныс алу гимнастикасы пайдалы.\nБасқаларға көмектесіп, қайырымдылыққа, волонтёрлыққа және адамдардың игілігі үшін қоғамдық істерге — материалдық пайда күтпей, пайдакүнемсіз қатысу. Өршілдікті басқалардың пайдасына бағыттап, жоғары рухани мақсаттарға ие болып, жанашырлық пен бірге күйзелуді дамыту.\nБизнесте, басқаруда, өз ісінде өзін жүзеге асырып, өз идеяларын жылжытып, оларды жүзеге асыруға көмектесу.\nҚажет болса, бұл үшін команда жинап, әлеуметтік белсенді болу.\nҚаржылық сауаттылықты сақтап, білімді іс жүзінде қолдану: әрдайым жинақ болып, қаражаттың бір бөлігін өсу мен дамуға салып, ақшаны бір жерде ұстамау."}, "ana": {"low": "Берік адамгершілік негіздерге ие болып, сол қағидаларды ұстану, қатені мойындаудан қорықпай, одан қорытынды жасау.\nАраласу ортасын мұқият таңдау — қасыңызда позитивті пікірлестер, ашық әрі қызықты адамдар болсын.\nБасқаларға көмектесіп, қайырымдылық пен волонтёрлықпен айналысу — пайдакүнемсіз, күштің молдығынан және қалауымен.\nЖақындарға, табиғатқа және жануарларға қамқорлық жасауға уақыт табу. Табиғатта көбірек болып, оның сыйын пайдаланып қана қоймай, айналадағы кеңістікке күтім жасау.\nСәтсіздік пен жағымсыз нәрсеге емес, бар, шығып жатқан және ұнайтын нәрсеге сүйену. Позитивті ойлау мен алғысты жаттықтыру.\nҮй жануарын асырап, оған жақсы қамқорлық жасау.\nӨзін барлық қасиетімен қабылдау. Бұл бұрынғыдай қалып, жақсаруға ұмтылмау дегенді білдірмейді — бұл өзін түсініп, жақсы көріп, қатесін кешіріп, жағымсыз күйде қалып қоймай, әрі қарай жүруге рұқсат беру. Өткенмен немесе алыс болашақпен өмір сүрмей, дәл қазір бастау.\nЧакраны белсендіруге жағымды әуенді музыка: табиғат дыбыстары, классика, дұға мен мантралар көмектеседі.\nАнамен үйлесімді қарым-қатынас құрып, байланыс орнатып, оның тәжірибесін қабылдап, түсіну. Мүмкіндігінше жақындармен және отбасымен қарым-қатынасты үйлестіру.\nӨмірдегі әр оқиғаны (тіпті жағымсызын да) тәжірибе мен болашақ әлеуетін бағалай отырып, даналықпен және алғыспен қабылдау.\nРенжіткен немесе қапаландырған адамдарға наразылықты ойша немесе қағазға айтып, бекер үміт артпай, оларды босату — адамдар оларға сай болуға міндетті емес.\nӨмірге позитивті көзқарас әдетке айналуы үшін алғысты үнемі жаттықтыру, мысалы, алғыс күнделігін жүргізу.\nШығармашылық пен қол еңбегімен айналысып, шама келгенше өз қолымен бірдеңе жасап, тамақ әзірлеу.\nАдамдардан жақсыны байқауды үйреніп, қызғанышсыз шын тәнті болып, мақтау сөз айту. Ашығырақ болып, махаббатты сыйлап, алғыспен қабылдап, ештеңе күтпей, таза жүректен жақсылық жасау.\nБақыттың, махаббаттың және үйлесімнің көзін өзінен табу, өзгенің бағасы мен мойындауына бағдарланбау және өзін басқалармен салыстырмау. Іште адамгершілік бағдарлардың орнықты жүйесі мен ішкі тірек болса, кез келген жағдайда төтеп беріп, айналадағыларға ұқыпты қарау оңайырақ.\nТәуелсіздік пен өзіне-өзі жеткіліктілікті дамыту — бұл жоғалтудан азырақ зардап шегуге көмектеседі. Адамдар мен оқиғаларға тәуелді болмау үшін сыртқы жағдайларға емес, тепе-теңдік пен бақыттың ішкі көздеріне сүйену.\nТастар: қызғылт кварц, жасыл және қызғылт турмалин, изумруд, ай тасы, кунцит, малахит, авантюрин, жасыл нефрит, халцедон, хризопраз, рубеллит.\nХош иістер: раушан, жасмин, самырсын, сандал, қарағай, ырғай (жимолость).\nТамақтану: чакраның энергиясын сақтау үшін жеткілікті мөлшерде жаңа немесе дұрыс әзірленген өсімдік өнімдерін — көкөніс пен жеміс, тамыржемістер, көк шөп, салат, шөптер және өсімдіктің кез келген бөлігін жеу маңызды.\nАнахатаның түстері — жасыл және қызғылт.", "norm": "Берік адамгершілік негіздерге ие болып, сол қағидаларды ұстану, қатені мойындаудан қорықпай, одан қорытынды жасау.\nАраласу ортасын мұқият таңдау — қасыңызда позитивті пікірлестер, ашық әрі қызықты адамдар болсын.\nБасқаларға көмектесіп, қайырымдылық пен волонтёрлықпен айналысу — пайдакүнемсіз, күштің молдығынан және қалауымен.\nЖақындарға, табиғатқа және жануарларға қамқорлық жасауға уақыт табу. Табиғатта көбірек болып, оның сыйын пайдаланып қана қоймай, айналадағы кеңістікке күтім жасау.\nСәтсіздік пен жағымсыз нәрсеге емес, бар, шығып жатқан және ұнайтын нәрсеге сүйену. Позитивті ойлау мен алғысты жаттықтыру.\nҮй жануарын асырап, оған жақсы қамқорлық жасау.\nӨзін барлық қасиетімен қабылдау. Бұл бұрынғыдай қалып, жақсаруға ұмтылмау дегенді білдірмейді — бұл өзін түсініп, жақсы көріп, қатесін кешіріп, жағымсыз күйде қалып қоймай, әрі қарай жүруге рұқсат беру. Өткенмен немесе алыс болашақпен өмір сүрмей, дәл қазір бастау.\nЧакраны белсендіруге жағымды әуенді музыка: табиғат дыбыстары, классика, дұға мен мантралар көмектеседі.\nАнамен үйлесімді қарым-қатынас құрып, байланыс орнатып, оның тәжірибесін қабылдап, түсіну. Мүмкіндігінше жақындармен және отбасымен қарым-қатынасты үйлестіру.\nӨмірдегі әр оқиғаны (тіпті жағымсызын да) тәжірибе мен болашақ әлеуетін бағалай отырып, даналықпен және алғыспен қабылдау.\nРенжіткен немесе қапаландырған адамдарға наразылықты ойша немесе қағазға айтып, бекер үміт артпай, оларды босату — адамдар оларға сай болуға міндетті емес.\nӨмірге позитивті көзқарас әдетке айналуы үшін алғысты үнемі жаттықтыру, мысалы, алғыс күнделігін жүргізу.\nШығармашылық пен қол еңбегімен айналысып, шама келгенше өз қолымен бірдеңе жасап, тамақ әзірлеу.\nАдамдардан жақсыны байқауды үйреніп, қызғанышсыз шын тәнті болып, мақтау сөз айту. Ашығырақ болып, махаббатты сыйлап, алғыспен қабылдап, ештеңе күтпей, таза жүректен жақсылық жасау.\nБақыттың, махаббаттың және үйлесімнің көзін өзінен табу, өзгенің бағасы мен мойындауына бағдарланбау және өзін басқалармен салыстырмау. Іште адамгершілік бағдарлардың орнықты жүйесі мен ішкі тірек болса, кез келген жағдайда төтеп беріп, айналадағыларға ұқыпты қарау оңайырақ.\nТәуелсіздік пен өзіне-өзі жеткіліктілікті дамыту — бұл жоғалтудан азырақ зардап шегуге көмектеседі. Адамдар мен оқиғаларға тәуелді болмау үшін сыртқы жағдайларға емес, тепе-теңдік пен бақыттың ішкі көздеріне сүйену.\nТастар: қызғылт кварц, жасыл және қызғылт турмалин, изумруд, ай тасы, кунцит, малахит, авантюрин, жасыл нефрит, халцедон, хризопраз, рубеллит.\nХош иістер: раушан, жасмин, самырсын, сандал, қарағай, ырғай (жимолость).\nТамақтану: чакраның энергиясын сақтау үшін жеткілікті мөлшерде жаңа немесе дұрыс әзірленген өсімдік өнімдерін — көкөніс пен жеміс, тамыржемістер, көк шөп, салат, шөптер және өсімдіктің кез келген бөлігін жеу маңызды.\nАнахатаның түстері — жасыл және қызғылт.", "high": "Өзінде негізгі рухани көзқарастарды, моральдық және адамгершілік қағидаларды қалыптастыру.\nАлғыс айта білетін және жауабына бере алатын ашық әрі мейірімді адамдармен араласу.\nБасқаларға көмектесіп, қайырымдылық пен волонтёрлықпен айналысу.\nЖақындарға, табиғатқа және жануарларға қамқорлық жасауға уақыт табу. Табиғатта көбірек болып, оның сыйын пайдаланып қана қоймай, айналадағы кеңістікке күтім жасау.\nСәтсіздік пен жағымсыз нәрсеге емес, бар, шығып жатқан және ұнайтын нәрсеге сүйену. Позитивті ойлау мен алғысты жаттықтыру.\nАнамен үйлесімді қарым-қатынас құрып, байланыс орнатып, оның тәжірибесін қабылдап, түсіну. Мүмкіндігінше жақындармен және отбасымен қарым-қатынасты үйлестіру.\nКлассикалық әдебиет пен өлең оқып, үйлесімді тыныштандыратын музыка (оның ішінде медитация) тыңдау.\nӨмірлік тәжірибе керекті сабақтар беретінін түсініп, қиындықтан шыдамдылықпен — шағымсыз, өзін және басқаларды кінәламай, жағдай құрбаны рөлінсіз өту.\nОбъективтілікке және жағдайға сырттан қарай білуге үйрену. Бұзушы эмоциялар емес, жанашырлық, қабылдау мен ақыл-парасат адамдардың мінез-құлқы мен оқиғаларды дұрыс бағалап, әділ әрі стратегиялық дұрыс шешім қабылдауға көмектеседі. Болашақта бұл көңіл қалу мен өкпеден аулақ болып, дұрыс өзара әрекет құруға көмектеседі.\nӨкпе жинамай, өзгенің ұстанымын қабылдай отырып, кешіруді үйрену. Пайдаланатын немесе зиян келтіретін жағдайлар мен адамдарды босатып, улы ортадан арылу.\nБақыттың, махаббаттың және үйлесімнің көзін өзінен табу, өзгенің бағасы мен мойындауына бағдарланбау және өзін басқалармен салыстырмау. Іште моральдық бағдарлардың орнықты жүйесі болса, кез келген жағдайда төтеп беріп, айналадағыларға ұқыпты қарау оңайырақ.\nӨмірге позитивті көзқарас әдетке айналуы үшін алғысты жаттықтыру, мысалы, алғыс күнделігін жүргізу.\nШығармашылық пен қол еңбегімен айналысып, шама келгенше өз қолымен бірдеңе жасап, тамақ әзірлеу.\nМәселеде — өзіңіздікінде де, өзгенікінде де — қалып қоймай, өзгенің жағымсыз эмоциясымен тұтасып кетпеу.\nҚандай да бір идеяға қатысты фанатизмге кетпей, ішкі икемділікті дамыту.\nӨз жағымсыз эмоциялары мен сезімдерін көбірек бақылап, оларды зерделеу: түсініп, тамырын тауып, емдеу.\nБіреуге немесе бірдеңеге шектен тыс байланып қалудан бас тарту. Өмірдің даналығын, оның еркін ағысын, циклдігін және кейбір оқиғалардың болмай қоймайтынын түсіну жан тыныштығын сақтауға көмектеседі.", "max": "Өзін барлық қасиеті мен кемшілігімен қабылдап, жақсы көруді үйрену.\nМейірімді, қабылдайтын және жан жылы адамдармен көбірек уақыт өткізу.\nЖақындарға, табиғатқа және жануарларға қамқорлық жасауға уақыт табу. Табиғатта көбірек болып, оның сыйын пайдаланып қана қоймай, айналадағы кеңістікке күтім жасау.\nҮй жануарын асырап, оған қамқорлық жасау.\nОбъективтілікке және жағдайға сырттан қарай білуге үйрену. Бұзушы эмоциялар емес, жанашырлық, қабылдау мен ақыл-парасат адамдардың мінез-құлқы мен оқиғаларды дұрыс бағалап, әділ әрі стратегиялық дұрыс шешім қабылдауға көмектеседі. Болашақта бұл көңіл қалу мен өкпеден аулақ болып, дұрыс өзара әрекет құруға көмектеседі.\nҚайырымдылық пен волонтёрлықпен айналысып, басқаларға пайдакүнемсіз көмектесу.\nЖақындармен және отбасымен, әсіресе анамен, әжемен және басқа әйел туыстармен қарым-қатынасты реттеу.\nШығармашылық пен қол еңбегімен айналысып, шама келгенше өз қолымен бірдеңе жасап, тамақ әзірлеу.\nМузыка — табиғат дыбыстары немесе жағымды аспаптық әуендер арқылы көңіл-күйді жақсартып, өз күйін үйлестіру.\nМәселеде — өзіңіздікінде де, өзгенікінде де — қалып қоймай, өзгенің жағымсыз эмоциясымен тұтасып кетпеу.\nӨкпе жинамай, өзгенің ұстанымын қабылдай отырып, кешіруді үйрену. Пайдаланатын немесе зиян келтіретін жағдайлар мен адамдарды босатып, улы ортадан арылу.\nТіпті қиын әрі жағымсыз жағдайлардан да өсудің дәні мен әлеуетін көруді үйреніп, өмірге солар арқылы беретін даналығы мен тәжірибесі үшін алғыс айту.\nҚандай да бір идеяға қатысты фанатизмге кетпей, ішкі икемділікті дамыту.\nӨз жағымсыз эмоциялары мен сезімдерін көбірек бақылап, оларды зерделеу: түсініп, тамырын тауып, емдеу.\nБіреуге немесе бірдеңеге шектен тыс байланып қалудан бас тарту. Өмірдің даналығын, оның еркін ағысын, циклдігін және кейбір оқиғалардың болмай қоймайтынын түсіну жан тыныштығын сақтауға көмектеседі.\nБақыттың, махаббаттың және үйлесімнің көзін өзінен табу, өзгенің бағасы мен мойындауына бағдарланбау және өзін басқалармен салыстырмау. Іште адамгершілік бағдарлардың орнықты жүйесі мен ішкі тірек болса, кез келген жағдайда төтеп беріп, айналадағыларға ұқыпты қарау оңайырақ.\nӘлеуметтік белсенді болып, жүрек жылуын, эмоция мен сезімді беріп, басқаларға өзін табуға, жүрегін естуге және оны босатуға көмектесу."}, "vis": {"low": "Араласу дағдыларын әртүрлі жолмен дамыту, оның ішінде сөйлеу техникасы мен шешендік шеберлік курстарынан өту.\nСезім мен эмоцияны жұмсақ әрі әдепті білдіруді үйрену. Әңгімелесушіге айту қиын болса, ойды қағазға немесе диктофонға жазудан бастауға болады.\nЭмоцияны жинамай, «өз тамағыңды қыспау». Қатты ән айтып, караокеге барып, вокалмен айналысқан пайдалы.\nӨкпені де кешіріп, босатып, шығарып, айтқан маңызды.\nЧакраның жұмысы үшін шетел тілі мен актёрлық шеберлік курстары тамаша келеді.\nШығармашылық серпін мен идеяларды жүзеге асырып, бала кезде армандаған нәрсені істеу маңызды: өлең жазу, сурет салу және т.б.\nТамақтағы қысылуды жою үшін тыныс алу гимнастикасы мен дене практикаларымен айналысу.\nТемекі шегу және эмоцияны «тамақпен басу» әдетінен бас тарту. Тамақтану мінез-құлқында бұзылыс болса, психологқа жүгініп, терапиядан өту.\nШектен шығудан — таңғалдыруға құмарлықтан (эпатаж) немесе өзіне тұйықталудан аулақ болу. Адамдармен араласуда ішкі тепе-теңдік пен үйлесімге келуге тырысу.\nҚоғамда өзін көрсетуге тырысып, көпшілік алдында болудан қашпау. Сөз сөйлеуге, өз өнімін немесе өзін таныстыруға, әлеуметтік желіде сторис жариялауға, рилс түсіруге мүмкіндік болса — қорқынышты жеңіп, мұны істеу. Тек тұрақты практика ғана мазасыздық пен сенімсіздіксіз ашылуға үйретеді.\nӘлсіздігін басқаларға көрсетуден қорықпай, өзін-өзі бағалау мен өзін қабылдаумен жұмыс істеу.\nСөзді қадағалауды үйреніп, басқаларды көбірек тыңдап, балағат сөзді азырақ қолдану немесе тек орынды, екпін үшін қолдану.\nӘңгіме сапасын жақсартып, өзіне сенімділікті арттыру үшін сөздік қорды толықтыру: кітап оқу, қызықты сұхбаттар мен фильмдер көру, шешендер мен ынталандырушылардың подкасттарын тыңдау.\nӨз пікірін — әдепті, орынды және әңгімелесушіні құрметтей отырып — қорғауды үйрену. Дауласу мен келіссөз жүргізу дағдыларын меңгеру.\nРухани дамып, жоғары күштерге, өзіне және оқиғаның жақсы аяқталатынына сенімді өсіру. Ішкі адамгершілік және моральдық қағидаларды қалыптастырып, солармен өмір сүру.\nЖағымсыз эмоциялармен — ашумен, ызамен, өкпемен — олар тек адам өзі жол бергенде ғана пайда болатынын түсіне отырып жұмыс істеу. Көбіне денсаулық мәселелері дәл жағымсыз ойлардан басталады. Вишудханы үйлестіре отырып, адам бұл байланысты байқауға және оған әсер етуге үйренеді.\nТастар: аквамарин, лазурит, көгілдір тас (бирюза), көкшіл агат, топаз, сапфир, інжу, содалит, амазонит, кианит, хризоколла.\nХош иістер: эвкалипт, камфора, шалфей, бұрыш жалбызы, лаванда, пачули.\nТүстер: көгілдір және көкшіл-жасыл (бирюзовый).\nТамақтану: жемістер мен жидектер.", "high": "Тамаша араласу дағдыларын әртүрлі жолмен міндетті түрде қолданып, оларды үнемі жетілдіру, оның ішінде сөйлеу техникасы мен шешендік өнер курстарында.\nСезім мен эмоцияны жұмсақ әрі әдепті білдіруді үйрену. Әңгімелесушіге айту қиын болса, ойды қағазға немесе диктофонға жазудан бастауға болады.\nӨз шекарасын міндетті түрде сөзбен — түсінікті тілмен және өткір емес түрде белгілеу. Сөздің тазалығын, интонация мен әзілді қадағалап, олардың орындылығын түсініп, цинизм мен кекесіннен аулақ болып, өзгенің шекарасын да құрметтеу.\nДауда қарсыласқа сөйлеуге мүмкіндік беріп, оның пікіріне үңіліп, талдау. Эмоция қайнап, айқайлағыңыз немесе өткір айтқыңыз келсе — терең дем алып, онға дейін санап немесе тынышталудың басқа тәсілдерін пайдалану.\nЭмоция мен сезімді дауыстап әнге қосып, караокеге барып, әншілікпен айналысқан пайдалы.\nКүліп, стендапқа барып, өзін-өзі мазақ ете отырып басқаларды күлдіретін, жай ғана өзіңіз бола алатын мұндай іс-шараларға өзіңіз қатысып көру.\nЧакраның энергиясын жүзеге асыру үшін шетел тілі мен актёрлық шеберлік курстары тамаша келеді.\nШығармашылық қабілет пен шабытты пайдалану: идея туғызып, түйсікке сеніп, өзіңіз үшін де, адамдар үшін де өзіндікін жасау.\nӨлең мен кітап жазып, сурет салып, тіпті кәдімгі үй жұмысын да өзіңізше, тапқырлықпен істеу.\nТамақтағы қысылуды жою үшін тыныс алу гимнастикасы мен дене практикаларымен айналысып, тынышталудың әртүрлі тәсілдерін қолдану.\nӨзі оқып, басқаларды да оқытып, тәлімгер болып, қолдау — коучинг пен психология тамаша келеді.\nДостармен жылы ортада кездесіп, әңгіме мен араласуға уақыт бөлу.\nКөбірек сөйлеп, үндемей қалмай, өз пікірін осында және қазір — бірақ әдепті айту.\nТемекі шегу және эмоцияны «тамақпен басу» әдетінен бас тарту. Тамақтану мінез-құлқында бұзылыс болса, психологқа жүгініп, терапиядан өту.\nШектен шығудан — таңғалдыруға құмарлықтан (эпатаж) немесе өзіне тұйықталудан аулақ болу. Адамдармен араласуда ішкі тепе-теңдік пен үйлесімге келуге тырысу.\nҚоғамда өзін көрсетіп, қабілеттері мен дағдыларын міндетті түрде көрсету: сөз сөйлеу, өз өнімін немесе өзін таныстыру, әлеуметтік желіде сторис жариялау, рилс түсіру.\nСөзді қадағалауды үйреніп, басқаларды көбірек тыңдап, балағат сөзді азырақ қолдану немесе тек орынды, екпін үшін қолдану.\nРухани дамып, жоғары күштерге, өзіне және оқиғаның жақсы барысына сенімді өсіру. Ішкі адамгершілік және моральдық қағидаларды қалыптастырып, солармен өмір сүру."}, "adj": {"low": "Ой-өріс пен ойлауды кеңейтіп, қалыптан шығып, ауқымды ойлауды жаттықтыру.\nТүйсікті тыңдап, санасыздықпен жұмыс істейтін практикаларды орындап, ішкі дауысқа сену.\nКезең-кезеңімен жылжып, көп мақсатқа шашырамау үшін стратегия әзірлеуді және жоспарлауды үйрену.\nРухани саналылық пен рухани ерікті дамыту. Әлем заңдарын зерттеп, оларды бұзбай, саналы әрекет етіп, ойлана отырып өмір құру.\nӨз ойын, сезімі мен эмоциясын талдай бастау — бұл өмірдегі әртүрлі жағдайлардың неге және не үшін болатынын түсінуге көмектеседі.\nЖаңа білім ала отырып, ақыл мен талдау қабілетін дамыту: ми шабуылына қатысып, кітап оқып, ойлауды үнемі кеңейту. Интеллектуалдық қабілеттерді ашып, күшейтуге басқатырғыштар, сөзжұмбақтар, жұмбақтар мен квесттер көмектеседі.\nСыртқы оқиғалар мен ішкі күйді бақылау. Ақпаратты түсіріп, талдау үшін күнделік немесе жоспарлағыш жүргізу.\nБілім алып, оқуға деген ниетті дамыту, өмірдің әртүрлі сұрақтарына жауап табу, тіл үйрену.\nЖазушылық пен шығармашылық дағдылар арқылы қиял мен елестетуді дамыту.\nИдея келгенде, оны ұзақ жәшікке салмай, жүзеге асыруға практикалық қадамдар жасау.\nЗейінділікті, бөлшекті байқай білуді және шоғырлануды дамыту.\nТастар: лазурит, көк авантюрин, аметист, сапфир, флюорит, содалит, кианит.\nХош иістер: лемонграсс, шегіргүл, жасмин, жалбыз, ладан, самырсын, кипарис, шырша мен қарағай, мускат жаңғағы, мирт.\nТүстер: көк және қою көк.\nТамақтану: ораза, көк түсті жидектер, оның ішінде қаражидек (черника) пен көкжидек (голубика).", "high": "Түйсікті тыңдап, санасыздықпен жұмыс істейтін практикаларды орындап, ішкі дауысқа сену.\nРухани саналылық пен рухани ерікті дамыту. Әлем заңдарын зерттеп, оларды бұзбай, саналы әрекет етіп, ойлана отырып өмір құру.\nИнтеллектуалдық қабілеттерді міндетті түрде қолдану: ми шабуылына қатысу, кітап оқу, басқатырғыш, сөзжұмбақ пен жұмбақ шешу, квесттерден өту, есте сақтауды жаттықтыру.\nЗерттеумен және ғылыми қызметпен айналысып, жинақтау мен талдауды зерттеу.\nСыртқы оқиғалар мен ішкі күйді бақылау. Ақпаратты түсіріп, талдау үшін күнделік немесе жоспарлағыш жүргізу. Күн сайын бастан жабысқақ ойлар мен логикалық тізбектерді «түсіріп», оларды идеяға айналдырып, жүзеге асыру қадамдарын жазу.\nОй, идея мен пайымдаумен алмасып, пікірсайысқа қатысып, міндеттерді бірге шешуге болатындай орта құру.\nҚабілеттерді жазушылық пен оқытуда жүзеге асырып, өз идеяларын жылжытып, білім беріп, тәлімгерлікте өзін байқап көру.\nПозитивті ойлауды жаттықтырып, жақсы оқиғалар мен әсерлерді байқау.\nНазарды денеге аудара отырып, медитация, дене практикалары мен спорт арқылы ақылға тынышталуға мүмкіндік беру.\nОй ағынын тоқтататын және «ой шайнағышты» азайтатын практикаларды қолдану.\nӘртүрлі халықтардың діндерін, философия мен психологияны зерттей отырып, рухани даму."}}, "mul": {"low": "### Чакраның сыйымдылығы қалыптан төмен\nТуғаннан мұндай көрсеткіштері бар адамның өмірлік энергия қоры аз және көбіне иммунитеті әлсіз. Көбіне оған негізділік, салмақты шешім қабылдау және мақсатқа тұрақты жылжу жетпейді. Тез шаршау — тіпті кәдімгі үй жұмысынан да, — жалқаулық пен шыдамсыздық та кедергі келтіруі мүмкін.\nОған шоғырлану, ұсақ-түйек пен нәзік тұстарды байқау қиын. Шешім қабылдаған соң, нәтижеге дейінгі барлық кезеңнен өтіп, жүйелі әрі жоспармен әрекет ету қиын. Бастағанын жарты жолда немесе тіпті басында, әсіресе алғашқы сәтсіздіктен кейін тастау әдеті бар.\nЖақсы жағында адам түйсікпен ішкі ресурсын көбейтуге ұмтылады: салауатты өмір салтын ұстанып, денелік те, әлеуметтік те белсенділік танытады. Ол қозғалыс керек екенін сезіп, оны күн тәртібіне қосады. Энергия деңгейін көтеріп, иммунитетті нығайтып, дербестеу әрі жауаптырақ болып, шешім қабылдауды үйренуге тырысады.\nОнда түйсікпен өз руы туралы көбірек білгісі келеді. Бұл чакраны белсендіру үшін бұл ниетті нақты қадамға айналдыру маңызды: ата-бабалар туралы мәлімет жинап, жазып, отбасылық альбом жүргізу немесе шежіре ағашын құру. Осылай энергия тамырмен байланыс арқылы нығаяды.\n### Муладхараның сыйымдылығы төмен болғандағы күшті жақтар\nМұндай адамдар бөлшекте қалып қоймай, бәрін өзіне артпай біледі. Олар жұмыс процестерін үйлестіргенде, басқаларды бақылағанда және міндеттерді бөлгенде өзін тамаша көрсетеді. Олар әлсіз жерлерді көріп, әрекетті оңтайландыра отырып, күш салудың ең жақсы жолдарын табады.\nЭнергияның жетіспеуін сезіне отырып, адам дауды арандатпайды және одан қашады, қауіпті инстинктпен сезеді. Ол қасарысып алға баспай, алдымен бақылап, содан кейін ғана шешім қабылдайды. Алайда оған арсыз әрі дөрекі адамдарға тойтарыс беруге шешімділік жетпейді.\n### Әлсіз жағы\nАдамға дене жүктемесі мен үнемі белсенділік — тек ұзақ жүру немесе баспалдақпен көтерілу ғана емес, тұрмыстық істер де ауыр келеді. Сондықтан шиеленіс пен шаршау дене деңгейінде де, эмоция деңгейінде де өсіп, апатия мен жаман көңіл-күйге әкеледі.\nОл тез шаршайды, демалып, күш жинағысы келеді, төзімділігі төмен.\nМұндай адамдар күш пен агрессия көрінісінен — өзінікінен де, өзгенікінен де — қорқады және оларды өзіне барынша тыйады. Көбіне оларға қашып, тығылып, көрінбей қалғысы келеді.\nАқшаның жетіспеуі, нашар тұрғын үй жағдайы, базалық қажеттіліктерді қамтамасыз етудегі қиындықтар болуы мүмкін. Бұл мазасыздық пен көңілсіздікті күшейтеді. Өз мәселелері мен сәтсіздігіне мұндай адам өзінен басқа кез келген адамды кінәлайды.\nҚиын жағдайдан шығуға қорқыныш, жалқаулық, өзіне және күшіне сенбеу, айналадағылардың мақұлдауын алмай, бірдеңені өз бетінше бастаудан және ерекшеленуден қорқу кедергі келтіреді.\nЖаңадан қорқу мен өзгеріске құлықсыздық қиындық қосады. Мұндай адамдар өткенмен өмір сүруге және істеген немесе істемеген нәрсеге өкінуге бейім. Олар көбіне өкпені ұзақ жинап, ескірген нәрсенің бәрін ұстап, естеліктермен өмір сүріп, енді нәтиже де, қуаныш та әкелмейтін нәрсеге — жоғалтудан (жұмысты, әдетті, тұрғылықты жерді, адамдарды) қорыққандықтан жабысады.\nДәл осы қорқыныш адамды консервативті етеді: оған жұмысын немесе іс түрін ауыстыру қиын, ол бір бағытпен жүріп, бір стратегияны ұстанады.\nӘлсіз жағында адам энергияны үнемдегендей: көбіне әрекетсіз жүріп, дене белсенділігі мен спорттан қашады. Ол шешім қабылдамай, батылдық пен дербестік көрсетпей, бәрі өзінен-өзі болады немесе реттеледі, не біреу келіп, бәрін ол үшін істейді деп үнемі үміттенеді. Күтпеген қиындықта абдырап, жағдайды жеңе алатынына сенбейді. Оған негізділік пен энергия жетпейді, сондықтан істі соңына дейін жеткізу қиын.\nРудағы үлкендермен — ата-анамен және туыстармен қиындықтар мен дау болуы мүмкін. Адам үнемі «қорғаныста» болып, басқалардың мінез-құлқын арандату немесе шабуыл деп қабылдайды. Сондықтан мұндай адамдар көбіне өзіне әртүрлі жағымсыз жағдайларды тартады, олар оларды есейіп, өмірлік ұстанымын өзгертуге мәжбүрлейді.", "norm": "### Чакраның сыйымдылығы қалыпты\nМуладхарасының мұндай сыйымдылығы бар адамның денсаулығы жақсы, иммунитеті мықты және ішкі энергия қоры бар.\nОл өзгерісті оңай қабылдайды, жаңадан қорықпайды, саяхат пен белсенді өмір салтын жақсы көреді.\nМұндай тұлғаның күші — өзіне сенімділікте, өзіне сенуде және сау өзін-өзі бағалауда. Ол өзін, шынайы тілектері мен қажеттіліктерін түсінеді. Мақсатты дұрыс қойып, оған жетудің жолын әрдайым таба білу қалағанын алуға көмектеседі.\nМұндай адамдарда бәрі шамасында: артық асығыссыз белсенділік, шектен тыс баяулықсыз шыдамдылық, адамдардан алыстамай және оларға сенімсіздіксіз дербестік.\nБұлар — байлайтын қорқыныш пен ішкі шектеусіз энергиялы, іскер адамдар. Олар қолайсыздықты еш қиындықсыз жеңіп, өзгеріске сабырмен қарайды.\nОлар ұзақ жаман көңіл-күйде болуды, өткенмен немесе болашақпен өмір сүруді ұнатпайды. Осы сәтте болып, ауыр тиетін және ескірген нәрсенің бәрінен — істен, заттан, байланыстан, адамдардан бас тарта алады.\nАдам өмір жолындағы мәселе мен қиындықты жеңуге қабілетті. Даулы жағдайда ол абдырамай, өзін сенімді сезінеді, тепе-теңдікті сақтап, салмақты шешім қабылдайды.\nБұл чакраның үйлесімді жұмысы рухты, дене және психологиялық төзімділікті қолдап, нығайтады, ынта мен табанды, ұзақ күш салу қабілетін туғызады. Мұндай сыйымдылық өмірге ерік береді және даралықты өзгенің пікірінен, айла-шарғыдан және басқа ықпалдан қорғайды.\nМұндай көрсеткіші бар адам өз денесін жақсы көреді, оның қалай құрылғанын түсінеді және оның барлық көрінісіне сабырмен қарайды. Ол басқа адамдардың денесіне құрметпен қарап, олардың шекарасын сақтайды.\nОл жермен және тірі табиғатпен байланысты сезінеді және сөздің жақсы мағынасында өзін жерге байланған сезінеді. Ол қызығушылық пен сау әуесқойлыққа толы, әлемді және өзін зерттегісі келеді. Ол өмірді бағалайды.\nСенімділік сезімі оны өмірге қажетті базалық қажеттіліктер туралы алаңдаушылықтан босатады: ол әлемде керектің бәрі бар және мұның бәрі оған қолжетімді екенін сезінеді.\n### Табиғи энергия пайдаланылмаса\nАдам жүктемеден, дене және ой белсенділігінен қашып, энергияны оған жол бермей жинаса, чакра әлсіз жағынан көрінуі мүмкін.\nСонда тамақты қорыту мен қоректік заттардың сіңуінде қиындықтар болуы мүмкін, сондықтан иммунитет төмендеп, жалпы хал нашарлайды. Әлсіздік, жалқаулық пен апатия тұрақты серікке айналады. Сүйек және бұлшықет жүйесі зардап шегіп, ішектің жұмысы бұзылуы мүмкін.\nОй деңгейінде адам өзіне сенімін жоғалтып, оған әртүрлі қорқыныш пен жүйке шиеленісі пайда болады. Ол белгісіздікте, аяқ астында берік жер мен базалық тіреу жоқ, ілініп тұрған күйде өмір сүреді. Энергия әлеуеті жүзеге аспаса, адам жағымсыз күйге оңай кетіп, кішкене себепке бола уайымдайды, ал оны жаман жаңалық, өсек, өз қорқынышы, мәселелер мен қиындықтар тепе-теңдіктен шығаруы мүмкін.", "high": "### Чакраның сыйымдылығы қалыптан жоғары\nЧакраның мұндай сыйымдылығы әдетте адамға мықты иммунитет береді және сыртқы қолайсыз факторларды — бактериялар мен вирустардан стресске дейін оңай жеңуге көмектеседі.\nАдам фанатизмсіз, бірақ күн тәртібі мен дұрыс тамақтануға мұқият қарайды. Ол бәрінде тепе-теңдікті сақтайды: дене белсенділігімен оңай әрі қуана айналысады, бірақ сонымен бірге керек кезде ұқыптылық, зейінділік пен шыдамдылыққа ие.\nОл табиғатпен және жермен байланысты сезінеді — ол туралы сөздің жақсы мағынасында жерге байланған деп айтуға болады. Ол өмірді бағалайды.\nМуладхарасының мұндай сыйымдылығы бар адамда өзіне және өз күшіне сенімділік бар. Оны екпінділік және дау мен дағдарыс жағдайынан сауатты әрі тиімді шыға білу ерекшелейді.\nОл өмірінің негіздеріне — тамаққа, баспанаға, қауіпсіздікке, жайлылыққа ақылмен қамқорлық жасайды. Ол әлемге шынайы қарайды, бейімділігінде негізді, салмақты шешім қабылдап, әрдайым мақсатқа жүреді. Оны дербестік, нәтижелілік және бастағанды әрдайым соңына дейін жеткізу әдеті ерекшелейді.\nМұндай адам өзіне, өмірге және адамдарға сенеді. Ол батыл әрі табанды, тәртіпті, ретті және ережені ұстануды жақсы көреді. Белсенді әрекет етеді және нақты жоспар құрып, алгоритмді түсінген бойда бірден бастағанды қалайды. Істі ұзаққа кейінге қалдырғанды ұнатпайды.\nБірінші чакра тепе-теңдікте болғанда, адам сабырлы әрі өзіне сенімді. Өмірде мұндай адамдар байыпты әрі прагматик, «қиялға берілмейді» және елес құрмайды. Бұлар — нақтылықты жақсы көретін, табандылығымен, байыптылығымен және жүйелілігімен ерекшеленетін сенімді әрі практикалық адамдар.\nМұндай сыйымдылық өмірге ерік береді және даралықты өзгенің пікірінен, айла-шарғыдан және басқа ықпалдан қорғайды. Өз өмірін өз бетінше құру қажеттілігі пайда болады.\nЖақсы сыйымдылықтың арқасында өз денесіне деген махаббат және өз шекарасын түсіну көрінеді. Басқа адамдардың шекарасына да құрмет бар.\nАдам түйсікпен өз қажеттіліктерін түсініп, соларды ұстанады. Көбіне мұндай адамдар бұл энергияны жүзеге асыра отырып, кәсіби спортпен айналысады, бұл оларға қатты көмектеседі. Олар қиындықтан қорықпайды және күрделі жағдайда бас имейді. Лайықты тойтарыс бере алады, бірақ сонымен бірге зұлымдық пен өкпе жинамайды, араздық пен дауды ұнатпайды. Өмірде адамдарға, ескірген қарым-қатынас пен істерге жабыспай, дербес жүреді.\nОлар үлкендерді құрметтеп, туыстармен жақсы қарым-қатынас сақтайды, оларға махаббатпен және қамқорлықпен қарайды, туыстық байланысты бағалап, отбасын мақтан тұтады.\nМұндай адамдар бірдеңе жасап, өз кеңістігін жайластырғанды жақсы көреді, тәртіпті бағалап, дәстүрді ұстанады.\nТырысқақтық, шыдамдылық пен ұқыптылықтың арқасында олар мұқият әрі күнделікті бір сарынды жұмысты орындай алады. Іс пен қарым-қатынаста олар байыпты, сенімді әрі тұрақты.\nОлар ұйымдасқан әрі негізді, өз стратегияларын құрып, мақсатқа апаратын қадамдарды ойластырады.\n### Әлсіз жағы\nТабиғи әлеует күшті болса, бірақ жүзеге аспаса және тепе-теңдікте сақталмаса, денсаулық мәселелері болуы мүмкін. Иммундық жүйе жүктемені жеңе алмауы мүмкін. Көбіне толуға да, шектен тыс арықтыққа да әкелетін салмақтың бұзылуы мен гормондық ақаулар пайда болады.\nАдам спортпен айналыспаса, енжар болса және энергиясын пайдаланбаса, ол ағзада тоқырап қалады — сылбырлық пен нашар хал осыдан. Немесе керісінше: шиеленіс пен энергияның артықтығы тәуекелге күшті құмарлық туғызады. Адам экстремалды спортқа беріліп немесе шектен тыс агрессия мен дауға бейімділік көрсетіп, төбелеске араласып, кез келген мәселені күшпен шешеді.\nАгрессия айналадағыларға да, өзіне де бағытталуы мүмкін. Көбіне адам тұрақсыз, шыдамсыз, бөлшекке үңілгенді ұнатпайды және адамдарға, нәзік тұстар мен ұсақ-түйекке мұқият емес. Айналадағылар мұны үстірттік, байыпсыздық пен шектен тыс әбігершілдік деп қабылдайды.\nМұндай адам айналадағыларға қысым жасап, тек өз мақсатын көріп, қасарысып, ештеңеге қарамай, жолындағының бәрін сыпырып тастайды.\nМатериалдыққа шектен тыс алаңдаушылық болуы мүмкін — сонда өмірдің мақсаты рухани дамусыз тек өз қажеттілігін қанағаттандыру болып қалады. Мұндай адамдар озбырлық пен қатаңдыққа бейім, айналадағыларға шектен тыс жабысып, қысым жасайды.\nОлар бар нәрсесін жоғалтудан қорыққандықтан, көбіне қорқыныш пен мазасыздыққа, сараңдық пен қызғанышқа бейім.", "max": "### Чакраның сыйымдылығы жоғары\nТабиғат бұл чакраға ең көп энергия береді. Адам тамаша дене пішінінде, оның иммунитеті қуатты, сүйегі мықты, тамырлары сау. Ол төзімділігімен, табандылығымен, шыдамдылығымен және өзгеріс пен жаңа жағдайға оңай бейімделе білуімен мақтана алады.\nОл орнықтылық, тұрақтылық және айналадағы кеңістікті ұйымдастырып, ретке келтіре білу қабілетінің арқасында өз тағдырын өзі құрады.\nКедергілер жеңіледі, ал жүктеме қатты шиеленіссіз көтеріледі, өйткені ағза бәрін тамаша жеңеді. Адам әлемге және өмірге сенімді. Бұл сенімділік оны базалық қажеттіліктер туралы алаңдаушылықтан босатады: ол әлемде өзіне керектің бәрі бар екенін сезінеді.\nМұндай энергияның белсенді әрі позитивті ойлайтын иесі шектейтін қорқыныштан және жалған күмәннан бос. Ол сыртқы әлемнің оқиғаларына сабырмен қарап, адамдарға ниеті түзу.\nАяқта берік тұрып, базалық қажеттіліктерге қамқорлық жасай білу оған аман қалу мен қиындықты жеңудің тамаша әлеуетін береді. Оны өмірге практикалық көзқарас, сәл тұрмыстылық, тамаша өзін ұстау және кез келген жағдайда тепе-теңдікті сақтай білу ерекшелейді. Сонымен бірге ол жаңадан және белгісізден қорықпайды және өміріне жақсы өзгерістерді оңай кіргізеді.\nӨмірге және өзіне сене отырып, табандылық, тәртіп пен ретке деген сүйіспеншілік арқасында ол істі соңына дейін жеткізіп, әрдайым табысқа жетеді. Әдетте оның туыстарымен қарым-қатынасы жақсы, ол қамқорлықты қабылдай біледі және ру мүшелерін қолдап, үлкендерді құрметтейді.\nОның әр әрекетін сенімділік пен негізділік ерекшелейді. Бұлар — шындықта барынша өмір сүретін, басқаларды соңынан ерте алатын белсенді іс адамдары. Сонымен бірге олар өз ұстанымын бөліспейтіндерге жабыспайды, өткенмен өмір сүрмейді және өзін ақтамайтын немесе тиімсіз нәрсені ұстамайды.\nМұндай сыйымдылық өмірге ерік береді және даралықты өзгенің пікірінен, айла-шарғыдан және басқа ықпалдан қорғайды.\nЖақсы сыйымдылықтың арқасында өз денесіне деген махаббат және өз шекарасын түсіну көрінеді. Ол басқа адамдардың шекарасына да дәл солай ұқыпты қарайды.\nОл жермен және тірі табиғатпен терең байланысты сезінеді және сөздің жақсы мағынасында өзін жерге байланған сезінеді. Оған әлемді зерттегісі келеді, ол өмірді бағалайды.\n### Әлсіз жағы\nМұндай күшті табиғи әлеует жүзеге аспаса және тепе-теңдікте сақталмаса, мәселелер туындауы мүмкін. Адам дене белсенділігінен қашып, спортпен айналыспаса және саяхаттамаса, чакра қауіп астында болады — оның аймағында жарақаттар мен аурулар болуы мүмкін. Көбіне толуға да, шектен тыс арықтыққа да әкелетін салмақтың бұзылуы мен гормондық ақаулар пайда болады.\nАдам материалдыққа шектен тыс байланып, қарапайым инстинкттермен және тек базалық қажеттіліктерін қанағаттандырумен өмір сүреді. Ол рухани дамымайды, бәріне сенбейді және екпінмен әрекет етеді. Табыс тауып, жинап, мақсатына ұмтыла отырып, ол біреудің басын басып өтіп, дауға бейімділік пен агрессиялы ықпал әдістерін көрсетуі мүмкін.\nАртық жерге байланушылық адамды консервативті етеді: оған жұмысын немесе іс түрін ауыстыру ауыр.\nАуырлық, салмақтылық — шын мәнінде денеде де, эмоциялық күйде де пайда болуы мүмкін. Ол орнынан қозғалып, өзгеріске бел буғызбайды, ал адам, тіпті жайсыз болса да, бір орынға, адамға, әдетке және тұрмысқа жабысып қалады.\nЧакраның энергиясы пайдаланылмаса, ол ағзада тоқырап қалады — сылбырлық пен нашар хал осыдан. Немесе керісінше: шиеленіс пен энергияның артықтығы тәуекелге күшті құмарлық береді — экстремалды спорт, шектен тыс агрессия, дауға бейімділік, төбелеске араласуға және кез келген мәселені күшпен шешуге дайындық.\nАгрессия айналадағыларға да, өзіне де бағытталуы мүмкін.\nМұндай адам басқаларға қысым жасап, тек өз мақсатын көріп, қасарысып, ештеңеге қарамай, жолындағының бәрін сыпырып тастайды.\nОл жұмысқа шектен тыс беріліп, шаршағанын байқамай, өзін шамадан тыс жүктеп, энергияны толық сарқылғанша жұмсап, өзін шаршап-шалдығуға жеткізуі мүмкін.\nМұндай адамдар озбырлық пен қатаңдыққа бейім, айналадағыларға шектен тыс жабысып, қысым жасайды.\nОлар бар нәрсесін жоғалтудан қорыққандықтан, көбіне қорқыныш пен мазасыздыққа, сараңдық пен қызғанышқа бейім."}, "sva": {"low": "### Чакраның сыйымдылығы қалыптан төмен\nСвадхистана әлсіз болса, адам өз ішкі тілегін, өз «Менінің» және денесінің қажеттіліктерін естуді білмейді. Ол өзіне сенбейтін сияқты, өзін кемсітіп, босаңсуды білмейді және өзі үшін бірдеңе істегенде кінә сезінеді. Ол өзіне ләззат алуға, рахаттануға және уақытты жеңіл әрі жағымды өткізуге тыйым салатын сияқты.\nОл бір жаман нәрсе болады деп шиеленісті күтумен өмір сүруі мүмкін. Немесе керісінше — сезімі мен ақылы «жетер» дегенде де тоқтай алмайды (мысалы, тойса да жей береді). Осыдан күшті тәуелділіктер мен зиянды әдеттер пайда болады.\nСыйымдылық төмен болса, интимдік салада қиындықтар пайда болады. Әдетте бұл шеткі жағдайлар: қатты қысылу мен қарсы жыныспен жақындықты қабылдамаудан бастап әдейі арандатушы мінез-құлық пен ашық сексуалдылыққа дейін. Адам өзін және денесін жақсы көрмейді, өзіне және айналадағыларға сыншыл, сондықтан жақындық ұят нәрсе ретінде қабылданады.\nБала көтерудегі қиындықтардың ықтималдығы жоғары. Әйелдерде баланы сақтау мен босануда қиындықтар болуы мүмкін, кесар тілігі мен шала туу тәуекелі бар. Өзін-өзі бағалаудың төмендігі қалыпты қарым-қатынас құруға кедергі келтіріп, не жалғыздыққа, не таңдамаушылыққа итермелейді.\nБұл көбіне бірге тәуелді қарым-қатынас тәуекелін туғызады: адам назар қалайды, жағуға және бейімделуге тырысады, бірақ нәтижесінде жақсы қарым-қатынасқа лайық емес екеніне одан да қатты сенеді.\nӘлсіз чакра ауыр қызғанышпен, даумен, ашуланшақтықпен, өмірге түнерген көзқараспен, құрбан позициясымен және сенімсіздікпен көрінуі мүмкін.\nӘйел жағындағы туыстармен, әсіресе анамен қиындықтар болуы мүмкін: не туыстық қарым-қатынастан бас тарту, үзілу мен өткір дау, не тәуелділік және бөлініп, ересек, дербес адам бола алмау.\nМұндай адамдар көбіне еркелете және құштарлықты білдіре алмайды. Олар бала қаламауы немесе ата-аналық инстинкті әлсіреген, бұзылған болуы мүмкін. Отбасылық байланыстар ауыр тиюі мүмкін, ру дәстүрін сақтап, өз отбасын құруға ниет болмауы мүмкін. Қарым-қатынасқа көзқарас қатты бұрмаланған, ерекше және қоғамда қабылданғаннан күрт өзгеше болады.\nСвадхистананың сыйымдылығы төмен болса, адам шығармашылық әлеуетін ашуға энергия мен серпінді сезінбейді. Ол ерекшеленуден қорқады, бұл табыс пен қаржылық әл-ауқатқа кедергі келтіреді. Өз тілегін, эмоциясы мен қажеттілігін білдіру оған қиын.\n### Свадхистананың сыйымдылығы төмен болғандағы күшті жақтар\nТөмен сыйымдылық балаларға, оларды көргісі келуге немесе тек солардың мүддесімен өмір сүруге байланып қалуға мүмкіндік бермейді. Мұндай адам отбасының негіздері мен құндылықтарын құрметтейді, бірақ отбасын жалғыз мақсат етпейді және серіктес таңдауға ойланып қарайды.\nОның отбасында әркімнің өз кеңістігі бар, балалар сенімді, күшті әрі тәуелсіз болып өседі, бәрінде таңдау еркіндігі бар. Чакраның энергиясын толтыруға түйсікпен ниет — шығармашылық пен өзін жүзеге асыруға құштарлық пайда болады. Адам өзіне жағымды нәрседен бас тартпайды: спаға барып, себепсіз өзін дәмді тағам мен әдемі заттармен қуантып, уақытты қызықты өткізіп, жұмсалған уақыт пен ақшаға кінә немесе ұят сезінбей өкінбейді. Ол өзіне қуана күтім жасап, табиғи сыртқы келбетін қабылдап, артықшылықтарын алға шығарады.\nЖұмыс пен демалыстың тепе-теңдігін сақтап, ләззат алудың сау тәсілдерін таңдай білу тәуелділіксіз өмір сүруге мүмкіндік береді.", "norm": "### Чакраның сыйымдылығы қалыпты\nҚалыпты сыйымдылық үйлесімді отбасылық өмірге және кез келген түрдегі — жақындармен, қарсы жыныспен, жұмыста — жақсы қарым-қатынасқа тамаша әлеует береді.\nБұл — шығармашылық даму мен жасырын қабілеттерді ашуға жақсы көрсеткіш. Мұндай адам жасауға, өз энергиясы мен позитивімен бөлісуге, басқаларды — жұмсақ, екпінсіз және қысымсыз — қуаттап, шабыттандыруға ұмтылады.\nАдамдармен қарым-қатынас қабылдау мен өзара құрметке құрылады. Адам сүйкімділігімен, сабырлы сенімділігімен және өзін-өзі сыйлауымен ерекшеленеді.\nСезімталдық, сүйкімділік, орнықты өзін-өзі бағалау және өзін ұсына білу қарсы жынысты тартады.\nМұндай адамдарды жақсы талғам, өмірге деген махаббат және дұрыс орта жасай білу ерекшелейді. Олар өз тілектеріне құлақ асып, артық өзімшілдіксіз дене мен жанның қажеттілігін ұстанады. Әр сәттен ләззат алып, тіпті ұсақ-түйекке де қуана біледі. Өзін қандай болса, солай қабылдайды. Өзіне жағымды нәрсеге: сапалы зат пен тамаққа, жақсы ортаға, қызықты бос уақытқа рұқсат береді. Бәрін тек балаға немесе тек үйге жұмсамай, кінә сезімінсіз өзіне және қажеттіліктеріне ақшаны қуана салады. Сонымен бірге ақша оларға қалай оңай кетсе, солай оңай келеді.\nМұндай адамға адамдар тартылады, оның үйлесімді қарым-қатынасы мен жемісті араласуы қалыптасады. Әдетте ол үйде жайлылық пен ыңғайлылық жасай біледі, ашық, әзілді түсінеді, жақындарына қамқорлық жасайды, бірақ оларды шектен тыс қамқорлықпен тұншықтырмай, өздері болуға мүмкіндік береді.\nОған өмірдің барлық саласын тепе-теңдікте ұстау тамаша шығады: отбасына толық сіңіп, құрбан болмай және жұмысқа шектен тыс берілген адамға айналмай, бірақ сонымен бірге әлеуетін ашып, қоғамда өсу. Ол өмірге және тіпті ұсақ-түйекке қуанады, ал жағымсыз жағдайды керекті тәжірибе ретінде қабылдайды.\n### Әлсіз жағы\nСеріктеспен дау, опасыздық, жүктілікті үзу, өз тілегінен бас тарту, балалық және жастық шақтағы ауыр оқиғалар энергияның ағысын бұзуы мүмкін.\nСондықтан өзін-өзі бағалау төмендеп, өзіне сенімсіздік, кінә мен ұят сезімі пайда болуы мүмкін. Денсаулық жағынан несеп-жыныс жүйесі мен бала көтеру қызметінде шамалы бұзылыстар болуы мүмкін.\nЧакраның жұмысын қалпына келтіру үшін оны үйлестіру тәсілдерін қолдану керек.", "high": "### Чакраның сыйымдылығы қалыптан жоғары\nМұндай адам — айналадағылар үшін позитивті энергияның көзі. Ол бәрімен оңай ортақ тіл табады, байланысқыш, араласуға, өзара әрекетке және жақын қарым-қатынасқа ашық.\nОған отбасын құрып, бала көру маңызды, ол үшін үй жайлылығы көп нәрсені білдіреді.\nОл жұмсақ сенімділіктің, табиғи магнетизм мен сүйкімділіктің арқасында қарсы жыныс арасында табысқа ие, көзқарас пен назарды тартады. Адамдармен қарым-қатынас қабылдау мен өзара құрметке құрылады. Сезімталдық, өзін ұсына білу және стиль сезімі айналадағыларды тартады. Мұндай адамдар жанасуды, құшақтауды, денелік байланысты жақсы көреді және өте сезімтал.\nТуыстарымен шынымен жақын қарым-қатынаста, отбасылық дәстүр мен құндылықтарды құрметтейді.\nМұндай адам агрессия мен дауға бейім емес — керісінше, басқаларға қайшылықты шешіп, одан дипломатиялық, шиеленіссіз шығуға көмектеседі. Бұған адамдар мен жағдайды нәзік сезіне білу көмектеседі. Онымен араласу байлайтын шеңберсіз, ыңғайсыздық пен қолайсыздықсыз достық әрі позитивті атмосферада өтеді.\nМұндай сыйымдылығы бар адамдар үйде жайлылық пен ыңғайлылық жасай біледі. Олар ашық, әзілді түсінеді, жақындарына қамқорлық жасайды, бірақ оларды шектен тыс қамқорлықпен тұншықтырмай, өздері болуға мүмкіндік береді.\nОларда сыйлық пен ақшаны «тарту» сыйы болуы мүмкін. Айналадағылар олардың рахаттана білуіне, жеңіл өмір сүруіне, жақындарына назар мен нәзіктік сыйлауына, басқаларды кемсітпей өзін жақсы көріп, өзіне қамқорлық жасай білуіне шын тәнті болады.\nОлар үйі мен отбасын жақсы көреді, бірақ сонымен бірге көбіне ләззат, өзгеріс, жарқын сезім мен жаңа энергия іздейді, көп саяхаттауы мүмкін. Оларға үлкен шулы ортада да, сүйікті адамымен оңаша да жақсы. Өмірдегі көп нәрсеге шығармашылықпен қарайды, идеяны жүзеге асырып, өзін көрсете алады. Жасанды қоздырғыштарсыз қуанып, шын көңілді бола алады.\nМұндай адам айналысатын ісін шын жақсы көреді және процестің өзінен ләззат алады. Тіпті шағын нәтиже үшін де өзін марапаттауды және қарапайым нәрседен рахаттануды ұмытпайды.\nОған өмірдің барлық саласын тепе-теңдікте ұстау тамаша шығады: отбасына толық сіңіп, құрбан болмай және жұмысқа шектен тыс берілген адамға айналмай, бірақ сонымен бірге әлеуетін ашып, жұмыста өсу.\n### Әлсіз жағы\nСвадхистананың энергиясы қалыптан әлдеқайда жоғары болса, бірақ пайдаланылмаса немесе ақылсыз жұмсалса, жағымсыз жағы қосылуы мүмкін.\nЛәззатқа шектен тыс құмарлық, гедонизм, тек алып, рахаттанғысы келу пайда болады. Адамдарға, уәделерге, оқиғалар мен істерге қатынас үстірт болады, сондықтан шын жақын қарым-қатынас құрып, отбасын құру мүмкін болмайды.\n«Кайф» пен эмоцияның соңынан үнемі қуу серіктестерді жиі ауыстыруға және опасыздыққа бейімділікке әкеледі. Табыстың сыртқы белгілеріне, «орауышқа» байланып қалу пайда болады. Адамға ләззаттың үнемі жаңа көздері керек, ол интимдік байланысты, тамақты, ішімдікті және т.б. асыра пайдаланады, ал көтерілуден кейін көбіне күштің құлдырауы болады.\nЕкінші шеткі жағдай да болуы мүмкін (әсіресе әйелдерде жиі): өзіне қарапайым күтімнен бас тарту, қарым-қатынас пен отбасына тәуелділік, құрбандыққа бейімділік. Шектейтін, әмір жүргізетін және жоғары назар талап ететін туыстармен дұрыс емес қарым-қатынас қалыптасуы мүмкін. Адам отбасына тұйықталып, тек жақындарының мүддесімен өмір сүріп, өз еркімен құрбан позициясын ұстанады. Энергия жүзеге аспаса, мұндай сыйымдылық үнемі сенімсіздік пен алаңдаушылық сезімін беруі мүмкін. Адам өмір жолы неде және қалағанына қалай жетуге болатынын түсінбей, абдырап, шынайы тілегін ұшқалақ серпін мен өзгенің пікірінен ажырата алмайды.", "max": "### Чакраның сыйымдылығы өте үлкен\nСвадхистананың мұндай күшті энергиясы — орасан зор әлеует.\nОл өз иесіне тек қарсы жыныс үшін ғана емес, айналадағылардың бәрі үшін сезімталдық пен тартымдылық береді. Бұлар — араласуда жағымды, байланысқа оңай баратын, басқаларды қабылдайтын және дауға бейім емес, өмірге толы энергиялы адамдар. Олар өзін және денесін жақсы көреді және өзіне қамқорлық жасағанды ұнатады.\nСонымен бірге олар басқа адамдардың терең қажеттілігін жақсы түсінеді, сезімтал әрі қамқор. Оларға барлық салада тепе-теңдікті сақтау сәтті шығады: олар кәсіби және әлеуметтік жағынан жүзеге асқан, бірақ жақындары да назардың жетіспеуінен зардап шекпейді. Оларға туыстарына қамқорлық, үйді жайластыру мен айналадағы сұлулық ерекше ләззат береді.\nЖаңа эмоция мен әсер іздеп, олар саяхаттауға, іс-шараларға баруға, жаңа адамдармен танысып, араласуға ұмтылады. Көбіне өмірді ойын және шытырман оқиғалар тізбегі ретінде қабылдайды. Табиғи қалпын сақтай отырып, шын жүректен көңілденіп, босаңсып, қоздырғышсыз қуана біледі. Олар тіпті ұсақ-түйектен де рахаттана алады және жеңіс пен түпкі нәтижеден гөрі процестің өзінен ләззат алады.\nМұндай адамдар өміріне риза, алғыс айта біледі және оптимизмімен басқалармен бөліседі. Олар жеңіл қозғалады, позитивті өмір сүріп, айналадағыларды соған үйретеді. Көбіне шығармашылықта өзін көрсетеді, әуестіктері әртүрлі және даралығын көрсеткенді жақсы көреді.\nАдам басқаларды кемсітпей, өз тілегі мен қажеттілігін ұстанады, армандарын жүзеге асырып, ұмтылысына батыл ереді. Ол керемет сүйкімді әрі тартымды. Сезімталдық, харизма, ерекше «тартымдылық» пен өзін ұсына білу адамдарды тартады. Оның талғамы мен стиль сезімі бар. Оған жанасу, құшақтау, денелік байланыс жағымды, ол өте сезімтал және бәрінде сұлулықты жақсы көреді.\nОл өмір мен адамдардан сыйлық қабылдай біледі, керек уақытта керек жерде болады. Күшті Свадхистананың арқасында мүмкіндіктер ашылып, ішкі қысылу мен шектейтін сенімдер кетеді.\nМұндай тұлға үшін отбасы, берік байланыс және бала көру мүмкіндігі өте маңызды. Олар туыстарымен жақсы қарым-қатынас сақтап, олардан қолдау алып, өздері де қолдайды.\nБұлар — әлемге ерекше бірдеңе әкеліп, жасап, туындатуға қабілетті энергия мен креативтің донорлары. Бұған ішкі еркіндік, жоғары өзін-өзі бағалау, қалыптың болмауы, жаңаға ашықтық, әуесқойлық пен өмірге деген махаббат көмектеседі.\n### Әлсіз жағы\nМұндай күшті энергияны ұқыпты пайдаланбаса және оған дұрыс жол бермесе, адам оның жағымсыз көріністеріне тап болады.\nОл бір сәттік серпінге еріп, тым бейқам әрі жауапсыз болуы мүмкін — тұрақты жұмыс тауып, берік отбасын құру мүмкін болмайтындай дәрежеге дейін. Оған жауапкершілік пен әрекетінің салдарынан қашып, жеңіл өмір сүріп, ләззат алғысы келеді.\nОл бала сияқты — еркелеп, талап етіп, нормалар мен ережелерді бұзуы мүмкін.\nИнтимдік салада әлсіз жағында бетімен кетушілік пен бәріне рұқсаттылық көрінеді. «Кешенсіз» адамның бейнесі таңғалдыратын ашықтықпен, жалаңаштық пен өз денесін көрсетуге деген сүйіспеншілікпен шектеседі. Мұндай адам өзін — тұрақты серіктеспен де, балалармен де — ауырлатқысы келмейді және әсер мен өткінші рахаттың соңынан қуып, өз эгосын қанағаттандыру үшін өмір сүреді.\nТұрмыстағы ретсіздік көбіне адамдармен және қарсы жыныспен қарым-қатынастағы ретсіздікке ұласады. Көбіне шеткі жағдайлар болады: адам анда-санда ажырасып, қарым-қатынасты үзеді немесе керісінше, өзін ұмытып, жақындарына сіңіп, отбасына басымен кетеді.\nКөбіне ата-анадан бөліну бұзылған: олардың пікіріне күшті тәуелділік және олардың көзқарасы мен ұстанымымен тұтасып кету бар. Ана тарапынан салқындық пен қабылдамау қатты жаралап, терең өкпе мен күйзеліс тудырады.\nӘлсіздігіне жол беру айтарлықтай елеулі тәуелділіктерге әкелуі мүмкін: ойындар, қоздырғыштар, артық жеу, табыстан көп шығын, бәрінде шамасыздық және шамадан тыс өмір сүру.\nӨмірде тепе-теңдік жоқ, адам көбіне өзін эмоциялық тербетеді. Көңіл-күйі оның күніне өзі үшін қанша істегеніне және қанша дене ләззатын (жақындық, тамақ, ұйқы және т.б.) алғанына байланысты. Сонымен бірге ол базалық, материалдық тілектерге шоғырланған, рухани дамымайды, оның бірінші орнында бәрі сыртқы. Гедонизм тұтынушылық пен есепшіл өзімшілдікке ұласуы мүмкін.\nЧакраның шектен тыс сыйымдылығы ұшқалақтық пен үстірттікті тудырып, адамды сенімсіз әрі өзін ғана ойлайтын етеді. Ол ұзақ мерзімді мақсаттар мен міндеттемелерге көңіл бөлмей, салдары мен болашақты ойламай, осында және қазір өмір сүреді. Ол жоспарлап, стратегия құра алмайды, сондықтан армандар арман күйінде қалады.\nСондықтан өмірде көтерілу мен құлдырау, бақыт пен апатия жиі әрі күрт ауысып, үнемі кезектеседі. Мұндай адамдар көбіне арандатушы әрі таңғалдыратын әрекет етіп, өзін қатты әрі жарқын жариялап, көпшілік үшін өмір сүреді."}, "man": {"low": "### Сыйымдылық қалыптан төмен\nМұндай сыйымдылығы бар адам сыртқы ынталандыруға, бағалау мен мақұлдауға қатты тәуелді болуы мүмкін. Өзін-өзі бағалаудың төмендігінен, сенімсіздік пен шешімсіздіктен оған жұмыста жүзеге асу жиі қиын. Ол өзгенің пікіріне өте қабылдағыш, сондықтан оны жолдан тайдыру оңай: біреу оның идеясы туралы кекесінмен айтса немесе оны кемсітсе болды — онымен айналысқысы келмей, ішкі от басында-ақ сөнеді.\nТапқанын ұстау оған қиын, өйткені ұшқалақ әрі ақылсыз шығын болуы мүмкін. Көбіне ақшаны басқара алмай, оған күшті тәуелділік, несие алуға және қарызға батуға бейімділік бар. Екі шеткі жағдай болуы мүмкін: апатия мен өзін құрбан сезінуден бастап жұмысқа шектен тыс берілу мен кәсіби шаршап-шалдығуға дейін.\nОның қысым мен кемсіту бар қарым-қатынасқа, улы байланысқа түсу, бірге тәуелділікке тап болу тәуекелі жоғары. Ол серіктес тарапынан тұрақтылық, орнықтылық сезімі және өз маңызының расталуы үшін ғана қарым-қатынаста қалуы мүмкін.\nЕрікті шешімдер оған оңай келмейді, ол жағдайға иіліп, бейімделуге бейім, көбіне өз қажеттілігіне зиян келтіріп. Билік пен басқару мүмкіндігін алса, оны асыра пайдалана бастауы мүмкін.\nЖоспарлау мен мақсат қою қиын, ал жоспарлар сенімділік пен табандылықтың жетіспеуінен көбіне жарты жолда бұзылады. Көбіне эмоциялық фонда қиындықтар болады: адам сезімді білдіре немесе басқара алмайды.\nКөбіне оның зиянды әдеттері, дәмді тамаққа тәуелділігі болады, одан да елеулі тәуелділіктер болуы мүмкін.\nМанипураның төмен сыйымдылығы жиі мұң мен тұрақсыздық сезіміне әкеледі.\nОл өкпе жинап, кекшіл болып, себебін өзінен көрмей, ештеңесі шықпағаны үшін басқаларға ашулануы мүмкін. Адамдарға төзбеушілік пен ешнәрсемен ақталмаған мақтаншақтық қарым-қатынасқа да, жалпы өмірге де кедергі келтіреді.\n### Манипураның сыйымдылығы төмен болғандағы күшті жақтар\nАдам ымыраға бара біледі және көбіне өзін кемсітпей және құрбан болмай, серіктестермен ортақ мақсатпен өмір сүреді.\nОл энергияның жетіспеуін толтыру керек екенін санасыз сезінетін сияқты. Ол үшін көп әрекет етіп, жұмыс істеп, әртүрлі курстардан өтеді (оның ішінде тренингтер, психологиялық бағдарламалар, қаржылық сауаттылық негіздерін оқиды). Бұл оған ішкі энергия қорын басқаруға, мағыналы өмір сүруге және қалағанына жетуге көмектеседі.\nОл дамып, әлсіздігін жеңе алады: дене пішінімен жұмыс істеп, денсаулығына қамқорлық жасап, дұрыс тамақтанып, күн тәртібін сақтайды.\nЖұмыс пен молшылықта оған икемділік пен тиімді жұмыс одақтарын құру таланты көмектеседі. Мұндай адам тек табыс табуды ғана емес, керекті серіктестерді тауып, олармен сәтті араласу құруды да біледі.", "norm": "### Чакраның сыйымдылығы қалыпты\nМанипурасының сыйымдылығы қалыпты адамға белсенді өмірлік ұстаным, адамдар мен оқиғаларға байыпты көзқарас және сау өзін-өзі бағалау тән. Онымен байланыс тауып, жемісті қарым-қатынас құру оңай. Ол дау-жанжалдан аулақ болуға тырысады, агрессия көрсетпейді және ақылға қонымды ымыраға қабілетті.\nҚиындықтар оған салыстырмалы түрде оңай келеді. Мұндай адамдар жауапкершіліктен қашпайды және кедергіден қорықпайды — керісінше, оларды тұлғалық өсу үшін пайдаланып, бәсекеге қуана түседі және жарыста өзін көрсетуге болатын жағдайларды жақсы көреді.\nОларда ерік күші мен өзін бақылау дағдылары бар. Адамда ұйымдастырушылық қабілет бар және адамдарды басқара алады, сонымен бірге күш пен билікті асыра пайдаланбай, ықыласты харизма, бедел және жеке үлгі арқылы жаулайды. Ол ынталандырып, шабыттандырады, тіпті қиын сәтте де төзімді әрі салмақты болып қалуға тырысады. Ол өмірге қуана, босаңси, жемісті жұмыс істей және дәл солай жақсы демала біледі.\nОл өзін тәртіпке сала біледі, өзін және тілектерін басқара алады және мүмкіндіктерін байыппен бағалайды.\n### Әлсіз жағы\nБалалық шақтағы ауыр оқиғалардан, қатаң тәрбиеден және ата-ананың озбыр мінез-құлқынан кейін чакра әлсіз жағына кетуі мүмкін. Сонда адамға дербес әрекет ету үшін мақсаттылық пен өз күшіне сенімділік жиі жетпейді, ойлағанды жүзеге асыруға энергия жетпейді. Жоспарлауда, қаржыны басқаруда, ақылға қонымды шығын мен салымда қиындықтар болуы мүмкін.\nДенсаулық жағынан сонда асқазан-ішек жолы жұмысының шамалы бұзылуы, аллергия және тамақтану тәртібінің бұзылуы болуы мүмкін.", "high": "### Чакраның сыйымдылығы қалыптан жоғары\nМұндай адамның рухы күшті және оған пікір көшбасшысы болып, қоғамда ілгерілеуге мүмкіндік беретін тамаша ерік қасиеттері бар. Көбіне мұндай адамдардан кәсіпкерлер, саясаткерлер мен басшылар шығады. Олар өзіне сенімді, қуатты харизмаға ие және басқаларға әсер ету, адамдарды басқару және тіпті өз мақсаты үшін айла-шарғы жасау қабілетін түсінеді.\nОл өзгенің айла-шарғысына қарсы тұрып, айналадағылардың бағасы мен пікіріне тәуелді болмай алады. Керек кезде бас тартып, өзін — әдепті әрі ұқыпты — қорғай алады. Ол энергияны дұрыс бөліп, оны шын маңызды мақсаттарға бағыттай алады. Әдетте оның беделі тамаша, ол оны өте қастерлейді.\nОның пікіріне беделді пікір ретінде құлақ асады. Мақсаттылық, күшті ұйымдастырушылық қабілет, белсенді өмірлік ұстаным, дербес әрекет ету, негізгі шешімдерді қабылдау, басқалар үшін жауапкершілік алу және барлық процесті бақылауда ұстау әдеті оны табысқа жеткізеді.\nАқшамен оның қарым-қатынасы әдетте жақсы: ол ақша энергиясын сезеді және оның ағындарын басқара біледі. Мұндай адамдар әдетте қаржылық табысқа жетіп, жақсы табыс тауып, ақшаны шебер басқарады, капиталды жинап, көбейтеді. Тіпті миллионер болмаса да, адам өзіне сенімді және ақша үшін уайымдамайды, өйткені түсінеді: олар керектің бәріне және лайықты өмірге әрдайым жетеді. Оның материалдыққа көзқарасы ақылды әрі сауатты — артық сараңдықсыз, жеңілтектіксіз және шамасыз жұмсау әдетінсіз.\nОл уақыт пен күшті шебер бөліп, сауатты тапсырып, тұрмыстық даналық танытады, іскерлік епшілдігі мен кәсіпкерлік қабілеті бар.\nБұлар — жауапты әрі міндетті адамдар. Олар сөзіне адал және бірдеңе уәде етсе, артық еске салусыз орындайды. Олар жақындарына, қызметкерлеріне және өздері жауап беретін бәріне қамқорлық жасай біледі және ықпалын басқаларды кемсітпей пайдаланады. Оларда кез келген мәселе бойынша нақты ұстаным және дамыған парыз сезімі бар.\nАдам өзін тәртіпке салуға қабілетті, өзін және тілектерін басқара алады және мүмкіндіктерін байыппен бағалайды.\n### Әлсіз жағы\nМұндай энергияны ұқыпты пайдаланбаса және оған дұрыс жол бермесе, адам оның жағымсыз көріністерін сезінеді.\nМұндай адамдарда өзін жүзеге асыруда қиындықтар болуы мүмкін. Олар материалдыққа шектен тыс байланған және жақсы өмір сүруге ұмтылып, жұмысқа шектен тыс беріліп кетуі мүмкін, бірақ сонымен бірге бәрібір жеткіліксіз табыс табады. Олар кедергіні байқамай және табысқа жету үшін басқаша әрекет ету немесе икемдірек болу керектігін түсінбей, мақсатқа тым қасарысып барады. Нәтижесінде мамандарды тыңдағысы және жемісті ынтымақтастық құрғысы келмегендіктен көп мүмкіндікті жіберіп алады.\nОлар дауға, өз пікірін таңуға және басқаларды басуға бейім. Билік алса, оны шамадан тыс көрсетіп, шынымен қатал әрі циник болуы мүмкін.\nӘлсіз жағында адам тым жабысқақ әрі талапшыл, бәрін толық бақылауда ұстап, кез келген ескертуді өткір әрі сынмен айтады. Байлық пен жоғары орын ол үшін өте маңызды және көбіне жабысқақ мақсатқа айналады. Мақтаншақтық, шыдамсыздық пен агрессиялылық адамдармен жемісті араласуға кедергі келтіреді.\nІшкі күші бола тұра, мұндай адам бәрібір өзгенің пікіріне тәуелді. Сондықтан оған ілгерілеу, байып, ықпалды болу соншалықты маңызды — өйткені, оның пікірінше, дәл осы айналадағылардың көзінше шынайы құндылық пен құрмет береді. Сондықтан мұндай адамдар өз молшылығы мен мәртебесін кез келген жолмен, мысалы, ең қымбат әрі беделді нәрсенің бәрін сатып алу арқылы алға шығарады. Сыртқы құндылықтардың соңынан қуып, олар шынайы кәсібін, рухани дамуды және материалдық емес мақсаттарды ұмытады.\nРетсіз әрі ойланбаған әрекеттегі молшылыққа деген ниет тек жасанды түрде қамтамасыз етілген өмірді көрсетуге мүмкіндік беретін қарыз бен несиеге әкеледі.", "max": "### Чакраның сыйымдылығы өте жоғары\nМанипураның жоғары сыйымдылығы адамға белсенді өмірлік ұстанымға ие болуға, жүзеге асуға, өзін көрсетуге, мансап сатысымен өсуге және қоғамда жоғары орынға жетуге мүмкіндік береді. Ол назар аударып, адамдарға әсер ете алады, сонымен бірге төзімді болып, эмоциясын басқарады. Бұл оған кез келген жағдайдан жеңімпаз болып шығуға мүмкіндік береді.\nБұл — сау өршілдігі, ерік қасиеттері және қабілеттеріне сенімділігі бар туа біткен көшбасшы.\nМұндай адам өзгенің шекарасын бұзбай, әдепті басқарады, бедел мен жеке үлгі арқылы әсер етеді, пікірлестерді шабыттандырып, тұтандырады. Айналадағылар мұндай басшыларды құрметтеп, оларға сеніп, жауапкершілігін сезеді. Және бұл ақталған: бұлар — ақшамен жұмыс істей білетін және адамдармен жемісті өзара әрекет ете алатын күшті, еңбекқор, энергиялы адамдар. Олар ықпалын басқаларды кемсітпей пайдаланады, команданы сауатты әрі ойластырып жинайды және кез келген ауқымдағы жобаларды басқаруға қабілетті.\nОл өзгенің айла-шарғысына қарсы тұрып, айналадағылардың бағасы мен пікіріне тәуелді болмай алады, керек кезде бас тартып, өзін — ұқыпты әрі әдепті — қорғай алады.\nМұндай сыйымдылығы бар адамға жұмыста және мансапта жүзеге асып, қоғамда өзін көрсетіп, жоғары позицияларға жету — немесе өзіне жұмыс істеп, өз ісін құру маңызды. Ол мақсаттылық, рух күші, өзін тәртіпке салу және мақсат қойып, оған жете білу маңызды спортта да жоғары нәтижеге жете алады.\nМұндай адамдар сынақты төзіммен көтереді және белгілі бір мағынада тіпті қиындықты жақсы көреді — оларға өзін жеңу арқылы әрекет ету ұнайды.\nОлар жұмыс істегенді және еңбек еткенді жақсы көреді, көбіне — жынысына қарамастан — жұмысқа шектен тыс беріліп, мансапқа басты көңіл бөледі. Олардың ішінде әрдайым жаңа жетістіктерге итермелейтін белгілі бір қанағатсыздық өмір сүреді.\nӨмірде оларға басымдықтар мен шекараларды дұрыс қою, тамаша араласу дағдылары, жағдайды көп қадам алға есептеп, әртүрлі сценарийлерді ойластыра білу көмектеседі.\n### Әлсіз жағы\nМұндай күшті энергияны ұқыпты пайдаланбаса және оған дұрыс жол бермесе, адам оның жағымсыз көріністерін сезінеді.\nҚырсықтық, ашуланшақтық, сенімсіздік, ашық немесе жасырын агрессия, айтыс пен дауға бейімділік жемісті өзара әрекет құруға кедергі келтіреді.\nӨзімшілдік, кез келген жолмен өзін бекітуге ұмтылыс пен жабысқақтық адам қоғамның нормалары мен ережелерін елемей бастайтын дәрежеге жетуі мүмкін.\nОңай емес мінезінен, бағынғысы және иерархияға кіргісі келмегендіктен оның тіпті тұрақты жұмысы болмауы мүмкін.\nШектен тыс ысырапшылдықтан қаржылық қиындықтар мен қарыздар болуы мүмкін, бұл жүйкелік пен алаңдаушылық тудырады.\nБилік пен басқару мүмкіндігін алса, мұндай адам өкілеттікті асыра пайдаланып, озбырлық жасауы мүмкін: өз қажеттілігі алдыңғы орынға шығып, икемділік пен салмақтылық жетпейді. Ол толық бақылауды, шектен тыс сынды және мәңгі наразылықты көрсетіп, айналадағыларға асыра талап қоюы мүмкін. Өзін бекіту қажеттілігі оны айла-шарғыға итермелейді.\nМатериалдық құндылықтар ол үшін бәрінен жоғары, ол рухани дамымайды. Ақша мен биліктің соңынан қуып, ол өз болмысын, шынайы кәсібін, рухани өсуді және материалдық емес құндылықтарды ұмытады.\nМұндай адам көбіне табыстылықтың көрінісін жасап, көп жағынан көзбояумен өмір сүреді."}, "ana": {"low": "### Чакраның сыйымдылығы қалыптан төмен\nБұл чакраның энергиясы төмен болса, адам оны санасыз түрде толтыруға және артық жұмсамауға тырысады. Сондықтан оның жақын адамдар шеңбері әдетте шағын болады және ол өзін сезім мен эмоцияға шашпайды.\nКөп эмоция ішінде айтылмай қалады, сондықтан мәселелер дене деңгейінде де білінеді. Көбіне жағымсыз жағдайлардан, сатқындықтан және басқа ауыр оқиғалардан кейін мұндай адамдар сенімін жоғалтып, руханилықтан бет бұрып, барлық бәлесіне айналасындағыларды және бүкіл әлемді кінәлайды.\nОларға адамдарды жақын жібермеу, арақашықтық ұстау және эмоциялық жақындаспау тән. Олар жаңа таныстыққа ұмтылмайды, сондықтан көп мүмкіндікті жіберіп алады. Сынды қабылдамайды, бірақ өздері сынағанды жақсы көреді.\n### Анахатаның сыйымдылығы төмен болғандағы күшті жақтар\nМұндай адам бір серіктеске байланысы мен адалдығын сақтай алады және достарына берілген.\nБұл адамдар өкпе жинамайды және жағдайды жүрекке жақын қабылдамай біледі. Олар адамдар мен оқиғалар туралы әділ әрі байыпты пікір айтады. Керек сәтте эмоцияны кейінге қалдырып, байыппен әрекет ете біледі, яғни дұрыс әрі ақылға қонымды шешім қабылдай алады. Сыртқы ықпалға төзімділік пен тәуелсіздік оларға айла-шарғыға берілмеуге көмектеседі. Мұндай адам өз шекарасын белгілеп, өзгенің шекарасын құрметтейді. Ол көмекті шын мұқтаж адамдарға, қамқорлығымен тұншықтырмай ұсынады.\nМұндай адамға эмоция алу маңызды және ол үшін көп нәрсеге, тіпті ашық арандатуға (провокация) дейін баруға дайын. Ол өзіне деген махаббаттың көрінуін талап етеді және шектен тыс жабысқақ болуы мүмкін.\nОған өз және өзгенің эмоциясын және сөзсіз белгілерін (невербальные сигналы) тану қиын, сондықтан араласуда қиындықтар болуы мүмкін.\nБасқаларға көмектескенде ол энергетикалық тұрғыдан қатты сарқылуы мүмкін, өйткені мұны ресурстан және күштің артықтығынан істемейді.\n### Әлсіз жағы\nМұндай адамдарда тек айналадағылармен ғана емес, қарым-қатынаста қиындықтар болуы мүмкін. Оларға өзін сүю қиын, өйткені өзін махаббатқа лайық емес деп санап, өз әрекеттері мен сезімдерін қабылдамай, сынайды. Сонымен бірге өзін аяуға, негізсіз талап қоюға және кежірленуге бейім. Айналадағылар оларды салқын, өзімшіл және немқұрайды деп көруі мүмкін. Олар шынымен де қатыгездікке дейін барған тасжүректік көрсетуі мүмкін, жанашырлық танытуға және басқалардың ісі мен жағдайына қызығуға бейім емес.\nӨзін-өзі бағалаудың төмендігі және адамның жай ғана, өзі болғаны үшін мойындауға, махаббатқа және құрметке лайық екеніне сенбеуі болуы мүмкін. Ол бұдан азап шегеді, бірақ өзгеруге және дамуға ұмтылмайды — керісінше, сезімнен мүлде бас тартып, циник болып кетуі мүмкін. Мұндай адамның өзі алдап, сатқындық жасаса, басқалардан да соны күдіктеніп, өте күдікшіл болып, шамасыз әрі себепсіз қызғанады.\nКөбіне ол адамдарды айыптап, өзін олардың орнына қоя алмайды.", "norm": "### Чакраның сыйымдылығы қалыпты\nМұндай адам өзіне тартады, араласуға жағымды, мейірімді әрі позитивті. Ол адамдарға сенеді, ашық, сезімін еркін білдіреді және өзін де, басқаларды да қандай болса, солай қабылдайды. Ол адалдықты бағалайды және өзі де ісіне, жақындарына және достарына берілген болып қалады. Махаббат көрсетуден қорықпайды және ұзақ қарым-қатынасқа ұмтылады.\nОл адамдарды жақсы сезінеді, сондықтан қолдауға шын мұқтаж адамдарға көмектеседі. Өмір бергенін алғыспен қабылдап, әр адамнан ең жақсы жақтары мен таланттарын көре біледі. Адамдар оған тартылады, ол да оларға жауап береді. Сонымен бірге ол өзін басқалармен теңестіруге, оларда еріп кетуге, бірге тәуелді (созависимые) қарым-қатынасқа түсуге, құрбан болуға немесе өзгенің мүддесі мен қажеттілігімен өмір сүруге бейім емес.\nМұндай адамдар шынайы махаббатты оның ең жоғары көрінісінде — толық қабылдаумен және адамға таңдау бостандығын бере білумен — сезіне алады.\nАйналадағылар мұндай адамға сеніп, оған ашылады, өйткені күшті эмпатияның арқасында ол адамдардың сезімдері мен ең терең қажеттіліктерін ешкімнен кем түсінбейді.\nҚарсы жүре білу, тегін көмектесу және өз қажеттілігі мен сезімін жасырмау оған оңай танысуға және пайдалы байланыс табуға, кең достар мен пікірлестер шеңберіне ие болуға, сондай-ақ өзара махаббат, қолдау, сенім мен құрметке негізделген шын жақын қарым-қатынас құруға көмектеседі.\n### Әлсіз жағы\nҚатты көңілі қалғаннан және ауыр тәжірибеден кейін адам әлем мен адамдарға деген сенімін жоғалтып, құрбан күйіне және мұңға түсіп, айналасынан жабылып, ашылудан қорқуы мүмкін. Мұндай кезеңдерде өзін-өзі бағалау төмендеп, ішкі тіректер шайқалады. Жүрек-қан тамырлары жүйесінің және қан айналымының жұмысы бұзылып, қысым, өкпе мен бронх мәселелері пайда болуы мүмкін.\nМұндай кезеңдер ұзаққа созылса, чакраны белсендіру тәсілдерін қолданып, оның жұмысын қолдау маңызды.", "high": "### Чакраның сыйымдылығы қалыптан жоғары\nМұндай адамдар керемет тартымды әрі сүйкімді, ашық, араласқыш және эмоциялы. Олар қамқорлық пен қабылдау энергиясымен, қолдауға және жылуымен бөлісуге деген тілегімен тартады. Оларда сезіну және жанашырлық таныту қабілеті дамыған, сонымен бірге өзімшілдіксіз өзін қабылдау мен өзін сүю бар.\nОлар сезімдерін оңай білдіріп, қуанышымен бөліседі, мақтау сөз айтады, адамдардың күшті қасиеттерін байқап, өзгенің жан жарасын емдеп, шабыттандыра алады. Олар ашық жүрекпен және жанмен өмір сүреді және бәрін сезгендей істейді, жақсы эмоцияны да, жаманын да білдіреді.\nБұлар — махаббатсыз және эмоциялар мен сезімдерден «денені шымырлатқан» сезімсіз өмірді елестете алмайтын, тез ғашық болатын әрі құмарлана беретін жандар.\nБұл адамға, өмірдің өзіне, жұмысқа және әуестікке ғашықтық болуы мүмкін. Махаббатпен өмір сүру — дәл солар туралы. Ешнәрсе оларды жүрегіне қарсы жүруге мәжбүрлей алмайды, әрі оларға өз ұмтылысына қарсы жүруге болмайды — әйтпесе көңілі қалады.\nОларға адамдарды өмірінен жіберу қиын, өйткені адамға жылуы мен қамқорлығын беріп, оған жанымен бауыр басады. Олар шетте қала алмайды — оларға үнемі біреуді құтқарып, біреуге көмектесу керек. Мұны қуанышпен және мүлде тегін, қиын жағдайға тап болғандарға жанашырлықпен және түсіністікпен істейді. Сонымен бірге тек кеңеспен және сөзбен ғана емес, нақты іспен де көмектеседі.\nОлар бәрін жүрекке жақын қабылдауға, лезде әрекет етуге, әділетсіздікке өкпелеп, ашулануға бейім. Бұл эмоцияларды баспай, мұндай күшті энергияға өзгенің шекарасын және рұқсат етілгеннің шегін бұзбай, еркін ағуға мүмкіндік беру маңызды.\nМұндай адам бірдеңені өз қолымен — шебер әрі махаббатпен, туындысына жүрегінің бір бөлшегін салып — жасай біледі.\nМахаббат сыйлау және қабылдау, алғыс сезіну — мұндай адамдардың ерекше қасиеттері. Олар кешіре біледі және кек сақтамайды, өкпе жасырмайды және кек алмайды. Олар айналадағылардың қателігіне жеңіл қарайды және сонымен бірге өзін кінәлап, қинап, өкініп, өткенмен өмір сүруге бейім емес.\nМұндай тұлғаны адалдық, әділдік және парыз сезімі анықтайды. Адам жағдайды жақсы түсінеді, адамдарды терең көріп, сезінеді.\nКөбіне мұндай адамдардың талғамы жақсы, олар эстетика мен сұлулықты бағалап, бәрінде үйлесімділікке тартылады — тек көрермен ретінде ғана емес, идеялар мен шығармашылық ұмтылыстарды көзге көрінетін заттарға айналдырып, сұлулық жасайтындар ретінде.\n### Әлсіз жағы\nЧакраның энергиясы пайдаланылмаса және жүзеге аспаса, оның жұмысы бұзылуы мүмкін.\nАдам жақсы болуға тырысып, көп назар мен көмек беріп, көбіне жабысқақтыққа дейін барады. Көбіне ол құрбан рөлінде қалады: жауабына алғыс алмай, өзін пайдаланылғандай сезінеді.\nСонда ол адамдарға сенуді қойып, ашуланып, көңілі қалып, қатайып, өкпе жинап, өзін-өзі жазғыруы мүмкін.\nНемесе керісінше — ашу-ызаға (истерика) беріліп, лезде, күрт, эмоциялы әрі қатты дауыспен әрекет етеді.\nСонымен бірге ол айналадағылар мен жақындарының өзіне деген көзқарасына қатты тәуелді. Бәріне дұрыс әрі жақсы болуға деген тілек тұйық шеңберге және өз қажеттілігін елемеуге әкеледі. Ал «бәріне мейірімді» бетпердесінің астында жасырынған нәрсе бір сәтте сыртқа кінә, ашу және эмоциялық бұзылулармен шығады.\nӘлсіз жағында ол жай ғана сүйе алмайды — назарды, адалдықтың дәлелін, ризашылық пен алғысты талап етеді. Бұл алданып қалудан немесе сүйікті адамын жоғалтудан қорқудан болады. Сондықтан мұндай чакра энергиясы бар адам себепсіз қызғануға бейім, бәрін бақылауға ұмтылып, басқалардың жеке кеңістігін бұзады.\nМұндай адамдарға көбіне байыптылық жетпейді: олар көп жағынан эмоция мен екпінмен өмір сүреді және күрт шешімдері мен әрекеттеріне жиі өкінеді. Бұл ішінара олардың нәзік, сезімтал табиғатынан және бәрін басқалардан жақынырақ әрі өткірірек қабылдау әдетінен болады. Жаралы, өзін аямайтын және шынайы, олар көбіне түсінілмей қалады. Олар айналадағылардан сезімнің, эмпатия мен түсіністіктің дәл сондай жарқын көрінісін күтеді, бірақ оны алмай, өздерін бағаламайтынына наразы болып қалады.", "max": "### Чакраның сыйымдылығы өте жоғары\nАдамда Анахатаның ең жоғары сыйымдылығы бар. Ол махаббат сыйлап, қабылдай біледі, шығармашылық қабілетін дамытады, әлемге ашық және оңай танысады.\nОл қамқорлық пен қабылдау энергиясымен, қолдауға және жылуымен бөлісуге деген тілегімен тартады. Мұндай адамдарда сезіну және жанашырлық таныту қабілеті дамыған. Олар оңай өзіне тартып, тамаша дос және пікірлес болады.\nКөбіне мұндай адамдар қолөнерге өте шебер, бір кәсіппен айналысады, заттарды өз қолымен жасап, оларды жылу мен махаббатқа толтырады. Олар басқаларға қуана көмектесіп, еріктілікке (волонтёрство) және қайырымдылыққа қатысады — бірақ өзін бекіту, ықпал ету және өзгенің өмірінде маңызды болу үшін емес, бұл шынымен керек екенін түсінгендіктен.\nБұлар — махаббатсыз және эмоциядан «денені шымырлатқан» сезімсіз өмірді елестете алмайтын, тез ғашық болатын әрі құмарлана беретін жандар. Жүрегінде не болса, жүзінде де, тілінде де сол. Күшті Анахатасын жақсы жағында өмір сүрсе, эмоцияны ұстап, жасыра алмайды.\nБұл адамға, өмірдің өзіне, жұмысқа және әуестікке ғашықтық болуы мүмкін. Махаббатпен өмір сүру — дәл солар туралы. Ешнәрсе оларды жүрегіне қарсы жүруге мәжбүрлей алмайды, әрі оларға өз ұмтылысына қарсы жүруге болмайды — әйтпесе көңілі қалады. Көбіне олар өзін аямайды және өздерінің адамгершілік ережелері мен адалдық заңдарын ұстанады. Бір нәрсеге — идеяға, бағытқа, салаға — берілсе, шабытпен және тіпті фанатикке дейін әрекет етуі мүмкін. Олардың жүрегі сенімге толы — жақсылыққа, махаббатқа, жоғары күштердің қолдауына және әр адамдағы рухани бастамаға.\nОларға адамдарды өмірінен жіберу қиын, өйткені адамға жылуы мен қамқорлығын беріп, оған жанымен бауыр басады. Олар шетте қала алмайды — оларға үнемі біреуді құтқарып, біреуге көмектесу керек. Мұны қуанышпен және мүлде тегін, қиын жағдайға тап болғандарға жанашырлықпен және түсіністікпен істейді.\nОлар бәрін жүрекке жақын қабылдауға, лезде әрекет етуге, әділетсіздікке өкпелеп, ашулануға бейім. Бұл эмоцияларды баспай, мұндай күшті энергияға өзгенің шекарасын және рұқсат етілгеннің шегін бұзбай, еркін ағуға мүмкіндік беру маңызды. Олар ашуланшақ, бірақ тез басылады және іштей кек сақтамайды. Тілектері мен қажеттіліктері туралы қарапайым әрі тура айта біледі.\nДаналығы мен әділдік сезімінің арқасында мұндай адам адамдардың қателігі мен кемшілігін кешіре біледі.\nКөбіне мұндай адамдар жанасу, жылы құшақ және әр адамдағы әдемілікке деген сенім арқылы емдей алады.\n### Әлсіз жағы\nЧакраның мұндай күшті энергиясы жүзеге аспаса, оның жұмысы бұзылуы мүмкін.\nАдамда махаббат пен мақұлдауға деген шектен тыс қажеттілік, басқа адамдардың сезімі мен эмоциясына тәуелділік пайда болады. Жалғыздық өте ауыр қабылданады және бұл оны бірге тәуелді, улы қарым-қатынасқа итермелейді.\nЖоғары сезімталдық пен қабылдағыштықпен бірге табиғат мұндай адамдарға шектен тыс эмоциялылық та береді. Адам ұнағысы және сүйікті болғысы келіп, көп берсе, бірақ жауап алмаса (немесе күткенінен аз алса), қуаныш тез көңіл қалуға, өкпеге және ашуға ауысады. Мұндай адамдар сынды өте ауыр қабылдайды және өзі туралы тіпті әділ пікірге де әрдайым шыдай бермейді.\nЖеке шекарамен қиындықтар бар: ол өзгенікін бұзып, өзінікін сезбейді. Мұндай адам басқа адамда еріп кетуге, сөзбе-сөз оның мүддесімен өмір сүріп, өзін құрбан етуге дайын, бірақ айналадағылардан да дәл соны, олардың пікірімен, қажеттілігімен және тілегімен санаспай, талап етеді. Ол назарымен, қызғанышымен және қамқорлығымен тұншықтыруы мүмкін.\nШын мәнінде бұл әрекеттерде махаббат өте аз: Анахатаның мұндай энергиясының иесі көбіне өз қажеттілігін қанағаттандырумен айналысып, өзімшіл әрекет етеді. Бір жағынан, ол өзін құрбан сезініп, бәрі оған қарыз деп сенеді, ал екінші жағынан — сезімдері мен тілектеріне қатты жабысып, қатал әрі талапшыл болуы мүмкін.\nОл басқа адаммен қатты бірігіп, өзгенің жағымсыз эмоциясын оңай жұқтырады, ал мұндай күйден өз бетінше шығу оған өте қиын. Тепе-теңдік пен үйлесімді көңіл күйді сақтауға шектен тыс эмоциялылық та, екпіншілдік те кедергі келтіреді."}, "vis": {"low": "### Чакраның сыйымдылығы қалыптан төмен\nМұндай сыйымдылықта адамның әлеммен өзара әрекетінде қиындықтар және араласуда бұзылулар болуы мүмкін.\nОл ойын, эмоциясы мен сезімін нашар білдіреді немесе мұны дәл емес әрі түсініксіз істейді. Көбіне түсінілмей және қабылданбай қалып, ол айналасына бейімделеді және шын ұстанымын айтпайды. Қоғамның пікірі мен бағасына тәуелділік пайда болады. Екі шеткі жағдай болуы мүмкін — үндемейтін немесе көп сөйлейтін, ал кейде күрт, тура әрі сынмен айтылған сөздер.\nВишудхасының сыйымдылығы төмен адамдар көбіне эмоцияны басып, өздеріне шынайы сөйлеуге және көрінуге жол бермейді — сөзбе-сөз «өз тамағын өзі басады». Әлсіз әрі сенімсіз көрінуден қорқып, олар боқауыз сөз бен мысқылды (сарказм) пайдаланып, цинизм мен дөрекілік бетпердесін киюі мүмкін.\nОлар өзін-өзі сынауға бейім, қоғамдық іс-әрекеттен, сөз сөйлеуден және көпшілік алдына шығудан қорқады. Оның үстіне оларды бағалайтын көп адаммен араласу оларды абдыратып тастайды.\nМұндай адамдарға шығармашылықта өзін көрсету және әлемге таланттарын көрсету оңай емес.\n### Вишудханың сыйымдылығы төмен болғандағы күшті жақтар\nЧакраның энергиясын толтыру үшін олар оқығанды жақсы көреді және дағдыларын үнемі жетілдіреді.\nЖақсы жағында мұндай адамдар дау тудырмайды, сабырлы әрі ұстамды және өзін білдіру энергиясын жақындары үшін сақтайды. Дәл оңашада олар шығармашылықпен айналысып, шабытын аша алады.\n### Әлсіз жағы\nМұндай адам келісімді, тәртіпті, мінез-құлық нормаларын, қоғамдық және адамгершілік ережелерін бұзуы мүмкін. Кез келген жолмен назар аудартуға ұмтылыс (эпатаж, тентектік, сөзді бөлу әдеті, қырсықтық) көрінуі мүмкін.\nЕкіжүзділік болуы мүмкін — ең алдымен адам өзіне адал емес. Ол өсек пен қауесетке әуес болып, әңгімелесушімен жиі келіспей, сынап, менменсіп әрекет етуі мүмкін.\nӘлсіз жағында адамдар идеяларынан бас тартып, басқалардан өзгеше және ерекше болудан қорқады, өйткені ойлағаны шықпайтынына сенімді.\nСөйлеуі нашар құрылуы мүмкін, кекештік және сөйлеудің басқа бұзылулары болуы мүмкін.", "norm": "### Чакраның сыйымдылығы қалыпты\nМұндай сыйымдылық адамға өз күшіне сеніп, өзін білдіруге мүмкіндік береді. Ол қабілеттерін байыппен бағалайды және әдепті сынды сабырлы, жағымды қабылдайды. Ол өзіне және жоғары күштерге сенеді, бұл сенім оған қиындықты оптимизммен қарсы алуға көмектеседі.\nОл өзін және тағдырын әртүрлі жолмен, оның ішінде шығармашылық арқылы іздейді. Бірақ көбіне көпшілікке танылуға және мойындалуға ұмтылмайды, көбіне өзі үшін жасап, туындатады — сырттан мақұлдау оған соншалықты маңызды емес.\nОл эмоциясы мен ойын еркін әрі әдепті білдіреді, пікірін айтудан және қорғаудан қорықпайды, оған құлақ асады. Ол өзіне де, басқаларға да адал, екіжүзділік жасамайды және шынайы болмысын көрсетуден қорықпайды.\nМұндай адамдар басқаларды тыңдай біледі және өзгенің пікірімен санасады, айтыс, пікірталас пен ара-жік ашуды жақсы көрмейді, дауысын сирек көтереді, сөзі сенімді әрі сабырлы.\nОның сөзі қарапайым әрі түсінікті, ол әрдайым ымыраға дайын, сондықтан оны әңгімелесуші ретінде бағалайды.\nВишудхасының сыйымдылығы қалыпты адамда адамгершілік қағидалары мен өз моралі ерте қалыптасады, ол қоғамның ережелерімен сәйкес келмесе де, соны ұстанады. Мұндай адамдар өзін және ішкі дауысын тыңдай біледі және өзімен үйлесімде өмір сүреді.\n### Әлсіз жағы\nЧакраның жұмысы балалық шақтағы ауыр оқиғалардан кейін (өзін көрсетуге жол бермегенде, өзін-өзі бағалауын басқанда), сондай-ақ адам оның энергиясын өзі пайдаланбаса бұзылуы мүмкін. Бұл көпшілік алдында сөйлеуден қорқуға, тұйықтыққа, сөйлеуде және шығармашылық қабілетті жүзеге асыруда қиындықтарға әкеледі, араласуда бұзылулар болуы мүмкін.\nСонда дене деңгейінде тамақ, қалқанша без, ауыз қуысы және жоғарғы тыныс жолдары мәселелері пайда болуы мүмкін.", "high": "### Чакраның сыйымдылығы қалыптан жоғары\nҚалыптан жоғары сыйымдылық адамға ерекше ішкі бостандық береді — өзін көрсету және білдіру бостандығын.\nОл өмірлік ұстанымын сенімді жариялайды және пікірін қорғайды.\nМұндай адамдар өзіне де, айналадағыларға да адал және өзгенің көзқарасын қабылдайды. Олар сезімдері, эмоциялары мен сөздері үшін жеке жауапкершілікті түсінеді.\nОлар нақты жағдайда өзін қалай ұстап, қалай сөйлеу керектігін түйсікпен түсініп, әртүрлі жағдайлар мен адамдарға бейімделе біледі.\nАдам қоғамда өзін көрсетуге, көзге түсуге, таланттары мен қабілеттерін көрсетіп, жағымды жауап алуға ұмтылады.\nОларды өте жиі шығармашылық тартады, олар шабытпен өмір сүргенді жақсы көреді — өлең жазады, ән айтады, сурет салады, музыкалық аспаптарда ойнайды және т.б. Бірақ олар өзін тек шығармашылықтың әдеттегі түрлерінде ғана емес, жалпы тек өз көзқарасына тән жаңа әрі бірегей нәрсе жасап та көрсете алады.\nҚалай болғанда да, жасау тілегі оған қажет: тіпті қарапайым кеңсе қызметкері болса да, айналадағыларды таңғалдырып, мойындау алу үшін жаңа идеялар мен стратегияларды іздеп, сынап көреді.\nВишудхасы қалыптан жоғары адам сызбаларды, үлгілер мен трафареттерді жақсы көрмейді — ол өзін білдірудің жаңа тәсілдерін іздеп, өз идеялары мен ой шағылыстарына сүйенеді.\nОл үнемі дамып, жаңаны білгісі келеді және көбіне мұны адамдармен араласу және өзара әрекет арқылы істейді. Даму үшін дипломатиялықты, сөйлеу өнерін және сендіре білуді пайдаланады.\nОл дау-жанжалға бейім емес, ымыраға дайын, келіспеушілікті реттей біледі және делдал бола алады.\nОл әңгімелесушіге бейімделіп, оның қимылы мен сөйлеу мәнерін қабылдап, оны айнадай көрсетіп, онымен бір толқында сөйлесе біледі. Бұл үйлесімді араласуға, пайдалы таныстық пен байланысқа, сондай-ақ дауыспен адамдарға әсер етуге көмектеседі. Мұндай адам айтқанында екпінді дұрыс қойып, шабыттандырып, ынталандыра біледі.\n### Әлсіз жағы\nЧакраның энергиясы пайдаланылмаса және жүзеге аспаса, чакра әлсіз жағына кетуі мүмкін.\nСонда адам көп сөйлейтін, ақпаратты, тіпті өсекті тарататын болады, сөз ағынын тоқтату оған өте қиын. Ол өзгенің пікірін қабылдамай, өзінікін — айқаймен, сөзді бөлумен, өткір үнмен және ашулы сөздермен — қызу қорғайды. Бұл, әрине, дау-жанжал, айтыс және сөзбен қысым көрсетуге итермелейді. Ашу мен ыза сөзбен, оның үстіне өзіне де, айналадағыларға да зиян келтіріп, білдіріледі.\nМұндай адамдар көпшілікті таңғалдырғанды, көзбояушылықпен, көрсету үшін, қатты әрі тиісу ниетімен сөйлегенді жақсы көреді. Олар сөзбен оңай ренжітіп, оны байқамай, күліп жіберуі мүмкін. Көбіне «Айтылған сөз — атылған оқ» мақалының дұрыстығына өз басынан көз жеткізеді, бірақ өздері не дұрыс емес екенін түсінбейді. Қиялдағанды, өтірік қосқанды және өмір оқиғаларын әсірелеп, өзін оқиғалардың батыры етіп көрсеткенді жақсы көреді. Оларға жанжалда тоқтау қиын — айналадағылардың реакциясына қарамай, оларды жай ғана алып кетеді. Тіпті біреуді жаралап қойса да: «Мен осындаймын, не істейін», — деуі мүмкін.\nВишудхасының сыйымдылығы жоғары адамға ымыра оңай келмейді, өйткені әдетте тек өзін ғана дұрыс деп санайды, көбіне менменсіп әрекет етеді, әңгімеде күрт әрі дөрекі болады. Ол көбіне ақпаратты өз пайдасына бұрмалап, әңгімелесушіні және оның үнін түсінуге тырыспайды. Сөйлегенде сөзді жұтып, асығады, буындар мен жалғауларды дұрыс айтпайды.\nКейде ол тұйықталып, жабылып, сол арқылы Вишудханың күшті энергиясын жауып тастауы мүмкін, бұл да денсаулыққа әсер етуі мүмкін. Апатия және жалпы өзін, оның ішінде шығармашылықта көрсеткісі келмеу болуы мүмкін.", "max": "### Чакраның сыйымдылығы өте жоғары\nМұндай жоғары сыйымдылық — қоғамда өзін көрсетуге, шығармашылықпен өзін білдіруге, шешендік және ынталандырушылық талантына арналған орасан зор әлеует.\nАдам ақпаратты нақты аудиторияға бейімдеп, оңай әрі әдепті жеткізе біледі.\nКөбіне оның жазушы мен редактор дағдылары болады, келіссөз бен пікірталасты жақсы біледі. Дипломатиялықтың және харизмалы сөзінің арқасында ол адамдарға әсер етіп, оларды бағыттап, ішкі таланттарын ашуға көмектеседі.\nМұндай адамдар өзіне сенімді, қорқыныштарын түсінеді және көпшілік алдында өзін көрсетіп, оларды жеңеді. Олар әлсіз жақтарын көрсетуден қорықпайды, көпшілік алдында адалдық пен ашықтық танытып, кейде таңғалдырып, қоғамдық нормалардың шегінде теңселеді. Олар мұны өз ерекшелігін және өмірдің, пікірлер мен көзқарастардың басқа қырларын көрсету үшін істейді.\nОған адамдар тартылады: ол жарқын сөзімен, харизмалы баяндауымен, кез келген тақырыпты қолдай білуімен, делдал болып, кез келген дауды реттей білуімен назар аудартады. Бұл кімге, не және қандай түрде айтуға болатынын және керектігін әрдайым білетін тамаша кеңесші әрі тәлімгер. Ол айтыс пен пікірталаста жеңеді, өйткені сөзді шебер әрі алуан түрлі меңгерген.\nКөбіне ол өзгенің пікіріне тәуелді емес, сондықтан қателіктен қорықпайды және өзін шығармашылықпен ең әртүрлі жолмен көрсетеді.\nОл қоғамда өзін көрсетуге, көзге түсуге, таланттары мен қабілеттерін көрсетіп, жағымды жауап алуға ұмтылады. Оған көрермендер, әңгімелесушілер мен шәкірттер керек.\nМұндай адамдарды өте жиі шығармашылық тартады, олар шабытпен өмір сүргенді жақсы көреді — өлең жазады, ән айтады, сурет салады, музыкалық аспаптарда ойнайды және т.б. Бірақ олар өзін тек шығармашылықтың әдеттегі түрлерінде ғана емес, жалпы тек өз көзқарасына тән жаңа әрі бірегей нәрсе жасап та көрсете алады.\nҚалай болғанда да, жасау тілегі оған қажет: тіпті қарапайым кеңсе қызметкері болса да, айналадағыларды таңғалдырып, мойындау алу үшін жаңа идеялар мен стратегияларды іздеп, сынап көреді.\nВишудхасының сыйымдылығы жоғары адам көбіне сызбалар мен үлгілерге қарсы жүреді, өзін білдірудің жаңа тәсілдерін іздеп, идеялары мен пайдалы табыстарымен бөліседі.\nОл үнемі дамып, жаңаны білгісі келеді және мұны негізінен адамдармен араласу және өзара әрекет арқылы істейді.\nОл әңгімелесушіге бейімделіп, оның қимылы мен сөйлеу мәнерін қабылдап, оны айнадай көрсетіп, онымен бір толқында сөйлесе біледі. Бұл үйлесімді араласуға, пайдалы таныстық пен байланысқа, сондай-ақ дауыспен адамдарға әсер етуге көмектеседі.\n### Әлсіз жағы\nМұндай үлкен энергия қоры пайдаланылмаса, чакраның энергиясы әлсіз жағына кетуі мүмкін.\nАдам көп сөйлейтін, ақпаратты, тіпті өсекті тарататын болады, сөз ағынын тоқтату оған өте қиын. Ол өзгенің пікірін қабылдамай, өзінікін — айқаймен, сөзді бөлумен, өткір үнмен және ашулы сөздермен — қызу қорғайды. Бұл, әрине, дау-жанжал, айтыс және сөзбен қысым көрсетуге итермелейді. Ашу мен ыза сөзбен, айналадағыларға зиян келтіріп, білдіріледі. Мұндай адамдар айналадағыларды таңғалдырғанды, көзбояушылықпен, көрсету үшін, қатты әрі тиісу ниетімен сөйлегенді жақсы көреді. Олар сөзбен оңай ренжітіп, оны байқамай, күліп жіберуі мүмкін. Көбіне «Айтылған сөз — атылған оқ» мақалының дұрыстығына өз басынан көз жеткізеді, бірақ өздері не дұрыс емес екенін түсінбейді. Қиялдағанды, өтірік қосқанды және өмір оқиғаларын әсірелеп, өзін оқиғалардың батыры етіп көрсеткенді жақсы көреді. Оларға жанжалда тоқтау қиын — айналадағылардың реакциясына қарамай, оларды жай ғана алып кетеді. Тіпті біреуді жаралап қойса да: «Мен осындаймын, не істейін», — деуі мүмкін.\nОл эмоциясының күшін әсірелеп, шектен тыс ойнап, жақындарын ара-жік ашуға итермелеп, «бір актердің театрын» ұйымдастыруы мүмкін. Басқаларды сынап, өзін ең жақсы жағынан көрсетуге тырысады, бірақ оның сыны көбіне әділ емес және сындарлы емес.\nОл өзін естіп, көргенін қалайды, бірақ мұны үйлесімді әрі әдемі түрде жеткізе алмайды.\nЫмыра оған қиын келеді, өйткені әдетте тек өзін ғана дұрыс деп санайды, көбіне менменсіп әрекет етеді, әңгімеде күрт әрі дөрекі болады. Әлсіз жағында ол ақпаратты өз пайдасына бұрмалауға бейім және әңгімелесушіні және оның үнін түсінуге тырыспайды. Сөйлегенде сөзді жұтып, асығады және оларды дұрыс айтпайды.\nОл таланттарын қайда қолдануды іздейді, бірақ таппайды және көбіне жүйесіз әрекет етеді. Ол екпін мен шабытты сезінеді, бірақ ішкі сезімдерін қалай әдепті білдіруді түсінбегендіктен оларды сөндіреді — бұл оған шындыққа жанаспайтын әрі қолжетімсіз болып көрінеді. Осылайша ол өзін алдап, өз тілектерін түсінуін бұрмалайды."}, "adj": {"low": "### Чакраның сыйымдылығы қалыптан төмен\nАджнаның мұндай сыйымдылығында адамға логиканы пайдалану, ұқсастық табу және болып жатқаннан дұрыс қорытынды шығару қиын. Сондықтан ол бір «тырнаққа» қайта-қайта басып, бір қателікті қайталауы мүмкін. Көп ақпаратты сыйғызып, өңдей алмау зейінсіздікке және есте сақтау мәселелеріне әкелуі мүмкін.\nМұндай адамдар көп оқуы мүмкін, бірақ тәжірибеге көшуден қорқады. Оларға алаңдаушылық және өзіне әрі біліміне сенімсіздік тән, ал ұмытшақтығы мен сенгіштігінен оларды алдап кету оңай.\nОларда апатия және өмірдің мәнін жоғалту сезімі пайда болуы мүмкін, өйткені оларға тағдыры мен бағытын түсіну қиын. Мұндай сыйымдылығы бар адам жауапсыз әрекет етіп, болып жатқанның мәніне терең бойламай, адамдар мен жағдайлардың жетегінде кетуі мүмкін.\n### Аджнаның сыйымдылығы төмен болғандағы күшті жақтар\nАдамда тәжірибелік ойлау басым. Ол ұзақ ойланып, талдауға бейім емес, «осы жерде және қазір» өмір сүреді, қазіргіге сүйеніп, міндеттерді сындарлы шешеді. Оған білімді мүмкіндігінше тезірек тәжірибеде қолданып, жаңа дағдыларды пысықтау маңызды. Шешім қабылдағанда көп жағынан жеке тәжірибесіне сүйенеді. Мұндай адамдар білуге құмар және жаңаға тартылады, бірақ қысқа уақытта көп ақпаратты меңгере алмайды, сондықтан оларға бірнеше іспен қатар жұмыс істеу оңай емес және кезең-кезеңімен әрекет ету маңызды.\nАраласуда олар көбіне өте сенгіш және жағымсыз нәрсеге назар аударғанды жақсы көрмейді. Оларда өзін-өзі қайрау және ойда тұрып қалу әдеті жоқ — олар жағдайды тез жіберіп, әрі қарай жүреді. Жылдар өте келе олар тәжірибесі мен өз тарихын талдап, қорытынды жасап, даналана түседі.", "norm": "### Чакраның сыйымдылығы қалыпты\nМұндай сыйымдылығы бар адамда көбіне рухани ерік дамыған — ол әрекеттерін саналылық арқылы басқара алады. Ол түйсігіне құлақ асып, оны естиді, әртүрлі процестер туралы жиі ой толғайды. Ол логикалық, ұтымды ойлауды да, түйсікті, бейнелі ойлауды да пайдалана алады. Мұндай Аджнасы бар адамдар өз ойлары мен өзгенің әрекеттерін талдай біледі, оқиғалардың себеп-салдар байланысын түсінеді, бақылап, Ғаламның белгілерін байқай біледі. Оларда дамуға және жетілуге деген тілек бар, өйткені өзіне, жоғары күштерге және өз миссиясына деген сенім бар. Оларға ойлаудың икемділігі және жағдайға әртүрлі жағынан қарай білу тән. Олар шабыттанады, бірақ иллюзияда ұзақ тұрып қалмайды, шығармашылық ұмтылыстарды тәжірибемен біріктіріп, жаңа дағдылар алады. Аджнаның мұндай сыйымдылығы ақпаратты сұрыптап, жаңа білімге энергия қалуы үшін пайдасыз әрі қолданылмайтын ақпараттан арылу қабілетін береді.\n### Әлсіз жағы\nБалалық шақта ауыр тәжірибе болса — адамның көзқарасын қабылдамаса, зияткерлік қабілетін көрсетуге жол бермесе, оның түйсігі мен ішкі сезімдерін жоққа шығарса — энергия тоқырап, әлсіз жағында көрінуі мүмкін. Алаңдаушылық, күмәншілдік (скептицизм), көңілсіздік, өзіне және жоғары күштерге сенбеу, есте сақтаудың нашарлауы және ұйқысыздық болуы мүмкін. Бас ауруына және ми қан айналымының бұзылуына бейімділік пайда болады.", "high": "### Чакраның сыйымдылығы қалыптан жоғары\nМұндай адам ешқашан жеткен жетістігіне тоқтап қалмайды: ол үнемі жаңаны іздеп, әлемге әсер ету және сыртқы процестерді басқару тәсілдерін зерттейді. Оның рухани еркі дамыған — ол әрекеттерін саналылық арқылы басқара алады.\nАджнасының мұндай сыйымдылығы бар адамдар өмірге көбіне философиялық тұрғыдан қарайды, ой толғағанды жақсы көреді және стратегиялық ойлауға ие. Олардың есте сақтауы жақсы, көп ақпаратты есте сақтап, өңдей алады.\nАдам дүниетанымын белсенді қалыптастырады, уақыт өте оны өзгертіп, түрлендіре алады, өмірдің мәні мен тағдырын іздейді. Ол өмірдің рухани жағына қызығады, өзінің адамгершілік кодексін жасап, соны ұстанады. Оның ойлауы ешнәрсемен шектелмеген: ол болып жатқанның көп қыры болуы мүмкін екенін түсінеді және әртүрлі көзқарастарды оңай қабылдайды.\nОның зияткерлік және талдау қабілеттері тамаша, ақыл дауысы күшті және оқиғаларға логикалық тұрғыдан қарайды. Бұлар — ақпаратты ретке келтіріп, болжай білетін тамаша жоспарлаушылар. Бәрін ойластыру, егжей-тегжейді салыстыру, нәзік тұстарын түсіну — дәл солар туралы. Олар тек тексерілген әдістерге сенеді және шешім үшін оларға салмақты негіздер мен дәлелдер керек. Мұндай адам білімге құштар, оқығанды және ақылының күшін көрсеткенді жақсы көреді.\nОның қалағанын көз алдына елестету (визуализация) және іске асыру әлеуеті үлкен: ол арманын егжей-тегжейлі елестете алады, және ол жүзеге асады. Бірақ дәл осы қабілет қорқыныш пен алаңдаушылық тудырады, өйткені адам өзін-өзі қайрауға және иллюзия тұтқынында өмір сүруге бейім. Жаман нәрсе туралы ойлап, жағымсыздықты өзі тартады — ол көңіл бөлген сала белсенді болады.\nБәрінде тәртіп пен логикаға деген қажеттілік айқын болуы мүмкін, ал бұл өлшемдерге сай келмейтін нәрсе оған мүлде мүмкін емес болып көрінеді. Оған нақты логикалық дәлелдер керек — ол көріп, сезініп, талдағанда ғана сенеді.\nБірақ бұл оның жоғары күштер мен рухани заңдарға сенбейтінін білдірмейді. Керісінше, ол ойлауын дамытып, саналылығын арттырып, бұл салаларды зерттеп, құпия білім мен эзотериканы меңгергісі келеді.\n### Әлсіз жағы\nЧакраның жоғары энергиясы пайдаланылмаса, оның жұмысы бұзылып, әлсіз жағына кетуі мүмкін.\nМұндай адамдар осы жерде және қазір өмір сүре алмайды: олар не өткенде тұрып қалады, не болашаққа жабысып, қиял мен иллюзияда өмір сүреді. Олар оқиғалардың маңызын соншалықты әсірелеуі мүмкін, сонда алаңдаушылық пен мазасыздық пайда болып, қорқынышты түстер мен елестер мазалайды.\nӨзгенің ой-пікірі мен көзқарасын мойындамай, мұндай адам жағдайға өз көзқарасын таңып, адамдарды өз шеңбері мен үлгілеріне қамайды. Ол фактілермен сендіріп, қысым көрсетіп, ақыл жағынан артықшылығын көрсетіп, зияткерлік тұрғыдан басуы мүмкін. Руханилықпен байланысты нәрсенің бәрін «ғылыми емес» және фактілермен расталмаған деп жоққа шығаруы мүмкін.\nОл көбіне қырсық әрі күмәншіл, оның пікірін өзгерту мүмкін емес. Ол басқа адамдардың ой-пікірі мен қорытындыларын сынайды. Ойдың көптігі мен ақыл кернеуі ұйқысыздыққа және бас ауруына әкеледі.\nОл сондай-ақ өзін-өзі қайрауға және иллюзия тұтқынында өмір сүруге бейім. Жаман нәрсе туралы ойлап, жағымсыздықты өзі тартады — ол көңіл бөлген сала белсенді болады.\nМұндай адамдарға босаңсып, жағдайды өз ағымына жіберу өте қиын: олар маңызды бірдеңені жіберіп алудан қорқып, егжей-тегжейді ұқыпты әрі мұқият қадағалайды. Әлемді ақ пен қараға бөлу және жағымсыз көңіл күй өзіне, жоғары күштерге және болашаққа сенімсіздік тудырады, ол мазасыздықпен, қорқынышпен, алаңдаушылықпен, тұрақты кернеумен және цинизммен білінеді.", "max": "### Чакраның сыйымдылығы өте жоғары\nЧакраның өте үлкен сыйымдылығы адамға ойшыл мен талдаушының талантын береді. Бұл энергияны міндетті түрде пайдаланып, оған қолданыс табу керек. Ол жеткен жетістігіне тоқтап қалмай, әлемге әсер ету және сыртқы процестерді басқару тәсілдерін үнемі зерттейді. Оның рухани еркі дамыған — ол әрекеттерін саналылық арқылы басқара алады.\nМұндай сыйымдылығы бар адамдар орасан көп ақпаратты есте сақтап, өңдей алады. Олар әрдайым ақиқаттың түбіне жетіп, заттардың мәнін түсініп, логикалық тізбек құрып, кез келген процесс пен жағдайға түсініктеме тапқысы келеді. Олардың зияткерлік және талдау қабілеттері тамаша, ақыл дауысы күшті және оқиғаларға логикалық тұрғыдан қарайды.\nОлар оқиғаларды болжап, стратегия әзірлеп, жоспар құра біледі, алысты көреді. Бәрін ойластыру, егжей-тегжейді салыстыру, нәзік тұстарын түсіну — дәл солар туралы. Олар тек тексерілген әдістерге сенеді және шешім үшін оларға салмақты негіздер мен дәлелдер керек.\nМұндай адам әрдайым білімге құштар, оқығанды және ақылының күшін көрсеткенді жақсы көреді. Оның қалағанын көз алдына елестету (визуализация) және іске асыру күші орасан зор: ол арманын егжей-тегжейлі елестете алады, және ол жүзеге асады. Бірақ дәл осы қабілет қорқыныш пен алаңдаушылық тудырады, өйткені адам өзін-өзі қайрауға және иллюзия тұтқынында өмір сүруге бейім. Жаман нәрсе туралы ойлап, жағымсыздықты өзі тартады — ол көңіл бөлген сала белсенді болады.\nБәрінде тәртіп пен логикаға деген қажеттілік айқын болуы мүмкін, ал бұл өлшемдерге сай келмейтін нәрсе оған мүлде мүмкін емес болып көрінеді. Оған нақты логикалық дәлелдер керек — ол көріп, сезініп, талдағанда ғана сенеді.\nБірақ бұл оның жоғары күштер мен рухани заңдарға сенбейтінін білдірмейді. Керісінше, ол ойлауын дамытып, саналылығын арттырып, бұл салаларды зерттеп, құпия білім мен эзотериканы меңгергісі келеді. Ол тек жұмыста және жақындары үшін ғана емес, ұстаз, коуч және тәлімгер бола алады. Ол кез келген жағдайды түсініп, оны логикалық бөліктерге жіктеп, шешу жолдарын көрсете алады.\nОл жұмбақты жақсы көреді, өйткені жаңа мен белгісізді тануда оның ішкі өсуі және әлеуетінің ашылуы жатыр. Бұлар — өзін де, айналадағы әлемді де танитын зерттеушілер. Олар бірегей теория немесе данышпан идея ойлап тауып, айналадағыларды таңғалдырып, керекті мәселені таңғаларлық жолмен — көбіне басқаларға түсініксіз жолмен — шешетін стратегия әзірлей алады.\nМұндай сыйымдылығы бар адам көбіне көп адамды жақсы көрмейді, өзіне және ойларына берілуге бейім және солай күш жинайды — өзін интроверт ретінде көрсетуі мүмкін. Өзіне-өзі жеткіліктілігінің арқасында ол тәуелсіз әрі өзіне сенімді.\n### Әлсіз жағы\nМұндай үлкен сыйымдылық пайдаланылмаса, чакраның энергиясы әлсіз жағына кетуі мүмкін.\nБір жағынан, адам қиял әлеміне кетіп, айлакерлікпен алдап, шындықты иллюзиямен бағалауы мүмкін. Екінші жағынан — күмәншіл және сыншыл болып, тасжүректік пен цинизм танытып, дүниетанымын қырсықтықпен қорғауы мүмкін.\nОнда зияткерлік тәкаппарлық, өзімшілдік (эгоцентризм) және тек өз пікірі ғана дұрыс деген сенім қалыптасады. Ол басқаларды тар ойлы әрі ақымақ деп санайды және тұрмыстық, қарапайым әңгімеге қатысқысы келмейді. Менмендік айналадағылармен араласуды қиындатады.\nОл не өткенде тұрып қалуға, не болашаққа жабысып, қиял мен иллюзияда өмір сүруге бейім. Мұндай адамдар оқиғаларды соншалықты әсірелеп, өзін қайрап, сол ойларда тұрып қалуы мүмкін, сонда алаңдаушылық пен мазасыздық пайда болып, қорқынышты түстер мен елестер мазалауы мүмкін.\nӘлсіз жағында адам көбіне жағдайға өз көзқарасын таңып, адамдарды өз шеңбері мен үлгілеріне қамайды. Ол фактілермен сендіріп, қысым көрсетіп, ақыл жағынан артықшылығын көрсетіп, зияткерлік тұрғыдан басуы мүмкін.\nОл көбіне сезімдерін қабылдамайды, түйсігін естімейді және оған сенбейді. Руханилықпен байланысты нәрсенің бәрі ғылыммен расталмағандықтан жоққа шығарылуы мүмкін.\nОл қырсық әрі күмәншіл, оның пікірін өзгерту мүмкін емес. Ол басқа адамдардың ой-пікірі мен қорытындыларын сынауға бейім. Ойдың көптігі мен ақыл кернеуі ұйқысыздыққа және бас ауруына әкеледі.\nМұндай адамдарға босаңсып, жағдайды өз ағымына жіберу өте қиын: олар маңызды бірдеңені жіберіп алудан қорқып, егжей-тегжейді ұқыпты әрі мұқият қадағалайды. Бұл ұмытшақтыққа және есте сақтаудың нашарлауына әкеледі. Қарым-қатынаста күңкілдектіктен, сынау әдетінен, ұсақтықтан және бәрінде шектен тыс логикадан қиындықтар болуы мүмкін.\nӨз зияткерлігін онша адал емес тілектер мен пайдакүнем мүдделер үшін пайдалануға бейімділік бар."}, "intro": {"typ": "Тұлға типі адамның типологиясын — осы өмірдегі ішкі құрылымы мен жанының негізін ашады. Әр типологияның өз даму жолы және мінездің ерекше қырлары бар.", "contours": "Барлық контурлар — адамның мінезі мен мүмкіндіктері құралатын бір пазлдың бөліктері. Тұлғаны талдағанда үш контурдың да әсерін және олардың өзара байланысын ескеріңіз. Контурларды талдау адамның өмір оқиғаларына реакциясының шынайы көзін табуға көмектеседі: адамға көбіне бір нәрсе сияқты көрінеді, ал шын мәнінде мүлде басқа нәрсе болып жатады, бұл өзін де, басқаларды да түсінуді қиындатады. Адамның қарым-қатынаста, жұмыста және өзін жүзеге асыруда қандай қажеттіліктерін қанағаттандыратынын көруге болады. Мүмкін ол өз-өзінде шатасып қалған шығар, оған маманның талдауы керек — контурлардың сипаттамасы бұл жұмысқа қосымша құрал болады.", "rod": "Ру міндеті (родовая задача) — рудан мұраға қалған нәрсе. Ата-бабалар жинаған әлеует оларға ресурс болған. Бірақ ерте ме, кеш пе рудан біреу бұл әлеуетті теріс жағынан өмір сүре бастап, теңгерімді бұзған, сөйтіп ол рудың мәселесіне айналған. Адам осы мәселелерді шешуді және бұл қасиеттерді оң жаққа шығаруды — ру ресурсын пайдалана бастап, оны ұрпақтарына мәселе емес, күш ретінде беруді өз мойнына алған. Бұл — бүкіл өмірдің басты жұмысы. Ру міндетінде тұрған чакралар да адамның ең толы чакраларымен қатар жетекші болып саналады. Адамдарды көбіне ру саны бойынша кәсіптер мен істерге тартады, өйткені осылай бұл міндеттерді шешу оңайырақ әрі тезірек. Мақсат-мұрат туралы сұрақтың жауабы көбіне дәл ру міндетінде жатады.", "kar": "Кармалық міндет — өткен өмірден келген міндет, «кармалық құйрық». Бұл — жанның бұрынғы өмірлерде жинап үлгергені және осы өмірде шешуге келгені. Ол адамның нәзік жоспарына, денсаулығы мен тағдырына әсер етеді, мінезі мен мінез-құлқына күшті із қалдырады. Адам кармалық міндетін неғұрлым жақсы орындаса, осы өмірде соғұрлым жақсы сезінеді. Оны оң жаққа бұрса, табысқа жету оңайырақ, сонымен бірге дене, рухани және ой-сана күйі жақсарады. Ру міндеті іс түрін меңзесе, кармалық міндет мінез бен мінез-құлыққа әсер етеді. Ру міндеті де, кармалық міндет те адамды өмір бойы жалғасады — бұл бүкіл өмірдің жұмысы.", "periods": "Өмірдің әр кезеңіне өз сандар жұбы сәйкес келеді. Жоғарғы сан кезеңнің міндеттері мен тәуекелдерін көрсетеді. Төменгісі — позитив коды: ол қиын жағдайдан шығуға және жоғарғы санның міндетін ең аз кедергімен шешуге не көмектесетінін меңзейді.", "emo": "Эмоциялық реактивтілік типі адамның өзіне қанша энергия қалдыратынын, өзі туралы қаншалықты ойлайтынын, ал қанша энергия беретінін, басқа адамдардың ісіне қаншалықты араласуға дайын екенін, сондай-ақ командада жұмыс істеуге бейімділігін көрсетеді.", "intuition": "Түйсік (интуиция) контуры ми жарты шарларының жұмысын интеллектуалдық контурдан да дәлірек көрсетеді, өйткені ми қарқынды жұмыс істегенде, міндетке қарай күн өрімі (солнечное сплетение) мен жүрек энергиялары да қосылады. Сондықтан ол біздің әлеуетімізді күштірек ашады. Сөздік (вербальная) түйсік — сөз бен логикаға сүйену, сөзсіз (невербальная) түйсік — бейнелерге, түйсінулерге және сезімдерге сүйену.", "karma_now": "Қазіргі карма — адамның басқа міндеттерге қарамастан өмір бойы үнемі кездесетін нәрсесі, бір түрі «күнделікті жеңіл карма». Ата-анадан келген карма адамға ата-анасының қарым-қатынасы мен тәжірибесінен не берілгенін көрсетеді.", "want": "«Қалаймын» және «істей аламын» көрсеткіштері адамның тілектері мен ұмтылыстарының нақты мүмкіндіктеріне қаншалықты сәйкес келетінін көрсетеді. «Қалаймын» «істей аламыннан» әлдеқайда көп болса, адам, сірә, тез тұтанып, уәде беріп, көп іс жоспарлайды, бірақ ынтасы тез сөніп, бастаған ісі де тез тасталады. Іскерлік ынтымақтастық үшін бұл маңызды, өйткені екпінмен құрылған жоспар нәтижеге кепілдік бермейді. Мақсатқа баяу жылжудың себебі өмірлік энергия қорының аздығы, күш пен денсаулықтың жетіспеуі, тез шаршау да болуы мүмкін — сондықтан энергияны сақтау тәсілі ретінде жалқаулық пайда болады (бұл «істей аламынның» өте төмен көрсеткіштеріне қатысты). Мұндай адамға демалыс, ұзақ ұйқы және шаршап-шалдықпай кезең-кезеңімен жұмыс істеу ерекше маңызды: көп алынған міндеттеме не орындалмайды, не бәрін үлгеруге тырысу денсаулыққа зиян келтіреді. «Істей аламын» «қалаймыннан» көп болса, адам, сірә, ішкі ынтаның жетіспеуінен, психологиялық кедергілерден немесе оңай емес мінезінен бар әлеуетін пайдаланбайды. Осы себептерді жойса, оған көп ресурс ашылады.", "yin": "Инь Яннан көп болса, адамда әйелдік мінез-құлық — жұмсақтық, нәзіктік, сезімталдық күштірек дамыған, ал энергия ішкі әлемге бағытталған (интроверсия). Ян Иньнен көп болса, ерлік мінез-құлық — қаттылық, өткірлік, басым болуға ұмтылыс басым, ал энергия сыртқы әлемге бағытталған (экстраверсия). Айырма үлкен болса, адамға қандай энергия — әйелдік пе, ерлік пе — жетпейтіні көрінеді. Ең дұрысы — олар тепе-теңдікте болғаны.", "sex": "Тартымдылық әлеуеті (сексуальный потенциал), немесе магнетизм, назарды тартуға және ұстап тұруға көмектесетін харизмаға жауап береді. Ол арқылы адамның басқаларға қаншалықты ықпал ете алатынын байқауға болады. Жоғары магнетизм шартты түрде 1000-нан басталады — мұндай адамдар сирек байқалмай қалады және ерекше күш салмай-ақ оңай танымал болады.", "yamy": "«Мен» және «Біз» көрсеткіштері көшбасшылық әлеуетті көрсетеді. «Мен» «Бізден» көп болса, адамда туғаннан көшбасшылыққа бейімділік бар. Мәндері шамамен тең болса, көшбасшылыққа да, командада тең дәрежеде жұмыс істеуге де қабілеті бар. «Біз» «Меннен» көп болса, адам көшбасшы рөлінен гөрі ұжымда жұмыс істеуге көбірек бейім.", "chakras": "Чакралардың базалық сыйымдылығы (базовая ёмкость) — пайызбен берілген туа біткен көрсеткіш. Ол әр чакраның әлеуетін, ерекшеліктерін және өмірге қалай әсер ететінін көрсетеді. Адамның міндеті — өз деректерімен толыққанды, сапалы әрі ресурста қалай өмір сүруге болатынын және өмір бойы чакралармен қалай жұмыс істеу керектігін түсіну."}, "emo": {"Холодный": "Адам басқалардың ісіне онша араласпайды. Өзімшілдік сәл басым, бірақ басқаларды өз қажеттілігіне тартуды да білмейді. Адамдарға әлсіз жауап береді, араласуға және үн қатуға асықпайды.", "Самоотверженный": "Адам өзін ұмытуға дайын, байқамай өзін шетке ысырып, өз құнын сезінбеуі мүмкін. Ол басқалардың ісіне араласады, бірақ мұны ашық көрсетпеуі мүмкін, өте қамқор бола алады, өзін басқа адамнан бөлмей, онымен тұтасып кетіп, кейін көңілі қалуы мүмкін. Әлсіз жағында мұндай адамдарды елемей, пайдаланып кетуі мүмкін.", "Среднереактивный": "Өз мұқтажына да, өзгенікіне де орташа араласады. Мұндай адам көмектесуі немесе үн қатуы үшін оны өтіну керек. Өзімшілдік басым — ол өзі туралы көбірек ойлайды, бірақ басқаларды да ұмытпайды. Бұл — өзімшілдіктің әбден сау деңгейі: өзін ойлады — басқаларды да ойлады (әсіресе одан әдеппен бірдеңе өтінсе).", "Энергичный": "Альтруизм басым — адам басқалар туралы көбірек ойлайды, адамдарға көмектесуге қуана үлес қосады және өзін басқалар арқылы, өз істері арқылы жақсы көретін сияқты. Нәтиже мен адамдардың алғысын көргенде өзін жайлы сезінеді. Әдетте көмекті өзі ұсынады, бірақ өзін де ұмытпайды.", "Эгоистический": "Өзімшілдік үш есе басым: мұндай адам басқаларды өзіне көмектесуге тартып, ресурс алуға ұмтылады. Дұрыс тәрбиеленсе немесе өзімен жұмыс істесе, мұндай адамдардан соңынан ерте алатын жақсы басшылар шығады, ең нашар жағдайда — басқалардың мүддесі мен сезімін елемейтін айлакерлер (манипуляторлар).", "Сверхэнергичный": "Өзімшілдіктің күшті көрсеткіші және альтруизмнің одан да күшті көрсеткіші. Өз ісіне де, өзгенің ісіне де жоғары араласу. Бұл — өзі үшін де, басқалар үшін де «тау қопара» алатын адам: ол өз мұқтажына да, өзгенікіне де үн қатады, ал кейде басқалардың мүддесі мен мәселесіне тым беріліп, тіпті оларды өзінікі деп санай бастайды."}, "task": {"1": "Тұрақтылық пен орнықтылықты сақтай отырып, өз мақсаттарына жүру және өз руы мен жақын ортасын бір-бірімен байланысты біртұтас жүйе ретінде мойындау.", "2": "Өзіне-өзі жеткілікті бола тұра, айналадағылармен және жақындармен үйлесімді қарым-қатынас құру. Өзін қабылдап, тәуелділікке түспей, босаңси білу.", "3": "Өзін-өзі тәртіпке салу, мақсаттылық және саналы тұтыну арқылы өз өмірінің иесі болу — яғни не жейтініңізге, уақыт пен ресурсты қалай жұмсайтыныңызға және қабілетіңізді қалай пайдаланатыныңызға мұқият болу.", "4": "Өзін және адамдарды жақсы көруге, оңай кешіруге және алғыс айта білуге үйрену. Құрбандыққа да, немқұрайдылыққа да кетпей, эмоциялық тепе-теңдікке ұмтылу.", "5": "Айналадағы әлемді өзгерте алатын талант пен идеяларды аша отырып, өзін көрсетуге үйрену. Әлеуметтік белсенді болу — дау арқылы емес, дипломатияны дамыта отырып.", "6": "Интеллектуалдық жағынан жүзеге асу: оқу, жаңа нәрсе жасау және білім мен идеяларды адамдарға жеткізу. Өзіне сүйене отырып, ішкі тұтастыққа жету.", "7": "Сенім мен өзіне деген сенімділікті өсіре отырып, рухани даму. Оңашаланып кетпей, өзінің ерекшелігі мен ішкі күшін қабылдау.", "8": "Өзгерістер мен кедергілерден қорықпай, мақсаттарға жете отырып, ішкі күшін тану. Мейірімділікті сақтап, өмірдің мәнін тауып, қиындықтардан өсуге мүмкіндік табу.", "9": "Адамгершілік қағидаларды сақтап, рухани құндылықтарға сүйене отырып, үздіксіз өзін-өзі дамыту жолымен жүру. Мақсаттарға агрессиямен, ақталмаған құрбандықпен және қысыммен емес, жанашырлық пен мейірім арқылы жету."}, "risk_mul": "ішек жұмысының бұзылуы (қабыну, іш қату, геморрой, жарықтар), омыртқа, сүйек және бұлшықет мәселелері, табанның жалпақтығы, байламдардың жарақаты, мениск зақымы, табан шығуы, аяқ сүйегі мен жамбас мойнының сынуы, табиғи иммунитеттің әлсіреуі, аутоиммунды бұзылыстарға бейімділік, қозғалыстың шектелуі, буын аурулары (артрит, артроз), салмақтың бұзылуы (артық не жетіспеу), аяқ веналарының варикозы, үрей ұстамалары (панические атаки), ВСД (вегетососудистая дистония), анемия, тамыр мәселелері, тістің ерте түсуі және тістің нашар күйі, денелік төзімділіктің әлсіздігі және тез шаршау.", "risk_sva": "бала көтеру, оны сақтап, дүниеге әкелудегі қиындықтар, ер адамдарда сперматозоидтар белсенділігінің төмендеуі және әйелдерде ұрпақ өрбіту қабілетінің төмендеуі, аналық без немесе ен жұмысының бұзылуы, жыныс жүйесінің аурулары, омыртқаның төменгі бөлігінің мәселелері, етеккір циклінің бұзылуы, цистит және қуық жұмысының бұзылуы, бүйректегі тас және бүйрек жұмысының бұзылуы, қуықасты безінің (простата) аурулары, интимдік бұзылыстар, лимфа жүйесінің бұзылуы, жыныс гормондарының теңгерімсіздігі, үнемі күштің құлдырауы және энергияның жетіспеуі.", "risk_man": "тері мәселелері (псориаз, акне және т.б.), терідегі аллергия, жарық (грыжа), ойық жара (язва), колит, гастрит, панкреатит, ұйқы безі мен өт қабы жұмысының бұзылуы, өт қабындағы тас, қант деңгейінің жоғарылауы (диабет), нәжіс бұзылыстары, асқазан-ішек жолындағы кез келген ауырсыну мен жайсыздық, бауыр жұмысының бұзылуы, дискинезия, бауырдың ауыр зақымдары, дәрумендер мен минералдардың нашар сіңуі, зат алмасудың бұзылуы, тамақтану тәртібі мен сипатының бұзылуы.", "risk_ana": "жүрек жеткіліксіздігі және жүректің туа біткен ерекшеліктері, жүректің ауыр жүктемесі, стенокардия, ырғақтың бұзылуы, тахикардия мен аритмия, вегетососудистая дистония, жүрек бұлшықетінің қабынуы, қол аурулары, үрей ұстамалары (панические атаки), өкпенің қабынуы, пневмония, демікпе (астма), бронхит, құрғақ немесе ылғалды жөтел, созылмалы өкпе аурулары, қолтықасты аймағындағы қабыну, қол мен білектің сынуы, жарақаты және шығуы, мастопатия, мастит, кеуде аймағындағы жаңа өскіндер (оның ішінде қатерсіз), кеуде қуысының, жүрек пен өкпенің аурулары, қабырға жарақаты, сколиоз, кифоз және арқаның жоғарғы бөлігінің басқа бұзылыстары, айырша без (вилочковая железа) жұмысының бұзылуы.", "risk_vis": "тамақ аурулары (фарингит, баспа, тонзиллит және т.б.), жоғарғы тыныс жолдары мен мұрын-жұтқыншақ аурулары, дауыс байламдарының мәселелері, қалқанша және қалқанша маңы бездерінің бұзылуы (тиреотоксикоз, зоб, аутоиммунды тиреоидит, гипо- және гипертиреоз және т.б.), тұтығу және сөйлеу бұзылыстары, созылмалы ЛОР-аурулары, гайморит, синусит, отит, тіс мәселелері мен тістің түсуі, тіл мен қызыл иек аурулары, тамақтану тәртібі мен сипатының бұзылуы.", "risk_adj": "бастың соғылуы мен жарақаттары, бас аймағындағы жаңа өскіндер, ми қан айналымының бұзылуы, бас айналу, созылмалы шаршау синдромы, бас аймағындағы қабыну, құлақ аурулары және естудің төмендеуі, көз жарақаттары мен қабынуы, көру қабілетінің нашарлауы, бас ауруы мен мигрень, гайморит, мұрын қалқасының қисаюы, тұмау, жақ сүйегінің қабынуы және тіс түсуі, бет жарақаттары, ұйқысыздық, қорқыныш пен фобиялар, көңілсіз күй, психосоматикалық бұзылыстар.", "chakra_hdr": "Чакралардың базалық сыйымдылығы (базовая ёмкость) — пайызбен берілген туа біткен көрсеткіш. Ол әр чакраның әлеуетін, ерекшеліктерін және өмірге қалай әсер ететінін көрсетеді. Адамның міндеті — өз деректерімен толыққанды, сапалы әрі ресурста қалай өмір сүруге болатынын және өмір бойы чакралармен қалай жұмыс істеу керектігін түсіну.", "life_act_hdr": "Бұл жұмыс, хобби, әуестік және қызығушылық болуы мүмкін.", "life_str_intro": "Кезеңнің міндеттері {CH} арқылы жүзеге асады.", "mon_rec0": "Айдың ұсыныстарын ай кодының екінші саны бойынша қараңыз.", "rod_risk_hdr": "Ру сценарийі мен ру ұстанымдары өмірде көрініп, адамды ру міндетін орындауға итермелейді, оған әсер етіп, белгілі бір тәуекелдер туғызады.", "kar_risk_hdr": "Кармалық сценарий өмірге әсер етіп, адамның тағдырында белгілі бір оқиғалар мен жағдайлар туғызады және оны кармалық міндетті орындауға итермелейді. Міндетті байқамаса, түсінбесе немесе орындамаса, тәуекелдер пайда болуы мүмкін.", "real_hdr": "Бұл сан адамның {Wa} міндетті не арқылы және қандай стратегияның арқасында орындап, {Wg} ықпалдың әлеуеті мен ресурсын ала алатынын көрсетеді.", "chakra_name": {"1": "Муладхара чакрасы", "2": "Свадхистана чакрасы", "3": "Манипура чакрасы", "4": "Анахата чакрасы", "5": "Вишудха чакрасы", "6": "Аджна чакрасы", "7": "Сахасрара чакрасы", "8": "Трансформация арнасы (канал Трансформации)", "9": "Салдар арнасы (канал Последствий)"}, "real_intro": "{W} міндет {CH} арқылы жүзеге асады. Дәл соның қасиеттері мен сапалары {Wa} сценарийді өзгертуге және одан шығуға көмектеседі. Сонымен бірге {Wa} міндетті теріс жағынан өмір сүрсе немесе орындамаса, бұл сала тәуекелге ұшырайды.", "real_intro9": "{W} міндет Салдар арнасы (канал Последствий) арқылы жүзеге асады. Дәл соның қасиеттері мен сапалары {Wa} сценарийді өзгертуге және одан шығуға көмектеседі. {W} міндетте тоғыз тұрса, тәуекелдер міндеттің бірінші саны бойынша күшейеді.", "real_risk9_extra": ", жасырын аурулар.", "typ_hdr": "Тұлға типі адамның типологиясын — осы өмірдегі ішкі құрылымы мен жанының негізін ашады. Әр типологияның өз даму жолы және мінездің ерекше қырлары бар.", "year_q_intro": "Бұл сұрақтар жылдың мақсаттарын қоюға, энергияны дұрыс арнаға бағыттауға, ал жыл соңында қорытынды жасауға көмектеседі.", "ystr_intro": "{CH} қасиеттері мен әсері осы кезеңді өмір сүруге көмектеседі. Бірақ оның міндеттерін орындамаса және әлеуетін пайдаланбаса, бұл сала тәуекелге ұшырап, теріс жағынан көрінуі мүмкін.", "mul_risk_in": ["low", "high", "max"], "man_risk_in": ["low", "high", "max"], "ana_levels": {"low": ["14", "18", "23", "27", "32", "36", "41"], "norm": ["45", "50", "54"], "high": ["59", "68", "73", "77"], "max": ["95", "99"]}, "adj_levels": {"low": ["18", "24", "29", "35", "41"], "norm": ["47"], "high": ["59", "65", "71", "76", "82", "88"], "max": ["99"]}, "ana_risk_in": ["low", "high", "max"], "vis_levels": {"low": ["0", "7", "14", "21", "26", "29", "43"], "norm": ["50"], "high": ["57", "64", "71", "78", "84", "86"], "max": ["93", "99"]}, "sva_risk_in": ["low", "high", "max"], "adj_risk_in": ["low", "high", "max"], "mul_levels": {"low": ["10", "15", "20", "25", "30", "33", "35", "40"], "norm": ["45", "50", "55"], "high": ["60", "75", "80"], "max": ["90", "95", "99"]}, "harm_levels": {"mul": {"low": ["10", "15", "20", "25", "30", "33", "35", "40", "45", "50", "55"], "high": ["60", "75", "80"], "max": ["90", "95", "99"]}, "sva": {"low": ["21", "22", "28", "41", "45", "49", "51", "52", "55"], "high": ["61", "63", "65", "72", "79", "83", "99"]}, "man": {"low": ["6", "12", "18", "25", "31", "37", "44", "50"], "high": ["56", "62", "69", "75", "81", "99"]}, "ana": {"low": ["14", "18", "23", "27", "32", "36", "41", "50", "54"], "norm": ["45"], "high": ["59", "68", "73", "77"], "max": ["95", "99"]}, "vis": {"low": ["0", "7", "14", "21", "26", "29", "43", "50"], "high": ["57", "64", "71", "78", "84", "86", "93", "99"]}, "adj": {"low": ["18", "24", "29", "35", "41", "47"], "high": ["59", "65", "71", "76", "82", "88", "99"]}}, "sva_levels": {"low": ["21", "22", "28", "41"], "norm": ["45", "49", "51", "52", "55"], "high": ["61", "63", "65", "72", "79", "83"], "max": ["99"]}, "man_levels": {"low": ["6", "12", "18", "25", "31", "37", "44"], "norm": ["50"], "high": ["56", "62", "69", "75", "81"], "max": ["99"]}, "vis_risk_in": ["low", "high", "max"]};
